window.CHAPTER_DATA = {};

window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c11b-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 1</div>\n      <h2>The Living World</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"margin:24px 0; background:#f0fdf4; border:1px solid #bbf7d0; border-radius:12px; padding:18px; text-align:center;\">\n    <div style=\"font-size:0.95rem; font-weight:800; color:#166534; margin-bottom:12px;\">\n      Figure 1.1: Standard Taxonomic Hierarchy (Ascending Order) &amp; Binomial Nomenclature Architecture\n    </div>\n    <svg viewBox=\"0 0 840 280\" style=\"max-width:100%; height:auto; font-family:'Plus Jakarta Sans', system-ui, sans-serif;\">\n      <!-- Background panel -->\n      <rect x=\"10\" y=\"10\" width=\"820\" height=\"260\" rx=\"10\" fill=\"#ffffff\" stroke=\"#86efac\" stroke-width=\"1.5\"/>\n\n      <!-- LEFT: Taxonomic Pyramid/Steps -->\n      <text x=\"30\" y=\"36\" font-size=\"12\" font-weight=\"bold\" fill=\"#14532d\">1. Taxonomic Categories (Hierarchy):</text>\n      \n      <!-- Kingdom -->\n      <rect x=\"30\" y=\"50\" width=\"360\" height=\"24\" rx=\"4\" fill=\"#15803d\"/>\n      <text x=\"140\" y=\"67\" font-size=\"11\" font-weight=\"bold\" fill=\"#ffffff\">KINGDOM (e.g., Animalia / Plantae)</text>\n      <text x=\"35\" y=\"66\" font-size=\"9\" fill=\"#dcfce7\">Highest Rank</text>\n\n      <!-- Phylum/Division -->\n      <rect x=\"50\" y=\"78\" width=\"320\" height=\"24\" rx=\"4\" fill=\"#16a34a\"/>\n      <text x=\"145\" y=\"95\" font-size=\"11\" font-weight=\"bold\" fill=\"#ffffff\">PHYLUM / DIVISION (e.g., Chordata)</text>\n\n      <!-- Class -->\n      <rect x=\"70\" y=\"106\" width=\"280\" height=\"24\" rx=\"4\" fill=\"#22c55e\"/>\n      <text x=\"160\" y=\"123\" font-size=\"11\" font-weight=\"bold\" fill=\"#ffffff\">CLASS (e.g., Mammalia)</text>\n\n      <!-- Order -->\n      <rect x=\"90\" y=\"134\" width=\"240\" height=\"24\" rx=\"4\" fill=\"#4ade80\"/>\n      <text x=\"170\" y=\"151\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\">ORDER (e.g., Carnivora)</text>\n\n      <!-- Family -->\n      <rect x=\"110\" y=\"162\" width=\"200\" height=\"24\" rx=\"4\" fill=\"#86efac\"/>\n      <text x=\"175\" y=\"179\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\">FAMILY (e.g., Felidae)</text>\n\n      <!-- Genus -->\n      <rect x=\"130\" y=\"190\" width=\"160\" height=\"24\" rx=\"4\" fill=\"#bbf7d0\"/>\n      <text x=\"178\" y=\"207\" font-size=\"11\" font-weight=\"bold\" fill=\"#14532d\">GENUS (e.g., Panthera)</text>\n\n      <!-- Species -->\n      <rect x=\"150\" y=\"218\" width=\"120\" height=\"26\" rx=\"4\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n      <text x=\"168\" y=\"235\" font-size=\"11\" font-weight=\"bold\" fill=\"#15803d\">SPECIES (e.g., leo)</text>\n      <text x=\"155\" y=\"255\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#166534\">Basic Unit of Classification</text>\n\n      <!-- Direction Arrow -->\n      <line x1=\"405\" y1=\"230\" x2=\"405\" y2=\"60\" stroke=\"#059669\" stroke-width=\"2.5\" marker-end=\"url(#arrowUp)\"/>\n      <defs>\n        <marker id=\"arrowUp\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" orient=\"auto\">\n          <path d=\"M0,6 L3,0 L6,6 L3,4 Z\" fill=\"#059669\"/>\n        </marker>\n      </defs>\n      <text x=\"415\" y=\"145\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#059669\" transform=\"rotate(-90 415 145)\">Decreasing Specificity &bull; Increasing Generality &longrightarrow;</text>\n\n      <!-- RIGHT: Binomial Nomenclature Anatomy -->\n      <text x=\"470\" y=\"36\" font-size=\"12\" font-weight=\"bold\" fill=\"#14532d\">2. Binomial Nomenclature Rules (Carolus Linnaeus):</text>\n      \n      <rect x=\"470\" y=\"55\" width=\"345\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1\"/>\n\n      <!-- Example box -->\n      <rect x=\"485\" y=\"70\" width=\"315\" height=\"48\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"1.5\"/>\n      <text x=\"500\" y=\"100\" font-size=\"18\" font-style=\"italic\" font-weight=\"bold\" fill=\"#065f46\">Mangifera indica <tspan font-style=\"normal\" font-size=\"12\" fill=\"#64748b\">Linn.</tspan></text>\n\n      <!-- Explanatory tags -->\n      <path d=\"M 540,118 L 540,140\" stroke=\"#059669\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n      <rect x=\"490\" y=\"140\" width=\"110\" height=\"42\" rx=\"4\" fill=\"#ffffff\" stroke=\"#059669\"/>\n      <text x=\"496\" y=\"156\" font-size=\"9\" font-weight=\"bold\" fill=\"#059669\">Generic Name (Genus)</text>\n      <text x=\"496\" y=\"172\" font-size=\"8\" fill=\"#334155\">&bull; Begins with Capital 'M'</text>\n\n      <path d=\"M 640,118 L 640,140\" stroke=\"#059669\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n      <rect x=\"610\" y=\"140\" width=\"115\" height=\"42\" rx=\"4\" fill=\"#ffffff\" stroke=\"#059669\"/>\n      <text x=\"616\" y=\"156\" font-size=\"9\" font-weight=\"bold\" fill=\"#059669\">Specific Epithet (Species)</text>\n      <text x=\"616\" y=\"172\" font-size=\"8\" fill=\"#334155\">&bull; Begins with small 'i'</text>\n\n      <path d=\"M 750,118 L 750,140\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n      <rect x=\"730\" y=\"140\" width=\"70\" height=\"42\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n      <text x=\"735\" y=\"156\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#475569\">Citation</text>\n      <text x=\"735\" y=\"172\" font-size=\"7.5\" fill=\"#64748b\">Linnaeus</text>\n\n      <!-- Rule summary text -->\n      <text x=\"488\" y=\"202\" font-size=\"8.5\" fill=\"#334155\">&bull; <strong>Latin Origin:</strong> Printed in <em>Italics</em>; underlined separately if handwritten.</text>\n      <text x=\"488\" y=\"218\" font-size=\"8.5\" fill=\"#334155\">&bull; <strong>Law of Priority:</strong> Earliest validly published name stands as correct taxon.</text>\n      <text x=\"488\" y=\"234\" font-size=\"8.5\" fill=\"#334155\">&bull; <strong>Tautonyms:</strong> Permitted in ICZN (e.g., <em>Naja naja</em>), prohibited in ICBN.</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 10: Biodiversity, Binomial Nomenclature, Taxonomic Hierarchy, Taxon Concepts &amp; Taxonomic Keys</div>\n\n  <!-- c11b-ch1-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why are living organisms classified?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Biological Significance of Biological Classification:</strong><br>\n    The Earth is inhabited by an immense diversity of living organisms (approximately 1.7 to 1.8 million species described so far, termed global biodiversity). Classification is the scientific arrangement of organisms into distinct groups and categories based on their observable similarities, differences, and evolutionary affinities. Living organisms are classified for the following essential scientific reasons:<br><br>\n    <strong>1. Ease of Study and Systematic Organization:</strong><br>\n    It is impossible to study every living organism individually. By classifying organisms into categories (such as kingdoms, phyla, and classes), the study of one or two representative members of a group provides a reliable general understanding of the characteristics of the entire group.<br><br>\n    <strong>2. Universal Identification and Prevention of Confusion:</strong><br>\n    Living organisms possess diverse vernacular (local) names in different geographic regions and languages. Classification establishes a standardized global framework (Binomial Nomenclature), enabling scientists worldwide to refer unambiguously to the same organism by a unique, universally accepted scientific name.<br><br>\n    <strong>3. Understanding Evolutionary and Phylogenetic Relationships:</strong><br>\n    Biological classification reflects the evolutionary trajectory (phylogeny) of organisms, demonstrating how complex multi-cellular forms originated and diversified from simpler ancestral unicellular forms over geological time.<br><br>\n    <strong>4. Discovery and Placement of New Organisms:</strong><br>\n    Whenever a newly discovered organism is identified, classification provides an exact taxonomic hierarchy and framework where it can be properly categorized according to its morphological, physiological, anatomical, and genetic traits.<br><br>\n    <strong>5. Applied Biological Sciences:</strong><br>\n    Accurate taxonomic classification is indispensable in agriculture, forestry, industry, biotechnology, pharmacognosy, and ecological conservation programs.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of vast biodiversity (1.7–1.8 million species) & impossibility of individual study</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Facilitates standardized identification and reveals phylogenetic/evolutionary links</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Enables systematic placement of new species and practical applications in agriculture/biotech</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why are the classification systems changing every now and then?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Dynamic Evolution of Biological Classification Systems:</strong><br>\n    Classification systems in biology are never static; they undergo continuous refinement and modification due to the progressive expansion of scientific knowledge, technological breakthroughs, and deeper insights into evolutionary biology:<br><br>\n    <strong>1. Historical Shift from Superficial to Natural Criteria:</strong><br>\n    Early classification systems (e.g., Aristotle, Theophrastus, and Linnaeus) were largely <em>Artificial Systems</em> based merely on superficial morphological habits, habitats, and economic utility (e.g., classifying plants into herbs, shrubs, trees; or based solely on stamen numbers). As scientific inquiry advanced, <em>Natural Systems</em> (e.g., Bentham and Hooker) emerged, incorporating internal features such as anatomy, histology, embryology, and phytochemistry.<br><br>\n    <strong>2. Advancement of Microscopy and Analytical Tools:</strong><br>\n    With the advent of high-resolution light microscopy and electron microscopy (TEM and SEM), cellular ultrastructure—such as distinguishing prokaryotes from eukaryotes, cellular organelles, and specialized wall compositions (e.g., peptidoglycan, chitin, cellulose)—became clearly observable. This necessitated the transition from the Two-Kingdom system to Ernst Haeckel’s Three-Kingdom, Copeland’s Four-Kingdom, and R.H. Whittaker’s Five-Kingdom system (1969).<br><br>\n    <strong>3. Integration of Molecular Biology and Genetic Phylogeny:</strong><br>\n    Modern taxonomy heavily relies on molecular data, including DNA and RNA sequencing, 16S ribosomal RNA analysis (Carl Woese’s Three-Domain system), amino acid sequencing of conserved proteins (such as cytochrome c), and karyotype analyses. These molecular markers often reveal true genealogical affinities that diverge from deceptive phenotypic or convergent morphological traits.<br><br>\n    <strong>4. Discovery of Novel Taxa:</strong><br>\n    Continuous exploration of extreme habitats (deep sea hydrothermal vents, acidic hot springs, Antarctic ice sheets) unearths novel taxa (e.g., Archaebacteria, extremophiles) that challenge existing taxonomic boundaries, requiring the creation of new categories and taxonomic adjustments.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Evolution from artificial (superficial traits) to natural and phylogenetic systems</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of microscopy, biochemical analysis, and organelle ultrastructure discovery</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Integration of molecular genetics (DNA/RNA/16S rRNA sequencing) and discovery of novel taxa</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What different criteria would you choose to classify people that you meet often?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Classification Criteria for Everyday Human Social Interactions:</strong><br>\n    In scientific taxonomy, criteria are chosen based on the objective of classification. Similarly, to classify people encountered regularly, both biological and sociological criteria can be utilized depending on the operational context:<br><br>\n    <strong>1. Age and Developmental Phase:</strong><br>\n    • Children / Toddlers (0–12 years)<br>\n    • Adolescents / Teenagers (13–19 years)<br>\n    • Adults / Working Professionals (20–59 years)<br>\n    • Senior Citizens (60+ years)<br><br>\n    <strong>2. Nature of Social / Functional Relationship:</strong><br>\n    • Family members and immediate relatives<br>\n    • Close personal friends and peer group<br>\n    • Teachers, mentors, and academic instructors<br>\n    • Classmates, study partners, and school peers<br>\n    • Professional service providers (shopkeepers, bus drivers, doctors)<br>\n    • Acquaintances / Strangers<br><br>\n    <strong>3. Academic / Professional Activity Domain:</strong><br>\n    • Science stream, Commerce stream, Humanities/Arts stream<br>\n    • Co-curricular activities: Sports/Athletics, Music/Arts, Debate/Literature, Coding/Robotics<br><br>\n    <strong>4. Geographic / Linguistic Background:</strong><br>\n    • Neighborhood / Local community residents<br>\n    • Regional origin and mother tongue (Hindi, English, Tamil, Bengali, Punjabi, etc.)<br><br>\n    <strong>Scientific Significance:</strong><br>\n    This demonstrates that classification is inherently hierarchical and purposeful: no single criterion suffices for all situations, and categorized groups facilitate organized social communication, collaboration, and systematic understanding.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Categorisation by age groups and developmental milestones</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Categorisation by functional relationship and social intimacy (family, peers, instructors)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Categorisation by professional/academic domain and geographic/linguistic factors</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What do we learn from identification of individuals and populations?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Key Learnings from the Scientific Identification of Individuals and Populations:</strong><br>\n    Identification involves recognizing an unknown organism and assigning it to an already established taxonomic rank by comparing its diagnostic traits with known species. The biological insights gained include:<br><br>\n    <strong>A. Learnings from Individual Identification:</strong><br>\n    1. <em>Morphological &amp; Anatomical Characteristics:</em> Delineates structural features such as body symmetry, presence of notochord, leaf venation, floral formula, and reproductive organs.<br>\n    2. <em>Exact Taxonomic Position:</em> Places the organism precisely into its correct domain, kingdom, phylum/division, class, order, family, genus, and species.<br>\n    3. <em>Physiological &amp; Ecological Role:</em> Identifies nutritional mode (autotroph, heterotroph, saprophyte), ecological niche, and environmental adaptations.<br>\n    4. <em>Economic &amp; Medical Utility:</em> Discovers potential medicinal value, agricultural utility, toxicity, or pathogenicity.<br><br>\n    <strong>B. Learnings from Population Identification:</strong><br>\n    1. <em>Intraspecific Genetic Variation:</em> Reveals morphological polymorphism, genetic diversity, and phenotypic plasticity within the same species across varying geographical habitats.<br>\n    2. <em>Reproductive Dynamics &amp; Gene Flow:</em> Highlights interbreeding capabilities, isolating mechanisms, allele frequencies, and natural selection pressures.<br>\n    3. <em>Demographic Structure:</em> Provides data on population size, age distribution, sex ratio, birth/death rates, and carrying capacity.<br>\n    4. <em>Ecological Interactions &amp; Biogeography:</em> Maps geographic distribution, habitat preference, symbiotic associations, predator-prey dynamics, and endangered/vulnerable conservation status.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Learnings at individual level: anatomical traits, exact taxonomic rank, and economic utility</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Learnings at population level: genetic diversity, interbreeding, allele frequency, and conservation status</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Given below is the scientific name of Mango. Identify the correctly written name:<br><em>Mangifera Indica</em><br><em>Mangifera indica</em>\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Identification &amp; Botanical Nomenclature Analysis:</strong><br><br>\n    The correctly written scientific name is: <br>\n    $$\\mathbf{\\textit{Mangifera indica}}$$\n    (Full author citation: $\\textit{Mangifera indica}\\text{ Linn.}$, where Linn. indicates that the species was first described by Carolus Linnaeus).<br><br>\n    <strong>Universal Rules of Binomial Nomenclature Justification:</strong><br>\n    1. <strong>Two-Part Scientific Name:</strong> Each biological name consists of two Latinized words—the first word represents the <em>Genus</em> (generic name) and the second word represents the <em>specific epithet</em>.<br>\n    2. <strong>Capitalization Rules:</strong> The generic name must always start with a <strong>Capital letter</strong> (e.g., <em>Mangifera</em>), whereas the specific epithet must strictly begin with a <strong>small letter</strong> (e.g., <em>indica</em>). Therefore, <em>Mangifera Indica</em> with a capital 'I' violates the International Code of Botanical Nomenclature (ICBN) and is invalid.<br>\n    3. <strong>Typographical Formatting:</strong> When printed, biological names must be rendered in <em>Italics</em> to indicate their Latin origin. When handwritten, the generic name and specific epithet must be underlined separately (<u>Mangifera</u> <u>indica</u>).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct selection of \\textit{Mangifera indica} (small letter for specific epithet)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Citation of ICBN rules regarding capitalization of genus and lowercase specific epithet</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define a taxon. Give some examples of taxa at different hierarchical levels.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Taxon (Plural: Taxa):</strong><br>\n    A <strong>taxon</strong> is a scientific term used to designate any concrete unit or taxonomic group of organisms of any rank in a biological classification system. It represents real biological entities assigned to a recognized taxonomic category based on shared diagnostic characteristics.<br><br>\n    <em>Distinction between Category and Taxon:</em> A 'category' is an abstract hierarchical rank (e.g., Kingdom, Class, Order, Genus), whereas a 'taxon' is the actual group of living organisms occupying that category (e.g., Plantae, Mammalia, Carnivora, <em>Homo</em>).<br><br>\n    <strong>Examples of Taxa at Different Hierarchical Levels:</strong><br>\n    <div style=\"overflow-x:auto; margin:14px 0;\">\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem; text-align:left;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Hierarchical Category (Rank)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Example Taxon (Plant Domain)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Example Taxon (Animal Domain)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Kingdom</td>\n            <td style=\"padding:8px 12px;\"><em>Plantae</em></td>\n            <td style=\"padding:8px 12px;\"><em>Animalia</em></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Division / Phylum</td>\n            <td style=\"padding:8px 12px;\"><em>Angiospermae</em></td>\n            <td style=\"padding:8px 12px;\"><em>Chordata</em> / <em>Arthropoda</em></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Class</td>\n            <td style=\"padding:8px 12px;\"><em>Dicotyledonae</em> / <em>Monocotyledonae</em></td>\n            <td style=\"padding:8px 12px;\"><em>Mammalia</em> / <em>Insecta</em></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Order</td>\n            <td style=\"padding:8px 12px;\"><em>Polymoniales</em> / <em>Sapindales</em></td>\n            <td style=\"padding:8px 12px;\"><em>Carnivora</em> / <em>Primata</em></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Family</td>\n            <td style=\"padding:8px 12px;\"><em>Solanaceae</em> / <em>Anacardiaceae</em></td>\n            <td style=\"padding:8px 12px;\"><em>Felidae</em> / <em>Hominidae</em></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Genus</td>\n            <td style=\"padding:8px 12px;\"><em>Solanum</em> / <em>Mangifera</em></td>\n            <td style=\"padding:8px 12px;\"><em>Panthera</em> / <em>Homo</em></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">Species</td>\n            <td style=\"padding:8px 12px;\"><em>Solanum tuberosum</em> (Potato)</td>\n            <td style=\"padding:8px 12px;\"><em>Panthera leo</em> (Lion) / <em>Homo sapiens</em></td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear scientific definition of a taxon as a concrete biological unit at any rank</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Distinction between abstract hierarchical rank (category) and real organism group (taxon)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiple correct examples of taxa across distinct ranks (Kingdom, Class, Genus, Species)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Can you identify the correct sequence of taxonomical categories?<br>(a) Species &longrightarrow; Order &longrightarrow; Phylum &longrightarrow; Kingdom<br>(b) Genus &longrightarrow; Species &longrightarrow; Order &longrightarrow; Kingdom<br>(c) Species &longrightarrow; Genus &longrightarrow; Order &longrightarrow; Phylum\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Evaluation of Taxonomic Sequences:</strong><br><br>\n    The standard ascending taxonomic hierarchy established by Carolus Linnaeus and modern ICBN/ICZN codes is:<br>\n    $$\\mathbf{\\text{Species} \\longrightarrow \\text{Genus} \\longrightarrow \\text{Family} \\longrightarrow \\text{Order} \\longrightarrow \\text{Class} \\longrightarrow \\text{Phylum (or Division)} \\longrightarrow \\text{Kingdom}}$$<br>\n    Analyzing the given options:<br>\n    • <strong>Sequence (a):</strong> Species &longrightarrow; Order &longrightarrow; Phylum &longrightarrow; Kingdom<br>\n    This sequence is technically in the correct ascending order of hierarchy (Species is lower than Order, Order is lower than Phylum, and Phylum is lower than Kingdom), but intermediate categories (Genus, Family, Class) are omitted.<br><br>\n    • <strong>Sequence (b):</strong> Genus &longrightarrow; Species &longrightarrow; Order &longrightarrow; Kingdom<br>\n    This sequence is <strong>incorrect</strong> because Genus is placed before Species; in an ascending hierarchy, Species must precede Genus.<br><br>\n    • <strong>Sequence (c):</strong> Species &longrightarrow; Genus &longrightarrow; Order &longrightarrow; Phylum<br>\n    This sequence correctly reflects ascending taxonomic ranks (Species &longrightarrow; Genus, then jumping through Family to Order, then Class to Phylum).<br><br>\n    $$\\mathbf{\\text{Conclusion: Both (a) and (c) represent correct ascending hierarchical orders, with (c) being the most standard contiguous progression.}}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of (c) and (a) as valid ascending sequences and rejection of (b)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complete ascending hierarchy definition: Species → Genus → Family → Order → Class → Phylum → Kingdom</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Try to collect all the currently accepted meanings for the word 'species'. Discuss with your teacher the meaning of species in case of higher plants and animals on one hand, and bacteria on the other hand.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Accepted Scientific Concepts and Meanings of the Term 'Species':</strong><br>\n    • <strong>Biological Species Concept (Ernst Mayr, 1942):</strong> A species is a group of interbreeding or potentially interbreeding natural populations that are reproductively isolated from other such groups, producing viable and fertile offspring.<br>\n    • <strong>Morphological Species Concept:</strong> A group of individuals that share distinct, consistent structural and morphological characteristics distinguishing them from others.<br>\n    • <strong>Phylogenetic / Evolutionary Species Concept (Simpson &amp; Cracraft):</strong> An irreducible lineage of organisms that maintains its identity from other lineages and has an independent evolutionary trajectory.<br>\n    • <strong>Genetic / Molecular Species Concept:</strong> A cluster of organisms possessing a high degree of genetic identity and similarity across conserved genomic regions (e.g., DNA-DNA hybridization &gt; 70% or 16S rRNA gene similarity &gt; 97%).<br><br>\n\n    <strong>2. Comparison: Higher Plants and Animals vs. Bacteria (Prokaryotes):</strong><br>\n    <div style=\"overflow-x:auto; margin:12px 0;\">\n      <table style=\"width:100%; border-collapse:collapse; font-size:0.88rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Higher Plants and Animals (Eukaryotes)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Bacteria (Prokaryotes)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Reproduction Mode</td>\n            <td style=\"padding:8px 12px;\">Predominantly sexual reproduction with gametogenesis, syngamy, and meiosis.</td>\n            <td style=\"padding:8px 12px;\">Asexual reproduction via binary fission; lack true sexual reproduction.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0; background:#f8fafc;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Applicability of Biological Species Concept</td>\n            <td style=\"padding:8px 12px;\"><strong>Strictly Applicable:</strong> Reproductive isolation reliably demarcates distinct species boundaries.</td>\n            <td style=\"padding:8px 12px;\"><strong>Not Applicable:</strong> Because bacteria do not undergo sexual reproduction and natural interbreeding.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">Gene Transfer</td>\n            <td style=\"padding:8px 12px;\">Strict vertical gene transfer from parents to offspring.</td>\n            <td style=\"padding:8px 12px;\">Extensive Horizontal Gene Transfer (HGT) via transformation, conjugation, and transduction across diverse strains.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">Primary Delineation Criterion</td>\n            <td style=\"padding:8px 12px;\">Morphology, reproductive compatibility, karyology, and anatomy.</td>\n            <td style=\"padding:8px 12px;\">16S rRNA gene sequencing, whole genome average nucleotide identity (ANI &gt; 95–96%), and biochemical profiling.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Biological Species Concept (Ernst Mayr: reproductive isolation and interbreeding)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of Morphological and Phylogenetic/Molecular concepts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed contrast: higher organisms rely on sexual reproduction and reproductive isolation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed contrast: bacteria lack sexual reproduction, exhibit HGT, and are classified by 16S rRNA / genomics</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define and understand the following terms:<br>(i) Phylum<br>(ii) Class<br>(iii) Family<br>(iv) Order<br>(v) Genus\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Definitions of Taxonomic Categories:</strong><br><br>\n    <strong>(i) Phylum (Division in Plants):</strong><br>\n    A primary taxonomic category above Class and below Kingdom. It comprises a group of related classes sharing major fundamental structural and architectural body plans.<br>\n    • <em>Animal Example:</em> Phylum <strong>Chordata</strong> includes classes Mammalia, Aves, Reptilia, Amphibia, and Pisces due to common diagnostic features—presence of notochord, dorsal hollow nerve cord, and paired pharyngeal gill slits.<br>\n    • <em>Plant Example:</em> Division <strong>Angiospermae</strong>.<br><br>\n\n    <strong>(ii) Class:</strong><br>\n    A major taxonomic category comprising one or more related orders having a number of common diagnostic traits.<br>\n    • <em>Animal Example:</em> Class <strong>Mammalia</strong> includes Order Primata (monkeys, apes, humans) and Order Carnivora (cats, dogs, tigers), all characterized by mammary glands, hair on skin, and three middle ear ossicles.<br>\n    • <em>Plant Example:</em> Class <strong>Dicotyledonae</strong> includes orders Sapindales and Polymoniales.<br><br>\n\n    <strong>(iii) Order:</strong><br>\n    An assemblage of related families that exhibit a few similar, distinctive floral or morphological characteristics.<br>\n    • <em>Plant Example:</em> Order <strong>Polymoniales</strong> includes plant families Solanaceae and Convolvulaceae based mainly on floral characters.<br>\n    • <em>Animal Example:</em> Order <strong>Carnivora</strong> includes family Felidae (cats) and family Canidae (dogs).<br><br>\n\n    <strong>(iv) Family:</strong><br>\n    A taxonomic category encompassing a group of related genera with still fewer similarities compared to genus and species, characterized by both vegetative and reproductive/floral features.<br>\n    • <em>Plant Example:</em> Family <strong>Solanaceae</strong> contains distinct genera: <em>Solanum</em>, <em>Petunia</em>, and <em>Datura</em>.<br>\n    • <em>Animal Example:</em> Family <strong>Felidae</strong> includes genus <em>Panthera</em> (lion, tiger, leopard) and genus <em>Felis</em> (domestic cat).<br><br>\n\n    <strong>(v) Genus:</strong><br>\n    A group of closely related species which have more characters in common in comparison to species of other genera. It is an aggregate of closely related species.<br>\n    • <em>Plant Example:</em> Genus <strong><em>Solanum</em></strong> includes species <em>tuberosum</em> (potato), <em>melongena</em> (brinjal), and <em>nigrum</em> (black nightshade).<br>\n    • <em>Animal Example:</em> Genus <strong><em>Panthera</em></strong> includes <em>Panthera leo</em> (lion), <em>Panthera tigris</em> (tiger), and <em>Panthera pardus</em> (leopard).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Definition of Phylum/Division with chordate / angiosperm examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Definition of Class with Mammalia / Dicotyledonae examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Definition of Order with Polymoniales / Carnivora examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) Definition of Family with Solanaceae / Felidae examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(v) Definition of Genus as an aggregate of closely related species with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch1-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch1-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch1-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How is a key helpful in the identification and classification of an organism?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Role of Taxonomic Keys in Identification and Classification:</strong><br>\n    A <strong>taxonomic key</strong> is an indispensable analytical device used by biologists for identifying unknown plants and animals based on observable similarities and dissimilarities.<br><br>\n    <strong>Key Structural Principles of a Taxonomic Key:</strong><br>\n    1. <strong>Couplet:</strong> Keys are based on contrasting characters generally arranged in pairs called a <em>couplet</em>.<br>\n    2. <strong>Lead:</strong> Each statement in a taxonomic key is called a <em>lead</em>.<br>\n    3. <strong>Analytical Dichotomy:</strong> The user evaluates the contrasting statements against the unknown specimen. Accepting one statement leads to the elimination/rejection of the alternate choice, which either directly identifies the organism or directs the user to the next subordinate couplet.<br>\n    4. <strong>Separate Keys for Distinct Ranks:</strong> Separate taxonomic keys are developed for each taxonomic category such as family, genus, and species for comprehensive identification.<br><br>\n\n    <strong>Types of Taxonomic Keys:</strong><br>\n    • <strong>Dichotomous Indented Key:</strong> Provides choices with equal indentation under a single lead, showing natural subdivisions.<br>\n    • <strong>Bracketed Key:</strong> Pairs of contrasting statements are placed in adjacent numbered couplets with cross-references, providing swift, efficient diagnostic identification.<br><br>\n\n    <strong>Practical Utility in Taxonomy:</strong><br>\n    • Enables rapid, accurate identification of newly collected specimens without requiring exhaustive reference literature.<br>\n    • Synthesizes complex biological diagnostic information into a structured, step-by-step decision tree.<br>\n    • Forms the foundation of botanical and zoological floras, monographs, and diagnostic field guides.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of a taxonomic key as an analytical tool based on contrasting characters</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of couplet, lead, and dichotomous choice mechanism</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of separate keys for taxonomic ranks and importance in floras/monographs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <a href=\"../ncert-solutions-class-11-biology.html\" class=\"ch-nav-btn prev\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; text-decoration:none; color:#334155;\">← Class 11 Biology Hub</a>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Chapter 2 (Biological Classification) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c11b-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 2</div>\n      <h2>Biological Classification</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5\"/></svg>\n      Whittaker's Five Kingdom Classification &amp; Viral Architecture\n    </div>\n    <svg viewBox=\"0 0 850 260\" width=\"100%\" height=\"auto\" style=\"max-height:260px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <!-- Five Kingdom Overview -->\n      <rect x=\"10\" y=\"10\" width=\"480\" height=\"240\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"250\" y=\"32\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">R.H. WHITTAKER'S FIVE KINGDOM SCHEME (1969)</text>\n      \n      <!-- Monera -->\n      <rect x=\"25\" y=\"48\" width=\"80\" height=\"85\" rx=\"6\" fill=\"#fef2f2\" stroke=\"#f87171\"/>\n      <text x=\"65\" y=\"68\" font-size=\"10\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">MONERA</text>\n      <text x=\"65\" y=\"86\" font-size=\"7.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">Prokaryotic</text>\n      <text x=\"65\" y=\"100\" font-size=\"7.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">Unicellular</text>\n      <text x=\"65\" y=\"114\" font-size=\"7.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">Bacteria</text>\n\n      <!-- Protista -->\n      <rect x=\"115\" y=\"48\" width=\"80\" height=\"85\" rx=\"6\" fill=\"#fffbeb\" stroke=\"#fcd34d\"/>\n      <text x=\"155\" y=\"68\" font-size=\"10\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">PROTISTA</text>\n      <text x=\"155\" y=\"86\" font-size=\"7.5\" fill=\"#78350f\" text-anchor=\"middle\">Eukaryotic</text>\n      <text x=\"155\" y=\"100\" font-size=\"7.5\" fill=\"#78350f\" text-anchor=\"middle\">Unicellular</text>\n      <text x=\"155\" y=\"114\" font-size=\"7.5\" fill=\"#78350f\" text-anchor=\"middle\">Amoeba/Algae</text>\n\n      <!-- Fungi -->\n      <rect x=\"205\" y=\"48\" width=\"80\" height=\"85\" rx=\"6\" fill=\"#f5f3ff\" stroke=\"#c4b5fd\"/>\n      <text x=\"245\" y=\"68\" font-size=\"10\" font-weight=\"bold\" fill=\"#5b21b6\" text-anchor=\"middle\">FUNGI</text>\n      <text x=\"245\" y=\"86\" font-size=\"7.5\" fill=\"#4c1d95\" text-anchor=\"middle\">Eukaryotic</text>\n      <text x=\"245\" y=\"100\" font-size=\"7.5\" fill=\"#4c1d95\" text-anchor=\"middle\">Chitin Wall</text>\n      <text x=\"245\" y=\"114\" font-size=\"7.5\" fill=\"#4c1d95\" text-anchor=\"middle\">Heterotrophic</text>\n\n      <!-- Plantae -->\n      <rect x=\"295\" y=\"48\" width=\"85\" height=\"85\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#6ee7b7\"/>\n      <text x=\"337\" y=\"68\" font-size=\"10\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">PLANTAE</text>\n      <text x=\"337\" y=\"86\" font-size=\"7.5\" fill=\"#064e3b\" text-anchor=\"middle\">Eukaryotic</text>\n      <text x=\"337\" y=\"100\" font-size=\"7.5\" fill=\"#064e3b\" text-anchor=\"middle\">Cellulose Wall</text>\n      <text x=\"337\" y=\"114\" font-size=\"7.5\" fill=\"#064e3b\" text-anchor=\"middle\">Autotrophic</text>\n\n      <!-- Animalia -->\n      <rect x=\"390\" y=\"48\" width=\"88\" height=\"85\" rx=\"6\" fill=\"#eff6ff\" stroke=\"#93c5fd\"/>\n      <text x=\"434\" y=\"68\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">ANIMALIA</text>\n      <text x=\"434\" y=\"86\" font-size=\"7.5\" fill=\"#1e3a8a\" text-anchor=\"middle\">Eukaryotic</text>\n      <text x=\"434\" y=\"100\" font-size=\"7.5\" fill=\"#1e3a8a\" text-anchor=\"middle\">No Cell Wall</text>\n      <text x=\"434\" y=\"114\" font-size=\"7.5\" fill=\"#1e3a8a\" text-anchor=\"middle\">Holozoic</text>\n\n      <!-- Five Criteria Banner -->\n      <rect x=\"25\" y=\"148\" width=\"453\" height=\"88\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n      <text x=\"35\" y=\"166\" font-size=\"9\" font-weight=\"bold\" fill=\"#334155\">Primary Criteria Used by R.H. Whittaker:</text>\n      <text x=\"35\" y=\"184\" font-size=\"8.5\" fill=\"#475569\">1. <strong>Cell Complexity:</strong> Prokaryotic vs. Eukaryotic organization</text>\n      <text x=\"35\" y=\"198\" font-size=\"8.5\" fill=\"#475569\">2. <strong>Body Complexity:</strong> Unicellular vs. Multicellular / Tissue level</text>\n      <text x=\"35\" y=\"212\" font-size=\"8.5\" fill=\"#475569\">3. <strong>Mode of Nutrition:</strong> Phototrophic vs. Absorptive (Saprotrophic) vs. Ingestive (Holozoic)</text>\n      <text x=\"35\" y=\"226\" font-size=\"8.5\" fill=\"#475569\">4. <strong>Reproduction &amp; Phylogeny:</strong> Evolutionary relationships &amp; lineage descent</text>\n\n      <!-- Bacteriophage Diagram on Right -->\n      <rect x=\"510\" y=\"10\" width=\"330\" height=\"240\" rx=\"10\" fill=\"#ffffff\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"675\" y=\"32\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">T4 BACTERIOPHAGE STRUCTURE</text>\n      \n      <!-- Head / Capsid -->\n      <polygon points=\"675,45 710,65 710,105 675,125 640,105 640,65\" fill=\"#dbeafe\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n      <text x=\"675\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Icosahedral</text>\n      <text x=\"675\" y=\"97\" font-size=\"7.5\" fill=\"#1e40af\" text-anchor=\"middle\">Head (dsDNA)</text>\n\n      <!-- Collar & Sheath -->\n      <rect x=\"668\" y=\"125\" width=\"14\" height=\"12\" fill=\"#64748b\"/>\n      <rect x=\"669\" y=\"137\" width=\"12\" height=\"55\" fill=\"#cbd5e1\" stroke=\"#475569\" stroke-width=\"1\"/>\n      <!-- Baseplate & Tail Fibers -->\n      <polygon points=\"660,192 690,192 685,200 665,200\" fill=\"#334155\"/>\n      <!-- Tail fibers -->\n      <path d=\"M 665,198 L 640,215 L 630,235\" stroke=\"#1e293b\" stroke-width=\"1.5\" fill=\"none\"/>\n      <path d=\"M 670,198 L 655,220 L 648,238\" stroke=\"#1e293b\" stroke-width=\"1.5\" fill=\"none\"/>\n      <path d=\"M 680,198 L 695,220 L 702,238\" stroke=\"#1e293b\" stroke-width=\"1.5\" fill=\"none\"/>\n      <path d=\"M 685,198 L 710,215 L 720,235\" stroke=\"#1e293b\" stroke-width=\"1.5\" fill=\"none\"/>\n\n      <!-- Annotations -->\n      <text x=\"730\" y=\"80\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\">← Capsid (Protein Coat)</text>\n      <text x=\"730\" y=\"92\" font-size=\"7\" fill=\"#64748b\">Capsomeres protect viral genome</text>\n      <text x=\"730\" y=\"145\" font-size=\"8\" font-weight=\"bold\" fill=\"#334155\">← Contractile Sheath</text>\n      <text x=\"730\" y=\"198\" font-size=\"8\" font-weight=\"bold\" fill=\"#334155\">← Tail Fibres (Host Adsorption)</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 12: Five Kingdom Scheme, Monera, Archaebacteria, Protista, Fungi, Viruses, Viroids & Lichens</div>\n\n  <!-- c11b-ch2-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Discuss how classification systems have undergone several changes over a period of time.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Chronological Evolution of Classification Systems:</strong><br>\n    Over centuries, biological classification has evolved progressively from simplistic utilitarian schemes to phylogenetically grounded molecular frameworks:<br><br>\n    <strong>1. Two-Kingdom Classification (Carolus Linnaeus):</strong><br>\n    Linnaeus grouped all known organisms into two kingdoms: <strong>Plantae</strong> and <strong>Animalia</strong>. While simple, it suffered from severe limitations:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li>It did not distinguish between eukaryotes and prokaryotes (bacteria and cyanobacteria were placed under Plantae).</li>\n      <li>It grouped unicellular organisms (e.g., <em>Chlamydomonas</em>, <em>Amoeba</em>) with complex multicellular organisms (e.g., spirogyra, metazoans).</li>\n      <li>It failed to separate photosynthetic organisms (green plants) from heterotrophic, absorptive non-photosynthetic organisms (fungi).</li>\n    </ul>\n    <strong>2. Three-Kingdom Classification (Ernst Haeckel, 1866):</strong><br>\n    Haeckel separated unicellular microscopic organisms lacking tissue differentiation into Kingdom <strong>Protista</strong>, leaving multicellular plants in Plantae and multicellular animals in Animalia.<br><br>\n    <strong>3. Four-Kingdom Classification (Herbert Copeland, 1956):</strong><br>\n    Copeland created Kingdom <strong>Monera</strong> to house all prokaryotic organisms (lacking nuclear membranes and membrane-bound organelles), distinguishing them from eukaryotic Protista.<br><br>\n    <strong>4. Five-Kingdom Classification (R.H. Whittaker, 1969):</strong><br>\n    Whittaker resolved the ambiguity of fungi by creating Kingdom <strong>Fungi</strong> based on chitinous cell walls and saprotrophic absorptive nutrition. His five criteria were: (i) Cell structure (prokaryotic vs. eukaryotic), (ii) Thallus / body organisation, (iii) Mode of nutrition, (iv) Reproduction, and (v) Phylogenetic relationships.<br><br>\n    <strong>5. Three-Domain System (Carl Woese, 1990):</strong><br>\n    Divided Monera into two distinct domains: <strong>Archaea</strong> and <strong>Bacteria</strong>, based on 16S rRNA gene sequencing and unique cell membrane lipid architecture, placing all eukaryotes in Domain <strong>Eukarya</strong>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Linnaeus 2-kingdom system & its three major defects</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contribution of Haeckel (Protista) and Copeland (Monera)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed account of Whittaker’s 5-Kingdom system & 5 classification criteria</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reference to Woese’s 3-Domain system based on 16S rRNA</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State two economically important uses of: (a) heterotrophic bacteria (b) archaebacteria.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Two Economically Important Uses of Heterotrophic Bacteria:</strong><br>\n    Heterotrophic bacteria are the most abundant decomposers in nature and have extensive industrial and agricultural utility:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Dairy &amp; Fermentation Industry:</strong> <em>Lactobacillus</em> (Lactic Acid Bacteria / LAB) ferment lactose into lactic acid, causing curdling of milk to form curd, yoghurt, and cheese.</li>\n      <li><strong>Production of Antibiotics &amp; Nitrogen Fixation:</strong> Species of <em>Streptomyces</em> synthesize vital clinical antibiotics (e.g., streptomycin, tetracycline), while symbiotic bacteria like <em>Rhizobium leguminosarum</em> fix atmospheric nitrogen in legume root nodules, enriching soil fertility.</li>\n    </ul>\n    <strong>(b) Two Economically Important Uses of Archaebacteria:</strong><br>\n    Archaebacteria thrive under extreme environmental niches due to their unique branched branched-chain ether-linked pseudomurein walls:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Biogas (Methane) Production:</strong> <em>Methanogens</em> (e.g., <em>Methanobacterium</em>) present in the anaerobic rumen of ruminant animals (cows, buffaloes) ferment cellulosic plant matter, generating biogas (methane) from animal dung (gobar gas plants).</li>\n      <li><strong>Thermostable Enzymes in Biotechnology:</strong> <em>Thermus aquaticus</em> (a thermophilic bacterium closely allied with extreme conditions) provides <strong>Taq DNA polymerase</strong>, an enzyme capable of retaining catalytic fidelity at 95&deg;C during automated Polymerase Chain Reaction (PCR) DNA amplification.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Two valid commercial/ecological uses of heterotrophic bacteria (curd/antibiotics/N2 fixation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two valid uses of archaebacteria (methane/biogas generation from dung + Taq polymerase / biotechnology)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the nature of cell-walls in diatoms?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Distinctive Nature and Structural Composition of Diatom Cell Walls:</strong><br>\n    Diatoms (Chrysophytes) possess a uniquely engineered cell wall structure known as a <strong>frustule</strong>:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Two Overlapping Halves (Soap-Box Architecture):</strong> The cell wall forms two thin, overlapping shells that fit tightly together like the lid and base of a soapbox. The upper outer valve is termed the <strong>epitheca</strong>, and the smaller lower valve is termed the <strong>hypotheca</strong>.</li>\n      <li><strong>Silica Impregnation (Indestructible Nature):</strong> The walls are heavily embedded with hydrated amorphous silica ($SiO_2 \\cdot nH_2O$). Because silica is chemically inert and highly resistant to acids and enzymatic degradation, diatom cell walls are virtually indestructible.</li>\n      <li><strong>Formation of Diatomaceous Earth (Kieselguhr):</strong> When diatoms die, their organic protoplasm decomposes, but their siliceous frustules deposit on ocean beds over millions of years, forming enormous geologic deposits called <strong>diatomaceous earth</strong>.</li>\n      <li><strong>Economic Applications:</strong> Being gritty and porous, diatomaceous earth is extensively utilized in filtration of oils, syrups, and antibiotic broths, polishing metals, and manufacturing sound-proof heat insulators.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Description of overlapping valves (epitheca and hypotheca) fitting like a soapbox</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Impregnation with silica and indestructible nature of frustules</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of diatomaceous earth and industrial uses (filtration and polishing)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Find out what do the terms 'algal bloom' and 'red-tides' signify.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Algal Bloom:</strong><br>\n    An <strong>algal bloom</strong> is the rapid, explosive proliferation and excessive accumulation of microscopic phytoplankton—predominantly cyanobacteria (blue-green algae like <em>Microcystis</em>, <em>Anabaena</em>, <em>Oscillatoria</em>) and green algae—in nutrient-enriched water bodies (eutrophic lakes and slow-moving rivers).\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Cause:</strong> High concentration of agricultural runoff containing nitrates and phosphates (cultural eutrophication).</li>\n      <li><strong>Consequences:</strong> The dense layer of algae blocks sunlight penetration, depleting dissolved oxygen (DO) as dead algae are decomposed by aerobic bacteria, leading to massive fish mortality and production of noxious toxins (cyanotoxins).</li>\n    </ul>\n    <strong>2. Red Tides:</strong><br>\n    <strong>Red tides</strong> refer to a specific marine phenomenon where coastal ocean waters appear reddish, brown, or pink due to the explosive multiplication and bloom of red-pigmented <strong>dinoflagellates</strong> (such as <em>Gonyaulax polyedra</em> and <em>Gymnodinium</em>).\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Toxin Secretion (Saxitoxin):</strong> These blooming dinoflagellates release potent neurotoxins, notably <strong>saxitoxin</strong>, into the water column.</li>\n      <li><strong>Biological Hazard:</strong> The toxin accumulates in filter-feeding shellfish (clams, oysters, mussels). While harmless to the molluscs, consumption of contaminated shellfish by marine mammals, birds, or humans causes severe, often lethal <strong>Paralytic Shellfish Poisoning (PSP)</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of algal bloom, nutrient enrichment (eutrophication), and oxygen depletion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of red tides, mention of Gonyaulax (dinoflagellates), and saxitoxin impact on marine life/humans</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How are viroids different from viruses?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comparative Differences Between Viroids and Viruses:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Viroids (Discovered by T.O. Diener, 1971)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Viruses (Ivanowsky, Beijerinck, Stanley)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Protein Coat (Capsid)</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\">Completely absent (consist of naked RNA).</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\">Present (genetic material is enclosed within a protein coat called capsid made of capsomeres).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Genetic Material</td>\n            <td style=\"padding:8px 12px;\">Only single-stranded RNA (ssRNA).</td>\n            <td style=\"padding:8px 12px;\">Either DNA or RNA (single-stranded or double-stranded), never both.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Molecular Weight</td>\n            <td style=\"padding:8px 12px;\">RNA has very <strong>low molecular weight</strong>.</td>\n            <td style=\"padding:8px 12px;\">Nucleic acid has relatively <strong>high molecular weight</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Size</td>\n            <td style=\"padding:8px 12px;\">Much smaller than viruses (sub-viral infectious agents).</td>\n            <td style=\"padding:8px 12px;\">Larger than viroids (ranging from 20 to 300 nm).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">5. Host Specificity &amp; Examples</td>\n            <td style=\"padding:8px 12px;\">Exclusively infect higher plants (e.g., Potato Spindle Tuber Viroid - PSTVd).</td>\n            <td style=\"padding:8px 12px;\">Infect plants, animals, fungi, and bacteria (e.g., TMV, Influenza, HIV, Bacteriophages).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Absence of protein coat / capsid in viroids vs. presence in viruses</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nature of genetic material (only ssRNA of low MW in viroids vs. DNA/RNA in viruses)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Size comparison and representative examples (PSTVd vs. TMV/HIV)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe briefly the four major groups of Protozoa.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The Four Major Morphological &amp; Locomotory Groups of Protozoa:</strong><br>\n    Protozoans are unicellular, heterotrophic, eukaryotic microorganisms belonging to Kingdom Protista. They are classified into four groups based on their locomotory organelles:<br><br>\n    <strong>1. Amoeboid Protozoans:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Habitat &amp; Locomotion:</strong> Inhabit freshwater, seawater, or moist soil. Move and capture prey by extending false feet called <strong>pseudopodia</strong> (blunt cytoplasmic projections), e.g., <em>Amoeba</em>.</li>\n      <li><strong>Special Features:</strong> Marine forms possess silica shells on their surface. Parasitic forms like <em>Entamoeba histolytica</em> cause amoebic dysentery in humans.</li>\n    </ul>\n    <strong>2. Flagellated Protozoans:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Locomotion &amp; Lifestyle:</strong> Possess one or more whip-like <strong>flagella</strong> for active swimming. They are either free-living or endoparasitic.</li>\n      <li><strong>Pathogenic Example:</strong> <em>Trypanosoma gambiense</em> is transmitted by the tsetse fly (<em>Glossina</em>) and causes fatal Human African Trypanosomiasis (<strong>sleeping sickness</strong>).</li>\n    </ul>\n    <strong>3. Ciliated Protozoans:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Locomotion &amp; Ingestion:</strong> Aquatic, actively moving organisms possessing thousands of coordinated hair-like <strong>cilia</strong> beating rhythmically in metachronal waves, e.g., <em>Paramoecium</em>.</li>\n      <li><strong>Anatomical Specialisation:</strong> Feature an oral cavity (<strong>gullet</strong>) opening to the outside. The coordinated movement of cilia steers water laden with food particles directly into the gullet. Possess nuclear dualism (macronucleus and micronucleus).</li>\n    </ul>\n    <strong>4. Sporozoans:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Characteristics:</strong> Endoparasitic protozoans lacking specialized locomotory organelles (cilia, flagella, or pseudopodia). Characterized by having an infectious spore-like stage in their life cycle.</li>\n      <li><strong>Pathogenic Example:</strong> <em>Plasmodium vivax</em> and <em>Plasmodium falciparum</em>, the causative agents of <strong>malaria</strong>, which cycles between female <em>Anopheles</em> mosquitoes and human hosts.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Amoeboid protozoans: pseudopodia, silica shells, Amoeba/Entamoeba</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Flagellated protozoans: flagella, Trypanosoma (sleeping sickness)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ciliated protozoans: thousands of cilia, gullet, Paramoecium</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sporozoans: lack locomotory organs, infectious spore phase, Plasmodium (malaria)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Plants are autotrophic. Can you think of some plants that are partially heterotrophic?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Partially Heterotrophic Plants in Kingdom Plantae:</strong><br>\n    While the vast majority of angiosperms are photoautotrophic (possessing chlorophyll $a$ and $b$ to synthesize sugars via photosynthesis), certain specialized plants are <strong>partially heterotrophic</strong> because they supplement their nitrogen and mineral requirements by consuming insects or parasitizing other plants:<br><br>\n    <strong>1. Insectivorous (Carnivorous) Plants:</strong><br>\n    These plants grow in waterlogged, acidic bogs and nitrate-deficient soils. They have functional green leaves and carry out photosynthesis to produce carbohydrates, but trap and digest small insects to acquire vital nitrogenous compounds (amino acids):\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Pitcher Plant (<em>Nepenthes</em>):</strong> The leaf lamina is modified into a tubular pitcher filled with digestive enzymes and closed by a lid. Insects falling into the pitcher slip on waxy walls and are digested.</li>\n      <li><strong>Venus Flytrap (<em>Dionaea muscipula</em>):</strong> Leaf blades are modified into two sensitive hinged lobes with trigger hairs that snap shut within milliseconds when stimulated by an insect.</li>\n      <li><strong>Bladderwort (<em>Utricularia</em>):</strong> Aquatic plant with tiny segmented leaf-bladders operating under negative hydrostatic pressure to suck in aquatic micro-invertebrates.</li>\n      <li><strong>Sundew (<em>Drosera</em>):</strong> Leaves bear glandular tentacles secreting glistening, sticky mucilage containing proteolytic enzymes.</li>\n    </ul>\n    <strong>2. Parasitic Plants:</strong><br>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Total Stem Parasite (<em>Cuscuta</em> / Dodder / Amarbel):</strong> Lacks chlorophyll and functional roots; twines around host branches and sends adventitious roots called <strong>haustoria</strong> directly into host xylem and phloem to extract water, minerals, and readymade sugars.</li>\n      <li><strong>Partial Parasites (e.g., <em>Viscum</em> / Mistletoe):</strong> Possess green leaves to photosynthesize, but embed haustoria into host xylem to absorb water and inorganic minerals.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of why insectivorous plants trap insects (nitrogen-deficient habitats)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two examples of insectivorous plants (Nepenthes, Dionaea, Utricularia) and leaf modifications</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of parasitic plants (Cuscuta) and haustorial absorption mechanism</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What do the terms phycobiont and mycobiont signify?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Significance of Phycobiont and Mycobiont in Lichen Symbiosis:</strong><br>\n    Lichens represent a classic, obligate, mutualistic symbiotic partnership between an autotrophic algal component and a heterotrophic fungal component:<br><br>\n    <strong>1. Phycobiont (Photobiont):</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Definition:</strong> The photosynthetic, algal or cyanobacterial partner in the lichen thallus (typically green algae like <em>Trebouxia</em> or blue-green algae like <em>Nostoc</em>).</li>\n      <li><strong>Function &amp; Significance:</strong> Synthesizes organic carbohydrates through photosynthesis and supplies readymade nourishment to the fungal partner. When cyanobacteria are present, they also actively fix atmospheric nitrogen.</li>\n    </ul>\n    <strong>2. Mycobiont:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Definition:</strong> The non-photosynthetic fungal partner in the lichen thallus (predominantly Ascomycetes and rarely Basidiomycetes).</li>\n      <li><strong>Function &amp; Significance:</strong> Forms the structural body (thallus) that encloses and protects the delicate algal cells from desiccation, mechanical injury, and intense solar radiation. Its dense hyphal network anchors the lichen to substrates (rocks, bark) via rhizines and absorbs water and mineral nutrients from the atmosphere and substrate, channeling them to the phycobiont.</li>\n    </ul>\n    <strong>Key Ecological Note:</strong> Neither partner can survive independently in extreme alpine, arctic, or desert environments. Lichens are also highly sensitive bio-indicators of atmospheric sulfur dioxide ($SO_2$) pollution (\"pollution indicators\").\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and precise autotrophic nutritional role of phycobiont (algal partner)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition and structural/absorptive/protective role of mycobiont (fungal partner)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give a comparative account of the classes of Kingdom Fungi under the following: (i) mode of nutrition (ii) mode of reproduction.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comparative Analysis of the Four Classes of Kingdom Fungi:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 10px; color:#065f46;\">Class &amp; Common Name</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Mycelium Type</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">(i) Mode of Nutrition</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">(ii) Mode of Reproduction (Asexual &amp; Sexual)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">1. Phycomycetes<br><span style=\"font-weight:normal; font-size:0.75rem; color:#64748b;\">(Algal Fungi)</span></td>\n            <td style=\"padding:8px 10px;\">Aseptate and <strong>coenocytic</strong> (multinucleate).</td>\n            <td style=\"padding:8px 10px;\">Obligate parasites on plants, saprotrophs on decaying wood or in aquatic moist habitats.</td>\n            <td style=\"padding:8px 10px;\"><strong>Asexual:</strong> Zoospores (motile) or aplanospores (non-motile) formed endogenously in sporangia.<br><strong>Sexual:</strong> Zygospore formed by isogamous or oogamous fusion of gametes. (e.g., <em>Mucor</em>, <em>Rhizopus</em>, <em>Albugo</em>).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">2. Ascomycetes<br><span style=\"font-weight:normal; font-size:0.75rem; color:#64748b;\">(Sac Fungi)</span></td>\n            <td style=\"padding:8px 10px;\">Branched and <strong>septate</strong>.</td>\n            <td style=\"padding:8px 10px;\">Saprotrophic, decomposers, parasitic, or <strong>coprophilous</strong> (growing on dung).</td>\n            <td style=\"padding:8px 10px;\"><strong>Asexual:</strong> Conidia produced exogenously on special hyphae called conidiophores.<br><strong>Sexual:</strong> Ascospores produced endogenously in sac-like asci arranged in fruiting bodies called ascocarps. (e.g., <em>Penicillium</em>, <em>Aspergillus</em>, <em>Neurospora</em>).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">3. Basidiomycetes<br><span style=\"font-weight:normal; font-size:0.75rem; color:#64748b;\">(Club Fungi)</span></td>\n            <td style=\"padding:8px 10px;\">Branched and <strong>septate</strong> (with clamp connections).</td>\n            <td style=\"padding:8px 10px;\">Saprotrophic on soil, logs, and tree stumps, or internal parasites causing rusts and smuts.</td>\n            <td style=\"padding:8px 10px;\"><strong>Asexual:</strong> Asexual spores generally not found; vegetative fragmentation common.<br><strong>Sexual:</strong> Sex organs absent; somatogamy occurs. Basidiospores produced exogenously on a basidium inside basidiocarps. (e.g., <em>Agaricus</em>, <em>Ustilago</em>, <em>Puccinia</em>).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px; font-weight:700;\">4. Deuteromycetes<br><span style=\"font-weight:normal; font-size:0.75rem; color:#64748b;\">(Fungi Imperfecti)</span></td>\n            <td style=\"padding:8px 10px;\">Branched and <strong>septate</strong>.</td>\n            <td style=\"padding:8px 10px;\">Largely saprophytes or parasites; many are crucial decomposers of leaf litter helping mineral cycling.</td>\n            <td style=\"padding:8px 10px;\"><strong>Asexual:</strong> Reproduce exclusively by asexual conidia.<br><strong>Sexual:</strong> <em>Sexual (perfect) stage is completely unknown or absent</em>. If discovered, moved to Ascomycetes or Basidiomycetes. (e.g., <em>Alternaria</em>, <em>Colletotrichum</em>, <em>Trichoderma</em>).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Phycomycetes: coenocytic mycelium, nutrition (parasitic/saprophytic), zoospores & zygospores</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ascomycetes: septate, coprophilous/saprophytic, exogenous conidia & endogenous ascospores</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Basidiomycetes: septate, somatogamy, exogenous basidiospores on basidium</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Deuteromycetes: imperfect fungi, conidia reproduction, absence of sexual stage</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the characteristic features of Euglenoids?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Key Characteristic Features of Euglenoids:</strong><br>\n    Euglenoids (e.g., <em>Euglena viridis</em>) are distinctive unicellular, flagellated protists primarily found in stagnant freshwater bodies:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Absence of Cell Wall (Pellicle):</strong> Instead of a cellulosic cell wall, their body is bounded by a protein-rich flexible membrane layer called the <strong>pellicle</strong>, which permits active changes in cell shape (metaboly or euglenoid movement).</li>\n      <li><strong>Heterokont Flagella:</strong> They bear two unequal flagella inserted in an anterior invagination (reservoir): one long, active, locomotory flagellum extending outward, and one short, non-emergent flagellum.</li>\n      <li><strong>Mixotrophic Nutrition:</strong> They exhibit a remarkable dual mode of nutrition:\n        <ul style=\"margin:4px 0 6px 20px;\">\n          <li>In the presence of sunlight, they are <strong>photoautotrophic</strong>, possessing chlorophyll $a$ and $b$ identical to those in higher plants.</li>\n          <li>When deprived of sunlight in dark or nutrient-rich waters, they become <strong>heterotrophic predators</strong>, capturing and ingesting smaller organisms (saprotrophic / phagotrophic).</li>\n        </ul>\n      </li>\n      <li><strong>Photosensitive Stigma (Eye-Spot):</strong> An orange-red pigmented carotenoid eye-spot (stigma) located near the reservoir detects light intensity and directs phototactic movement toward optimal light.</li>\n      <li><strong>Reserve Food:</strong> Store carbohydrates in the form of unique $\\beta$-1,3-glucan granules called <strong>paramylon</strong> (paramylum).</li>\n      <li><strong>Osmoregulation:</strong> Possess an anterior contractile vacuole to expel excess water entering hypotonic freshwater environments.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Proteinaceous pellicle replacing cell wall and providing body flexibility</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of two unequal flagella (one long, one short) & photoreceptive eye-spot</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mixotrophic nutrition (autotrophic in sunlight, heterotrophic in dark) with plant-like pigments</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Paramylon reserve food and contractile vacuole osmoregulation</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give a brief account of viruses with respect to their structure and nature of genetic material. Also name four common viral diseases.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Account of Viral Structure and Genetic Material:</strong><br>\n    Viruses are non-cellular, sub-microscopic, obligate intracellular parasites that remain inert crystalline nucleoprotein structures outside living host cells:<br><br>\n    <strong>1. Structural Organization:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Core Genome (Nucleic Acid):</strong> Located internally, containing the infectious genetic blueprint. A single virus contains <em>either DNA or RNA</em>, never both simultaneously.</li>\n      <li><strong>Protein Coat (Capsid):</strong> The protective shell surrounding the nucleic acid, composed of small repeating protein subunits called <strong>capsomeres</strong>. Capsomeres are arranged geometrically in helical (e.g., Tobacco Mosaic Virus) or polyhedral / icosahedral forms (e.g., Adenovirus, Poliovirus).</li>\n      <li><strong>Viral Envelope:</strong> Some animal viruses (e.g., Influenza, HIV, SARS-CoV-2) possess an outer lipid-bilayer envelope derived from host membranes, studded with viral glycoproteins (spikes) facilitating host attachment.</li>\n    </ul>\n    <strong>2. Nature of Viral Genetic Material:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Plant Viruses:</strong> Generally possess single-stranded RNA (ssRNA), e.g., Tobacco Mosaic Virus (TMV).</li>\n      <li><strong>Bacteriophages (Bacterial Viruses):</strong> Usually possess double-stranded DNA (dsDNA), e.g., T4 bacteriophage.</li>\n      <li><strong>Animal Viruses:</strong> May possess single-stranded RNA (ssRNA - Influenza, Rabies, Polio, Retroviruses like HIV), double-stranded RNA (dsRNA - Reovirus), or double-stranded DNA (dsDNA - Poxvirus, Herpesvirus, Hepatitis B).</li>\n    </ul>\n    <strong>3. Four Common Viral Diseases:</strong><br>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>In Humans:</strong> (i) <em>Influenza</em> (Flu), (ii) <em>AIDS</em> (Acquired Immuno Deficiency Syndrome caused by HIV), (iii) <em>Smallpox / Chickenpox</em>, (iv) <em>Poliomyelitis</em> (Polio), (v) <em>Rabies</em>.</li>\n      <li><strong>In Plants:</strong> Tobacco mosaic disease, Cucumber mosaic, Leaf curling and yellow vein mosaic in <em>Bhindi</em>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Structure: Capsid made of capsomeres (helical/polyhedral) protecting internal genetic core</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Genome nature: DNA or RNA (never both); ssRNA in plant viruses, dsDNA in bacteriophages, diverse in animals</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Naming four common viral diseases in humans or plants</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch2-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch2-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch2-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Organise a discussion in your class on the topic - Are viruses living or non-living?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Debate: Are Viruses Living or Non-Living Entities?</strong><br>\n    Biologists describe viruses as entities existing at the <em>\"threshold of life\"</em> or biological twilight zone, because they exhibit a dual personality:<br><br>\n    <strong>A. Arguments and Characteristics Supporting that Viruses are Non-Living:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Lack of Cellular Organization:</strong> They are non-cellular (acellular); they have no cytoplasm, cell organelles (mitochondria, ribosomes, ER), or cell membrane.</li>\n      <li><strong>Metabolic Inertia:</strong> Outside a host cell, they possess no metabolic activity, respiratory machinery, or autonomous enzyme systems for generating ATP.</li>\n      <li><strong>Crystallizability:</strong> Like non-living chemical minerals, purified virus particles can be crystallized and stored indefinitely in bottles without losing infectious potential (first demonstrated by W.M. Stanley in 1935 for TMV).</li>\n      <li><strong>No Independent Growth:</strong> They do not show independent growth or division outside host living cytoplasm.</li>\n    </ul>\n    <strong>B. Arguments and Characteristics Supporting that Viruses are Living:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Genetic Material:</strong> They possess definite genetic material (either DNA or RNA) that encodes specific viral structural and functional proteins.</li>\n      <li><strong>Replication &amp; Reproduction:</strong> Inside living host cells, they take over the host cell's metabolic machinery to replicate their genome and assemble thousands of viral progeny.</li>\n      <li><strong>Mutation &amp; Evolution:</strong> Their genetic material undergoes spontaneous mutations and genetic recombination, evolving rapidly to evade host immune defenses (e.g., antigen drift in Influenza and HIV).</li>\n      <li><strong>Infectivity &amp; Specificity:</strong> They exhibit strict host specificity and cause infectious, transmissible diseases in specific host organisms.</li>\n    </ul>\n    <strong>Scientific Conclusion:</strong><br>\n    Viruses are best classified as <strong>obligate intracellular molecular parasites</strong> representing a vital evolutionary link between complex non-living prebiotic macromolecular assemblies and cellular living organisms.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Listing non-living attributes: acellular, no metabolism/respiration, crystallizable</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing living attributes: genetic material (DNA/RNA), autonomous replication in host, mutation & evolution</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 1</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 3 (Plant Kingdom) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c11b-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 3</div>\n      <h2>Plant Kingdom</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 11 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg>\n      Plant Kingdom Classification &amp; Alternation of Generations\n    </div>\n    <svg viewBox=\"0 0 850 250\" width=\"100%\" height=\"auto\" style=\"max-height:250px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <!-- Plant Kingdom Taxonomy Map -->\n      <rect x=\"10\" y=\"10\" width=\"460\" height=\"230\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"240\" y=\"30\" font-size=\"11\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">KINGDOM PLANTAE (EMBRYOPHYTA &amp; THALLOPHYTA)</text>\n      \n      <!-- Thallophyta -->\n      <rect x=\"25\" y=\"45\" width=\"130\" height=\"85\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#10b981\"/>\n      <text x=\"90\" y=\"65\" font-size=\"10\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">ALGAE</text>\n      <text x=\"90\" y=\"80\" font-size=\"7.5\" fill=\"#047857\" text-anchor=\"middle\">&bull; Chlorophyceae (Green)</text>\n      <text x=\"90\" y=\"95\" font-size=\"7.5\" fill=\"#047857\" text-anchor=\"middle\">&bull; Phaeophyceae (Brown)</text>\n      <text x=\"90\" y=\"110\" font-size=\"7.5\" fill=\"#047857\" text-anchor=\"middle\">&bull; Rhodophyceae (Red)</text>\n      <text x=\"90\" y=\"123\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">Non-vascular &bull; Thalloid</text>\n\n      <!-- Bryophyta -->\n      <rect x=\"175\" y=\"45\" width=\"135\" height=\"85\" rx=\"6\" fill=\"#f0fdf4\" stroke=\"#4ade80\"/>\n      <text x=\"242\" y=\"65\" font-size=\"10\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">BRYOPHYTA</text>\n      <text x=\"242\" y=\"80\" font-size=\"7.5\" fill=\"#15803d\" text-anchor=\"middle\">&bull; Liverworts (Marchantia)</text>\n      <text x=\"242\" y=\"95\" font-size=\"7.5\" fill=\"#15803d\" text-anchor=\"middle\">&bull; Mosses (Funaria, Sphagnum)</text>\n      <text x=\"242\" y=\"110\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">\"Amphibians of Plant Kingdom\"</text>\n      <text x=\"242\" y=\"123\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">Dominant Gametophyte (n)</text>\n\n      <!-- Pteridophyta -->\n      <rect x=\"330\" y=\"45\" width=\"125\" height=\"85\" rx=\"6\" fill=\"#fefce8\" stroke=\"#facc15\"/>\n      <text x=\"392\" y=\"65\" font-size=\"10\" font-weight=\"bold\" fill=\"#854d0e\" text-anchor=\"middle\">PTERIDOPHYTA</text>\n      <text x=\"392\" y=\"80\" font-size=\"7.5\" fill=\"#713f12\" text-anchor=\"middle\">&bull; Ferns, Selaginella, Equisetum</text>\n      <text x=\"392\" y=\"95\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">First Vascular Plants (Xylem/Phloem)</text>\n      <text x=\"392\" y=\"110\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">Dominant Sporophyte (2n)</text>\n      <text x=\"392\" y=\"123\" font-size=\"7\" fill=\"#15803d\" text-anchor=\"middle\">Origin of Heterospory</text>\n\n      <!-- Spermatophyta (Seed Plants) -->\n      <rect x=\"25\" y=\"145\" width=\"430\" height=\"85\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n      <text x=\"240\" y=\"162\" font-size=\"10\" font-weight=\"bold\" fill=\"#334155\" text-anchor=\"middle\">SPERMATOPHYTA (SEED-BEARING TRACHEOPHYTES)</text>\n      \n      <rect x=\"40\" y=\"172\" width=\"190\" height=\"50\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n      <text x=\"135\" y=\"188\" font-size=\"9\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Gymnosperms (Naked Seeds)</text>\n      <text x=\"135\" y=\"202\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Ovules not enclosed in ovary &bull; Cycas, Pinus</text>\n      <text x=\"135\" y=\"214\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Cones, Tracheids, Anemophilous Pollination</text>\n\n      <rect x=\"250\" y=\"172\" width=\"190\" height=\"50\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n      <text x=\"345\" y=\"188\" font-size=\"9\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Angiosperms (Flowering Plants)</text>\n      <text x=\"345\" y=\"202\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Seeds enclosed inside fruit &bull; Monocots &amp; Dicots</text>\n      <text x=\"345\" y=\"214\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Double Fertilization &bull; Triple Fusion (PEN 3n)</text>\n\n      <!-- Alternation of Generations Graphic on Right -->\n      <rect x=\"490\" y=\"10\" width=\"350\" height=\"230\" rx=\"10\" fill=\"#ffffff\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"665\" y=\"30\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">HAPLO-DIPLONTIC LIFE CYCLE</text>\n\n      <!-- Sporophyte Circle -->\n      <circle cx=\"580\" cy=\"110\" r=\"45\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"580\" y=\"105\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Sporophyte</text>\n      <text x=\"580\" y=\"120\" font-size=\"11\" font-weight=\"bold\" fill=\"#047857\" text-anchor=\"middle\">(2n)</text>\n\n      <!-- Gametophyte Circle -->\n      <circle cx=\"750\" cy=\"110\" r=\"45\" fill=\"#eff6ff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <text x=\"750\" y=\"105\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Gametophyte</text>\n      <text x=\"750\" y=\"120\" font-size=\"11\" font-weight=\"bold\" fill=\"#1d4ed8\" text-anchor=\"middle\">(n)</text>\n\n      <!-- Arrows -->\n      <path d=\"M 625,95 Q 665,65 705,95\" stroke=\"#dc2626\" stroke-width=\"2\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n      <text x=\"665\" y=\"70\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">MEIOSIS (R!)</text>\n      <text x=\"665\" y=\"82\" font-size=\"7.5\" fill=\"#475569\" text-anchor=\"middle\">Spores (n)</text>\n\n      <path d=\"M 705,125 Q 665,155 625,125\" stroke=\"#16a34a\" stroke-width=\"2\" fill=\"none\"/>\n      <text x=\"665\" y=\"152\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#16a34a\" text-anchor=\"middle\">SYNGAMY (Fertilization)</text>\n      <text x=\"665\" y=\"164\" font-size=\"7.5\" fill=\"#475569\" text-anchor=\"middle\">Zygote (2n)</text>\n\n      <!-- Life cycle summary pill -->\n      <rect x=\"510\" y=\"185\" width=\"310\" height=\"42\" rx=\"6\" fill=\"#f8fafc\" stroke=\"#e2e8f0\"/>\n      <text x=\"520\" y=\"202\" font-size=\"8\" fill=\"#334155\">&bull; <strong>Bryophytes:</strong> Gametophyte (n) dominant &amp; free-living; Sporophyte dependent.</text>\n      <text x=\"520\" y=\"216\" font-size=\"8\" fill=\"#334155\">&bull; <strong>Pteridophytes:</strong> Sporophyte (2n) dominant &amp; vascular; Gametophyte small.</text>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 11: Algae, Bryophytes, Pteridophytes, Gymnosperms, Alternation of Generations & Life Cycles</div>\n\n  <!-- c11b-ch3-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the basis of classification of algae?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Basis of Classification of Algae into Three Major Classes:</strong><br>\n    Algae are classified into three primary classes—<strong>Chlorophyceae</strong> (green algae), <strong>Phaeophyceae</strong> (brown algae), and <strong>Rhodophyceae</strong> (red algae)—based primarily on the following fundamental criteria:<br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 10px; color:#065f46;\">Classification Criteria</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Chlorophyceae (Green)</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Phaeophyceae (Brown)</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Rhodophyceae (Red)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">1. Major Photosynthetic Pigments</td>\n            <td style=\"padding:8px 10px;\">Chlorophyll $a$, $b$</td>\n            <td style=\"padding:8px 10px;\">Chlorophyll $a$, $c$, and xanthophyll carotenoid <strong>fucoxanthin</strong></td>\n            <td style=\"padding:8px 10px;\">Chlorophyll $a$, $d$, and phycobiliprotein <strong>r-phycoerythrin</strong></td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">2. Stored Food Material</td>\n            <td style=\"padding:8px 10px;\">True <strong>Starch</strong> (stored in pyrenoids)</td>\n            <td style=\"padding:8px 10px;\">Complex carbohydrates: <strong>Laminarin</strong> or <strong>Mannitol</strong></td>\n            <td style=\"padding:8px 10px;\"><strong>Floridean Starch</strong> (structurally similar to amylopectin and glycogen)</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">3. Cell Wall Composition</td>\n            <td style=\"padding:8px 10px;\">Inner cellulose, outer pectose layer</td>\n            <td style=\"padding:8px 10px;\">Cellulose covered externally by a gelatinous coating of <strong>algin</strong></td>\n            <td style=\"padding:8px 10px;\">Cellulose, pectin, and sulfated phycocolloids (agar, carrageen)</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px; font-weight:700;\">4. Flagellar Number &amp; Position of Insertion</td>\n            <td style=\"padding:8px 10px;\">2–8, equal, apical</td>\n            <td style=\"padding:8px 10px;\">2, unequal, lateral</td>\n            <td style=\"padding:8px 10px; color:#dc2626; font-weight:700;\">Completely absent in all life stages</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Major photosynthetic pigments across Chlorophyceae, Phaeophyceae, Rhodophyceae</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nature of stored reserve food (starch vs. laminarin/mannitol vs. floridean starch)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cell wall chemical composition (cellulose, algin, phycocolloids)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Flagellar apparatus (equal apical vs. unequal lateral vs. completely absent)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        When and where does reduction division take place in the life cycle of a liverwort, a moss, a fern, a gymnosperm and an angiosperm?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Site and Timing of Reduction Division (Meiosis) Across Plant Groups:</strong><br><br>\n    <strong>1. Liverwort (e.g., <em>Marchantia</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Where:</strong> Inside the <strong>capsule</strong> of the diploid sporophyte.</li>\n      <li><strong>When:</strong> During <strong>sporogenesis</strong>, when diploid spore mother cells (SMCs) undergo meiosis to form haploid spores ($n$) which are dispersed with the help of hygroscopic elaters.</li>\n    </ul>\n    <strong>2. Moss (e.g., <em>Funaria</em>, <em>Polytrichum</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Where:</strong> Inside the spore sac within the <strong>capsule</strong> region of the sporophyte (surrounding the columella).</li>\n      <li><strong>When:</strong> During spore formation, spore mother cells undergo meiosis to yield haploid spores released via peristomial teeth.</li>\n    </ul>\n    <strong>3. Fern (e.g., <em>Dryopteris</em>, <em>Pteris</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Where:</strong> Inside the <strong>sporangia</strong> borne in clusters called <strong>sori</strong> on the ventral surface of fertile leaves (sporophylls).</li>\n      <li><strong>When:</strong> Diploid spore mother cells undergo meiosis to produce haploid spores, which germinate into the independent monoecious gametophyte (prothallus).</li>\n    </ul>\n    <strong>4. Gymnosperm (e.g., <em>Pinus</em>, <em>Cycas</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Where &amp; When:</strong> Occurs in two distinct sporangia:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Microsporangia (pollen sacs):</em> Diploid microspore mother cells undergo meiosis to form haploid microspores (pollen grains).</li>\n          <li><em>Megasporangia (nucellus of ovule):</em> A single diploid megaspore mother cell (MMC) undergoes meiosis to produce a linear tetrad of 4 haploid megaspores, of which 3 degenerate and 1 forms the functional female gametophyte with archegonia.</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>5. Angiosperm (Flowering Plants):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Where &amp; When:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Anther (Microsporangium):</em> Microspore mother cells (pollen mother cells / PMC) undergo meiosis to generate haploid microspores (pollen grains).</li>\n          <li><em>Ovule (Megasporangium):</em> Megaspore mother cell inside the nucellus undergoes meiosis to produce 4 haploid megaspores (one functional megaspore forms the 7-celled, 8-nucleate female embryo sac).</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Liverwort & Moss: capsule of sporophyte during spore mother cell meiosis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fern: inside sporangia/sori on sporophylls</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gymnosperm: microsporangia (pollen) & megasporangium/nucellus (megaspore)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Angiosperm: anther locules (PMC to pollen) & ovule nucellus (MMC to embryo sac)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name three groups of plants that bear archegonia. Briefly describe the life cycle of any one of them.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Three Groups of Plants Bearing Archegonia (Archegoniatae):</strong><br>\n    The female sex organ called the <strong>archegonium</strong> (flask-shaped multicellular organ consisting of a neck and a venter enclosing an egg cell) is present in:\n    <ol style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Bryophyta</strong> (Liverworts and Mosses)</li>\n      <li><strong>Pteridophyta</strong> (Ferns, Horsetails, Club mosses)</li>\n      <li><strong>Gymnosperms</strong> (Conifers, Cycads, Ginkgo)</li>\n    </ol>\n    <em>(Note: Archegonia are completely absent in Angiosperms, where they are replaced by the reduced embryo sac).</em><br><br>\n    <strong>Brief Life Cycle of Bryophyta (e.g., <em>Funaria</em> / Moss):</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Dominant Phase (Gametophyte - n):</strong> The conspicuous, free-living, independent phase is the haploid gametophyte consisting of leafy shoots anchored to soil by multicellular rhizoids.</li>\n      <li><strong>Sex Organs:</strong> Formed at the apices of leafy stems:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Male organ: <strong>Antheridium</strong> (club-shaped, producing biflagellated, motile antherozoids).</li>\n          <li>Female organ: <strong>Archegonium</strong> (flask-shaped, with neck canal cells and a venter containing a non-motile egg).</li>\n        </ul>\n      </li>\n      <li><strong>Fertilization (Zooidogamy):</strong> Water is essential for reproduction. Antherozoids swim through a thin film of water towards the chemotactic stimulus of the archegonium. Syngamy produces a diploid zygote ($2n$).</li>\n      <li><strong>Dependent Sporophyte Phase (2n):</strong> The zygote does not undergo immediate meiosis; it develops into a multicellular diploid sporophyte consisting of a <strong>foot, seta, and capsule</strong>, which remains permanently attached to and nutritionally dependent on the green gametophyte.</li>\n      <li><strong>Spore Dispersal &amp; Germination:</strong> Spore mother cells in the capsule undergo meiosis to form haploid spores. Spores germinate into a juvenile creeping, green, filamentous stage called the <strong>protonema</strong>, which later develops leafy gametophore buds.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct naming of 3 archegoniate groups (Bryophytes, Pteridophytes, Gymnosperms)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of dominant haploid gametophyte and water requirement for fertilization</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Description of dependent sporophyte (foot, seta, capsule) and meiotic spore formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of protonema stage in moss life cycle and alternation of generations</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Mention the ploidy of the following: protonemal cell of a moss; primary endosperm nucleus in dicot, leaf cell of a moss; prothallus cell of a fern; gemma cell in Marchantia; meristem cell of monocot, ovum of a liverwort, and zygote of a fern.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Exact Ploidy Levels of the Given Plant Cells:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Cell / Structure</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Ploidy Level</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Biological Justification</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Protonemal cell of a moss</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Haploid ($n$)</td>\n            <td style=\"padding:8px 12px;\">Directly develops from the mitotic germination of a meiotically produced haploid spore.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Primary Endosperm Nucleus (PEN) in dicot</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:800;\">Triploid ($3n$)</td>\n            <td style=\"padding:8px 12px;\">Result of triple fusion: 1 haploid male gamete ($n$) + 2 haploid polar nuclei ($n+n$).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Leaf cell of a moss</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Haploid ($n$)</td>\n            <td style=\"padding:8px 12px;\">Forms part of the main vegetative body of the gametophyte ($n$).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Prothallus cell of a fern</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Haploid ($n$)</td>\n            <td style=\"padding:8px 12px;\">The prothallus is the independent gametophytic phase grown from a haploid spore.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">5. Gemma cell in <em>Marchantia</em></td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Haploid ($n$)</td>\n            <td style=\"padding:8px 12px;\">Asexual vegetative propagule produced on the haploid gametophytic thallus.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">6. Meristem cell of monocot</td>\n            <td style=\"padding:8px 12px; color:#2563eb; font-weight:800;\">Diploid ($2n$)</td>\n            <td style=\"padding:8px 12px;\">Actively dividing somatic vegetative tissue of the dominant sporophyte ($2n$).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">7. Ovum (egg cell) of a liverwort</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Haploid ($n$)</td>\n            <td style=\"padding:8px 12px;\">Female gamete produced by mitosis inside the haploid archegonium.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">8. Zygote of a fern</td>\n            <td style=\"padding:8px 12px; color:#2563eb; font-weight:800;\">Diploid ($2n$)</td>\n            <td style=\"padding:8px 12px;\">Formed by syngamy (fusion) of haploid antherozoid ($n$) and haploid ovum ($n$).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Protonemal cell (n) and Primary endosperm nucleus (3n)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Leaf cell of moss (n) and Prothallus cell of fern (n)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gemma cell of Marchantia (n) and Meristem cell of monocot (2n)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ovum of liverwort (n) and Zygote of fern (2n)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write a note on economic importance of algae and gymnosperms.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>A. Economic Importance of Algae:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Carbon Fixation &amp; Oxygen Production:</strong> Algae carry out at least 50% of the total carbon dioxide fixation on Earth via photosynthesis, serving as fundamental primary producers in aquatic food chains.</li>\n      <li><strong>Direct Food Source:</strong> Over 70 species of marine algae are edible, notably <em>Porphyra</em> (Nori), <em>Laminaria</em> (Kombu), and <em>Sargassum</em>.</li>\n      <li><strong>Hydrocolloids (Phycocolloids):</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Agar-agar:</strong> Derived from red algae (<em>Gelidium</em> and <em>Gracilaria</em>); used worldwide to solidify bacteriological culture media and prepare jellies, ice creams, and desserts.</li>\n          <li><strong>Algin:</strong> Hydrocolloid extracted from brown algae (e.g., <em>Laminaria</em>, <em>Ascophyllum</em>); used as a stabilizer, thickener in foods, paints, and dental impressions.</li>\n          <li><strong>Carrageenan:</strong> Extracted from red alga <em>Chondrus crispus</em>; used as a clearing and emulsifying agent.</li>\n        </ul>\n      </li>\n      <li><strong>Single Cell Protein (SCP) &amp; Space Food:</strong> Unicellular green alga <em>Chlorella</em> and cyanobacterium <em>Spirulina</em> are exceptionally rich in proteins and vitamins, used as nutritional supplements and food for space travelers.</li>\n    </ul>\n    <strong>B. Economic Importance of Gymnosperms:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Timber and Softwood:</strong> Conifers such as <em>Pinus</em>, <em>Cedrus deodara</em>, <em>Picea</em> (Spruce), and <em>Abies</em> (Fir) yield premium softwood lumber for heavy construction, railway sleepers, furniture, and packing cases.</li>\n      <li><strong>Paper Pulp:</strong> Conifer wood fibers are extensively digested to manufacture high-grade paper, newsprint, and rayon.</li>\n      <li><strong>Resins &amp; Turpentine:</strong> <em>Pinus roxburghii</em> yields oleoresin, which is distilled to produce <strong>turpentine oil</strong> (used in paints and varnishes) and <strong>rosin</strong> (used in sealing wax, waterproofing, and violin bows).</li>\n      <li><strong>Medicinal Products:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Taxol:</strong> Highly potent anticancer drug extracted from the bark of <em>Taxus brevifolia</em> (Yew).</li>\n          <li><strong>Ephedrine:</strong> Alkaloid extracted from <em>Ephedra</em>, used in treating asthma and respiratory bronchial spasms.</li>\n        </ul>\n      </li>\n      <li><strong>Edible Seeds (Chilgoza):</strong> Seeds of <em>Pinus gerardiana</em> (Chilgoza) are rich in fats and eaten as roasted dry fruits.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Economic value of algae: carbon fixation, agar, algin/carrageen, edible seaweeds, Chlorella SCP</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Economic value of gymnosperms: timber/softwood, paper pulp, turpentine/resins, Taxol & Ephedrine, Chilgoza</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Both gymnosperms and angiosperms bear seeds, then why are they classified separately?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Rationale for Classifying Gymnosperms and Angiosperms Separately:</strong><br>\n    Although both Gymnosperms and Angiosperms belong to the overarching division <strong>Spermatophyta</strong> (seed-bearing plants), they diverge fundamentally in crucial morphological and reproductive features:<br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.85rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 10px; color:#065f46;\">Distinguishing Feature</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Gymnosperms (<em>gymnos</em> = naked; <em>sperma</em> = seed)</th>\n            <th style=\"padding:8px 10px; color:#065f46;\">Angiosperms (<em>angeion</em> = vessel; <em>sperma</em> = seed)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">1. Ovule &amp; Seed Enclosure</td>\n            <td style=\"padding:8px 10px; color:#dc2626; font-weight:700;\">Ovules are <strong>naked</strong>, borne directly exposed on megasporophyll surfaces before and after fertilization.</td>\n            <td style=\"padding:8px 10px; color:#16a34a; font-weight:700;\">Ovules are completely enclosed inside the protective cavity of an <strong>ovary</strong> (carpel).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">2. Fruit Formation</td>\n            <td style=\"padding:8px 10px;\">No ovary exists; hence, <strong>no true fruits</strong> are ever formed. Seeds remain naked on cone scales.</td>\n            <td style=\"padding:8px 10px;\">Post-fertilization, the ovary matures into a <strong>true fruit</strong> containing enclosed seeds.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">3. Reproductive Organs</td>\n            <td style=\"padding:8px 10px;\">Reproduce via distinct unisexual <strong>strobili or cones</strong> (microsporangiate and megasporangiate cones).</td>\n            <td style=\"padding:8px 10px;\">Reproduce via specialized bisexual or unisexual <strong>flowers</strong> with perianth/calyx/corolla.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 10px; font-weight:700;\">4. Double Fertilization</td>\n            <td style=\"padding:8px 10px;\">Absent. Endosperm is pre-fertilization tissue and <strong>haploid ($n$)</strong>.</td>\n            <td style=\"padding:8px 10px;\">Universal hallmark: <strong>Double fertilization</strong> occurs; endosperm is post-fertilization <strong>triploid ($3n$)</strong>.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px; font-weight:700;\">5. Vascular Elements</td>\n            <td style=\"padding:8px 10px;\">Xylem lacks true vessels (only tracheids; except Gnetales); phloem lacks companion cells (possesses albuminous cells).</td>\n            <td style=\"padding:8px 10px;\">Xylem contains true vessels (tracheae); phloem possesses sieve tubes with companion cells.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Naked ovules/seeds on sporophylls vs. ovules enclosed within an ovary maturing into fruit</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Absence of double fertilization & haploid endosperm vs. double fertilization & triploid endosperm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cones/strobili vs. flowers; tracheids vs. true xylem vessels</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is heterospory? Briefly comment on its significance. Give two examples.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Heterospory:</strong><br>\n    <strong>Heterospory</strong> is the phenomenon of producing two distinctly different morphological and functional types of spores by the same plant sporophyte:\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Microspores:</strong> Smaller in size, produced in microsporangia, and germinate to produce the reduced male gametophyte.</li>\n      <li><strong>Megaspores:</strong> Much larger in size, produced in megasporangia, and germinate to produce the nutrient-rich female gametophyte.</li>\n    </ol>\n    <strong>Biological &amp; Evolutionary Significance (Precursor to the Seed Habit):</strong><br>\n    Heterospory is considered one of the greatest milestones in plant evolution and directly paved the way for the origin of the seed habit in higher plants:\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>Endosporic Development &amp; Retention:</strong> In heterosporous pteridophytes, the megaspore is not immediately shed; it is retained and germinates inside the parent megasporangium, shielded from environmental stresses.</li>\n      <li><strong>Abundant Maternal Nutrition:</strong> The large megaspore accumulates rich food reserves, nourishing the developing embryo within the female gametophyte.</li>\n      <li><strong>Development of Zygote inside Female Gametophyte:</strong> The fertilized zygote develops into a young embryo while still residing on the parent sporophyte. This retention of the developing embryo inside the megasporangium on the maternal plant is the critical evolutionary precursor to the <strong>seed habit</strong> seen in gymnosperms and angiosperms.</li>\n    </ul>\n    <strong>Two Examples of Heterosporous Pteridophytes:</strong><br>\n    1. <em>Selaginella</em> (Spike moss)<br>\n    2. <em>Salvinia</em> (Aquatic water fern) &bull; (Also <em>Marsilea</em>, <em>Isoetes</em>).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of heterospory: production of microspores and megaspores</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evolutionary significance: retention on parent sporophyte as direct precursor of seed habit</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two correct examples: Selaginella and Salvinia</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain briefly the following terms with suitable examples: (i) protonema (ii) antheridium (iii) archegonium (iv) diplontic (v) sporophyll (vi) isogamy.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Concise Explanation of Botanical Terms:</strong><br><br>\n    <strong>(i) Protonema:</strong><br>\n    The juvenile, creeping, green, branched, frequently filamentous haploid gametophytic stage in the life cycle of mosses, formed directly by the mitotic germination of a spore. It reproduces vegetatively by fragmentation and develops lateral buds that grow into leafy gametophores. <em>Example: Funaria, Sphagnum.</em><br><br>\n    <strong>(ii) Antheridium:</strong><br>\n    The multicellular, club-shaped or spherical male sex organ in cryptogams (algae, bryophytes, pteridophytes) surrounded by a sterile jacket of cells that produces flagellated, motile male gametes called antherozoids. <em>Example: Marchantia, Dryopteris.</em><br><br>\n    <strong>(iii) Archegonium:</strong><br>\n    The multicellular, flask-shaped female sex organ found in bryophytes, pteridophytes, and gymnosperms. It consists of a slender upper neck (containing neck canal cells) and a swollen lower venter containing a single non-motile egg (ovum). <em>Example: Riccia, Pinus.</em><br><br>\n    <strong>(iv) Diplontic Life Cycle:</strong><br>\n    A life cycle pattern wherein the dominant, free-living, photosynthetic phase of the plant is the diploid sporophyte ($2n$). The gametophytic phase is represented only by single to few-celled haploid gametes produced directly by meiosis. <em>Example: Fucus (brown alga), and all Gymnosperms and Angiosperms.</em><br><br>\n    <strong>(v) Sporophyll:</strong><br>\n    A specialized leaf or leaf-like laminar organ that bears sporangia on its surface or in its axils. In many pteridophytes and gymnosperms, sporophylls aggregate compactly to form strobili or cones. <em>Example: Fertile fronds of Dryopteris, Microsporophylls of Cycas.</em><br><br>\n    <strong>(vi) Isogamy:</strong><br>\n    A primitive mode of sexual reproduction characterized by the fusion of two morphologically similar and physiologically compatible gametes of equal size and shape (either both flagellated/motile or both non-motile). <em>Example: Chlamydomonas debaryanum, Ulothrix (flagellated motile), and Spirogyra (non-motile).</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition and example for Protonema & Antheridium</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition and example for Archegonium & Diplontic cycle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition and example for Sporophyll & Isogamy</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Differentiate between the following: (a) red algae and brown algae (b) liverworts and moss (c) homosporous and heterosporous pteridophyte.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between Red Algae and Brown Algae:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Trait</th><th style=\"padding:6px 10px;\">Red Algae (Rhodophyceae)</th><th style=\"padding:6px 10px;\">Brown Algae (Phaeophyceae)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Pigments</td><td style=\"padding:6px 10px;\">Chlorophyll $a$, $d$, and <strong>r-phycoerythrin</strong>.</td><td style=\"padding:6px 10px;\">Chlorophyll $a$, $c$, and <strong>fucoxanthin</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Stored Food</td><td style=\"padding:6px 10px;\"><strong>Floridean starch</strong>.</td><td style=\"padding:6px 10px;\"><strong>Laminarin</strong> or <strong>mannitol</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Flagella</td><td style=\"padding:6px 10px;\">Completely absent at all stages.</td><td style=\"padding:6px 10px;\">2 unequal lateral flagella in zoospores/gametes.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Examples</td><td style=\"padding:6px 10px;\"><em>Polysiphonia, Gracilaria, Gelidium</em>.</td><td style=\"padding:6px 10px;\"><em>Ectocarpus, Dictyota, Fucus, Laminaria</em>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Differences Between Liverworts and Mosses:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Trait</th><th style=\"padding:6px 10px;\">Liverworts (Hepaticopsida)</th><th style=\"padding:6px 10px;\">Mosses (Bryopsida)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Plant Body</td><td style=\"padding:6px 10px;\">Dorsoventrally flattened, prostrate thalloid (e.g., <em>Marchantia</em>).</td><td style=\"padding:6px 10px;\">Erect cylindrical axis bearing spirally arranged leaves.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Rhizoids</td><td style=\"padding:6px 10px;\">Unicellular and unbranched.</td><td style=\"padding:6px 10px;\">Multicellular with oblique septa and branched.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Protonema</td><td style=\"padding:6px 10px;\">Absent; spore directly forms thallus.</td><td style=\"padding:6px 10px;\">Prominent juvenile filamentous protonema present.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Spore Dispersal</td><td style=\"padding:6px 10px;\">By hygroscopic elaters inside capsule.</td><td style=\"padding:6px 10px;\">By sophisticated peristomial teeth mechanism.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(c) Differences Between Homosporous and Heterosporous Pteridophytes:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Trait</th><th style=\"padding:6px 10px;\">Homosporous Pteridophytes</th><th style=\"padding:6px 10px;\">Heterosporous Pteridophytes</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Spore Type</td><td style=\"padding:6px 10px;\">Produce only one kind of spore identical in size.</td><td style=\"padding:6px 10px;\">Produce two morphologically distinct spores: microspores and megaspores.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Gametophyte</td><td style=\"padding:6px 10px;\">Monoecious (bisexual) prothallus bearing both antheridia and archegonia.</td><td style=\"padding:6px 10px;\">Dioecious (unisexual): microspores form male gametophytes, megaspores form female.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Examples</td><td style=\"padding:6px 10px;\"><em>Dryopteris, Pteris, Lycopodium, Equisetum</em>.</td><td style=\"padding:6px 10px;\"><em>Selaginella, Salvinia, Marsilea</em>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear tabular differentiation of red vs brown algae (pigments, food, flagella)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differentiation of liverworts vs mosses (thallus vs erect, rhizoids, protonema)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differentiation of homosporous vs heterosporous pteridophytes with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the following (Column I with Column II):<br>(a) Chlamydomonas — (i) Moss<br>(b) Cycas — (ii) Pteridophyte<br>(c) Selaginella — (iii) Alga<br>(d) Sphagnum — (iv) Gymnosperm\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Column Matching with Botanical Classification:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.88rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Column I</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Column II (Correct Match)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Taxonomic Justification</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) <em>Chlamydomonas</em></td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Alga</td>\n            <td style=\"padding:8px 12px;\">Unicellular, biflagellated green alga belonging to Chlorophyceae.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) <em>Cycas</em></td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Gymnosperm</td>\n            <td style=\"padding:8px 12px;\">Naked-seeded plant with palm-like habit, pinnate leaves, and coralloid roots.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) <em>Selaginella</em></td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Pteridophyte</td>\n            <td style=\"padding:8px 12px;\">Vascular cryptogam (club moss) displaying heterospory and rhizophore.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(d) <em>Sphagnum</em></td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Moss</td>\n            <td style=\"padding:8px 12px;\">Peat moss (Bryophyta) with high water retention capacity used as packing material.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>Final Correct Option Matching Sequence:</strong><br>\n    <strong>(a) &rarr; (iii), &nbsp; (b) &rarr; (iv), &nbsp; (c) &rarr; (ii), &nbsp; (d) &rarr; (i)</strong>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Chlamydomonas matched to (iii) Alga</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cycas matched to (iv) Gymnosperm</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Selaginella matched to (ii) Pteridophyte</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Sphagnum matched to (i) Moss</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch3-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch3-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch3-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the important characteristics of gymnosperms.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Anatomical, Morphological &amp; Reproductive Features of Gymnosperms:</strong><br>\n    Gymnosperms (from Greek <em>gymnos</em> = naked; <em>sperma</em> = seed) are seed-bearing vascular plants characterized by the following diagnostic features:<br><br>\n    <strong>1. Naked Ovules and Absence of Fruit:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>The ovules are not enclosed by an ovary wall; they remain freely exposed on the surface of megasporophylls before and after fertilization. Consequently, seeds are naked, and no true fruits are produced.</li>\n    </ul>\n    <strong>2. Habit and Morphological Adaptations (Xerophytic Nature):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Include medium-sized trees to colossal tall trees (e.g., giant red-wood tree <em>Sequoia sempervirens</em>, one of the tallest living trees) and shrubs.</li>\n      <li>Possess a well-developed <strong>tap root system</strong>. In some genera, roots exhibit specialized symbiotic associations:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Pinus:</em> Roots form obligate fungal associations called <strong>mycorrhizae</strong>.</li>\n          <li><em>Cycas:</em> Specialized apogeotropic <strong>coralloid roots</strong> harbor symbiotic nitrogen-fixing cyanobacteria (<em>Anabaena cycadae</em>, <em>Nostoc</em>).</li>\n        </ul>\n      </li>\n      <li>Leaves are xerophytically adapted to withstand extreme temperature, wind, and water stress: needle-like leaves (reducing surface area), thick cuticle, and deeply sunken stomata.</li>\n    </ul>\n    <strong>3. Vascular Tissue Architecture:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Xylem consists primarily of <strong>tracheids</strong> with bordered pits (true xylem vessels are absent, except in advanced order Gnetales: <em>Gnetum</em>, <em>Ephedra</em>, <em>Welwitschia</em>).</li>\n      <li>Phloem contains sieve cells and albuminous cells (lacks true sieve tubes and companion cells).</li>\n    </ul>\n    <strong>4. Heterospory and Cone (Strobilus) Formation:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>All gymnosperms are strictly <strong>heterosporous</strong>, producing haploid microspores and megaspores.</li>\n      <li>Sporophylls are spirally arranged along an axis to form compact <strong>strobili or cones</strong>:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Male strobili (pollen cones):</em> Bear microsporophylls with microsporangia where pollen grains develop. The pollen grain represents the highly reduced male gametophyte.</li>\n          <li><em>Female strobili (seed cones):</em> Bear megasporophylls with megasporangia (ovules).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>5. Fertilization and Embryogeny:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Pollination is strictly <strong>anemophilous</strong> (wind-pollinated). Pollen grains reach the micropyle of ovules directly.</li>\n      <li>Fertilization occurs via a pollen tube carrying non-motile male gametes directly to the archegonia in the ovule (<strong>siphonogamy</strong>).</li>\n      <li>Endosperm is formed <em>prior to fertilization</em> from the female gametophyte and is therefore permanently <strong>haploid ($n$)</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Naked ovules/seeds, habit (Sequoia), tap roots, mycorrhiza (Pinus), coralloid roots (Cycas)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Xerophytic leaf adaptations (needle leaves, sunken stomata) & vascular traits (tracheids)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Heterospory and unisexual strobili/cones (male vs female)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Anemophilous pollination, siphonogamy, and haploid pre-fertilization endosperm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 2</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 4 (Animal Kingdom) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[4] = "<section class=\"chapter-section\" id=\"c11b-ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 4</div>\n      <h2>Animal Kingdom</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 14 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>\n      Fundamental Basis of Animal Classification &amp; Coelom Types\n    </div>\n    <svg viewBox=\"0 0 850 250\" width=\"100%\" height=\"auto\" style=\"max-height:250px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <!-- Coelom Architecture (3 Types) -->\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"230\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"30\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">PRIMARY CRITERIA: BODY CAVITY (COELOM) ORGANISATION</text>\n\n      <!-- 1. Acoelomate -->\n      <g transform=\"translate(60, 45)\">\n        <circle cx=\"80\" cy=\"70\" r=\"60\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n        <circle cx=\"80\" cy=\"70\" r=\"42\" fill=\"#fed7aa\" stroke=\"#ea580c\" stroke-width=\"1.5\"/>\n        <circle cx=\"80\" cy=\"70\" r=\"20\" fill=\"#fef08a\" stroke=\"#ca8a04\" stroke-width=\"1.5\"/>\n        <text x=\"80\" y=\"150\" font-size=\"11\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">1. ACOELOMATE</text>\n        <text x=\"80\" y=\"166\" font-size=\"8.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">No body cavity</text>\n        <text x=\"80\" y=\"180\" font-size=\"8\" fill=\"#475569\" text-anchor=\"middle\">Mesoderm forms solid parenchyma</text>\n        <text x=\"80\" y=\"194\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">e.g., Platyhelminthes</text>\n      </g>\n\n      <!-- 2. Pseudocoelomate -->\n      <g transform=\"translate(325, 45)\">\n        <circle cx=\"80\" cy=\"70\" r=\"60\" fill=\"#fefce8\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n        <!-- Scattered pouches -->\n        <circle cx=\"60\" cy=\"45\" r=\"10\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n        <circle cx=\"100\" cy=\"45\" r=\"10\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n        <circle cx=\"50\" cy=\"80\" r=\"10\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n        <circle cx=\"110\" cy=\"80\" r=\"10\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n        <circle cx=\"80\" cy=\"70\" r=\"20\" fill=\"#fef08a\" stroke=\"#ca8a04\" stroke-width=\"1.5\"/>\n        <text x=\"80\" y=\"150\" font-size=\"11\" font-weight=\"bold\" fill=\"#854d0e\" text-anchor=\"middle\">2. PSEUDOCOELOMATE</text>\n        <text x=\"80\" y=\"166\" font-size=\"8.5\" fill=\"#713f12\" text-anchor=\"middle\">False body cavity</text>\n        <text x=\"80\" y=\"180\" font-size=\"8\" fill=\"#475569\" text-anchor=\"middle\">Mesoderm in scattered pouches</text>\n        <text x=\"80\" y=\"194\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">e.g., Aschelminthes</text>\n      </g>\n\n      <!-- 3. Eucoelomate -->\n      <g transform=\"translate(590, 45)\">\n        <circle cx=\"80\" cy=\"70\" r=\"60\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n        <!-- True cavity with peritoneal mesodermal lining -->\n        <path d=\"M 45,70 A 35,35 0 0,1 115,70 A 35,35 0 0,1 45,70\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"80\" cy=\"70\" r=\"20\" fill=\"#fef08a\" stroke=\"#ca8a04\" stroke-width=\"1.5\"/>\n        <text x=\"80\" y=\"150\" font-size=\"11\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">3. COELOMATE (EUCOELOM)</text>\n        <text x=\"80\" y=\"166\" font-size=\"8.5\" fill=\"#047857\" text-anchor=\"middle\">True body cavity</text>\n        <text x=\"80\" y=\"180\" font-size=\"8\" fill=\"#475569\" text-anchor=\"middle\">Completely lined by mesoderm</text>\n        <text x=\"80\" y=\"194\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">e.g., Annelida to Chordata</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 14: Non-Chordates, Chordates, Coelom, Symmetry, Flight Adaptations & Taxonomic Identification</div>\n\n  <!-- c11b-ch4-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the difficulties that you would face in classification of animals, if common fundamental features are not taken into account?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Difficulties in Animal Classification Without Fundamental Features:</strong><br>\n    The animal kingdom encompasses over a million described species displaying astounding morphological diversity. Without standard, universally accepted fundamental criteria (such as levels of organization, symmetry, germ layers, coelom, and body segmentation), biological classification would encounter severe obstacles:<br><br>\n    <strong>1. Overwhelming Chaos and Confusion:</strong><br>\n    Animals sharing superficial or convergent adaptations (e.g., bats, birds, and flying insects) would be erroneously grouped together due to the presence of wings, masking their true genetic lineages.<br><br>\n    <strong>2. Misleading Grouping Based on Habitat:</strong><br>\n    Classifying solely by habitat would group jellyfish, whales, sharks, and squids together as \"aquatic animals,\" despite jellyfish lacking organs and whales being air-breathing placental mammals.<br><br>\n    <strong>3. Inability to Track Evolutionary Phylogeny:</strong><br>\n    Fundamental homologies—such as the emergence of bilateral symmetry, cephalization, true triploblastic coelom, and the notochord—allow scientists to map out evolutionary descent. Ignoring these would erase phylogenetic lineages.<br><br>\n    <strong>4. Impossibility of Placing Newly Discovered Species:</strong><br>\n    Every year thousands of new marine and terrestrial invertebrates are cataloged. Without fundamental architectural hallmarks, there would be no objective taxonomic rubric to assign new specimens to their correct phylum or class.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Risk of grouping unrelated species based on superficial analogies (e.g. wings/habitat)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Loss of phylogenetic and evolutionary relationships</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Impossibility of systematic placement of newly discovered species</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        If you are given a specimen, what are the steps that you would follow to classify it?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Hierarchical Scientific Steps to Classify an Unknown Animal Specimen:</strong><br><br>\n    <strong>Step 1: Determine the Level of Structural Organisation:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Cellular level:</em> Cells aggregate loosely without forming true tissues (Phylum Porifera).</li>\n      <li><em>Tissue level:</em> Cells performing similar functions form specialized tissues (Cnidaria, Ctenophora).</li>\n      <li><em>Organ / Organ-system level:</em> Tissues group into functional organs and systems (Platyhelminthes to Chordata).</li>\n    </ul>\n    <strong>Step 2: Assess Body Symmetry:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Asymmetrical:</em> Cannot be divided into equal halves through any central plane (most Sponges).</li>\n      <li><em>Radial symmetry:</em> Any plane passing through central longitudinal axis divides body into identical halves (Cnidaria, Ctenophores, Adult Echinoderms).</li>\n      <li><em>Bilateral symmetry:</em> Body can be divided into identical right and left halves in only one plane (Platyhelminthes to Chordates).</li>\n    </ul>\n    <strong>Step 3: Identify Germ Layer Organisation:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Diploblastic:</em> Developed from two embryonic layers—outer ectoderm and inner endoderm, separated by undifferentiated mesoglea (Cnidaria, Ctenophora).</li>\n      <li><em>Triploblastic:</em> Possesses three distinct germ layers—ectoderm, mesoderm, and endoderm (Platyhelminthes to Chordata).</li>\n    </ul>\n    <strong>Step 4: Examine Nature of the Body Cavity (Coelom):</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Acoelomate:</em> No cavity between gut and body wall (Platyhelminthes).</li>\n      <li><em>Pseudocoelomate:</em> Mesoderm exists as scattered pouches, not a true continuous peritoneal lining (Aschelminthes / Roundworms).</li>\n      <li><em>Eucoelomate:</em> True cavity completely lined by mesodermal peritoneum (Annelids, Arthropods, Molluscs, Echinoderms, Chordates).</li>\n    </ul>\n    <strong>Step 5: Inspect Metameric Segmentation &amp; Notochord Presence:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li>Check for true internal and external segmentation (metamerism) as seen in Annelids and Arthropods.</li>\n      <li>Check for a dorsal rod-like <strong>notochord</strong> derived from mesoderm: if present, classify under <strong>Chordata</strong>; if absent, classify under <strong>Non-chordata</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Level of organisation (cellular, tissue, organ system)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Body symmetry (asymmetrical, radial, bilateral)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Germ layers (diploblastic vs triploblastic) and coelom (acoelomate, pseudocoelomate, eucoelomate)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Segmentation and presence/absence of notochord (Chordate vs Non-chordate)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How useful is the study of the nature of body cavity and coelom in the classification of animals?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Diagnostic Significance of the Body Cavity (Coelom) in Animal Classification:</strong><br>\n    The presence or absence of a fluid-filled cavity between the body wall and the gut wall (the <strong>coelom</strong>) is one of the most decisive diagnostic benchmarks in zoological taxonomy:<br><br>\n    <strong>1. Fundamental Primary Categorisation:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Acoelomates:</strong> Animals in which the blastocoel is completely obliterated by solid mesodermal mesenchymal parenchyma cells. There is no cavity around internal organs, limiting their size and mechanical independence (e.g., <em>Platyhelminthes</em> / Flatworms).</li>\n      <li><strong>Pseudocoelomates:</strong> Animals in which the body cavity is derived directly from the persistent embryonic blastocoel rather than splitting of mesoderm. The mesoderm appears only as scattered pouches beneath the body wall, lacking an inner visceral mesodermal lining (e.g., <em>Aschelminthes</em> / Roundworms).</li>\n      <li><strong>Eucoelomates (True Coelomates):</strong> The coelom is a true fluid-filled body space arising entirely within embryonic mesoderm and lined on both parietal (body wall) and visceral (gut wall) sides by mesodermal epithelium (peritoneum). Subdivided into:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Schizocoelomates:</em> Formed by the splitting of mesodermal bands (Annelida, Arthropoda, Mollusca).</li>\n          <li><em>Enterocoelomates:</em> Formed by outpocketings of the embryonic archenteron (Echinodermata, Hemichordata, Chordata).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>2. Physiological and Functional Utility:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>The coelom provides room for the suspension, enlargement, muscular pulsation, and independent peristaltic movement of vital visceral organs (heart, gut, lungs).</li>\n      <li>Coelomic fluid acts as a hydrostatic skeleton (e.g., in annelids) providing locomotion and turgor, acts as a shock absorber against mechanical concussions, and facilitates metabolic exchange and excretion.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition of coelom (space lined by mesoderm between body wall and alimentary canal)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three major categories: Acoelomate (Platyhelminthes), Pseudocoelomate (Aschelminthes), Eucoelomate</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physiological advantages of coelom (space for organ growth, hydrostatic skeleton, shock protection)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish between intracellular and extracellular digestion.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Intracellular and Extracellular Digestion:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Intracellular Digestion</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Extracellular Digestion</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Site of Digestion</td>\n            <td style=\"padding:8px 12px;\">Occurs <strong>inside the cell cytoplasm</strong> within specialized food vacuoles or phagosomes.</td>\n            <td style=\"padding:8px 12px;\">Occurs <strong>outside cells</strong> within the specialized lumen of a gastrovascular cavity or tubular alimentary canal.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Enzyme Action</td>\n            <td style=\"padding:8px 12px;\">Lysosomal enzymes are secreted directly into the intracellular food vacuole.</td>\n            <td style=\"padding:8px 12px;\">Digestive glands and mucosal cells secrete enzymes into an open digestive cavity.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Size of Ingested Food</td>\n            <td style=\"padding:8px 12px;\">Can digest only microscopic food particles or single-celled organisms ingested by phagocytosis.</td>\n            <td style=\"padding:8px 12px;\">Capable of breaking down large, complex macroscopic food chunks or prey.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Efficiency &amp; Regional Specialisation</td>\n            <td style=\"padding:8px 12px;\">Relatively less efficient; no regional differentiation for digestion and absorption.</td>\n            <td style=\"padding:8px 12px;\">Highly efficient; permits extensive regional organ specialization (mouth, stomach, intestine, glands).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">5. Occurrence / Examples</td>\n            <td style=\"padding:8px 12px;\">Protozoans and <strong>Porifera</strong> (sponges via choanocytes). Also initial phase in Cnidaria and Ctenophora.</td>\n            <td style=\"padding:8px 12px;\"><strong>Annelida, Arthropoda, Mollusca, Echinodermata, and all Chordates</strong> (also partly in Cnidaria/Platyhelminthes).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Site comparison: inside food vacuole vs outside cells in cavity/gut lumen</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism & prey size: phagocytosis of microscopic particles vs enzyme secretion on large prey</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate animal examples for both types</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the difference between direct and indirect development?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comparative Differences Between Direct and Indirect Development:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Direct Development</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Indirect Development</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Larval Stage</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\">Completely absent.</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\">Involves one or more distinct, free-living intermediate <strong>larval stages</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Resemblance of Young to Adult</td>\n            <td style=\"padding:8px 12px;\">The hatchling or newborn closely resembles the adult in body plan and morphology, differing only in size and sexual maturity.</td>\n            <td style=\"padding:8px 12px;\">The larva looks morphologically very different from the adult in structure, feeding apparatus, and locomotion.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Metamorphosis</td>\n            <td style=\"padding:8px 12px;\">No metamorphosis occurs; growth is continuous and isometric.</td>\n            <td style=\"padding:8px 12px;\">Undergoes dramatic transformation called <strong>metamorphosis</strong> (retrogressive or progressive) to reach adulthood.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Representative Examples</td>\n            <td style=\"padding:8px 12px;\"><em>Hydra</em>, Earthworms, Birds, Reptiles, and <strong>Mammals</strong> (including humans).</td>\n            <td style=\"padding:8px 12px;\">Porifera (amphiblastula), Cnidaria (planula), Platyhelminthes (miracidium), Insects (caterpillar, maggot), Frogs (tadpole), Echinoderms (bipinnaria).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Absence of larva in direct vs presence of morphologically distinct larva in indirect</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Resemblance of newborn to adult vs requirement of metamorphosis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate animal examples for both categories</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the peculiar features that you find in parasitic platyhelminthes?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Morphological, Physiological &amp; Anatomical Adaptations in Parasitic Platyhelminthes:</strong><br>\n    Endoparasitic flatworms (e.g., <em>Taenia solium</em> / tapeworm and <em>Fasciola hepatica</em> / liver fluke) inhabit hostile microenvironments such as the human bile ducts or intestinal lumen. They exhibit remarkable evolutionary modifications:<br><br>\n    <strong>1. Organs of Adhesion (Hooks and Suckers):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Possess specialized muscular <strong>suckers</strong> (acetabula) and chitinous <strong>hooks</strong> (rostellum) to firmly anchor themselves to the intestinal mucosa, preventing expulsion by peristalsis.</li>\n    </ul>\n    <strong>2. Protective Thick Tegument:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Body is covered by a living syncytial, metabolically active outer coating called the <strong>tegument</strong>, which is resistant to digestive enzymes, bile salts, and host immune surveillance.</li>\n    </ul>\n    <strong>3. Extreme Degeneration or Total Loss of Digestive System:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Since they bathe in predigested chyme in the host small intestine, <em>Taenia</em> completely lacks a mouth and alimentary canal; it absorbs dissolved nutrients directly across its microtriches-covered body surface.</li>\n    </ul>\n    <strong>4. Highly Developed Reproductive System and Fecundity:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Reproductive organs are enormously enlarged. They are hermaphroditic, with each mature proglottid containing both male and female systems, producing millions of fertilized eggs to ensure high transmission probability despite hazards of finding new hosts.</li>\n    </ul>\n    <strong>5. Anaerobic Respiration:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Adapted to thrive in virtually oxygen-free intestinal lumen via facultative or obligate anaerobic glycolysis.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of hooks and suckers for anchorage to host mucosa</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thick protective syncytial tegument and absence/reduction of digestive system</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Huge reproductive potential (hermaphroditism, millions of eggs) and anaerobic metabolism</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the reasons that you can think of for the arthropods to constitute the largest group of the animal kingdom?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Evolutionary Success Factors Accounting for Arthropod Dominance (>80% of All Animal Species):</strong><br>\n    Phylum Arthropoda constitutes over two-thirds of all named living organisms on Earth. Their unprecedented evolutionary triumph is attributed to several key biological adaptations:<br><br>\n    <strong>1. Tough Chitinous Cuticular Exoskeleton:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>The outer body is enveloped by an impermeable, hardened chitin-protein exoskeleton. It provides structural support, protection against mechanical injury and predators, and, crucially, prevents desiccation (water loss), allowing colonization of arid terrestrial habitats.</li>\n    </ul>\n    <strong>2. Jointed Appendages (Extensive Diversification):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Paired, segmented, jointed limbs operated by internal striated muscles have been modified into diverse specialized tools: walking legs, jumping legs, swimming paddles, grasping claws (chelae), biting mandibles, and piercing-sucking proboscises.</li>\n    </ul>\n    <strong>3. Highly Efficient Tracheal Respiratory System:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Insects possess a network of branching air tubes (tracheae and spiracles) that deliver oxygen directly to tissues without relying on blood circulatory speed, supporting exceptionally high metabolic rates.</li>\n    </ul>\n    <strong>4. Flight (Wings in Insects):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Insects were the first animals to evolve powered flight, enabling rapid dispersal, escaping predators, foraging over vast geographic ranges, and finding mates.</li>\n    </ul>\n    <strong>5. Compound Eyes and Advanced Sensory Systems:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Possess mosaic-forming <strong>compound eyes</strong> (composed of thousands of ommatidia), sensitive antennae detecting pheromones, statocysts for balance, and auditory organs.</li>\n    </ul>\n    <strong>6. High Reproductive Output and Metamorphosis:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Short generation times, vast egg counts, and complete metamorphosis (holometabolous development: egg &rarr; larva &rarr; pupa &rarr; adult) eliminate competitive resource overlap between larvae (leaf-feeders) and adults (nectar-feeders).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Chitinous exoskeleton preventing water loss and offering protection</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Jointed appendages adapted for diverse functions (walking, feeding, defense)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tracheal respiratory system and evolution of powered flight in insects</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Compound eyes, pheromone detection, and high fecundity with niche-differentiating metamorphosis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Water vascular system is the characteristic of which group of the following: (a) Porifera (b) Ctenophora (c) Echinodermata (d) Chordata?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Option: (c) Echinodermata</strong><br><br>\n    <strong>Detailed Biological Explanation &amp; Working Mechanism:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li>The <strong>water vascular system</strong> (also known as the <strong>ambulacral system</strong>) is an exclusive, diagnostic hallmark of <strong>Phylum Echinodermata</strong> (e.g., <em>Asterias</em> / Starfish, <em>Echinus</em> / Sea urchin, <em>Antedon</em> / Sea lily, <em>Cucumaria</em> / Sea cucumber).</li>\n      <li>It is a specialized hydrostatic coelomic network consisting of:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>A sieve-like perforated plate on the aboral surface called the <strong>madreporite</strong>.</li>\n          <li>A stone canal connecting to a central circular <strong>ring canal</strong>.</li>\n          <li>Five <strong>radial canals</strong> extending into the arms.</li>\n          <li>Hundreds of hydraulic, muscular, sucker-bearing <strong>tube feet (podia)</strong> operated by contractile ampullae.</li>\n        </ul>\n      </li>\n      <li><strong>Functions of Water Vascular System:</strong>\n        <ol style=\"margin:2px 0 4px 15px;\">\n          <li>Locomotion and adhesion to rocky seabeds.</li>\n          <li>Capture, handling, and transport of prey (such as prying open bivalve molluscs).</li>\n          <li>Gas exchange (respiration) through the thin walls of tube feet and dermal branchiae.</li>\n          <li>Excretion of nitrogenous wastes via diffusion.</li>\n        </ol>\n      </li>\n    </ul>\n    <em>Clarification Note: In contrast, Porifera (sponges) possess a <strong>water canal system</strong> (Ostia &rarr; Spongocoel &rarr; Osculum) driven by choanocyte flagella, which is completely distinct from the hydraulic water vascular system of echinoderms.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of (c) Echinodermata</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of ambulacral mechanism (madreporite, tube feet) and functions (locomotion, food capture, respiration)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        \"All vertebrates are chordates but all chordates are not vertebrates\". Justify the statement.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Rigorous Justification of the Statement:</strong><br><br>\n    <strong>1. Fundamental Hallmarks of Phylum Chordata:</strong><br>\n    All animals placed under Phylum Chordata must possess the following three diagnostic features at some stage in their life cycle:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A solid, dorsal, longitudinal rod called the <strong>notochord</strong>.</li>\n      <li>A dorsal, hollow, single <strong>nerve cord</strong>.</li>\n      <li>Paired <strong>pharyngeal gill slits</strong> (and a post-anal tail).</li>\n    </ul>\n    <strong>2. Classification of Phylum Chordata into Subphyla:</strong><br>\n    Phylum Chordata is subdivided into three distinct subphyla:\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(i) Urochordata (Tunicata):</strong> The notochord is present <em>only in the larval tail</em> and disappears during retrogressive metamorphosis in the sessile adult (e.g., <em>Ascidia</em>, <em>Salpa</em>, <em>Doliolum</em>).</li>\n      <li><strong>(ii) Cephalochordata:</strong> The notochord extends from head to tail tip (<em>rostrum</em> to tail) and persists throughout life, without ever being transformed into a backbone (e.g., <em>Branchiostoma</em> / Amphioxus).</li>\n      <li><strong>(iii) Vertebrata (Craniata):</strong> The embryonic notochord is completely replaced by a cartilaginous or bony <strong>vertebral column (backbone)</strong> in the adult.</li>\n    </ul>\n    <strong>Logical Conclusion:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Since all members of Vertebrata possess a notochord during their embryonic phase, <strong>all vertebrates are fundamentally chordates</strong>.</li>\n      <li>However, the protochordates (Urochordata and Cephalochordata) possess a notochord but <em>never develop a vertebral column</em>. Hence, <strong>all chordates are NOT vertebrates</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of chordate hallmarks (notochord, dorsal hollow nerve cord, pharyngeal slits)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Account of Protochordates (Urochordata & Cephalochordata) lacking a vertebral column</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that Vertebrata replaces embryonic notochord with bony/cartilaginous backbone</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How important is the presence of air bladder in Pisces?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Functional Importance of the Air Bladder (Swim Bladder) in Pisces:</strong><br>\n    The air bladder (or swim bladder) is a hydrostatic, gas-filled sac situated dorsally in the body cavity between the alimentary canal and the vertebral column in bony fishes (Class <strong>Osteichthyes</strong>):<br><br>\n    <strong>1. Hydrostatic Organ for Neutral Buoyancy:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>By regulating the volume and pressure of oxygen, nitrogen, and carbon dioxide within the bladder (via the gas gland and ovale or pneumatic duct), the fish adjusts its specific gravity to match the density of water at various depths.</li>\n      <li>This achieves <strong>neutral buoyancy</strong>, allowing the fish to hover effortlessly at any chosen water depth without constantly exerting muscular swimming effort.</li>\n    </ul>\n    <strong>2. Contrast with Chondrichthyes (Cartilaginous Fishes):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Cartilaginous fishes (e.g., sharks, dogfish <em>Scoliodon</em>, stingrays) <strong>lack an air bladder</strong>. Consequently, they are heavier than water and must swim continuously to generate hydrodynamic lift, otherwise they sink to the bottom.</li>\n    </ul>\n    <strong>3. Energy Conservation:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>The buoyancy conferred by the air bladder allows bony fishes to rest motionlessly in the water column, conserving substantial metabolic energy.</li>\n    </ul>\n    <strong>4. Accessory Respiratory &amp; Auditory Roles:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>In lungfishes (Dipnoi, e.g., <em>Protopterus</em>), the air bladder is heavily vascularized and functions as an accessory lung during seasonal droughts.</li>\n      <li>In many teleosts, the air bladder connects to the inner ear via <strong>Weberian ossicles</strong>, acting as a sound resonator to enhance auditory acuity.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary function: hydrostatic buoyancy regulation allowing effortless hovering</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast with cartilaginous fishes (sharks) which must swim continuously to avoid sinking</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accessory functions: energy conservation, auditory perception (Weberian ossicles), and respiration in lungfishes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the modifications that are observed in birds that help them fly?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical, Physiological &amp; Morphological Flight Adaptations in Birds (Class Aves):</strong><br><br>\n    <strong>1. Forelimbs Modified into Wings:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Forelimbs are completely modified into aerofoil wings covered with flight feathers (remiges and rectrices) that generate lift and thrust.</li>\n    </ul>\n    <strong>2. Pneumatic (Hollow) Skeleton:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Long bones are hollow and filled with air cavities (<strong>pneumatic bones</strong>) rather than heavy bone marrow, drastically reducing specific body weight while retaining high tensile strength.</li>\n    </ul>\n    <strong>3. Streamlined Spindle-Shaped Body:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Streamlined contour offers minimum aerodynamic resistance during flight through air.</li>\n    </ul>\n    <strong>4. Powerful Flight Muscles &amp; Keeled Sternum:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Breastbone (sternum) is modified into a massive ventral ridge called a <strong>keel</strong> (carina), which anchors colossal flight muscles: <em>Pectoralis major</em> (depresses the wing) and <em>Pectoralis minor</em> (elevates the wing).</li>\n    </ul>\n    <strong>5. Air Sacs and Continuous Biphasic Respiration:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Lungs are supplemented by 9 interconnected membranous <strong>air sacs</strong> that extend into bones. They ensure continuous unidirectional airflow across parabronchi, allowing gas exchange during both inhalation and exhalation to fulfill intense flight metabolic demands.</li>\n    </ul>\n    <strong>6. Weight-Reduction Adaptations:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Absence of heavy jaws and teeth; replaced by a lightweight keratinous <strong>beak</strong>.</li>\n      <li>Absence of a urinary bladder; nitrogenous wastes are excreted as semisolid paste of insoluble <strong>uric acid</strong> (uricotelism).</li>\n      <li>Females possess only a single functional <strong>left ovary and oviduct</strong>, shedding the weight of the right reproductive tract.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Forelimbs modified into wings and pneumatic (hollow air-filled) bones</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Streamlined body, keeled sternum, and powerful flight pectoralis muscles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Air sacs connected to lungs ensuring continuous double respiration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Weight reduction: toothless beak, absence of urinary bladder, single functional left ovary</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Could the number of eggs or young ones produced by an oviparous and viviparous mother be equal? Why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: No, the number of eggs produced by an oviparous mother is vastly greater than the number of young ones produced by a viviparous mother.</strong><br><br>\n    <strong>Biological and Evolutionary Reasons:</strong><br><br>\n    <strong>1. High Vulnerability and Predation Risk in Oviparous Species:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Oviparous animals (e.g., frogs, bony fishes, reptiles, birds) lay eggs outside the maternal body in aquatic or terrestrial environments.</li>\n      <li>These eggs are exposed to severe environmental fluctuations (temperature, desiccation, floods) and intense predation by aquatic and terrestrial carnivores.</li>\n      <li>A huge percentage of eggs and hatched larvae perish before reaching reproductive maturity. Therefore, oviparous mothers must produce thousands to millions of eggs (e.g., millions of eggs in teleosts) to ensure that at least a small fraction survives to perpetuate the species.</li>\n    </ul>\n    <strong>2. Internal Protection and High Survival Rate in Viviparous Species:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Viviparous animals (e.g., eutherian mammals) retain the fertilized zygote internally within the female uterus.</li>\n      <li>The developing embryo receives continuous physiological protection, optimal temperature, oxygen, and nourishment directly from maternal blood via the <strong>placenta</strong>.</li>\n      <li>After birth, young ones receive intensive parental care and lactation, ensuring an extraordinarily high survival rate. Consequently, producing 1 to few offspring per reproductive cycle is evolutionarily optimal and conserves maternal resources.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Direct answer: No, oviparous mothers produce significantly more eggs than viviparous young</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Oviparous hazards: external development, environmental threats, high predation loss requiring large numbers</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Viviparous advantages: intrauterine embryonic protection, placenta, parental care giving high survival</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Segmentation in the body is first observed in which of the following: (a) Platyhelminthes (b) Aschelminthes (c) Annelida (d) Arthropoda?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Option: (c) Annelida</strong><br><br>\n    <strong>Scientific Justification:</strong>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li>True <strong>metameric segmentation</strong> (metamerism) is an evolutionary hallmark first exhibited by animals belonging to <strong>Phylum Annelida</strong> (e.g., <em>Pheretima</em> / Earthworm, <em>Hirudinaria</em> / Leech, <em>Nereis</em>).</li>\n      <li><strong>Definition of Metamerism:</strong> The body is divided both externally (by grooves/annuli) and internally (by intersegmental septa) into a linear series of repeating segments called <strong>metameres</strong> or somites, with serial repetition of at least some organs (such as nephridia, ganglia, and blood vessels).</li>\n      <li><em>Platyhelminthes</em> exhibit pseudo-segmentation (proglottids in tapeworms formed by strobilization, not true metamerism).</li>\n      <li><em>Aschelminthes</em> are unsegmented roundworms.</li>\n      <li><em>Arthropoda</em> display metamerism, but evolved chronologically after Annelida.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (c) Annelida</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of true metameric segmentation with serial repetition of internal organs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch4-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch4-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch4-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the following:<br>(a) Operculum — (i) Ctenophora<br>(b) Parapodia — (ii) Mollusca<br>(c) Scales — (iii) Porifera<br>(d) Comb plates — (iv) Reptilia<br>(e) Radula — (v) Annelida<br>(f) Hairs — (vi) Cyclostomata and Chondrichthyes<br>(g) Choanocytes — (vii) Osteichthyes<br>(h) Gill slits — (viii) Mammalia\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Matching of Anatomical Structures with Phyla / Classes:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Structure</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Correct Match</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Biological Function &amp; Significance</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) Operculum</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(vii) Osteichthyes</td>\n            <td style=\"padding:8px 12px;\">Bony protective gill cover covering 4 pairs of gills in bony fishes.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) Parapodia</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(v) Annelida</td>\n            <td style=\"padding:8px 12px;\">Lateral, paddle-like fleshy appendages for swimming in marine annelids like <em>Nereis</em>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) Scales</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Reptilia</td>\n            <td style=\"padding:8px 12px;\">Epidermal dry, cornified scales or scutes preventing evaporative water loss.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(d) Comb plates</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Ctenophora</td>\n            <td style=\"padding:8px 12px;\">Eight external rows of ciliated comb plates helping in locomotion in sea walnuts.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(e) Radula</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Mollusca</td>\n            <td style=\"padding:8px 12px;\">Rasping, file-like chitinous feeding organ present in the mouth of molluscs.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(f) Hairs</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(viii) Mammalia</td>\n            <td style=\"padding:8px 12px;\">Keratinous epidermal hair coat providing thermal insulation and sensory reception.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(g) Choanocytes</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Porifera</td>\n            <td style=\"padding:8px 12px;\">Collar cells lining the spongocoel maintaining water currents and trapping food particles.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(h) Gill slits</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(vi) Cyclostomata &amp; Chondrichthyes</td>\n            <td style=\"padding:8px 12px;\">Separate, un-operculated exposed pharyngeal gill slits for aquatic respiration.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>Final Option Matching Sequence:</strong><br>\n    <strong>(a) &rarr; (vii), &nbsp; (b) &rarr; (v), &nbsp; (c) &rarr; (iv), &nbsp; (d) &rarr; (i), &nbsp; (e) &rarr; (ii), &nbsp; (f) &rarr; (viii), &nbsp; (g) &rarr; (iii), &nbsp; (h) &rarr; (vi)</strong>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) to (vii) Osteichthyes & (b) to (v) Annelida</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) to (iv) Reptilia & (d) to (i) Ctenophora</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) to (ii) Mollusca & (f) to (viii) Mammalia</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(g) to (iii) Porifera & (h) to (vi) Cyclostomata/Chondrichthyes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 3</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 5 (Morphology of Flowering Plants) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[5] = "<section class=\"chapter-section\" id=\"c11b-ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 5</div>\n      <h2>Morphology of Flowering Plants</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 14 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2v20M8 8l4-4 4 4M8 16l4 4 4-4\"/></svg>\n      Floral Architecture &amp; Placentation Patterns in Angiosperms\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"30\" font-size=\"11\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">FIVE MAJOR TYPES OF PLACENTATION IN ANGIOSPERM OVARY</text>\n\n      <!-- 1. Marginal -->\n      <g transform=\"translate(30, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"140\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <path d=\"M 40,30 Q 30,80 40,130 Q 80,110 80,80 Q 80,50 40,30\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"48\" cy=\"55\" r=\"4\" fill=\"#ca8a04\"/>\n        <circle cx=\"48\" cy=\"75\" r=\"4\" fill=\"#ca8a04\"/>\n        <circle cx=\"48\" cy=\"95\" r=\"4\" fill=\"#ca8a04\"/>\n        <circle cx=\"48\" cy=\"115\" r=\"4\" fill=\"#ca8a04\"/>\n        <text x=\"70\" y=\"145\" font-size=\"10\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">1. Marginal</text>\n        <text x=\"70\" y=\"160\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">Ventral suture (Pea)</text>\n      </g>\n\n      <!-- 2. Axile -->\n      <g transform=\"translate(195, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"140\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <circle cx=\"70\" cy=\"75\" r=\"45\" fill=\"#f0fdf4\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n        <!-- 3 Septa -->\n        <line x1=\"70\" y1=\"75\" x2=\"70\" y2=\"30\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n        <line x1=\"70\" y1=\"75\" x2=\"31\" y2=\"97\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n        <line x1=\"70\" y1=\"75\" x2=\"109\" y2=\"97\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n        <circle cx=\"63\" cy=\"62\" r=\"3.5\" fill=\"#ca8a04\"/><circle cx=\"77\" cy=\"62\" r=\"3.5\" fill=\"#ca8a04\"/>\n        <circle cx=\"56\" cy=\"85\" r=\"3.5\" fill=\"#ca8a04\"/><circle cx=\"84\" cy=\"85\" r=\"3.5\" fill=\"#ca8a04\"/>\n        <text x=\"70\" y=\"145\" font-size=\"10\" font-weight=\"bold\" fill=\"#166534\" text-anchor=\"middle\">2. Axile</text>\n        <text x=\"70\" y=\"160\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">Multilocular (Tomato, Citrus)</text>\n      </g>\n\n      <!-- 3. Parietal -->\n      <g transform=\"translate(360, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"140\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <circle cx=\"70\" cy=\"75\" r=\"45\" fill=\"#fefce8\" stroke=\"#ca8a04\" stroke-width=\"1.5\"/>\n        <!-- Ovules on inner wall -->\n        <circle cx=\"35\" cy=\"60\" r=\"3.5\" fill=\"#ca8a04\"/><circle cx=\"35\" cy=\"90\" r=\"3.5\" fill=\"#ca8a04\"/>\n        <circle cx=\"105\" cy=\"60\" r=\"3.5\" fill=\"#ca8a04\"/><circle cx=\"105\" cy=\"90\" r=\"3.5\" fill=\"#ca8a04\"/>\n        <text x=\"70\" y=\"145\" font-size=\"10\" font-weight=\"bold\" fill=\"#854d0e\" text-anchor=\"middle\">3. Parietal</text>\n        <text x=\"70\" y=\"160\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">Inner ovary wall (Mustard)</text>\n      </g>\n\n      <!-- 4. Free Central -->\n      <g transform=\"translate(525, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"140\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <circle cx=\"70\" cy=\"75\" r=\"45\" fill=\"#eff6ff\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n        <circle cx=\"70\" cy=\"75\" r=\"16\" fill=\"#bfdbfe\" stroke=\"#1d4ed8\"/>\n        <!-- Ovules on central column -->\n        <circle cx=\"70\" cy=\"65\" r=\"3\" fill=\"#ca8a04\"/><circle cx=\"70\" cy=\"85\" r=\"3\" fill=\"#ca8a04\"/>\n        <circle cx=\"60\" cy=\"75\" r=\"3\" fill=\"#ca8a04\"/><circle cx=\"80\" cy=\"75\" r=\"3\" fill=\"#ca8a04\"/>\n        <text x=\"70\" y=\"145\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">4. Free Central</text>\n        <text x=\"70\" y=\"160\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">No septa (Dianthus, Primrose)</text>\n      </g>\n\n      <!-- 5. Basal -->\n      <g transform=\"translate(685, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"140\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <ellipse cx=\"70\" cy=\"75\" rx=\"35\" ry=\"45\" fill=\"#fdf4ff\" stroke=\"#a21caf\" stroke-width=\"1.5\"/>\n        <circle cx=\"70\" cy=\"105\" r=\"6\" fill=\"#ca8a04\"/>\n        <line x1=\"70\" y1=\"120\" x2=\"70\" y2=\"111\" stroke=\"#a21caf\" stroke-width=\"2\"/>\n        <text x=\"70\" y=\"145\" font-size=\"10\" font-weight=\"bold\" fill=\"#86198f\" text-anchor=\"middle\">5. Basal</text>\n        <text x=\"70\" y=\"160\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">Single ovule at base (Sunflower)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 14: Roots, Stems, Leaves, Inflorescence, Flowers, Placentation & Floral Formulas</div>\n\n  <!-- c11b-ch5-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is meant by modification of root? What type of modification of root is found in the: (a) Banyan tree (b) Turnip (c) Mangrove trees?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Root Modification:</strong><br>\n    Root modification refers to permanent morphological, anatomical, and structural changes undergone by roots to perform specialized functions other than their normal physiological roles of water/mineral absorption and anchorage (such as mechanical support, food storage, and respiration).<br><br>\n    <strong>Modifications in the Specified Plants:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(a) Banyan tree (<em>Ficus benghalensis</em>) &mdash; Prop Roots (Pillar Roots):</strong><br>\n      Massive, adventitious aerial roots arise from heavy horizontal branches and grow vertically downward into the soil. Upon entering the soil, they become thick, woody, and pillar-like, providing mechanical support to the colossal canopy.</li>\n      <li><strong>(b) Turnip (<em>Brassica rapa</em>) &mdash; Napiform Tap Root:</strong><br>\n      The primary tap root becomes spherical and swollen with stored carbohydrates (starch), narrowing abruptly at the lower tip into a slender tail.</li>\n      <li><strong>(c) Mangrove trees (e.g., <em>Rhizophora</em>) &mdash; Pneumatophores (Respiratory Roots):</strong><br>\n      In waterlogged, saline, oxygen-deficient coastal swamp soils, subterranean roots produce negatively geotropic, erect peg-like vertical aerial roots that emerge above water. They bear numerous aerating pores called <strong>lenticels (pneumathodes)</strong> to intake oxygen for underground tissue respiration.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of root modification for secondary physiological/mechanical functions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Banyan tree: Prop roots for mechanical support</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Turnip: Napiform tap root for food storage</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Mangroves: Pneumatophores with lenticels for oxygen intake</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Justify the following statements on the basis of external features: (a) Underground parts of a plant are not always roots (b) Flower is a modified shoot.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Justification: Underground parts of a plant are not always roots:</strong><br>\n    Roots lack nodes, internodes, leaves, and buds. In contrast, several underground plant structures are morphologically <strong>modified stems</strong> because they exhibit diagnostic stem characteristics:\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Potato Tuber:</strong> Bears \"eyes\", which are axillary buds situated in the axils of scale-leaf scars at definite nodes.</li>\n      <li><strong>Ginger and Turmeric Rhizome:</strong> Horizontally growing underground stems with distinct nodes, internodes, scaly leaves, and terminal buds.</li>\n      <li><strong>Colocasia and Corm of Amorphophallus:</strong> Vertically condensed underground stems with circular nodes and axillary buds.</li>\n      <li><strong>Onion Bulb:</strong> Highly reduced disc-like stem bearing fleshy concentric scale leaves storing food.</li>\n    </ul>\n    <strong>(b) Justification: Flower is a modified shoot:</strong><br>\n    Goethe first proposed that a flower is an indeterminate vegetative shoot condensed and modified for sexual reproduction:\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Condensation of Axis:</strong> The apical meristem transforms into a floral meristem; internodes do not elongate, condensing the floral axis into a swollen <strong>thalamus (receptacle)</strong>.</li>\n      <li><strong>Homology with Leaves:</strong> Floral whorls (sepals, petals, stamens, and carpels) are borne successively at swollen nodes like modified leaves (phylls): sepals &asymp; microphylls, petals &asymp; leaves, stamens &asymp; microsporophylls, carpels &asymp; megasporophylls.</li>\n      <li><strong>Axillary Position &amp; Reversion:</strong> Flowers arise in the axils of bracts (modified leaves), precisely where vegetative axillary branches normally emerge. In abnormal conditions (e.g., in <em>Cleome</em> or <em>Rosa</em>), floral axes occasionally elongate between whorls (anthophore, androphore, gynophore).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Clear evidence of stem features (nodes, internodes, buds, scale leaves) in tubers/rhizomes</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Explanation of condensed axis (thalamus) and floral organs as homologous modified leaves</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How is a pinnately compound leaf different from a palmately compound leaf?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Pinnately and Palmately Compound Leaves:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Feature</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Pinnately Compound Leaf</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Palmately Compound Leaf</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Arrangement of Leaflets</td>\n            <td style=\"padding:8px 12px;\">Leaflets (pinnae) are attached laterally along an elongated common central axis called the <strong>rachis</strong> (which represents the extended midrib).</td>\n            <td style=\"padding:8px 12px;\">Leaflets are articulated and radiate out from a <strong>single common point</strong> at the tip of the petiole (like fingers from a palm).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Presence of Rachis</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\">Rachis is present, prominent, and bears leaflets at intervals.</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\">Rachis is completely absent or extremely reduced.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Subdivisions</td>\n            <td style=\"padding:8px 12px;\">Can be unipinnate (paripinnate/imparipinnate), bipinnate, tripinnate, or decompound.</td>\n            <td style=\"padding:8px 12px;\">Classified based on leaflet number: unifoliolate, bifoliolate, trifoliolate, quadrifoliolate, or multifoliolate.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Representative Examples</td>\n            <td style=\"padding:8px 12px;\"><strong>Neem</strong> (<em>Azadirachta indica</em>), Rose, Cassia, Tamarind, Gulmohar.</td>\n            <td style=\"padding:8px 12px;\"><strong>Silk cotton</strong> (<em>Bombax ceiba</em>), Citrus, <em>Oxalis</em>, <em>Marsilea</em>.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Arrangement: lateral along rachis vs radiating from single petiole tip</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence vs absence of rachis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct botanical examples for both (Neem vs Silk Cotton)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain with suitable examples the different types of phyllotaxy.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Phyllotaxy:</strong><br>\n    <strong>Phyllotaxy</strong> is the pattern of arrangement of leaves on the stem or branch. Its primary adaptive objective is to position leaf blades in a non-overlapping configuration to maximize sunlight interception.<br><br>\n    <strong>Three Major Types of Phyllotaxy:</strong><br><br>\n    <strong>1. Alternate (Spiral) Phyllotaxy:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>A <strong>single leaf</strong> arises at each node in an alternate and spiral fashion along the stem axis.</li>\n      <li><em>Examples:</em> <strong>China rose</strong> (<em>Hibiscus rosa-sinensis</em>), <strong>Mustard</strong> (<em>Brassica campestris</em>), and <strong>Sunflower</strong> (<em>Helianthus annuus</em>).</li>\n    </ul>\n    <strong>2. Opposite Phyllotaxy:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>A <strong>pair of leaves</strong> arises at each node on opposite sides facing each other. Subtypes:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Opposite decussate:</em> Successive pairs lie at right angles to each other (e.g., <em>Calotropis</em>, <em>Ocimum</em> / Holy Basil).</li>\n          <li><em>Opposite superposed:</em> Successive pairs lie in the exact same plane (e.g., <strong>Guava</strong> / <em>Psidium guajava</em>, <em>Syzygium</em>).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Whorled Phyllotaxy:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>More than two leaves</strong> arise at each node to form a circular ring or whorl around the stem.</li>\n      <li><em>Examples:</em> <strong>Alstonia</strong> (Devil's tree), <em>Nerium</em> (Oleander).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of phyllotaxy and adaptive purpose</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Alternate: single leaf per node, examples (China rose, Mustard, Sunflower)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Opposite: pair of leaves per node, examples (Calotropis, Guava)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Whorled: >2 leaves per node, example (Alstonia)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define the following terms: (a) aestivation (b) placentation (c) actinomorphic (d) zygomorphic (e) superior ovary (f) perigynous flower (g) epipetalous stamen.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Precise Botanical Definitions of Floral Terms:</strong><br><br>\n    <strong>(a) Aestivation:</strong><br>\n    The mode of arrangement of accessory floral leaves (sepals or petals) in a floral bud with respect to other members of the same whorl. Major types: Valvate, Twisted, Imbricate, and Vexillary.<br><br>\n    <strong>(b) Placentation:</strong><br>\n    The pattern of distribution and attachment of ovules upon the fertile tissue called placenta within the ovary of a flower. Types: Marginal, Axile, Parietal, Free-central, and Basal.<br><br>\n    <strong>(c) Actinomorphic (Radial Symmetry):</strong><br>\n    A flower that can be divided into two equal radial halves in <strong>any vertical plane</strong> passing through the central axis (represented by $\\oplus$). <em>Examples: Mustard, Datura, Chilli.</em><br><br>\n    <strong>(d) Zygomorphic (Bilateral Symmetry):</strong><br>\n    A flower that can be divided into two similar halves in <strong>only one vertical plane</strong> (represented by $%$). <em>Examples: Pea, Gulmohar, Bean, Cassia.</em><br><br>\n    <strong>(e) Superior Ovary (Hypogynous Flower):</strong><br>\n    An ovary that occupies the highest apical position on the convex thalamus, while sepals, petals, and stamens are inserted below it. Symbolized as $\\underline{\\text{G}}$. <em>Examples: Mustard, China rose, Brinjal.</em><br><br>\n    <strong>(f) Perigynous Flower:</strong><br>\n    A flower in which the gynoecium is situated at the center, and other floral parts are located on the rim or margin of a saucer- or cup-shaped thalamus at approximately the same level. The ovary is termed <strong>half-inferior</strong>. <em>Examples: Plum, Rose, Peach.</em><br><br>\n    <strong>(g) Epipetalous Stamen:</strong><br>\n    A condition in which the filaments of stamens are fused or attached to the inner face of the corolla petals (represented by $\\overgroup{\\text{C}\\quad\\text{A}}$). <em>Example: Brinjal (Solanaceae), Datura.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Aestivation & (b) Placentation definitions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Actinomorphic & (d) Zygomorphic with symmetry planes & examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Superior ovary & (f) Perigynous flower / half-inferior ovary</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(g) Epipetalous stamen definition with Brinjal example</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Differentiate between: (a) Racemose and cymose inflorescence (b) Apocarpous and syncarpous ovary.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between Racemose and Cymose Inflorescence:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Feature</th><th style=\"padding:6px 10px;\">Racemose Inflorescence</th><th style=\"padding:6px 10px;\">Cymose Inflorescence</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Peduncle Growth</td><td style=\"padding:6px 10px;\">Main axis shows <strong>unlimited continuous growth</strong>; does not terminate in a flower.</td><td style=\"padding:6px 10px;\">Main axis has <strong>limited growth</strong>; terminates in a flower.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Order of Flower Opening</td><td style=\"padding:6px 10px;\"><strong>Acropetal succession</strong> (oldest flowers at base, youngest near apex) and centripetal.</td><td style=\"padding:6px 10px;\"><strong>Basipetal succession</strong> (oldest flower at apex, youngest towards base) and centrifugal.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Examples</td><td style=\"padding:6px 10px;\">Radish, Mustard, Crotalaria.</td><td style=\"padding:6px 10px;\">Jasmine, Teak, Bougainvillea, <em>Solanum</em>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Differences Between Apocarpous and Syncarpous Ovary:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Feature</th><th style=\"padding:6px 10px;\">Apocarpous Ovary</th><th style=\"padding:6px 10px;\">Syncarpous Ovary</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Carpel Fusion</td><td style=\"padding:6px 10px;\">Carpels are multiple (multicarpellary) and <strong>completely free</strong> from one another.</td><td style=\"padding:6px 10px;\">Two or more carpels are <strong>fused together</strong> to form a single compound pistil.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Fruit Formation</td><td style=\"padding:6px 10px;\">Gives rise to an aggregate of fruitlets (etaerio of achenes, berries, or follicles).</td><td style=\"padding:6px 10px;\">Develops into a single simple fruit (e.g., berry, capsule, drupe).</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Examples</td><td style=\"padding:6px 10px;\"><strong>Lotus</strong> (<em>Nelumbo</em>), <strong>Rose</strong>, <em>Michelia</em> (Champa).</td><td style=\"padding:6px 10px;\"><strong>Mustard</strong>, <strong>Tomato</strong>, <em>Hibiscus</em>, Brinjal.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Racemose vs Cymose: peduncle termination, succession order (acropetal vs basipetal), examples</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Apocarpous vs Syncarpous: free vs fused carpels, aggregate vs simple fruit, examples</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw the labelled diagram of the following: (i) gram seed (ii) V.S. of maize grain.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Morphological and Anatomical Architecture of Seeds:</strong><br><br>\n    <strong>(i) Non-Endospermic Dicot Seed &mdash; Gram Seed (<em>Cicer arietinum</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Seed Coat:</strong> Double-layered; outer thick brownish <strong>testa</strong> and inner thin membranous <strong>tegmen</strong>.</li>\n      <li><strong>Hilum &amp; Micropyle:</strong> Hilum is the scar of stalk attachment; just above it lies a minute pore, the <strong>micropyle</strong> (for water/oxygen entry).</li>\n      <li><strong>Embryo:</strong> Consists of two massive, fleshy, starch-rich <strong>cotyledons</strong> enclosing an embryonal axis (tigellum).\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Upper conical tip: <strong>Plumule</strong> (future shoot).</li>\n          <li>Lower pointed tip: <strong>Radicle</strong> (future root).</li>\n          <li><em>Endosperm:</em> Completely absorbed during embryogeny (exalbuminous / non-endospermic).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>(ii) Endospermic Monocot Seed &mdash; V.S. of Maize Grain (<em>Zea mays</em>):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Fused Pericarp &amp; Testa:</strong> Single-seeded fruit (caryopsis) where fruit wall is fused with seed coat.</li>\n      <li><strong>Aleurone Layer:</strong> A specialized protein-rich outer layer separating the endosperm from the embryo.</li>\n      <li><strong>Endosperm:</strong> Large, bulky tissue storing starch, occupying two-thirds of the grain volume.</li>\n      <li><strong>Embryo:</strong> Shield-shaped single cotyledon called the <strong>scutellum</strong> positioned laterally against the endosperm.\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Coleoptile:</strong> Protective hollow sheath enclosing the plumule.</li>\n          <li><strong>Coleorhiza:</strong> Protective parenchymatous sheath enclosing the radicle and root cap.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Gram seed components: testa, tegmen, hilum, micropyle, 2 cotyledons, radicle, plumule</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Maize grain: fused pericarp, aleurone layer, endosperm, scutellum, coleoptile, coleorhiza</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe modifications of stem with suitable examples.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Diverse Morphological Modifications of Stem:</strong><br><br>\n    <strong>1. Underground Modifications (Storage &amp; Perennation):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Tuber:</strong> Swollen terminal ends of underground branches storing starch, bearing buds/eyes. <em>Example: Potato (Solanum tuberosum).</em></li>\n      <li><strong>Rhizome:</strong> Fleshy, prostrate dorsiventral horizontal stem with distinct nodes, internodes, and scaly leaves. <em>Example: Ginger (Zingiber officinale), Turmeric.</em></li>\n      <li><strong>Corm:</strong> Unbranched, stout, vertically growing condensed underground stem. <em>Example: Colocasia, Amorphophallus (Zamikand).</em></li>\n      <li><strong>Bulb:</strong> Highly reduced discoid stem bearing fleshy scale leaves. <em>Example: Onion (Allium cepa), Garlic.</em></li>\n    </ul>\n    <strong>2. Sub-Aerial Modifications (Vegetative Propagation):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Runner:</strong> Creeping prostrate branch rooting at nodes. <em>Example: Grass (Cynodon dactylon), Oxalis.</em></li>\n      <li><strong>Stolon:</strong> Slender lateral branch arching downward to touch the ground. <em>Example: Mint (Mentha), Jasmine.</em></li>\n      <li><strong>Offset:</strong> Short, thick lateral branch of one internode length with a rosette of leaves and a tuft of roots. <em>Example: Pistia, Eichhornia (Water hyacinth).</em></li>\n      <li><strong>Sucker:</strong> Arises from underground stem, grows horizontally, then emerges obliquely upward. <em>Example: Chrysanthemum, Banana, Pineapple.</em></li>\n    </ul>\n    <strong>3. Aerial Modifications (Specialised Adaptive Functions):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Stem Tendrils:</strong> Axillary buds modified into slender spirally coiled climbing structures. <em>Example: Gourds (cucumber, pumpkin, watermelon) and Grapevine.</em></li>\n      <li><strong>Thorns:</strong> Axillary buds modified into woody, straight, pointed protective organs preventing grazing. <em>Example: Citrus, Bougainvillea.</em></li>\n      <li><strong>Phylloclades:</strong> Green, flattened or cylindrical succulent stems taking over photosynthesis and storing water in xerophytes. <em>Example: Opuntia (flattened), Euphorbia (cylindrical).</em></li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Underground stem modifications (Tuber, Rhizome, Corm, Bulb) with examples</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sub-aerial modifications (Runner, Stolon, Offset, Sucker) with examples</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Aerial modifications (Tendrils, Thorns, Phylloclades) with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Take one flower each of the families Fabaceae and Solanaceae and write its semi-technical description. Also give their floral formula.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Family Fabaceae (e.g., <em>Pisum sativum</em> &mdash; Pea Flower):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Inflorescence:</strong> Racemose.</li>\n      <li><strong>Flower:</strong> Bisexual, zygomorphic, hypogynous, bracteate, pentamerous.</li>\n      <li><strong>Calyx:</strong> Sepals 5, gamosepalous (fused), valvate or imbricate aestivation.</li>\n      <li><strong>Corolla:</strong> Petals 5, polypetalous, papilionaceous consisting of a large posterior <strong>standard</strong> (vexillum), two lateral <strong>wings</strong> (alae), and two anterior fused petals forming a <strong>keel</strong> (carina); vexillary aestivation.</li>\n      <li><strong>Androecium:</strong> Stamens 10, <strong>diadelphous</strong> [9 + 1] (9 filaments fused into a tube, 1 free posterior stamen), dithecous anthers.</li>\n      <li><strong>Gynoecium:</strong> Monocarpellary, superior unilocular ovary with marginal placentation, single style.</li>\n    </ul>\n    <strong>Floral Formula of Fabaceae:</strong><br>\n    $$\\% \\; \\text{ ⚥ } \\; \\text{K}_{(5)} \\; \\text{C}_{1+2+(2)} \\; \\text{A}_{(9)+1} \\; \\underline{\\text{G}}_{1}$$\n    <br>\n    <strong>2. Family Solanaceae (e.g., <em>Solanum nigrum</em> &mdash; Makoi / Black Nightshade):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Inflorescence:</strong> Solitary, axillary or cymose (as in <em>Solanum</em>).</li>\n      <li><strong>Flower:</strong> Bisexual, actinomorphic, hypogynous, ebracteate, pentamerous.</li>\n      <li><strong>Calyx:</strong> Sepals 5, gamosepalous, persistent, valvate aestivation.</li>\n      <li><strong>Corolla:</strong> Petals 5, gamopetalous, rotate or infundibuliform, valvate aestivation.</li>\n      <li><strong>Androecium:</strong> Stamens 5, <strong>epipetalous</strong> (attached to corolla tube), alternating with petals, free (polyandrous), anthers dithecous.</li>\n      <li><strong>Gynoecium:</strong> Bicarpellary, syncarpous, superior ovary, bilocular, obliquely placed ovary with <strong>swollen placenta</strong> bearing numerous ovules with axile placentation.</li>\n    </ul>\n    <strong>Floral Formula of Solanaceae:</strong><br>\n    $$\\oplus \\; \\text{ ⚥ } \\; \\text{K}_{(5)} \\; \\overgroup{\\text{C}_{(5)} \\quad \\text{A}_{5}} \\; \\underline{\\text{G}}_{(2)}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Semi-technical description of Fabaceae (papilionaceous, diadelphous 9+1, monocarpellary)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate floral formula of Fabaceae</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Semi-technical description of Solanaceae (actinomorphic, persistent calyx, epipetalous, swollen placenta)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate floral formula of Solanaceae</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the various types of placentations found in flowering plants.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Detailed Description of the Five Primary Types of Placentation:</strong><br><br>\n    <strong>1. Marginal Placentation:</strong><br>\n    The placenta forms a continuous ridge along the <strong>ventral suture</strong> of a monocarpellary unilocular ovary, and ovules are borne in two alternating rows along the ridge. <em>Example: Pea (Pisum), Gram, Bean.</em><br><br>\n    <strong>2. Axile Placentation:</strong><br>\n    The ovary is multicarpellary, syncarpous, and partitioned into two or more chambers (multilocular) by radial septa. The walls of carpels meet at the central axis where the placenta forms, bearing ovules in each locule. <em>Examples: Tomato, China rose, Lemon, Orange.</em><br><br>\n    <strong>3. Parietal Placentation:</strong><br>\n    The ovules develop on the <strong>inner peripheral wall</strong> of a syncarpous, unilocular ovary. In some cases (such as Brassicaceae), the ovary becomes falsely two-chambered due to the development of a false septum called the <strong>replum</strong>. <em>Examples: Mustard, Argemone.</em><br><br>\n    <strong>4. Free Central Placentation:</strong><br>\n    The ovules are borne on a distinct central axis column in a unilocular ovary, and septa are completely absent. <em>Examples: Dianthus, Primrose (Primula).</em><br><br>\n    <strong>5. Basal Placentation:</strong><br>\n    The placenta develops directly at the <strong>base of the ovary</strong> and bears a <strong>single solitary ovule</strong>. <em>Examples: Sunflower (Helianthus), Marigold (Tagetes).</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Marginal placentation with Pea example</span><span class=\"marking-marks\">0.8 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Axile placentation with Tomato/Citrus example</span><span class=\"marking-marks\">0.8 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Parietal placentation and false septum (replum) with Mustard example</span><span class=\"marking-marks\">0.8 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Free central placentation with Dianthus example</span><span class=\"marking-marks\">0.8 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Basal placentation with Sunflower example</span><span class=\"marking-marks\">0.8 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is a flower? Describe the parts of a typical angiosperm flower.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of a Flower:</strong><br>\n    A flower is a specialized, condensed reproductive shoot of angiosperms, bearing modified leaves adapted for sexual reproduction and the subsequent production of seeds and fruits.<br><br>\n    <strong>Four Concentric Whorls of a Typical Flower (from Outermost to Innermost):</strong><br><br>\n    <strong>1. Calyx (Outermost Non-Essential Whorl):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Composed of individual units called <strong>sepals</strong>, which are typically green and leaf-like.</li>\n      <li>Protects the delicate internal floral organs in the bud condition.</li>\n    </ul>\n    <strong>2. Corolla (Second Non-Essential Whorl):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Composed of individual units called <strong>petals</strong>, brightly colored and often fragrant.</li>\n      <li>Attracts pollinating agents (insects, birds) and shields sexual organs.</li>\n    </ul>\n    <strong>3. Androecium (Male Reproductive Whorl):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Composed of <strong>stamens</strong> (microsporophylls). Each stamen consists of a slender stalk (filament) and a terminal bilobed <strong>anther</strong>.</li>\n      <li>Each anther lobe contains two pollen sacs (microsporangia) producing haploid pollen grains.</li>\n    </ul>\n    <strong>4. Gynoecium / Pistil (Female Reproductive Whorl):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Composed of one or more <strong>carpels</strong> (megasporophylls). Each carpel consists of three parts:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Stigma:</strong> Sticky receptive terminal landing platform for pollen grains.</li>\n          <li><strong>Style:</strong> Slender elongated neck through which the pollen tube travels.</li>\n          <li><strong>Ovary:</strong> Swollen basal portion containing one or more ovules attached to the placenta.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of flower as modified reproductive shoot</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calyx (sepals) and Corolla (petals) descriptions and functions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Androecium (stamens, filament, anther, pollen sacs)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Gynoecium (carpels, stigma, style, ovary with ovules)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How do the various leaf modifications help plants?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Adaptive Value of Diverse Leaf Modifications:</strong><br>\n    Leaves frequently undergo structural modifications beyond photosynthesis to aid survival:<br><br>\n    <strong>1. Leaf Tendrils (Climbing Support):</strong><br>\n    In weak-stemmed plants, entire leaves or leaflets modify into slender, sensitive, coiling filaments that twine around supports to elevate the photosynthetic foliage towards light. <em>Example: Wild pea (Lathyrus), Garden pea (Pisum sativum).</em><br><br>\n    <strong>2. Leaf Spines (Defense &amp; Xerophytic Water Conservation):</strong><br>\n    In arid xerophytes, leaves are reduced to sharp, stiff spines. This dramatically minimizes surface area for transpiration and protects succulents from herbivorous predators. <em>Example: Opuntia, Cactus, Aloe.</em><br><br>\n    <strong>3. Fleshy Storage Leaves (Food &amp; Water Reserves):</strong><br>\n    Fleshy scale leaves store reserves of water, mucilage, and carbohydrates. <em>Example: Onion and Garlic bulbs, Bryophyllum.</em><br><br>\n    <strong>4. Phyllodes (Photosynthesis with Reduced Transpiration):</strong><br>\n    In <em>Acacia auriculiformis</em> (Australian acacia), the bipinnate lamina sheds early. The petiole flattens into a sickle-shaped green blade called a <strong>phyllode</strong>, which synthesizes food while losing minimal water through transpiration.<br><br>\n    <strong>5. Insect Traps (Carnivorous Nitrogen Supplementation):</strong><br>\n    Leaves modify into pitchers (<em>Nepenthes</em>), bladders (<em>Utricularia</em>), or snapping traps (<em>Dionaea</em>) to capture insects and digest them to obtain nitrogenous compounds in nutrient-poor bogs.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Leaf tendrils for climbing support (Pea) and leaf spines for defense/water saving (Opuntia)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fleshy leaves for food/water storage (Onion, Aloe)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phyllode (Australian Acacia) and insectivorous modifications (Nepenthes, Utricularia)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define the term inflorescence. Explain the basis for the different types of inflorescence in flowering plants.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Inflorescence:</strong><br>\n    An <strong>inflorescence</strong> is the natural arrangement and mode of distribution of a cluster of flowers on the floral axis (called the <strong>peduncle</strong> or mother axis) of a plant.<br><br>\n    <strong>Basis of Classification into Major Types:</strong><br>\n    Inflorescences are classified primarily on whether the main growing apex continues to grow indefinitely or terminates in the formation of a flower:<br><br>\n    <strong>1. Racemose Inflorescence (Indeterminate / Indefinite Growth):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The main axis (peduncle) <strong>continues to grow</strong> continuously by its apical bud and does not terminate in a flower.</li>\n      <li>Flowers are produced laterally in <strong>acropetal succession</strong> (oldest flowers at the base, youngest buds towards the growing apex).</li>\n      <li>In flat-topped inflorescences, the opening of flowers is <strong>centripetal</strong> (from periphery towards center).</li>\n    </ul>\n    <strong>2. Cymose Inflorescence (Determinate / Definite Growth):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The apical bud of the main axis <strong>terminates in a flower</strong>, arresting further vertical growth of the peduncle.</li>\n      <li>Further growth continues via lateral branches arising below the terminal flower, each also terminating in a flower.</li>\n      <li>Flowers are arranged in <strong>basipetal succession</strong> (terminal apical flower is the oldest, youngest flowers are towards the base).</li>\n      <li>In flat-topped cymes, flower opening is <strong>centrifugal</strong> (from center towards periphery).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of inflorescence and floral axis (peduncle)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Racemose criteria: continuous apical growth, acropetal succession, centripetal opening</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cymose criteria: apical flower termination, basipetal succession, centrifugal opening</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch5-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch5-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch5-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the floral formula of an actinomorphic, bisexual, hypogynous flower with five united sepals, five free petals, five free stamens and two united carpels with superior ovary and axile placentation.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Step-by-Step Derivation of the Floral Formula:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Actinomorphic (Radial Symmetry):</strong> Represented by the symbol &mdash; $\\oplus$</li>\n      <li><strong>2. Bisexual (Hermaphrodite / Perfect Flower):</strong> Represented by &mdash; $\\text{⚥}$</li>\n      <li><strong>3. Calyx:</strong> 5 united sepals (gamosepalous) &mdash; $\\text{K}_{(5)}$</li>\n      <li><strong>4. Corolla:</strong> 5 free petals (polypetalous) &mdash; $\\text{C}_{5}$</li>\n      <li><strong>5. Androecium:</strong> 5 free stamens (polyandrous, not epipetalous) &mdash; $\\text{A}_{5}$</li>\n      <li><strong>6. Gynoecium:</strong> Bicarpellary (2), united carpels (syncarpous &mdash; enclosed in brackets), superior ovary (hypogynous &mdash; line under G) &mdash; $\\underline{\\text{G}}_{(2)}$</li>\n    </ul>\n    <br>\n    <strong>Final Accurate Floral Formula:</strong><br>\n    $$\\oplus \\; \\text{ ⚥ } \\; \\text{K}_{(5)} \\; \\text{C}_{5} \\; \\text{A}_{5} \\; \\underline{\\text{G}}_{(2)}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct symbols for symmetry (\\oplus) and sexuality (\\text{⚥})</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct representation of calyx K(5) and corolla C5</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct representation of androecium A5</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct representation of gynoecium \\underline{G}(2)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 4</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 6 (Anatomy of Flowering Plants) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[6] = "<section class=\"chapter-section\" id=\"c11b-ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 6</div>\n      <h2>Anatomy of Flowering Plants</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2v20M2 12h20\"/><circle cx=\"12\" cy=\"12\" r=\"7\"/></svg>\n      Plant Anatomy: Dicot vs. Monocot Stem Architecture &amp; Stomatal Apparatus\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Dicot Stem T.S. -->\n      <g transform=\"translate(30, 25)\">\n        <rect x=\"0\" y=\"0\" width=\"240\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"120\" y=\"24\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">DICOT STEM (T.S.)</text>\n        <circle cx=\"120\" cy=\"105\" r=\"65\" fill=\"#f1f5f9\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n        <circle cx=\"120\" cy=\"105\" r=\"22\" fill=\"#e2e8f0\" stroke=\"#94a3b8\"/>\n        <text x=\"120\" y=\"108\" font-size=\"8.5\" fill=\"#475569\" text-anchor=\"middle\">Pith</text>\n        <!-- Ring of wedge-shaped bundles -->\n        <circle cx=\"120\" cy=\"60\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"120\" cy=\"150\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"75\" cy=\"105\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"165\" cy=\"105\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"88\" cy=\"73\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"152\" cy=\"73\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"88\" cy=\"137\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <circle cx=\"152\" cy=\"137\" r=\"10\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n        <text x=\"120\" y=\"180\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\" text-anchor=\"middle\">&bull; Ring Arrangement &bull; Open Bundles</text>\n      </g>\n\n      <!-- Monocot Stem T.S. -->\n      <g transform=\"translate(300, 25)\">\n        <rect x=\"0\" y=\"0\" width=\"240\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"120\" y=\"24\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">MONOCOT STEM (T.S.)</text>\n        <circle cx=\"120\" cy=\"105\" r=\"65\" fill=\"#f1f5f9\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n        <!-- Scattered vascular bundles -->\n        <circle cx=\"90\" cy=\"80\" r=\"7\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"145\" cy=\"85\" r=\"7\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"115\" cy=\"115\" r=\"7.5\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"80\" cy=\"125\" r=\"6\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"155\" cy=\"130\" r=\"6\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"110\" cy=\"60\" r=\"5\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"135\" cy=\"62\" r=\"5\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"70\" cy=\"100\" r=\"5\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <circle cx=\"170\" cy=\"100\" r=\"5\" fill=\"#fef2f2\" stroke=\"#dc2626\" stroke-width=\"1.2\"/>\n        <text x=\"120\" y=\"180\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">&bull; Scattered Bundles &bull; Closed (No Cambium)</text>\n      </g>\n\n      <!-- Stomatal Apparatus -->\n      <g transform=\"translate(570, 25)\">\n        <rect x=\"0\" y=\"0\" width=\"250\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"125\" y=\"24\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">STOMATAL APPARATUS</text>\n        <!-- Two kidney shaped guard cells -->\n        <path d=\"M 105,65 C 85,85 85,115 105,135 C 115,120 115,80 105,65\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n        <path d=\"M 145,65 C 165,85 165,115 145,135 C 135,120 135,80 145,65\" fill=\"#dcfce7\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n        <!-- Stomatal pore -->\n        <ellipse cx=\"125\" cy=\"100\" rx=\"6\" ry=\"20\" fill=\"#0f172a\"/>\n        <!-- Chloroplast dots in guard cells -->\n        <circle cx=\"102\" cy=\"90\" r=\"2\" fill=\"#15803d\"/><circle cx=\"102\" cy=\"110\" r=\"2\" fill=\"#15803d\"/>\n        <circle cx=\"148\" cy=\"90\" r=\"2\" fill=\"#15803d\"/><circle cx=\"148\" cy=\"110\" r=\"2\" fill=\"#15803d\"/>\n        <!-- Subsidiary cells -->\n        <path d=\"M 70,60 C 60,100 60,110 70,140\" stroke=\"#94a3b8\" stroke-width=\"1.5\" fill=\"none\"/>\n        <path d=\"M 180,60 C 190,100 190,110 180,140\" stroke=\"#94a3b8\" stroke-width=\"1.5\" fill=\"none\"/>\n        <text x=\"125\" y=\"158\" font-size=\"8.5\" fill=\"#334155\" text-anchor=\"middle\">Stomatal Pore + Guard Cells</text>\n        <text x=\"125\" y=\"172\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">+ Subsidiary Cells</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 12: Meristems, Tissues, Stomata, Monocot vs Dicot Anatomy, Secondary Growth & Periderm</div>\n\n  <!-- c11b-ch6-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State the location and function of different types of meristems.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Classification of Meristematic Tissues Based on Location in the Plant Body:</strong><br><br>\n    <strong>1. Apical Meristem:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><strong>Location:</strong> Situated at the growing tips of roots (Root Apical Meristem &mdash; RAM) and shoots (Shoot Apical Meristem &mdash; SAM).</li>\n      <li><strong>Function:</strong> Responsible for <strong>primary growth</strong> of the plant, causing elongation of the main axis and its branches, and producing primary permanent tissues (dermal, ground, and primary vascular tissues).</li>\n    </ul>\n    <strong>2. Intercalary Meristem:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><strong>Location:</strong> Located between mature permanent tissues, commonly at the base of internodes or leaf bases (e.g., in grasses, mint, and bamboo).</li>\n      <li><strong>Function:</strong> Facilitates rapid internodal elongation and regenerates parts removed by grazing herbivores (in grasses). Being derived from apical meristem, it is also a primary meristem.</li>\n    </ul>\n    <strong>3. Lateral Meristem:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><strong>Location:</strong> Arranged parallel to the longitudinal lateral axes of roots and stems (e.g., fascicular vascular cambium, interfascicular cambium, and cork cambium / phellogen).</li>\n      <li><strong>Function:</strong> Responsible for <strong>secondary growth</strong>, causing an increase in the girth (thickness/diameter) of the plant body by adding secondary xylem, secondary phloem, and cork.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Apical meristem: position at shoot/root apex and role in primary elongation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Intercalary meristem: position between mature tissues and role in internode elongation/regeneration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lateral meristem: parallel lateral position and role in secondary growth (girth increase)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Cork cambium forms tissues that form the cork. Do you agree with this statement? Explain.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: Yes, I fully agree with this statement.</strong><br><br>\n    <strong>Detailed Biological Explanation of Phellogen Activity:</strong><br>\n    As woody dicot stems and roots increase in girth due to secondary vascular growth, the peripheral epidermis and outer cortical layers experience severe tangential stress, stretching, and eventually rupture. To replace the broken protective epidermal layer, a secondary lateral meristem develops called the <strong>cork cambium</strong> (or <strong>phellogen</strong>):<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Origin of Phellogen:</strong> Typically arises from dedifferentiation of collenchymatous or parenchymatous cells in the outer cortex (hypodermis).</li>\n      <li><strong>Centrifugal &amp; Centripetal Activity:</strong> Phellogen cells are rectangular, thin-walled, and divide periclinally on both outer and inner faces:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Outer Cuts (Centrifugal):</strong> Differentiates into <strong>cork</strong> or <strong>phellem</strong>. Cells of phellem become dead at maturity, lose protoplasts, and their radial and tangential cell walls are heavily impregnated with an impervious waxy, fatty substance called <strong>suberin</strong>. This renders the cork completely impermeable to water and gases, protecting underlying living tissues from desiccation, mechanical abrasion, and pathogen entry.</li>\n          <li><strong>Inner Cuts (Centripetal):</strong> Differentiates into secondary cortex or <strong>phelloderm</strong>, composed of living parenchymatous cells containing chloroplasts or starch.</li>\n        </ul>\n      </li>\n      <li><strong>Periderm:</strong> Phellogen, phellem (cork), and phelloderm together constitute the protective secondary covering called the <strong>periderm</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative agreement and reason for phellogen initiation (rupture of epidermis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of cork (phellem) toward exterior by periclinal divisions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Suberized walls of cork conferring impermeability and protection; formation of periderm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the process of secondary growth in the stems of woody angiosperms with the help of schematic diagrams. What is its significance?\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Process of Secondary Growth in Dicot Stems:</strong><br>\n    Secondary growth is the increase in girth (thickness) caused by the activity of two lateral meristems: <strong>vascular cambium</strong> and <strong>cork cambium</strong>.<br><br>\n    <strong>A. Activity of Vascular Cambium (Stele Region):</strong>\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Formation of Cambial Ring:</strong> In dicot stems, intrafascicular cambium strip is present within open vascular bundles. The medullary ray cells adjacent to it dedifferentiate to form strips of <strong>interfascicular cambium</strong>. Together, they unite to form a continuous, circular <strong>cambial ring</strong>.</li>\n      <li><strong>Formation of Secondary Xylem &amp; Phloem:</strong> The cambial ring cuts off cells on both sides:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Towards the interior (pith): Differentiates into <strong>secondary xylem (wood)</strong>. Cambium is much more active internally; hence, secondary xylem accumulates rapidly.</li>\n          <li>Towards the exterior (cortex): Differentiates into <strong>secondary phloem</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Crushing of Primary Tissues:</strong> The relentless inward accumulation of secondary xylem crushes the primary and secondary phloem, cortex, and epidermis.</li>\n      <li><strong>Formation of Annual Rings:</strong> In temperate zones, cambium activity varies with seasons:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Spring wood (early wood):</em> Wide vessels with broad cavities formed when sap flow is high.</li>\n          <li><em>Autumn wood (late wood):</em> Narrow vessels with thick walls formed during winter dormancy.</li>\n          <li>One spring wood + one autumn wood ring forms one <strong>annual growth ring</strong>, used to determine the age of a tree (<strong>dendrochronology</strong>).</li>\n        </ul>\n      </li>\n      <li><strong>Heartwood vs. Sapwood:</strong> With age, central secondary xylem becomes plugged with tyloses, impregnated with tannins, resins, and oils, turning dark, hard, durable, and non-conducting (<strong>heartwood / duramen</strong>). Outer lighter, water-conducting wood is <strong>sapwood / alburnum</strong>.</li>\n    </ol>\n    <strong>B. Activity of Cork Cambium (Cortex Region):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Phellogen cuts off suberized cork (phellem) externally and phelloderm internally, forming the periderm. Phellogen produces lens-shaped openings called <strong>lenticels</strong> for gaseous exchange across the impermeable cork.</li>\n    </ul>\n    <strong>Biological Significance of Secondary Growth:</strong><br>\n    1. Increases mechanical strength and rigidity to support large woody tree trunks.<br>\n    2. Replaces damaged, worn-out primary vascular elements with massive secondary conduits.<br>\n    3. Provides commercial timber, cork, resins, and tannins.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of continuous cambial ring from intra- and interfascicular cambium</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of secondary xylem internally and secondary phloem externally</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Spring wood vs autumn wood, annual rings and heartwood vs sapwood</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phellogen, periderm, and lenticels in extra-stelar region</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three points of biological significance (strength, conducting capacity, perennation)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw illustrations to bring out the anatomical difference between: (a) Monocot root and Dicot root (b) Monocot stem and Dicot stem.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Anatomical Differences Between Dicot Root and Monocot Root:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Anatomical Feature</th><th style=\"padding:6px 10px;\">Dicot Root (e.g., Sunflower / Gram)</th><th style=\"padding:6px 10px;\">Monocot Root (e.g., Maize)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">1. Vascular Bundles</td><td style=\"padding:6px 10px;\">Diarch to hexarch (usually <strong>2 to 4, rarely 6</strong> xylem &amp; phloem patches).</td><td style=\"padding:6px 10px;\"><strong>Polyarch</strong> (more than 6, often 8 to 20 or more xylem/phloem bundles).</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">2. Pith (Medulla)</td><td style=\"padding:6px 10px;\">Extremely small, inconspicuous or completely absent.</td><td style=\"padding:6px 10px;\">Large, well-developed, and prominent.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">3. Cambium &amp; Secondary Growth</td><td style=\"padding:6px 10px;\">Vascular cambium arises secondarily from pericycle and conjunctive tissue; undergoes prominent secondary growth.</td><td style=\"padding:6px 10px;\">Cambium completely absent; no secondary growth occurs.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Anatomical Differences Between Dicot Stem and Monocot Stem:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Anatomical Feature</th><th style=\"padding:6px 10px;\">Dicot Stem (e.g., Sunflower)</th><th style=\"padding:6px 10px;\">Monocot Stem (e.g., Maize)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">1. Hypodermis</td><td style=\"padding:6px 10px;\"><strong>Collenchymatous</strong> (provides flexible tensile support).</td><td style=\"padding:6px 10px;\"><strong>Sclerenchymatous</strong> (provides rigid mechanical support).</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">2. Ground Tissue</td><td style=\"padding:6px 10px;\">Differentiated into cortex, endodermis, pericycle, medullary rays, and central pith.</td><td style=\"padding:6px 10px;\">Undifferentiated continuous mass of parenchyma extending from hypodermis to center.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">3. Vascular Bundles</td><td style=\"padding:6px 10px;\">Conjoint, collateral, <strong>open</strong> (cambium present), arranged in a neat broken <strong>ring</strong>.</td><td style=\"padding:6px 10px;\">Conjoint, collateral, <strong>closed</strong> (no cambium), <strong>scattered</strong> throughout ground tissue.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">4. Bundle Sheath &amp; Phloem Parenchyma</td><td style=\"padding:6px 10px;\">Bundle sheath absent; phloem parenchyma present.</td><td style=\"padding:6px 10px;\">Surrounded by prominent sclerenchymatous <strong>bundle sheath</strong>; phloem parenchyma absent.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Dicot vs Monocot root: bundle number (diarch/tetrarch vs polyarch), pith size, cambium</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Dicot vs Monocot stem: hypodermis (collenchyma vs sclerenchyma), bundle arrangement (ring vs scattered), open vs closed</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Cut a transverse section of young stem of a plant from your school garden and observe it under the microscope. How would you ascertain whether it is a monocot stem or a dicot stem? Give reasons.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Microscopic Diagnostic Criteria to Distinguish Monocot Stem from Dicot Stem:</strong><br><br>\n    Upon examining the stained transverse section (T.S.) under high-power magnification, observe the following diagnostic structural features:<br><br>\n    <strong>A. Signs Confirming a DICOT Stem:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Ring Arrangement of Vascular Bundles:</strong> Vascular bundles are uniform, wedge-shaped, and arranged in a clean, orderly circular ring around the central axis.</li>\n      <li><strong>Open Vascular Bundles:</strong> A distinct strip of meristematic <strong>intrafascicular cambium</strong> is sandwiched between the outer phloem and inner xylem.</li>\n      <li><strong>Differentiated Ground Tissue:</strong> Ground tissue is clearly demarcated into an outer collenchymatous hypodermis, a multi-layered parenchymatous cortex, a wavy starch sheath (endodermis), a pericycle with sclerenchymatous semilunar patches, and a prominent central parenchymatous <strong>pith</strong>.</li>\n    </ul>\n    <strong>B. Signs Confirming a MONOCOT Stem:</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Scattered Vascular Bundles:</strong> Numerous oval vascular bundles are randomly scattered throughout an undifferentiated parenchymatous ground tissue (smaller bundles crowded towards periphery, larger ones towards the center).</li>\n      <li><strong>Closed Vascular Bundles:</strong> Cambium is completely absent (bundles are closed).</li>\n      <li><strong>Sclerenchymatous Bundle Sheath:</strong> Each bundle is encased by a dense sheath of sclerenchyma fibers.</li>\n      <li><strong>Y- or V-shaped Xylem:</strong> Xylem vessels are arranged in the shape of the letter 'Y' with a prominent lysigenous water cavity (protoxylem lacuna).</li>\n      <li><strong>Absence of Phloem Parenchyma:</strong> Phloem consists solely of sieve tubes and companion cells.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Vascular bundle arrangement: ring in dicot vs scattered in monocot</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bundle nature: open (cambium present) in dicot vs closed (cambium absent) in monocot</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ground tissue: differentiated (cortex, endodermis, pith) in dicot vs undifferentiated in monocot</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        The transverse section of a plant material shows the following anatomical features: (a) the vascular bundles are conjoint, scattered and surrounded by a sclerenchymatous bundle sheaths (b) phloem parenchyma is absent. What will you identify it as?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Identification:</strong><br>\n    The plant material is definitively identified as a <strong>Monocotyledonous Stem</strong> (e.g., <em>Zea mays</em> / Maize stem).<br><br>\n    <strong>Detailed Scientific Justification:</strong><br>\n    <ul style=\"margin:6px 0 10px 20px;\">\n      <li><strong>1. \"Vascular bundles are conjoint and scattered\":</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Conjoint:</em> Xylem and phloem lie along the same radial plane, a hallmark of stems (roots have radial bundles where xylem and phloem lie on alternating radii).</li>\n          <li><em>Scattered:</em> Scattered distribution (atactostele) throughout the undifferentiated parenchymatous ground tissue is an exclusive anatomical signature of monocot stems. Dicot stems have bundles arranged in a neat single ring.</li>\n        </ul>\n      </li>\n      <li><strong>2. \"Surrounded by a sclerenchymatous bundle sheath\":</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>In monocot stems, every vascular bundle is completely encased by a prominent fibrous sheath of dead, lignified sclerenchyma cells providing rigidity, which is absent in dicot stems.</li>\n        </ul>\n      </li>\n      <li><strong>3. \"Phloem parenchyma is absent\":</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>A classic textbook diagnostic feature of monocot stems is the total absence of phloem parenchyma (phloem consists only of sieve tube elements and companion cells). In contrast, phloem parenchyma is abundantly present in dicot stems.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate identification as Monocotyledonous Stem (e.g., Maize stem)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification of conjoint & scattered bundles vs dicot ring arrangement</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Justification of sclerenchymatous bundle sheath and absence of phloem parenchyma</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why are xylem and phloem called complex tissues?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Explanation for Classifying Xylem and Phloem as Complex Permanent Tissues:</strong><br><br>\n    <strong>1. Definition of Complex Tissue:</strong><br>\n    In plant anatomy, a <strong>simple permanent tissue</strong> (such as parenchyma, collenchyma, and sclerenchyma) is composed of only one type of structurally and functionally identical cell. In contrast, a <strong>complex tissue</strong> is composed of <strong>more than one type of cell</strong> that originate from the same meristem and coordinate harmoniously as a unified physiological unit to perform a common transport function.<br><br>\n    <strong>2. Cellular Heterogeneity of Xylem (Wood):</strong><br>\n    Xylem is composed of four distinct cellular elements coordinating to conduct water, dissolved mineral ions, and provide mechanical strength:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>Tracheids:</em> Elongated dead tube-like cells with tapering ends and bordered pits.</li>\n      <li><em>Vessels (Tracheae):</em> Long cylindrical syncytial tubes with perforated end walls.</li>\n      <li><em>Xylem Fibres:</em> Highly thickened, lignified dead sclerenchymatous fibers offering mechanical tensile strength.</li>\n      <li><em>Xylem Parenchyma:</em> The only <strong>living</strong> cells of xylem, storing starch, fats, and assisting radial water transport.</li>\n    </ul>\n    <strong>3. Cellular Heterogeneity of Phloem (Bast):</strong><br>\n    Phloem is composed of four distinct cellular elements coordinating to translocate organic photosynthates (sucrose):\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>Sieve Tube Elements:</em> Long tubular conducting cells with perforated end walls (sieve plates); enucleated at maturity.</li>\n      <li><em>Companion Cells:</em> Specialized nucleated parenchymatous sister cells maintaining the metabolic pressure gradient of sieve tubes.</li>\n      <li><em>Phloem Parenchyma:</em> Living elongated cells storing resins, latex, mucilage, and food.</li>\n      <li><em>Phloem Fibres (Bast Fibres):</em> Dead lignified sclerenchymatous fibers providing tensile strength (e.g., jute, flax, hemp).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of complex tissue (composed of multiple cell types functioning as a single unit)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Four cellular components of xylem and their roles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Four cellular components of phloem and their roles</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is stomatal apparatus? Explain the structure of stomata with a labelled diagram.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Stomatal Apparatus:</strong><br>\n    The <strong>stomatal apparatus</strong> is the specialized epidermal functional complex consisting of the microscopic <strong>stomatal aperture (pore)</strong>, flanked by a pair of specialized <strong>guard cells</strong>, and surrounded by specialized epidermal cells called <strong>subsidiary (accessory) cells</strong>.<br><br>\n    <strong>Detailed Structural Components:</strong><br><br>\n    <strong>1. Stomatal Pore:</strong><br>\n    A minute elliptical opening in the leaf epidermis through which gaseous exchange ($CO_2$ uptake, $O_2$ release) and evaporative water loss (transpiration) occur.<br><br>\n    <strong>2. Guard Cells:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Shape:</strong> Typically <strong>kidney-shaped (reniform)</strong> in dicot leaves, and <strong>dumbbell-shaped</strong> in grasses and monocots.</li>\n      <li><strong>Wall Thickening:</strong> The inner wall facing the stomatal pore is thick, rigid, and inelastic, whereas the outer wall away from the pore is thin, elastic, and flexible.</li>\n      <li><strong>Cellular Contents:</strong> Unlike ordinary epidermal cells, guard cells possess a conspicuous nucleus, abundant cytoplasm, and functional <strong>chloroplasts</strong>.</li>\n      <li><strong>Stomatal Mechanism:</strong> When potassium ions ($K^+$) and water enter guard cells, turgor pressure increases, causing the thin outer walls to bulge outward; this pulls the thick inner concave walls apart, <strong>opening the stomatal pore</strong>. When turgor drops, the walls relax, <strong>closing the pore</strong>.</li>\n    </ul>\n    <strong>3. Subsidiary Cells:</strong><br>\n    Specialized epidermal cells surrounding the guard cells that serve as chemical and water reservoirs, facilitating rapid ionic and turgor adjustments in guard cells.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of stomatal apparatus (pore + guard cells + subsidiary cells)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed structural description of guard cells (kidney/dumbbell, inner vs outer wall thickening, chloroplasts)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of stomatal opening and closing via turgor pressure changes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the three basic tissue systems in the flowering plants. Give the tissue names under each system.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The Three Basic Tissue Systems in Flowering Plants (Julius von Sachs, 1875):</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Tissue System</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Constituent Tissues / Cellular Elements</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Primary Physiological Functions</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Epidermal Tissue System</td>\n            <td style=\"padding:8px 12px;\">\n              &bull; Epidermis with waxy cuticle<br>\n              &bull; Stomata (guard cells &amp; subsidiary cells)<br>\n              &bull; Epidermal appendages: <strong>Trichomes</strong> (stem hairs) and <strong>Root hairs</strong> (unicellular tubular absorbs)\n            </td>\n            <td style=\"padding:8px 12px;\">Protection against desiccation and mechanical injury, gas exchange, transpiration, and water/mineral absorption.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Ground (Fundamental) Tissue System</td>\n            <td style=\"padding:8px 12px;\">\n              &bull; Hypodermis (collenchyma / sclerenchyma)<br>\n              &bull; General cortex (parenchyma)<br>\n              &bull; Endodermis (starch sheath / Casparian strips)<br>\n              &bull; Pericycle<br>\n              &bull; Medullary rays and central <strong>Pith</strong><br>\n              &bull; <strong>Mesophyll</strong> in leaves (palisade &amp; spongy)\n            </td>\n            <td style=\"padding:8px 12px;\">Photosynthesis (mesophyll), nutrient/starch storage, secretor functions, and mechanical tensile support.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Vascular (Conducting) Tissue System</td>\n            <td style=\"padding:8px 12px;\">\n              &bull; <strong>Xylem:</strong> Tracheids, vessels, xylem fibres, xylem parenchyma<br>\n              &bull; <strong>Phloem:</strong> Sieve tubes, companion cells, phloem fibres, phloem parenchyma<br>\n              &bull; <strong>Cambium</strong> (in open bundles of dicots)\n            </td>\n            <td style=\"padding:8px 12px;\">Long-distance translocation of sap (water/minerals via xylem) and photosynthates (sucrose via phloem); mechanical support.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Epidermal tissue system: epidermis, stomata, trichomes, root hairs</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Ground tissue system: cortex, endodermis, pericycle, pith, mesophyll</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Vascular tissue system: xylem, phloem, and vascular cambium</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How is the study of plant anatomy useful to us?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Practical Applications and Utility of Plant Anatomy:</strong><br>\n    The anatomical study of internal plant structure has immense industrial, agricultural, and scientific value:<br><br>\n    <strong>1. Quality Control &amp; Pharmacognosy:</strong><br>\n    Enables identification of adulterants and counterfeits in commercial herbal medicines, spices (cinnamon, saffron, cloves), and crude botanical drugs by examining microscopic cell structures (trichomes, stomata, calcium oxalate raphides/druses).<br><br>\n    <strong>2. Timber &amp; Wood Technology:</strong><br>\n    Helps timber industries distinguish high-strength hardwood from softwood, evaluate grain patterns, determine fiber length for paper pulp quality, and calculate tree age via dendrochronology (annual growth rings).<br><br>\n    <strong>3. Crop Breeding and Disease Resistance:</strong><br>\n    Breeding scientists evaluate anatomical barriers against pests and pathogens: thick cuticles, sclerenchymatous hypodermis, and dense silicified epidermis confer resistance to sucking insect pests and fungal hyphal penetration.<br><br>\n    <strong>4. Evolutionary Phylogeny &amp; Taxonomy:</strong><br>\n    Internal structural features (vascular bundle arrangement, vessel perforation plates, nodal anatomy) help resolve complex taxonomic disputes and decipher evolutionary relationships among plant families.<br><br>\n    <strong>5. Forensic Botany:</strong><br>\n    Fragmented leaf, root, or wood evidence found at crime scenes can be matched to precise botanical species through micro-anatomical sectioning.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Pharmacognosy & detection of adulteration in herbal drugs and spices</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Timber industry (wood quality, paper pulp, dendrochronology)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Crop breeding for pest resistance, taxonomic classification, and forensic botany</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is periderm? How does periderm formation take place in the dicot stems?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Periderm:</strong><br>\n    The <strong>periderm</strong> is a protective secondary tissue of secondary origin that replaces the ruptured epidermis of stems and roots during secondary growth. It is composed of three distinct concentric layers:\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Phellogen:</strong> Cork cambium (the secondary lateral meristem).</li>\n      <li><strong>Phellem:</strong> Cork (outer dead, suberized protective layer).</li>\n      <li><strong>Phelloderm:</strong> Secondary cortex (inner living parenchymatous layer).</li>\n    </ol>\n    <strong>Step-by-Step Formation of Periderm in Dicot Stems:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Trigger:</strong> Due to continuous formation of secondary xylem and phloem by vascular cambium, internal pressure stretches and breaks the primary epidermis and outer cortex.</li>\n      <li><strong>2. Dedifferentiation to form Phellogen:</strong> Mature living parenchymatous or collenchymatous cells in the sub-epidermal layer (outer cortex) dedifferentiate into a secondary meristem called <strong>phellogen (cork cambium)</strong>.</li>\n      <li><strong>3. Periclinal Cell Divisions:</strong> Phellogen cells divide periclinally, giving off cells towards the exterior and interior:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Centrifugally (Outer):</em> Cut-off cells lose protoplasm and become dead, compactly arranged hexagonal cells impregnated with <strong>suberin</strong>, forming the impervious <strong>phellem (cork)</strong>.</li>\n          <li><em>Centripetally (Inner):</em> Cut-off cells mature into living parenchymatous cells with cellulosic walls, forming the <strong>phelloderm (secondary cortex)</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>4. Formation of Lenticels:</strong> At certain intervals, phellogen produces loosely arranged, thin-walled parenchymatous cells called <strong>complementary cells</strong> instead of suberized cork. These rupture the epidermis to form lens-shaped aerating pores called <strong>lenticels</strong>, permitting vital gas exchange across the impermeable cork layer.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of periderm and naming its three constituent layers (phellogen, phellem, phelloderm)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Origin of phellogen from cortical dedifferentiation due to secondary expansion stress</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Activity of phellogen: suberized dead cork externally and living phelloderm internally</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation and gas exchange function of lenticels with complementary cells</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch6-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch6-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch6-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the internal structure of a dorsiventral leaf with the help of labelled diagram.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical Architecture of a Dorsiventral (Dicotyledonous) Leaf:</strong><br>\n    A transverse section (T.S.) of a typical dorsiventral leaf (e.g., Sunflower / Mango) shows three distinct tissue regions:<br><br>\n    <strong>1. Epidermis (Upper &amp; Lower):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Adaxial Epidermis (Upper):</strong> Covered by a thick, waxy, water-impermeable <strong>cuticle</strong>; generally bears fewer or no stomata (hypostomatic condition).</li>\n      <li><strong>Abaxial Epidermis (Lower):</strong> Bears numerous stomata with kidney-shaped guard cells to facilitate transpiration and gas exchange, covered by a thinner cuticle.</li>\n    </ul>\n    <strong>2. Mesophyll (Ground Tissue):</strong><br>\n    The green photosynthetic tissue sandwiched between upper and lower epidermis, richly packed with chloroplasts and differentiated into two distinct zones:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Palisade Parenchyma (Adaxial):</strong> Located beneath the upper epidermis; composed of vertically elongated, columnar, tightly packed cylindrical cells with narrow intercellular spaces, maximizing sunlight absorption.</li>\n      <li><strong>Spongy Parenchyma (Abaxial):</strong> Located below palisade cells and extending to the lower epidermis; composed of loosely arranged, oval or spherical cells with large intercellular spaces and conspicuous <strong>air cavities (sub-stomatal chambers)</strong> facilitating rapid gaseous diffusion.</li>\n    </ul>\n    <strong>3. Vascular System (Vascular Bundles):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Seen in the veins and midrib. Reticulate venation results in bundles of varying sizes.</li>\n      <li>Each bundle is <strong>conjoint, collateral, and closed</strong> (no cambium).</li>\n      <li>Xylem lies towards the upper (adaxial) surface, while phloem lies towards the lower (abaxial) surface.</li>\n      <li>Each vascular bundle is completely encased by a prominent layer of tightly packed parenchymatous cells called the <strong>bundle sheath</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Epidermis: adaxial vs abaxial, cuticle thickness, and stomatal distribution</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mesophyll: palisade parenchyma (columnar, tight) vs spongy parenchyma (loose, air cavities)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vascular bundles: conjoint, collateral, closed, xylem facing adaxial, phloem abaxial</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bundle sheath surrounding veins</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 5</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 7 (Structural Organisation in Animals) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[7] = "<section class=\"chapter-section\" id=\"c11b-ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 7</div>\n      <h2>Structural Organisation in Animals</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 14 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      Animal Tissues (Epithelial &amp; Muscular) &amp; Frog Morpho-Anatomy\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"30\" font-size=\"11\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">FUNDAMENTAL ANIMAL TISSUES &amp; INTERCELLULAR JUNCTIONS</text>\n\n      <!-- 1. Squamous Epithelium -->\n      <g transform=\"translate(30, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"170\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"85\" y=\"22\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Squamous Epithelium</text>\n        <!-- Flat tiles -->\n        <polygon points=\"25,60 75,50 95,80 45,90\" fill=\"#ecfdf5\" stroke=\"#059669\"/>\n        <circle cx=\"60\" cy=\"70\" r=\"4\" fill=\"#047857\"/>\n        <polygon points=\"75,50 125,55 145,85 95,80\" fill=\"#ecfdf5\" stroke=\"#059669\"/>\n        <circle cx=\"110\" cy=\"68\" r=\"4\" fill=\"#047857\"/>\n        <polygon points=\"45,90 95,80 115,115 65,125\" fill=\"#ecfdf5\" stroke=\"#059669\"/>\n        <circle cx=\"80\" cy=\"102\" r=\"4\" fill=\"#047857\"/>\n        <text x=\"85\" y=\"145\" font-size=\"8\" fill=\"#334155\" text-anchor=\"middle\">Single layer of flattened cells</text>\n        <text x=\"85\" y=\"158\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Diffusion boundary (Alveoli, Capillaries)</text>\n      </g>\n\n      <!-- 2. Cuboidal & Columnar -->\n      <g transform=\"translate(225, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"180\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"90\" y=\"22\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Columnar / Ciliated</text>\n        <!-- Tall pillar cells with cilia -->\n        <line x1=\"30\" y1=\"52\" x2=\"150\" y2=\"52\" stroke=\"#64748b\" stroke-dasharray=\"2,2\"/>\n        <rect x=\"35\" y=\"55\" width=\"25\" height=\"65\" fill=\"#eff6ff\" stroke=\"#2563eb\"/>\n        <ellipse cx=\"47\" cy=\"100\" rx=\"4\" ry=\"7\" fill=\"#1e40af\"/>\n        <rect x=\"65\" y=\"55\" width=\"25\" height=\"65\" fill=\"#eff6ff\" stroke=\"#2563eb\"/>\n        <ellipse cx=\"77\" cy=\"100\" rx=\"4\" ry=\"7\" fill=\"#1e40af\"/>\n        <rect x=\"95\" y=\"55\" width=\"25\" height=\"65\" fill=\"#eff6ff\" stroke=\"#2563eb\"/>\n        <ellipse cx=\"107\" cy=\"100\" rx=\"4\" ry=\"7\" fill=\"#1e40af\"/>\n        <rect x=\"125\" y=\"55\" width=\"25\" height=\"65\" fill=\"#eff6ff\" stroke=\"#2563eb\"/>\n        <ellipse cx=\"137\" cy=\"100\" rx=\"4\" ry=\"7\" fill=\"#1e40af\"/>\n        <!-- Cilia on apical surface -->\n        <line x1=\"47\" y1=\"55\" x2=\"47\" y2=\"45\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n        <line x1=\"77\" y1=\"55\" x2=\"77\" y2=\"45\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n        <line x1=\"107\" y1=\"55\" x2=\"107\" y2=\"45\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n        <line x1=\"137\" y1=\"55\" x2=\"137\" y2=\"45\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n        <text x=\"90\" y=\"145\" font-size=\"8\" fill=\"#334155\" text-anchor=\"middle\">Basal nuclei &amp; Apical cilia</text>\n        <text x=\"90\" y=\"158\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"middle\">Bronchioles, Fallopian tubes</text>\n      </g>\n\n      <!-- 3. Muscle Tissues -->\n      <g transform=\"translate(430, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"180\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"90\" y=\"22\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Muscle Fiber Types</text>\n        <!-- Skeletal muscle with striations -->\n        <rect x=\"25\" y=\"42\" width=\"130\" height=\"18\" rx=\"3\" fill=\"#fee2e2\" stroke=\"#dc2626\"/>\n        <line x1=\"40\" y1=\"42\" x2=\"40\" y2=\"60\" stroke=\"#b91c1c\"/><line x1=\"60\" y1=\"42\" x2=\"60\" y2=\"60\" stroke=\"#b91c1c\"/><line x1=\"80\" y1=\"42\" x2=\"80\" y2=\"60\" stroke=\"#b91c1c\"/>\n        <line x1=\"100\" y1=\"42\" x2=\"100\" y2=\"60\" stroke=\"#b91c1c\"/><line x1=\"120\" y1=\"42\" x2=\"120\" y2=\"60\" stroke=\"#b91c1c\"/>\n        <text x=\"90\" y=\"73\" font-size=\"7.5\" fill=\"#991b1b\" text-anchor=\"middle\">Skeletal: Striated, Syncytial, Voluntary</text>\n\n        <!-- Smooth muscle spindle -->\n        <path d=\"M 25,95 Q 90,82 155,95 Q 90,108 25,95\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n        <circle cx=\"90\" cy=\"95\" r=\"3.5\" fill=\"#b45309\"/>\n        <text x=\"90\" y=\"118\" font-size=\"7.5\" fill=\"#92400e\" text-anchor=\"middle\">Smooth: Non-striated, Uninucleate, Involuntary</text>\n\n        <!-- Cardiac muscle -->\n        <rect x=\"25\" y=\"128\" width=\"130\" height=\"18\" rx=\"3\" fill=\"#fdf4ff\" stroke=\"#a21caf\"/>\n        <line x1=\"75\" y1=\"128\" x2=\"75\" y2=\"146\" stroke=\"#86198f\" stroke-width=\"2.5\"/>\n        <text x=\"90\" y=\"158\" font-size=\"7.5\" fill=\"#701a75\" text-anchor=\"middle\">Cardiac: Intercalated Discs, Involuntary</text>\n      </g>\n\n      <!-- 4. Cellular Junctions -->\n      <g transform=\"translate(635, 45)\">\n        <rect x=\"0\" y=\"0\" width=\"185\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"92\" y=\"22\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Epithelial Junctions</text>\n        <rect x=\"20\" y=\"40\" width=\"145\" height=\"34\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n        <text x=\"25\" y=\"55\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\">Tight Junction:</text>\n        <text x=\"25\" y=\"67\" font-size=\"7.5\" fill=\"#475569\">Prevents leakage across tissue</text>\n\n        <rect x=\"20\" y=\"80\" width=\"145\" height=\"34\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n        <text x=\"25\" y=\"95\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\">Adhering Junction:</text>\n        <text x=\"25\" y=\"107\" font-size=\"7.5\" fill=\"#475569\">Cements neighboring cells</text>\n\n        <rect x=\"20\" y=\"120\" width=\"145\" height=\"34\" rx=\"4\" fill=\"#ffffff\" stroke=\"#94a3b8\"/>\n        <text x=\"25\" y=\"135\" font-size=\"8\" font-weight=\"bold\" fill=\"#16a34a\">Gap Junction:</text>\n        <text x=\"25\" y=\"147\" font-size=\"7.5\" fill=\"#475569\">Ionic channels for communication</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 14: Animal Tissues, Epithelial Junctions, Cockroach Anatomy & Frog Sexual Dimorphism</div>\n\n  <!-- c11b-ch7-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Answer in one word or one sentence:<br>(i) Give the common name of <em>Periplaneta americana</em>.<br>(ii) How many spermathecae are found in earthworm / cockroach?<br>(iii) What is the position of ovaries in cockroach?<br>(iv) How many segments are present in the abdomen of cockroach?<br>(v) Where do you find Malpighian tubules?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Precise Anatomical Answers:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(i) Common name of <em>Periplaneta americana</em>:</strong><br>\n      <strong>American Cockroach</strong> (common household pest).</li>\n      <li><strong>(ii) Spermathecae in cockroach / earthworm:</strong><br>\n      In female cockroach, there is <strong>one pair of spermathecae</strong> (situated in the 6th abdominal segment). <em>(In earthworm, there are 4 pairs situated in 6th to 9th segments).</em></li>\n      <li><strong>(iii) Position of ovaries in cockroach:</strong><br>\n      A pair of large ovaries lies laterally in the <strong>2nd to 6th abdominal segments</strong> embedded in fat bodies.</li>\n      <li><strong>(iv) Number of segments in the abdomen of cockroach:</strong><br>\n      The abdomen in both male and female adult cockroaches consists of <strong>10 segments</strong> (embryo has 11 segments).</li>\n      <li><strong>(v) Location of Malpighian tubules:</strong><br>\n      At the junction of the <strong>midgut (mesenteron) and hindgut (ileum)</strong> in cockroach, floating freely in the hemolymph.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) American cockroach & (ii) One pair of spermathecae in female cockroach</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) 2nd to 6th abdominal segments & (iv) 10 segments in abdomen</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(v) Junction of midgut and hindgut</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Answer the following: (i) What is the function of a nephron / nephridium? (ii) How many types of nephridia are found in earthworm based on location?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(i) Function of a Nephron / Nephridium:</strong><br>\n    The <strong>nephron</strong> (in vertebrates) and <strong>nephridium</strong> (in invertebrates like annelids) is the microscopic structural and functional unit of the excretory system. Its primary physiological functions are:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Excretion:</strong> Ultrafiltration of blood/coelomic fluid, selective reabsorption of vital solutes (glucose, amino acids, ions), and active tubular secretion to eliminate metabolic nitrogenous wastes (urea, ammonia, or uric acid).</li>\n      <li><strong>Osmoregulation:</strong> Regulates the volume, water content, and ionic electrolyte balance ($Na^+$, $K^+$, $Cl^-$) of body fluids.</li>\n    </ul>\n    <strong>(ii) Three Types of Nephridia in Earthworm Based on Location:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Septal Nephridia:</strong> Present on both sides of intersegmental septa from segment 15 to the last segment opening into intestine (enteronephric).</li>\n      <li><strong>2. Integumentary Nephridia:</strong> Minute nephridia attached to the inner body wall lining from segment 3 to the last, discharging wastes directly to exterior (exonephric).</li>\n      <li><strong>3. Pharyngeal Nephridia:</strong> Present as three paired tufts in segments 4, 5, and 6 opening into the pharynx and buccal cavity (enteronephric).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Dual function: excretion of nitrogenous wastes and osmoregulatory fluid balance</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Three types based on location: Septal, Integumentary, and Pharyngeal nephridia</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw a neat labelled diagram of the alimentary canal of a cockroach.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical Organization of the Alimentary Canal of Cockroach (<em>Periplaneta americana</em>):</strong><br>\n    The digestive tract is divided into three distinct morphological regions:<br><br>\n    <strong>1. Foregut (Stomodaeum) &mdash; Ectodermal, lined with cuticular intima:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Mouth &amp; Pharynx:</strong> Opens into a short muscular pharynx, receiving ducts from paired <strong>salivary glands</strong> and salivary reservoirs.</li>\n      <li><strong>Oesophagus:</strong> A narrow, thin-walled tube leading into a large, thin-walled sac called the <strong>crop</strong> (used for temporary food storage).</li>\n      <li><strong>Gizzard (Proventriculus):</strong> A thick, circular muscular organ equipped internally with <strong>six chitinous cuticular teeth</strong> and bristles that grind food particles into a fine powder.</li>\n    </ul>\n    <strong>2. Midgut (Mesenteron / Ventriculus) &mdash; Endodermal, true digestive zone:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>At the junction of gizzard and midgut, there is a ring of <strong>6 to 8 blind tubular finger-like Hepatic (Gastric) Caeca</strong> that secrete digestive enzymes (amylases, maltases, lipases).</li>\n      <li>Midgut lumen is lined by the permeable peritrophic membrane protecting epithelial cells.</li>\n    </ul>\n    <strong>3. Hindgut (Proctodaeum) &mdash; Ectodermal, lined with cuticle:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>At the junction of midgut and hindgut, there are <strong>100 to 150 yellow, fine, hair-like Malpighian tubules</strong> (excretory in function).</li>\n      <li>Differentiated into: (i) short narrow <strong>ileum</strong>, (ii) long coiled <strong>colon</strong>, and (iii) broad <strong>rectum</strong> with 6 rectal papillae for water and salt reabsorption, opening at the anus.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Foregut components: pharynx, oesophagus, salivary glands, crop (storage), gizzard with 6 teeth</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Midgut with 6-8 hepatic caeca for digestive enzyme secretion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hindgut with Malpighian tubules (100-150), ileum, colon, and rectum with rectal papillae</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Compare the following: (a) Simple epithelium and compound epithelium (b) Cardiac muscle and striated muscle (c) Dense regular and dense irregular connective tissues (d) Adipose and blood tissue (e) Simple gland and compound gland.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comparative Analysis of Tissue Pairs:</strong><br><br>\n    <strong>(a) Simple Epithelium vs. Compound Epithelium:</strong><br>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Simple:</em> Composed of a <strong>single layer</strong> of cells resting on a basement membrane. Functions in absorption, secretion, and filtration (e.g., lining of stomach, renal tubules, lung alveoli).</li>\n      <li><em>Compound (Stratified):</em> Composed of <strong>two or more layers</strong> of cells. Main function is providing mechanical and chemical protection against stress and wear-and-tear (e.g., skin epidermis, buccal cavity, pharynx).</li>\n    </ul>\n    <strong>(b) Cardiac Muscle vs. Striated (Skeletal) Muscle:</strong><br>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Cardiac Muscle:</em> Involuntary, branched, uninucleate fibers located exclusively in the heart wall, possessing specialized zig-zag communicating junctions called <strong>intercalated discs</strong> with gap junctions. Never undergoes fatigue.</li>\n      <li><em>Striated Muscle:</em> Voluntary, unbranched, multinucleate (syncytial) cylindrical fibers attached to skeletal bones. Subject to fatigue upon prolonged lactic acid accumulation.</li>\n    </ul>\n    <strong>(c) Dense Regular vs. Dense Irregular Connective Tissue:</strong><br>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Dense Regular:</em> Collagen fibers are packed in parallel bundles between rows of fibroblasts, providing high unidirectional tensile strength (e.g., <strong>tendons</strong> connecting muscle to bone, <strong>ligaments</strong> connecting bone to bone).</li>\n      <li><em>Dense Irregular:</em> Fibroblasts and fibers (predominantly collagen) are oriented in criss-cross, irregular random directions to resist mechanical forces from multiple angles (e.g., in the <strong>dermis of skin</strong>).</li>\n    </ul>\n    <strong>(d) Adipose Tissue vs. Blood:</strong><br>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Adipose:</em> Loose connective tissue specialized in synthesizing and storing neutral fats (triglycerides) within adipocytes; acts as a subcutaneous heat insulator and shock-absorbing cushion.</li>\n      <li><em>Blood:</em> Fluid connective tissue comprising plasma (55%) and formed cellular elements (RBCs, WBCs, platelets); translocates respiratory gases, nutrients, and hormones throughout the body.</li>\n    </ul>\n    <strong>(e) Simple Gland vs. Compound Gland:</strong><br>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><em>Simple Gland:</em> Has an <strong>unbranched duct</strong> leading from secretory units (e.g., sweat glands, gastric glands, crypts of Lieberk&uuml;hn).</li>\n      <li><em>Compound Gland:</em> Has a repeatedly <strong>branched duct</strong> system (e.g., salivary glands, exocrine pancreas, mammary glands).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Simple (single layer, absorption) vs Compound (multi-layered, protection)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cardiac (branched, intercalated discs, involuntary) vs Striated (syncytial, voluntary)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Dense regular (parallel fibers, tendons) vs irregular (random criss-cross, dermis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Adipose (fat storage, insulation) vs Blood (fluid plasma, gas transport)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Simple gland (unbranched duct) vs Compound gland (branched duct)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the following and where do you find them in animal body: (a) Chondrocytes (b) Axons (c) Ciliated epithelium?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition, Identity &amp; Anatomical Distribution:</strong><br><br>\n    <strong>(a) Chondrocytes:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>What they are:</strong> Mature cartilage-forming cells that reside enclosed in fluid-filled cavities called <strong>lacunae</strong> within the pliable, solid, non-vascular chondroitin sulfate matrix of cartilage.</li>\n      <li><strong>Where found:</strong> At the tip of the human nose, outer ear pinna, intervertebral discs, ring supports of trachea, and articular surfaces of long bones.</li>\n    </ul>\n    <strong>(b) Axons:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>What they are:</strong> Long, slender, cylindrical cytoplasmic nerve fiber projections arising from the cyton (soma) of a neuron that conduct action potentials (nerve impulses) away from the cell body toward synaptic terminals.</li>\n      <li><strong>Where found:</strong> In peripheral nerves, white matter tracts of the brain and spinal cord, and sensory/motor nerves throughout the body.</li>\n    </ul>\n    <strong>(c) Ciliated Epithelium:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>What it is:</strong> A specialized epithelial tissue consisting of cuboidal or columnar cells bearing hundreds of hair-like protoplasmic projections called <strong>cilia</strong> on their apical free surface. Cilia beat rhythmically to propel particles, mucus, or fluids in a specific direction.</li>\n      <li><strong>Where found:</strong> Inner lining of the <strong>respiratory tract (bronchioles and trachea)</strong> to sweep out inhaled dust particles and mucus, and inner lining of the <strong>Fallopian tubes (oviducts)</strong> to propel ova towards the uterus.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Chondrocytes: definition (cartilage cells in lacunae) & location (nose tip, pinna, joints)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Axons: definition (neuron fiber conducting away from cyton) & location (nerves, CNS white matter)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Ciliated epithelium: definition (cilia beating) & location (bronchioles, fallopian tubes)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the various types of epithelial tissues with the help of labelled diagrams.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Classification of Epithelial Tissues:</strong><br>\n    Epithelial tissue forms protective coverings or inner linings for free surfaces, characterized by closely packed cells with minimal intercellular matrix, resting upon a non-cellular collagenous basement membrane.<br><br>\n    <strong>A. Simple Epithelium (Single Layer of Cells):</strong><br>\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Squamous Epithelium (Pavement Epithelium):</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Thin, flat, polygonal tile-like cells with irregular boundaries and central bulging nuclei.</li>\n          <li><em>Function:</em> Forms a delicate diffusion boundary.</li>\n          <li><em>Location:</em> Walls of blood vessels (endothelium), air sacs of lungs (alveoli), Bowman's capsule in nephrons.</li>\n        </ul>\n      </li>\n      <li><strong>Cuboidal Epithelium:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Cube-like cells with spherical centrally located nuclei. In some regions (e.g., Proximal Convoluted Tubule / PCT of nephron), apical surfaces bear microvilli forming a brush border to expand absorptive surface area.</li>\n          <li><em>Function:</em> Secretion and absorption.</li>\n          <li><em>Location:</em> Ducts of glands and tubular parts of nephrons in kidneys.</li>\n        </ul>\n      </li>\n      <li><strong>Columnar Epithelium:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Tall, pillar-like, cylindrical cells with elongated oval nuclei situated near the base. Free surface may possess microvilli or mucus-secreting goblet cells.</li>\n          <li><em>Function:</em> Secretion of enzymes/mucus and active nutrient absorption.</li>\n          <li><em>Location:</em> Lining of stomach, small intestine, and gall bladder.</li>\n        </ul>\n      </li>\n      <li><strong>Ciliated Epithelium:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Columnar or cuboidal cells bearing motile cilia on their free surfaces.</li>\n          <li><em>Function:</em> Moves particles or mucus in a unidirectional current.</li>\n          <li><em>Location:</em> Bronchioles, trachea, fallopian tubes, ventricles of brain (ependyma).</li>\n        </ul>\n      </li>\n    </ol>\n    <strong>B. Compound (Stratified) Epithelium:</strong><br>\n    Made of multiple cell layers with limited secretory/absorptive role. Provides mechanical, chemical, and thermal protection against abrasion. <em>Location: Dry surface of skin (keratinized stratified squamous), moist surface of buccal cavity, pharynx, esophagus, and vagina.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Simple squamous: flat tiles, diffusion boundary, lung alveoli/capillaries</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simple cuboidal: cube-shaped, secretion/absorption, PCT kidney tubules/ducts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simple columnar & ciliated: tall cells, basal nuclei, cilia function in bronchioles/oviducts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Compound epithelium: multi-layered, protective barrier against abrasion, skin/pharynx</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish between: (a) Exocrine and endocrine glands (b) Tight junctions, adhering junctions and gap junctions.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between Exocrine and Endocrine Glands:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Feature</th><th style=\"padding:6px 10px;\">Exocrine Glands</th><th style=\"padding:6px 10px;\">Endocrine Glands</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">1. Presence of Ducts</td><td style=\"padding:6px 10px;\"><strong>Duct glands</strong>; discharge secretions via dedicated tubular ducts.</td><td style=\"padding:6px 10px;\"><strong>Ductless glands</strong>; lack ducts completely.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">2. Nature of Secretion</td><td style=\"padding:6px 10px;\">Mucus, saliva, digestive enzymes, bile, sweat, sebum, earwax, milk.</td><td style=\"padding:6px 10px;\">Chemical messengers called <strong>hormones</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">3. Route of Transport</td><td style=\"padding:6px 10px;\">Discharged directly onto an epithelial surface or into a lumen.</td><td style=\"padding:6px 10px;\">Secreted directly into venous capillary blood and lymph.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">4. Examples</td><td style=\"padding:6px 10px;\">Salivary glands, sweat glands, liver, exocrine pancreas.</td><td style=\"padding:6px 10px;\">Pituitary, thyroid, adrenals, parathyroid, endocrine islets of Langerhans.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Differences Between Specialized Cellular Junctions:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.84rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Junction Type</th><th style=\"padding:6px 10px;\">Molecular Mechanism</th><th style=\"padding:6px 10px;\">Primary Physiological Role</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:6px 10px; font-weight:700;\">1. Tight Junctions (<em>Zonula occludens</em>)</td>\n            <td style=\"padding:6px 10px;\">Adjacent cell membranes fuse tightly by trans-membrane proteins (claudins and occludins).</td>\n            <td style=\"padding:6px 10px;\"><strong>Prevents leakage</strong> of substances across an epithelial cell layer (e.g., intestinal mucosa, urinary bladder).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:6px 10px; font-weight:700;\">2. Adhering Junctions (Desmosomes)</td>\n            <td style=\"padding:6px 10px;\">Cadherin cadherin-anchored protein plaques anchored to cytoplasmic keratin intermediate filaments.</td>\n            <td style=\"padding:6px 10px;\">Performs <strong>cementing</strong> to keep neighboring cells firmly anchored together under mechanical shearing forces (e.g., epidermis, cardiac muscle).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:6px 10px; font-weight:700;\">3. Gap Junctions (Nexus)</td>\n            <td style=\"padding:6px 10px;\">Porous hexameric protein channels called <strong>connexons</strong> bridge adjacent cytoplasm.</td>\n            <td style=\"padding:6px 10px;\">Facilitates <strong>rapid intercellular communication</strong> by allowing direct passage of ions, small molecules, second messengers, and rapid electrical action potentials.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Exocrine (ducts, enzymes/sweat) vs Endocrine (ductless, hormones in blood)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Precise roles: Tight (stop leakage), Adhering (cementing/strength), Gap (intercellular ionic flow)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw a neat diagram of the digestive system of frog.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical Architecture of the Digestive System of Frog (<em>Rana tigrina</em>):</strong><br>\n    The digestive system consists of an alimentary canal and associated digestive glands:<br><br>\n    <strong>1. Alimentary Canal (Relatively Short due to Carnivorous Diet):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Mouth &amp; Buccopharyngeal Cavity:</strong> Bounded by wide jaws; upper jaw bears row of sharp <strong>maxillary teeth</strong> and two patches of <strong>vomerine teeth</strong> on palate (prevent prey escape). Possesses a muscular, bilobed, highly extensible tongue attached at the anterior rim and free posteriorly.</li>\n      <li><strong>Oesophagus:</strong> Short broad muscular tube dilating into the stomach.</li>\n      <li><strong>Stomach:</strong> Crescent-shaped muscular sac with gastric glands secreting $HCl$ and pepsinogen; produces acidic chyme.</li>\n      <li><strong>Intestine:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Duodenum:</em> Receives the hepatopancreatic duct carrying bile and pancreatic juice.</li>\n          <li><em>Ileum:</em> Coiled loop lined by microvilli for nutrient digestion and absorption.</li>\n        </ul>\n      </li>\n      <li><strong>Rectum:</strong> Reabsorbs water, opening into a common terminal chamber called the <strong>cloaca</strong>, which opens outside via the <strong>cloacal aperture</strong> (common outlet for feces, urine, and gametes).</li>\n    </ul>\n    <strong>2. Associated Digestive Glands:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Liver:</strong> Multilobed, secretes bile stored in the green <strong>gall bladder</strong> (emulsifies fats).</li>\n      <li><strong>Pancreas:</strong> Irregular gland lying between stomach and duodenum, secreting pancreatic juice containing trypsin, amylase, and lipase.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mouth, vomerine/maxillary teeth, and anteriorly attached bilobed extensible tongue</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stomach (acid chyme) and intestine (duodenum & coiled ileum)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Digestive glands: multilobed liver with gall bladder, and pancreas</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cloaca and cloacal aperture serving as common terminal chamber</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Mention the function of the following: (a) Ureters in frog (b) Malpighian tubules in cockroach (c) Body wall in earthworm.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Specific Physiological Functions:</strong><br><br>\n    <strong>(a) Ureters in Frog:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>In Male Frog:</em> The ureters act as <strong>urinogenital ducts</strong>. They emerge from kidneys, receive vasa efferentia carrying spermatozoa from testes via Bidder's canal, and transport both urine and sperm into the cloaca.</li>\n      <li><em>In Female Frog:</em> The ureters function exclusively as <strong>urinary ducts</strong> to transport urine from kidneys into the cloaca (oviducts open separately into cloaca).</li>\n    </ul>\n    <strong>(b) Malpighian Tubules in Cockroach:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>100 to 150 fine, yellow, thread-like tubules floating in hemolymph that act as the primary <strong>excretory and osmoregulatory organs</strong>.</li>\n      <li>Lined by glandular and ciliated epithelium, they extract potassium urate and water from hemolymph, convert it into insoluble <strong>uric acid</strong>, and discharge it into the hindgut lumen, ensuring maximum water conservation (uricotelism).</li>\n    </ul>\n    <strong>(c) Body Wall in Earthworm:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Cutaneous Respiration:</strong> Highly vascularized epidermis secretes moist mucus; atmospheric oxygen dissolves into the moisture film and diffuses into blood capillaries.</li>\n      <li><strong>Locomotion:</strong> Outer circular and inner longitudinal muscle layers contract antagonistically with chitinous S-shaped setae to produce peristaltic burrowing locomotion.</li>\n      <li><strong>Protection:</strong> Secretes protective cuticle preventing internal organ damage and desiccation.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Ureters in frog: urinogenital duct in males vs solely urinary in females</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Malpighian tubules: extraction of urate wastes from hemolymph and uric acid excretion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Earthworm body wall: cutaneous gas exchange, muscle/setae locomotion, and protection</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give the schematic diagram of an open circulatory system of cockroach.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Open Circulatory System of Cockroach (<em>Periplaneta americana</em>):</strong><br>\n    Cockroaches possess an <strong>open circulatory system</strong> where blood (hemolymph) does not flow through closed capillaries, but directly bathes visceral organs in open fluid spaces called <strong>sinuses</strong> within the hemocoel:<br><br>\n    <strong>1. Structural Components:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Hemolymph:</strong> Colorless blood composed of clear fluid plasma and phagocytic hemocytes (lacks respiratory pigment like hemoglobin; does not transport oxygen).</li>\n      <li><strong>Heart:</strong> Elongated, pulsating, dorsal muscular tube differentiated into <strong>13 funnel-shaped chambers</strong> (3 thoracic and 10 abdominal). Each chamber possesses a pair of lateral openings guarded by valves called <strong>ostia</strong>.</li>\n      <li><strong>Alary Muscles:</strong> 12 pairs of triangular fan-like muscles attached between heart chambers and terga that contract to expand the pericardial space.</li>\n      <li><strong>Hemocoelic Sinuses:</strong> Partitioned by two horizontal fibro-muscular membranes (dorsal and ventral diaphragms) into three sinuses:\n        <ol style=\"margin:2px 0 4px 15px;\">\n          <li><em>Dorsal Pericardial Sinus:</em> Encloses the heart.</li>\n          <li><em>Middle Perivisceral Sinus:</em> Largest space enclosing the alimentary canal and gonads.</li>\n          <li><em>Ventral Perineural Sinus:</em> Surrounds the ventral nerve cord.</li>\n        </ol>\n      </li>\n    </ul>\n    <strong>Schematic Course of Circulation:</strong><br>\n    $$\\text{Pericardial Sinus} \\xrightarrow{\\text{through Ostia}} \\text{Heart (Chambers 13 to 1)} \\xrightarrow{\\text{Anterior Aorta}} \\text{Head Sinus}$$\n    $$\\downarrow$$\n    $$\\text{Perivisceral \\& Perineural Sinuses (visceral bathing)} \\xrightarrow{\\text{Diaphragm Pores}} \\text{Pericardial Sinus}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">13-chambered dorsal heart with ostia and 12 pairs of alary muscles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three hemocoelic sinuses: pericardial, perivisceral, and perineural separated by diaphragms</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complete flow sequence from heart to head sinus, perivisceral sinuses and back via ostia</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Mention the role of the following in cockroach: (a) Antennae (b) Compound eyes (c) Maxillary palps (d) Anal cerci.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Sensory &amp; Behavioral Roles in Cockroach:</strong><br><br>\n    <strong>(a) Antennae (Thread-like Tactile &amp; Olfactory Organs):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Arise from membranous sockets in front of the eyes. Composed of scape, pedicel, and multi-segmented flagellum.</li>\n      <li>Rich in tactile, olfactory, and thermal receptors; monitor environmental surroundings, locate food, detect air currents, and perceive sex pheromones.</li>\n    </ul>\n    <strong>(b) Compound Eyes (Visual Photoreception):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A pair of kidney-shaped sessile compound eyes situated dorsolaterally on head capsule, each composed of roughly <strong>2,000 hexagonal ommatidia</strong>.</li>\n      <li>Gives <strong>mosaic vision (apposition/superposition)</strong> with high sensitivity to motion in dim light (nocturnal vision) but low image resolution.</li>\n    </ul>\n    <strong>(c) Maxillary Palps (Gustatory &amp; Manipulative Feeding):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Five-segmented sensory appendages borne on the first pair of maxillae.</li>\n      <li>Carry chemoreceptors (taste/smell) and mechanoreceptors used to inspect, taste, hold, and manipulate food particles into the pre-oral cavity during chewing.</li>\n    </ul>\n    <strong>(d) Anal Cerci (Acoustic &amp; Seismic Vibration Detection):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A pair of jointed, 15-segmented sensory appendages projecting from the 10th abdominal tergum in <strong>both males and females</strong>.</li>\n      <li>Extremely sensitive to low-frequency substrate vibrations and subtle air movements, triggering instantaneous escape running reflexes when a predator approaches.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Antennae: tactile, olfactory, and chemical environmental monitoring</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Compound eyes: 2000 ommatidia per eye conferring mosaic nocturnal vision</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Maxillary palps: taste, smell, and food manipulation in mouthparts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Anal cerci: detection of subtle ground and air vibrations triggering escape reflexes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the cellular components of blood?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Formed Cellular Elements of Blood:</strong><br>\n    Human blood consists of fluid plasma (55%) and formed cellular elements (45%), which comprise three major cell types:<br><br>\n    <strong>1. Red Blood Cells (RBCs / Erythrocytes):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Count &amp; Shape:</strong> Most abundant (5.0 to 5.5 million/$\\text{mm}^3$ of blood). Biconcave discs; lack nuclei, mitochondria, and Golgi apparatus at maturity in mammals to maximize hemoglobin volume.</li>\n      <li><strong>Function:</strong> Contain iron-porphyrin protein <strong>hemoglobin</strong> (12–16 g/100 mL blood) which binds oxygen reversibly to form oxyhemoglobin for systemic tissue transport.</li>\n    </ul>\n    <strong>2. White Blood Cells (WBCs / Leukocytes):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Count &amp; Characteristics:</strong> Nucleated cells (6,000–8,000/$\\text{mm}^3$). Subdivided into:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Granulocytes (with cytoplasmic granules &amp; lobed nuclei):</strong>\n            <br>&bull; <em>Neutrophils (60–65%):</em> Phagocytic cells engulfing invading bacteria.\n            <br>&bull; <em>Eosinophils (2–3%):</em> Resist parasitic infections and mediate allergic responses.\n            <br>&bull; <em>Basophils (0.5–1%):</em> Secrete histamine, serotonin, and heparin in inflammatory responses.\n          </li>\n          <li><strong>Agranulocytes (without specific cytoplasmic granules):</strong>\n            <br>&bull; <em>Monocytes (6–8%):</em> Large phagocytic cells maturing into tissue macrophages.\n            <br>&bull; <em>Lymphocytes (20–25%):</em> B-cells (humoral antibody immunity) and T-cells (cell-mediated immunity).\n          </li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Blood Platelets (Thrombocytes):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Cellular fragments (150,000 to 350,000/$\\text{mm}^3$) budded from giant bone marrow cells called <strong>megakaryocytes</strong>.</li>\n      <li>Release thromboplastin and clotting factor cascades essential for <strong>hemostasis (blood coagulation)</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Erythrocytes (RBCs): biconcave, enucleate, hemoglobin transport of oxygen</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Leukocytes (WBCs): granulocytes (neutrophils, eosinophils, basophils) and agranulocytes (monocytes, lymphocytes)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thrombocytes (Platelets): origin from megakaryocytes and function in blood clotting</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the female reproductive system of cockroach with a labelled diagram.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical Organization of Female Reproductive System in Cockroach:</strong><br><br>\n    <strong>1. Ovaries:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A pair of large, yellowish ovaries lying laterally in the <strong>2nd to 6th abdominal segments</strong> embedded in fat bodies.</li>\n      <li>Each ovary is formed of a group of <strong>8 ovarian tubules or ovarioles</strong> containing a linear chain of developing ova in various maturation stages.</li>\n    </ul>\n    <strong>2. Oviducts &amp; Common Oviduct (Vagina):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The individual ovarioles of each ovary unite posteriorly into a short, wide lateral <strong>oviduct</strong>.</li>\n      <li>The two lateral oviducts join in the midline to form a single, broad median oviduct called the <strong>vagina</strong>, opening into the female genital chamber (bursa copulatrix).</li>\n    </ul>\n    <strong>3. Spermathecae:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A pair of unequal, pyriform sacs located in the 6th abdominal segment, opening by a common pore into the dorsal wall of the genital chamber. They receive and store viable spermatozoa delivered during copulation.</li>\n    </ul>\n    <strong>4. Collaterial Glands:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A pair of large, branched, tubular glands situated behind the ovaries. They secrete the hard, proteinaceous, dark-brown sclerotized casing of the egg capsule called the <strong>ootheca</strong>.</li>\n    </ul>\n    <strong>5. Genital Pouch (Chamber) &amp; Gonapophyses:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Formed by the 7th, 8th, and 9th sterna (7th sternum is boat-shaped). Contains three pairs of chitinous valvate blades called <strong>gonapophyses (ovipositor)</strong> to guide eggs into oothecae.</li>\n      <li>Each ootheca encapsulates <strong>16 fertilized eggs</strong> arranged in two parallel rows.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Pair of ovaries in 2nd-6th segments, each having 8 ovarioles with linear chains of ova</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lateral oviducts uniting into median vagina opening into genital chamber</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pair of spermathecae for storing sperm & collaterial glands forming ootheca</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Genital pouch (7th, 8th, 9th sterna) and 16 eggs per ootheca</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish between a male frog and a female frog.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Morphological &amp; Anatomical Sexual Dimorphism in Frog (<em>Rana tigrina</em>):</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Characteristic Feature</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Male Frog</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Female Frog</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Vocal Sacs</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Present.</strong> Possesses a pair of bluish wrinkled vocal sacs beneath the throat that amplify croaking to attract females during the monsoon breeding season.</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\"><strong>Absent.</strong> Vocal sacs are completely absent; produces only faint sounds.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Copulatory (Nuptial) Pad</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Present.</strong> Develops a thickened, swollen, sticky nuptial pad on the ventral base of the first digit of the forelimb to firmly grip the female during amplexus.</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\"><strong>Absent.</strong> Forelimb digits are smooth with no copulatory pad.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Body Size &amp; Abdomen</td>\n            <td style=\"padding:8px 12px;\">Relatively smaller, slender body with a narrower abdomen.</td>\n            <td style=\"padding:8px 12px;\">Noticeably larger in body size; abdomen becomes visibly distended and bulky during the breeding season due to thousands of ova.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Ureter Function</td>\n            <td style=\"padding:8px 12px;\">Ureter functions as a <strong>urinogenital duct</strong> (conducts both urine and spermatozoa into cloaca).</td>\n            <td style=\"padding:8px 12px;\">Ureter acts strictly as a <strong>urinary duct</strong> (transports only urine; coiled oviducts open separately into cloaca).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">5. Bidder's Canal</td>\n            <td style=\"padding:8px 12px;\">Present inside the kidney to receive sperm from vasa efferentia.</td>\n            <td style=\"padding:8px 12px;\">Completely absent.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Vocal sacs: present in males for breeding call amplification, absent in females</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Copulatory pad on 1st forelimb digit of males for amplexus grip, absent in females</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ureter: urinogenital duct in males vs strictly urinary duct in females; Bidder’s canal</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 6</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 8 (Cell: The Unit of Life) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[8] = "<section class=\"chapter-section\" id=\"c11b-ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 8</div>\n      <h2>Cell: The Unit of Life</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 15 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v4M12 18v4M2 12h4M18 12h4\"/></svg>\n      Fluid Mosaic Membrane &amp; Organelle Endomembrane System\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"425\" y=\"30\" font-size=\"11\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">SINGER &amp; NICOLSON FLUID MOSAIC MODEL OF CELL MEMBRANE (1972)</text>\n\n      <!-- Bilayer graphic -->\n      <g transform=\"translate(40, 50)\">\n        <rect x=\"0\" y=\"0\" width=\"450\" height=\"150\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        \n        <!-- Hydrophilic heads top -->\n        <circle cx=\"30\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"30\" y1=\"48\" x2=\"30\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"55\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"55\" y1=\"48\" x2=\"55\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"80\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"80\" y1=\"48\" x2=\"80\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"105\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"105\" y1=\"48\" x2=\"105\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n\n        <!-- Integral Transmembrane Protein -->\n        <rect x=\"130\" y=\"25\" width=\"45\" height=\"100\" rx=\"10\" fill=\"#a78bfa\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n        <text x=\"152\" y=\"75\" font-size=\"8\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">Integral</text>\n        <text x=\"152\" y=\"87\" font-size=\"7\" fill=\"#ffffff\" text-anchor=\"middle\">Protein</text>\n\n        <!-- More heads -->\n        <circle cx=\"200\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"200\" y1=\"48\" x2=\"200\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"225\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"225\" y1=\"48\" x2=\"225\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"250\" cy=\"40\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"250\" y1=\"48\" x2=\"250\" y2=\"72\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n\n        <!-- Hydrophilic heads bottom -->\n        <circle cx=\"30\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"30\" y1=\"102\" x2=\"30\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"55\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"55\" y1=\"102\" x2=\"55\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"80\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"80\" y1=\"102\" x2=\"80\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"105\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"105\" y1=\"102\" x2=\"105\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"200\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"200\" y1=\"102\" x2=\"200\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"225\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"225\" y1=\"102\" x2=\"225\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n        <circle cx=\"250\" cy=\"110\" r=\"8\" fill=\"#38bdf8\" stroke=\"#0284c7\"/><line x1=\"250\" y1=\"102\" x2=\"250\" y2=\"78\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n\n        <!-- Labels -->\n        <text x=\"310\" y=\"45\" font-size=\"8\" font-weight=\"bold\" fill=\"#0284c7\">&larr; Polar Hydrophilic Head</text>\n        <text x=\"310\" y=\"75\" font-size=\"8\" font-weight=\"bold\" fill=\"#d97706\">&larr; Non-polar Fatty Acid Tails</text>\n        <text x=\"310\" y=\"105\" font-size=\"8\" font-weight=\"bold\" fill=\"#7c3aed\">&larr; Quasi-fluid Phospholipid Bilayer</text>\n      </g>\n\n      <!-- Chromosome Morphotypes on Right -->\n      <g transform=\"translate(520, 50)\">\n        <rect x=\"0\" y=\"0\" width=\"300\" height=\"150\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"150\" y=\"20\" font-size=\"9.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">TYPES OF CHROMOSOMES BY CENTROMERE</text>\n        \n        <!-- Metacentric -->\n        <g transform=\"translate(25, 30)\">\n          <path d=\"M 15,10 L 15,45 Q 15,50 15,55 L 15,90\" stroke=\"#2563eb\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n          <circle cx=\"15\" cy=\"50\" r=\"4.5\" fill=\"#dc2626\"/>\n          <text x=\"15\" y=\"105\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Metacentric</text>\n          <text x=\"15\" y=\"115\" font-size=\"6.5\" fill=\"#64748b\" text-anchor=\"middle\">Median (V-shaped)</text>\n        </g>\n\n        <!-- Sub-metacentric -->\n        <g transform=\"translate(95, 30)\">\n          <path d=\"M 15,20 L 15,40 Q 15,45 15,50 L 15,90\" stroke=\"#059669\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n          <circle cx=\"15\" cy=\"40\" r=\"4.5\" fill=\"#dc2626\"/>\n          <text x=\"15\" y=\"105\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Sub-meta</text>\n          <text x=\"15\" y=\"115\" font-size=\"6.5\" fill=\"#64748b\" text-anchor=\"middle\">Sub-median (L-shape)</text>\n        </g>\n\n        <!-- Acrocentric -->\n        <g transform=\"translate(165, 30)\">\n          <path d=\"M 15,30 L 15,35 Q 15,38 15,42 L 15,90\" stroke=\"#d97706\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n          <circle cx=\"15\" cy=\"35\" r=\"4.5\" fill=\"#dc2626\"/>\n          <text x=\"15\" y=\"105\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">Acrocentric</text>\n          <text x=\"15\" y=\"115\" font-size=\"6.5\" fill=\"#64748b\" text-anchor=\"middle\">Near end (J-shape)</text>\n        </g>\n\n        <!-- Telocentric -->\n        <g transform=\"translate(235, 30)\">\n          <path d=\"M 15,32 L 15,90\" stroke=\"#7c3aed\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n          <circle cx=\"15\" cy=\"30\" r=\"4.5\" fill=\"#dc2626\"/>\n          <text x=\"15\" y=\"105\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#5b21b6\" text-anchor=\"middle\">Telocentric</text>\n          <text x=\"15\" y=\"115\" font-size=\"6.5\" fill=\"#64748b\" text-anchor=\"middle\">Terminal (i-shape)</text>\n        </g>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 15: Cell Theory, Prokaryotes, Fluid Mosaic Membrane, Organelles, Nucleus & Chromosomes</div>\n\n  <!-- c11b-ch8-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following is not correct?<br>(a) Robert Brown discovered the cell.<br>(b) Schleiden and Schwann formulated the cell theory.<br>(c) Virchow explained that cells are formed from pre-existing cells.<br>(d) A unicellular organism carries out its life activities within a single cell.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Answer: (a) Robert Brown discovered the cell.</strong><br><br>\n    <strong>Historical and Scientific Justification:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Statement (a) is <strong>incorrect</strong> because the cell was first discovered and named by <strong>Robert Hooke in 1665</strong> (observing dead cork tissue under his compound microscope). <strong>Robert Brown (1831)</strong> discovered the <strong>nucleus</strong> inside plant cells (orchids).</li>\n      <li>Statement (b) is correct: Matthias Schleiden (1838, botanist) and Theodore Schwann (1839, zoologist) jointly synthesized the classic Cell Theory.</li>\n      <li>Statement (c) is correct: Rudolf Virchow (1855) modified cell theory by stating <em>\"Omnis cellula-e cellula\"</em> (all cells arise from pre-existing cells via cell division).</li>\n      <li>Statement (d) is correct: Unicellular organisms (e.g., <em>Amoeba</em>, <em>Chlamydomonas</em>) independently execute all essential metabolic, nutritional, excretory, and reproductive functions within a single cell.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of statement (a) as incorrect</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clarification that Hooke discovered cell (1665) while Robert Brown discovered nucleus (1831)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        New cells generate from:<br>(a) bacterial fermentation<br>(b) regeneration of old cells<br>(c) pre-existing cells<br>(d) abiotic materials.\n      </div>\n      <div class=\"q-marks\">[1 Mark]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Option: (c) pre-existing cells</strong><br><br>\n    <strong>Scientific Explanation:</strong><br>\n    According to the modern Cell Principle established by <strong>Rudolf Virchow (1855)</strong> with his famous aphorism <strong>\"Omnis cellula-e cellula\"</strong>, new daughter cells arise exclusively through the mitotic or meiotic division of pre-existing parent living cells. Spontaneous generation from non-living abiotic materials was definitively disproved by Louis Pasteur.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct choice: (c) pre-existing cells and mention of Rudolf Virchow’s cell lineage theory</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the following:<br>Column I &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Column II<br>(a) Cristae &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (i) Flat membranous sacs in stroma<br>(b) Cisternae &mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (ii) Infoldings in mitochondria<br>(c) Thylakoids &mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (iii) Disc-shaped sacs in Golgi apparatus\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Structural Matching:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Column I</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Column II (Correct Match)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Organellar Function</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) Cristae</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Infoldings in mitochondria</td>\n            <td style=\"padding:8px 12px;\">Increases surface area for electron transport chain ($F_0-F_1$ ATP synthase complexes).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) Cisternae</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Disc-shaped sacs in Golgi apparatus</td>\n            <td style=\"padding:8px 12px;\">Concentric flattened sacs (cis &amp; trans face) modifying and packaging glycoproteins/glycolipids.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) Thylakoids</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Flat membranous sacs in stroma</td>\n            <td style=\"padding:8px 12px;\">Stacked like coins into grana in chloroplasts, housing chlorophyll and photosynthetic light reaction machinery.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>Final Sequence: (a) &rarr; (ii), &nbsp; (b) &rarr; (iii), &nbsp; (c) &rarr; (i)</strong>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Cristae to (ii) Infoldings in mitochondria</span><span class=\"marking-marks\">0.7 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cisternae to (iii) Disc-shaped sacs in Golgi apparatus</span><span class=\"marking-marks\">0.7 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Thylakoids to (i) Flat membranous sacs in stroma</span><span class=\"marking-marks\">0.6 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which of the following is not correct?<br>(a) Gram-negative bacteria have a thick peptidoglycan wall.<br>(b) Mesosomes are infoldings of cell membrane.<br>(c) Bacterial cell wall is made of peptidoglycan.<br>(d) Pili and fimbriae are involved in bacterial motility.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Incorrect Statements: Both (a) and (d) are incorrect based on NCERT facts:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Why (a) is incorrect:</strong> Gram-positive bacteria have a thick (20–80 nm) homogeneous peptidoglycan wall with teichoic acid. <strong>Gram-negative bacteria possess a very thin peptidoglycan layer</strong> (2–7 nm) sandwiched in the periplasmic space between the inner plasma membrane and an outer lipopolysaccharide (LPS) membrane.</li>\n      <li><strong>Why (d) is incorrect:</strong> <strong>Pili and fimbriae do not play any role in bacterial motility.</strong> Pili (made of pilin protein) form sex pili for bacterial conjugation (DNA transfer), and fimbriae are bristle-like proteinaceous fibers that anchor bacteria to rocks in streams or host epithelial tissues. <em>Bacterial motility is mediated strictly by flagella.</em></li>\n    </ul>\n    <em>(Note: In typical single-choice CBSE examination keys, statement (d) is the primary targeted answer regarding motility).</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of (d) [and/or a] as incorrect</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific explanation that bacterial motility is mediated exclusively by flagella (not pili/fimbriae)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is a mesosome in a prokaryotic cell? Mention the functions that it performs.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Mesosome:</strong><br>\n    A <strong>mesosome</strong> is a characteristic, complexly folded, invaginated membranous structure of prokaryotic cells formed by the in-folding of the plasma membrane into the cytoplasm. It occurs in the form of vesicles, tubules, and lamellae, and is predominantly prominent in Gram-positive bacteria.<br><br>\n    <strong>Vital Cellular Functions Performed by Mesosomes:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Cellular Respiration and Secretion:</strong> Prokaryotes lack mitochondria. Mesosomal folds carry electron transport enzymes and ATP synthases, functioning as the prokaryotic respiratory equivalent of eukaryotic mitochondrial cristae.</li>\n      <li><strong>2. Surface Area Amplification:</strong> Drastically increases the total surface area of the plasma membrane and its associated enzymatic content.</li>\n      <li><strong>3. Cell Wall Synthesis:</strong> Contains enzymes that synthesize and cross-link peptidoglycan precursors during binary fission.</li>\n      <li><strong>4. DNA Replication and Daughter Cell Distribution:</strong> Remains attached to the bacterial nucleoid; aids in chromosome replication and ensures equal segregation of genetic material into daughter cells by forming the transverse cross-septum.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of mesosome as plasma membrane invagination in prokaryotes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Respiration (equivalent to mitochondrial cristae) & enzymatic surface area expansion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role in cell wall synthesis, DNA replication, and binary fission cross-wall septum</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How do neutral solutes move across the plasma membrane? Can the polar molecules also move across it in the same way? If not, then how are these transported across the membrane?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Transport Mechanisms Across the Selectively Permeable Plasma Membrane:</strong><br><br>\n    <strong>1. Transport of Neutral (Non-Polar) Solutes:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Neutral, lipid-soluble molecules (e.g., $O_2$, $CO_2$, steroid hormones, ethanol) dissolve directly into the hydrophobic non-polar hydrocarbon core of the phospholipid bilayer.</li>\n      <li>They move across by <strong>simple passive diffusion</strong> along their electrochemical concentration gradient (from higher to lower concentration) without requiring metabolic cellular energy (ATP) or carrier proteins.</li>\n    </ul>\n    <strong>2. Transport of Polar Molecules:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Can polar molecules move in the same way? NO.</strong> Polar, charged, or hydrophilic molecules (e.g., glucose, amino acids, ions like $Na^+$, $K^+$, $Ca^{2+}$) cannot pass through the hydrophobic fatty acid core of the lipid bilayer due to electrostatic repulsion.</li>\n      <li><strong>Mechanism of Polar Molecule Transport:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Facilitated Diffusion (Passive):</em> Transported down their concentration gradient via specialized membrane transport proteins (<strong>ion channels, porins, and permease carrier proteins</strong>) without expenditure of ATP. Water moves through aquaporins (channel proteins) via osmosis.</li>\n          <li><em>Active Transport (Energy-Dependent):</em> When transported <strong>against</strong> their electrochemical gradient (from lower to higher concentration), carrier proteins (pumps) utilize energy derived from the hydrolysis of ATP. A classic example is the <strong>$Na^+/K^+$ ATPase pump</strong> (pumps 3 $Na^+$ out and 2 $K^+$ in per ATP hydrolyzed).</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Neutral solute transport via simple passive diffusion through lipid bilayer down gradient</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear statement: No, polar molecules cannot diffuse through non-polar lipid core</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Facilitated diffusion using transport channel proteins and permeases down gradient</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Active transport via ATP-driven carrier pumps against concentration gradient (Na+/K+ pump)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name two cell-organelles that are double membrane-bound. What are the characteristics of these two organelles? State their functions and draw labelled diagrams.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Two Double Membrane-Bound Semiautonomous Organelles:</strong><br>\n    The two prominent double membrane-bound organelles in eukaryotic cells are: <strong>1. Mitochondria</strong> and <strong>2. Chloroplasts</strong> (Plastids).<br><br>\n    <strong>A. Mitochondria (\"Powerhouses of the Cell\"):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Structural Characteristics:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Outer membrane:</em> Smooth, continuous, and highly permeable due to porins.</li>\n          <li><em>Inner membrane:</em> Thrown into numerous deep convoluted infoldings called <strong>cristae</strong>, which project into the gel-like matrix. The cristae bear millions of racket-shaped oxysomes ($F_0-F_1$ particles / ATP synthases).</li>\n          <li><em>Semiautonomous nature:</em> The matrix contains a single circular naked dsDNA molecule, a few RNA molecules, <strong>70S ribosomes</strong>, and enzymes of the Krebs (TCA) cycle.</li>\n        </ul>\n      </li>\n      <li><strong>Function:</strong> Aerobic respiration, $\\beta$-oxidation of fatty acids, and generation of metabolic energy currency (ATP) via oxidative phosphorylation.</li>\n    </ul>\n    <strong>B. Chloroplasts (\"Kitchen of the Plant Cell\"):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Structural Characteristics:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Enclosed by two continuous smooth lipid membranes separated by an intermembrane space.</li>\n          <li>Internal matrix is called the <strong>stroma</strong>, which contains enzymes for the Calvin cycle (dark reaction, e.g., RuBisCO), circular dsDNA, 70S ribosomes, and starch grains.</li>\n          <li>Suspended in the stroma is a membranous system of flattened sacs called <strong>thylakoids</strong> stacked like coins into <strong>grana</strong> (interconnected by stroma lamellae). Thylakoid membranes contain chlorophyll and carotenoids.</li>\n        </ul>\n      </li>\n      <li><strong>Function:</strong> Photosynthesis: light reaction occurs in thylakoid membranes (photolysis of water, ATP &amp; NADPH generation) and dark reaction occurs in stroma (carbon fixation into carbohydrates).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Mitochondria and Chloroplasts as double membrane-bound</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural characteristics of Mitochondria (outer/inner membrane, cristae, matrix, 70S ribosomes, circular DNA)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural characteristics of Chloroplasts (stroma, thylakoids, grana, stroma lamellae)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Precise functions: Cellular ATP generation vs Photosynthetic carbohydrate synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the characteristics of prokaryotic cells?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Hallmark Characteristics of Prokaryotic Cells (e.g., Bacteria, Archaea, BGA, Mycoplasma):</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Absence of True Nucleus (Incipient Nucleus / Genophore):</strong> Genetic material is not enclosed by a nuclear envelope; it exists as a naked, supercoiled, double-stranded circular DNA molecule called the <strong>nucleoid</strong>. Basic histone proteins are completely absent.</li>\n      <li><strong>2. Plasmids:</strong> Many bacteria carry small, extra-chromosomal, self-replicating circular double-stranded DNA rings called <strong>plasmids</strong> that confer unique phenotypes such as antibiotic resistance (R-plasmids) and fertility (F-plasmids).</li>\n      <li><strong>3. Absence of Membrane-Bound Organelles:</strong> Completely lack endoplasmic reticulum, Golgi complex, lysosomes, mitochondria, microbodies, and plastids.</li>\n      <li><strong>4. 70S Ribosomes:</strong> Protein synthesis is carried out by <strong>70S ribosomes</strong> (composed of 50S and 30S subunits) measuring about 15 nm by 20 nm, often arranged on mRNA as <strong>polysomes (polyribosomes)</strong>.</li>\n      <li><strong>5. Complex Cell Envelope:</strong> A three-layered outer boundary consisting of: (i) outer glycocalyx (capsule or slime layer), (ii) middle peptidoglycan cell wall, and (iii) inner plasma membrane.</li>\n      <li><strong>6. Mesosomes &amp; Inclusion Bodies:</strong> Cell membrane invaginates to form mesosomes (respiration, DNA replication). Reserve materials are stored in cytoplasm as non-membrane bound <strong>inclusion bodies</strong> (phosphate granules, cyanophycean granules, glycogen granules, gas vacuoles).</li>\n      <li><strong>7. Small Size &amp; Rapid Multiplication:</strong> Size typically 1–2 $\\mu m$ (except Mycoplasma &asymp; 0.3 $\\mu m$); divide extremely rapidly by binary fission.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nucleoid / incipient nucleus lacking nuclear envelope and histones</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of 70S ribosomes (polysomes) & lack of membrane-bound organelles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cell envelope (glycocalyx, peptidoglycan wall, plasma membrane) and mesosomes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Plasmids, inclusion bodies, and rapid binary fission multiplication</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Multicellular organisms have division of labour. Explain.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Explanation of Division of Labour in Multicellular Organisms:</strong><br><br>\n    <strong>1. Contrast with Unicellular Organisms:</strong><br>\n    In a unicellular organism (like <em>Amoeba</em>), all biological life activities—ingestion, digestion, cellular respiration, osmoregulation, excretion, locomotion, and reproduction—must be performed by a single cell. This severely limits physiological specialization, body size, and environmental adaptability.<br><br>\n    <strong>2. Principle of Division of Labour:</strong><br>\n    In multicellular organisms, cells differentiate morphologically and biochemically to form specialized tissues, organs, and organ systems, each allocated specific physiological responsibilities:<br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Epithelial Tissue:</strong> Forms protective barriers, lines cavities, and controls selective diffusion.</li>\n      <li><strong>Muscular Tissue:</strong> Highly specialized contractile actin-myosin fibers produce mechanical movement and locomotion.</li>\n      <li><strong>Nervous Tissue:</strong> Excitable neurons conduct rapid electrochemical action potentials for coordination and sensory perception.</li>\n      <li><strong>Circulatory System:</strong> Blood and heart coordinate systemic translocation of gases, nutrients, and waste products.</li>\n    </ul>\n    <strong>3. Intracellular Division of Labour:</strong><br>\n    Even at the subcellular level, division of labour is replicated through membrane-bound organelles: mitochondria synthesize ATP, lysosomes digest macromolecules, ribosomes translate proteins, and nucleus directs genomic regulation. This hierarchy maximizes cellular efficiency and organismal longevity.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison between single-cell constraints and multicellular specialization</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tissue/organ level division of labour (muscle, nerve, vascular, epithelial examples)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Intracellular organelle-level division of labour and overall biological efficiency</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Cell is the basic unit of life. Discuss in brief.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Justification of \"Cell is the Basic Structural and Functional Unit of Life\":</strong><br><br>\n    <strong>1. Structural Autonomy:</strong><br>\n    Anything less than a complete, intact cell does not ensure independent living. Sub-cellular components (isolated mitochondria, purified DNA, or organelles) cannot survive or replicate outside the coordinated living protoplasmic environment. The cell is the smallest structural entity that exhibits all attributes of life.<br><br>\n    <strong>2. Functional Universality:</strong><br>\n    Every vital biochemical process—glycolysis, oxidative phosphorylation, enzymatic catalysis, protein biosynthesis, and DNA replication—takes place exclusively within cellular boundaries.<br><br>\n    <strong>3. Continuity of Life:</strong><br>\n    Every organism, regardless of its ultimate macroscopic size or complexity (from giant banyan trees to human beings), initiates its life cycle as a <strong>single cell: the fertilized egg (zygote)</strong>. Through repeated rounds of mitotic division and differentiation, the zygote generates the trillions of coordinated cells comprising the mature organism.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Structural autonomy: sub-cellular entities cannot live independently</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Functional universality: all metabolic and biochemical reactions occur within cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Continuity of life: all multicellular organisms originate from a single-celled zygote</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are nuclear pores? State their function.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Structure of Nuclear Pores:</strong><br>\n    The nucleus is enveloped by a double-membraned nuclear envelope (inner and outer membranes separated by a 10–50 nm perinuclear space). At numerous points, the outer and inner membranes fuse together to create circular microscopic apertures called <strong>nuclear pores</strong>, which are embedded with an octagonal macromolecular channel complex called the <strong>Nuclear Pore Complex (NPC)</strong>.<br><br>\n    <strong>Biological Functions of Nuclear Pores:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Selective Bidirectional Nucleo-Cytoplasmic Transport:</strong> They act as gatekeepers regulating the traffic of macromolecules between the nucleoplasm and the cytoplasm:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Export from Nucleus to Cytoplasm:</em> Translocates messenger RNA (mRNA), transfer RNA (tRNA), and assembled ribosomal subunits (rRNA + ribosomal proteins) synthesized inside the nucleolus into the cytoplasm for protein translation.</li>\n          <li><em>Import from Cytoplasm to Nucleus:</em> Translocates DNA polymerases, RNA polymerases, histone proteins, ribosomal proteins, and transcription factors synthesized in the cytoplasm into the nucleus.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: fusion of inner/outer nuclear membranes to form nuclear pore complexes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Function: bidirectional selective transport of RNA/ribosomes out and polymerases/histones in</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Both lysosomes and vacuoles are endomembrane structures, yet they differ in terms of their functions. Comment.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comparative Functional Analysis of Lysosomes and Vacuoles:</strong><br>\n    While both lysosomes and vacuoles are single-membrane bound vesicles originating from the endomembrane system (coordinated pathway of ER &rarr; Golgi apparatus &rarr; Lysosomes/Vacuoles), their internal chemical composition and physiological roles diverge sharply:<br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Lysosomes</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Vacuoles (Plant Central Vacuole)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Limiting Membrane</td>\n            <td style=\"padding:8px 12px;\">Single unit membrane with proton ($H^+$) pumps.</td>\n            <td style=\"padding:8px 12px;\">Single semipermeable membrane called the <strong>tonoplast</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Internal Content</td>\n            <td style=\"padding:8px 12px;\">Rich in ~50 hydrolytic enzymes: <strong>hydrolases, lipases, proteases, carbohydrases, nucleases</strong> active at acidic pH (~4.5–5.0).</td>\n            <td style=\"padding:8px 12px;\">Contains <strong>cell sap</strong>: water, excretory products, mineral ions, sugars, and water-soluble pigments (anthocyanins).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Primary Function</td>\n            <td style=\"padding:8px 12px;\"><strong>Intracellular digestion:</strong> Digestion of phagocytosed foreign pathogens (heterophagy) and degraded cellular organelles (autophagy / \"suicidal bags\").</td>\n            <td style=\"padding:8px 12px;\"><strong>Osmoregulation &amp; Turgor:</strong> Tonoplast actively pumps ions against concentration gradient into vacuole, maintaining high turgor pressure to keep plant cells rigid and un-wilted.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Specialized Forms</td>\n            <td style=\"padding:8px 12px;\">Primary lysosomes, secondary lysosomes, autophagic vacuoles, and residual bodies.</td>\n            <td style=\"padding:8px 12px;\">Sap vacuole (plants), <strong>Contractile vacuole</strong> (osmoregulation in <em>Amoeba</em>), and <strong>Food vacuole</strong> (phagocytosis).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Lysosome structure and acid hydrolytic enzymes (proteases, lipases, nucleases)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vacuole structure (tonoplast), cell sap content, and turgor pressure maintenance</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Functional comparison: intracellular digestion/autophagy vs osmoregulation/storage</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the structure of the following with the help of labelled diagrams: (i) Nucleus (ii) Centrosome.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Anatomical Architecture of Nucleus and Centrosome:</strong><br><br>\n    <strong>(i) Nucleus (Discovered by Robert Brown, 1831):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Nuclear Envelope:</strong> Two parallel unit membranes separated by a 10–50 nm perinuclear space. The outer membrane is studded with ribosomes and is continuous with the rough endoplasmic reticulum (RER). It is interrupted by octagonal <strong>nuclear pores</strong>.</li>\n      <li><strong>Nuclear Matrix (Nucleoplasm / Karyolymph):</strong> Transparent semi-fluid colloidal ground substance containing nucleotides, enzymes (DNA and RNA polymerases), and mineral ions.</li>\n      <li><strong>Chromatin (Flemming, 1879):</strong> Entangled network of nucleoprotein fibers composed of DNA, basic histone proteins, non-histone proteins, and RNA, which condenses into distinct chromosomes during cell division.</li>\n      <li><strong>Nucleolus:</strong> Dense, non-membrane bound spherical colloidal structure within nucleoplasm that acts as the factory for <strong>ribosomal RNA (rRNA) synthesis</strong> and ribosomal subunit assembly.</li>\n    </ul>\n    <strong>(ii) Centrosome (Boveri, 1888):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>A non-membrane bound organelle located near the nucleus in animal cells, consisting of two perpendicular cylindrical structures called <strong>centrioles</strong> embedded in an amorphous pericentriolar cloud.</li>\n      <li><strong>Cartwheel Microtubular Architecture ($9 + 0$ Pattern):</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Composed of nine evenly spaced peripheral triplets of <strong>tubulin</strong> microtubules arranged in a ring. Central microtubules are absent ($9 + 0$).</li>\n          <li>The central proteinaceous rod is called the <strong>hub</strong>, connected to peripheral triplets by radial proteinaceous <strong>spokes</strong> (resembling a cartwheel).</li>\n        </ul>\n      </li>\n      <li><strong>Function:</strong> Forms the basal bodies of cilia and flagella, and organizes the <strong>mitotic spindle apparatus</strong> during animal cell division.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nucleus: nuclear envelope with pores, nucleoplasm, chromatin, and nucleolus (rRNA factory)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Centrosome: pair of perpendicular centrioles, 9+0 triplet cartwheel architecture, spindle organizer</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is a centromere? How does the position of centromere form the basis of classification of chromosomes. Support your answer with a diagram showing the position of centromere on different types of chromosomes.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Centromere:</strong><br>\n    The <strong>centromere</strong> (or <strong>primary constriction</strong>) is the clear, non-staining, constricted chromosomal region that holds two sister chromatids together. On its outer lateral surfaces, it bears disc-shaped trilaminar protein plaques called <strong>kinetochores</strong>, to which the spindle fibers attach during mitotic and meiotic anaphase chromosome segregation.<br><br>\n    <strong>Classification of Chromosomes Based on the Position of Centromere:</strong><br><br>\n    <strong>1. Metacentric Chromosome:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The centromere is situated exactly in the <strong>middle</strong> of the chromosome, forming two equal arms ($p = q$).</li>\n      <li>Appears characteristically <strong>V-shaped</strong> during anaphase movement.</li>\n    </ul>\n    <strong>2. Sub-Metacentric Chromosome:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The centromere is located <strong>slightly away from the middle</strong> point, resulting in one slightly shorter arm (called the $p$-arm) and one slightly longer arm (the $q$-arm).</li>\n      <li>Appears characteristically <strong>L-shaped</strong> during anaphase movement.</li>\n    </ul>\n    <strong>3. Acrocentric Chromosome:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The centromere is situated <strong>close to one end</strong>, producing one extremely short minute arm and one very long arm.</li>\n      <li>Appears characteristically <strong>J-shaped</strong> during anaphase movement. Some acrocentrics bear non-staining secondary constrictions carrying terminal knob-like <strong>satellites (SAT chromosomes)</strong>.</li>\n    </ul>\n    <strong>4. Telocentric Chromosome:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The centromere is located strictly at the <strong>terminal tip</strong> of the chromosome, having only one visible arm.</li>\n      <li>Appears characteristically <strong>i-shaped / rod-shaped</strong> during anaphase movement.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of centromere and role of kinetochores in spindle fiber attachment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Metacentric (median, equal arms, V-shaped) & Sub-metacentric (sub-median, L-shaped)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acrocentric (sub-terminal, J-shaped, satellite) & Telocentric (terminal, i-shaped)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Diagrammatic representation showing arm ratios and anaphase shapes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch8-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch8-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch8-q15')\">\n      <div class=\"q-num\">Question 15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is a satellite chromosome? What does secondary constriction indicate?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Satellite (SAT) Chromosomes and Secondary Constrictions:</strong><br><br>\n    <strong>1. Secondary Constriction:</strong><br>\n    While every chromosome possesses a primary constriction (centromere), certain specific chromosomes possess constant, non-staining, narrow chromosomal indentations called <strong>secondary constrictions</strong> at fixed loci.<br>\n    These secondary constrictions act as <strong>Nucleolar Organizer Regions (NOR)</strong> because they contain genes encoding 18S, 5.8S, and 28S ribosomal RNAs (rRNA), directing the assembly of the nucleolus during telophase.<br><br>\n    <strong>2. Satellite (Trabant):</strong><br>\n    The small, rounded, knob-like chromosomal segment located distal to the secondary constriction at the chromosome terminus is called a <strong>satellite</strong>. Chromosomes bearing such satellites are termed <strong>SAT-chromosomes</strong> (e.g., human chromosomes 13, 14, 15, 21, and 22).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of secondary constriction and identification as Nucleolar Organizer Region (NOR)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of satellite as distal terminal knob and naming of SAT chromosomes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 7</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 9 (Biomolecules) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[9] = "<section class=\"chapter-section\" id=\"c11b-ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 9</div>\n      <h2>Biomolecules</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 15 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"18\" cy=\"5\" r=\"3\"/><circle cx=\"6\" cy=\"12\" r=\"3\"/><circle cx=\"18\" cy=\"19\" r=\"3\"/><line x1=\"8.59\" y1=\"13.51\" x2=\"15.42\" y2=\"17.49\"/><line x1=\"15.41\" y1=\"6.51\" x2=\"8.59\" y2=\"10.49\"/></svg>\n      Enzymatic Activation Energy Barrier &amp; Chemical Bonds in Biomolecules\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Graph: Activation Energy -->\n      <g transform=\"translate(40, 25)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">ENZYME ACTION: LOWERING ACTIVATION ENERGY</text>\n        <!-- Axes -->\n        <line x1=\"40\" y1=\"180\" x2=\"350\" y2=\"180\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <line x1=\"40\" y1=\"180\" x2=\"40\" y2=\"35\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <text x=\"35\" y=\"30\" font-size=\"8.5\" fill=\"#334155\" text-anchor=\"end\">Potential Energy</text>\n        <text x=\"200\" y=\"196\" font-size=\"8.5\" fill=\"#334155\" text-anchor=\"middle\">Progress of Reaction &rarr;</text>\n\n        <!-- Substrate line -->\n        <line x1=\"40\" y1=\"130\" x2=\"80\" y2=\"130\" stroke=\"#059669\" stroke-width=\"2\"/>\n        <text x=\"60\" y=\"122\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">Substrate (S)</text>\n\n        <!-- Uncatalyzed curve (Red) -->\n        <path d=\"M 80,130 C 130,10 200,10 270,165\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.2\" stroke-dasharray=\"4,2\"/>\n        <text x=\"175\" y=\"28\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#dc2626\">Activation Energy without enzyme</text>\n\n        <!-- Catalyzed curve (Green) -->\n        <path d=\"M 80,130 C 130,70 190,70 270,165\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2.5\"/>\n        <text x=\"175\" y=\"80\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#15803d\">Activation Energy with enzyme</text>\n\n        <!-- Product line -->\n        <line x1=\"270\" y1=\"165\" x2=\"330\" y2=\"165\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n        <text x=\"300\" y=\"157\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\">Product (P)</text>\n      </g>\n\n      <!-- Chemical Bonds on Right -->\n      <g transform=\"translate(440, 25)\">\n        <rect x=\"0\" y=\"0\" width=\"380\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"190\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">MAJOR COVALENT BONDS IN BIOPOLYMERS</text>\n\n        <!-- Peptide bond -->\n        <rect x=\"15\" y=\"38\" width=\"350\" height=\"42\" rx=\"6\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"55\" font-size=\"9\" font-weight=\"bold\" fill=\"#7c3aed\">1. Peptide Bond (\\(\\mathbf{-CO-NH-}\\)):</text>\n        <text x=\"25\" y=\"70\" font-size=\"8\" fill=\"#334155\">Forms between \\(\\alpha\\)-carboxyl of one amino acid &amp; \\(\\alpha\\)-amino group of next (-H\\(_2\\)O)</text>\n\n        <!-- Glycosidic bond -->\n        <rect x=\"15\" y=\"88\" width=\"350\" height=\"42\" rx=\"6\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"105\" font-size=\"9\" font-weight=\"bold\" fill=\"#059669\">2. Glycosidic Bond (\\(\\mathbf{-C-O-C-}\\)):</text>\n        <text x=\"25\" y=\"120\" font-size=\"8\" fill=\"#334155\">Dehydration linkage uniting adjacent monosaccharides (e.g., \\(\\alpha\\)-1,4 / \\(\\beta\\)-1,4)</text>\n\n        <!-- Phosphodiester bond -->\n        <rect x=\"15\" y=\"138\" width=\"350\" height=\"42\" rx=\"6\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"155\" font-size=\"9\" font-weight=\"bold\" fill=\"#2563eb\">3. Phosphodiester Bond (\\(\\mathbf{3'-5'}\\)):</text>\n        <text x=\"25\" y=\"170\" font-size=\"8\" fill=\"#334155\">Bridges 3'-OH of one pentose sugar to 5'-phosphate of adjacent nucleotide in DNA/RNA</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 15: Macromolecules, Chemical Bonds, Proteins, DNA Double Helix & Enzyme Catalysis</div>\n\n  <!-- c11b-ch9-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are macromolecules? Give examples.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Definition of Macromolecules:</strong><br>\n    Biomolecules found in living tissues are divided into two distinct analytical fractions when ground in trichloroacetic acid ($Cl_3C-COOH$):\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Acid-Soluble Pool (Filtrate / Biomicromolecules):</strong> Small organic molecules with molecular weights ranging strictly between <strong>18 and 800 Daltons (Da)</strong> (e.g., simple sugars, amino acids, nucleotides).</li>\n      <li><strong>Acid-Insoluble Fraction (Retentate / Biomolecules):</strong> Large, polymeric compounds characterized by high molecular weights exceeding <strong>10,000 Daltons</strong>. These are defined as <strong>biomacromolecules</strong>.</li>\n    </ul>\n    <strong>The Four Major Classes of Macromolecules in Living Systems:</strong><br>\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Proteins:</strong> Heteropolymers of $\\alpha$-amino acids joined by peptide bonds (e.g., Collagen, Hemoglobin, Insulin, RuBisCO).</li>\n      <li><strong>Polysaccharides:</strong> Complex polymers of monosaccharides linked by glycosidic bonds (e.g., Cellulose, Starch, Glycogen, Chitin).</li>\n      <li><strong>Nucleic Acids:</strong> Long polynucleotide chains linked by 3'-5' phosphodiester bonds (e.g., Deoxyribonucleic acid / DNA, Ribonucleic acid / RNA).</li>\n      <li><em>Note on Lipids:</em> Lipids have molecular weights under 800 Da, but form macromolecular aggregate vesicles in the acid-insoluble retentate due to hydrophobic interactions; hence, they are not strictly chemical macromolecules.</li>\n    </ol>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition based on acid-insoluble retentate with molecular weight >10,000 Daltons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Four classes: Proteins, Polysaccharides, Nucleic acids, and clarification regarding lipids</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Representative examples for each major class</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Illustrate a glycosidic, peptide and a phospho-diester bond.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Biochemical Nature and Formation of Key Biopolymer Linkages:</strong><br><br>\n    <strong>1. Peptide Bond (in Polypeptides / Proteins):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Formed when the carboxyl group ($-COOH$) of one $\\alpha$-amino acid reacts with the amino group ($-NH_2$) of the succeeding amino acid with the elimination of a water molecule (condensation dehydration reaction).</li>\n      <li>$$\\text{R}_1\\text{-CH(NH}_2\\text{)-COOH} + \\text{H}_2\\text{N-CH(R}_2\\text{)-COOH} \\xrightarrow{-\\text{H}_2\\text{O}} \\text{R}_1\\text{-CH(NH}_2\\text{)-}\\mathbf{CO-NH}\\text{-CH(R}_2\\text{)-COOH}$$</li>\n      <li>The planar linkage $\\mathbf{-CO-NH-}$ is the <strong>peptide bond</strong>.</li>\n    </ul>\n    <strong>2. Glycosidic Bond (in Polysaccharides):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Formed between two individual monosaccharide rings when the anomeric hydroxyl ($-OH$) group of one sugar condenses with a hydroxyl group of an adjacent sugar with the loss of one water molecule.</li>\n      <li>$$\\text{C}_6\\text{H}_{11}\\text{O}_5\\text{-OH} + \\text{HO-C}_6\\text{H}_{11}\\text{O}_5 \\xrightarrow{-\\text{H}_2\\text{O}} \\text{C}_6\\text{H}_{11}\\text{O}_5\\mathbf{-O-}\\text{C}_6\\text{H}_{11}\\text{O}_5$$</li>\n      <li>The ether linkage $\\mathbf{-C-O-C-}$ is the <strong>glycosidic bond</strong> (e.g., $\\alpha$-1,4-linkage in maltose/amylose; $\\beta$-1,4 in cellulose).</li>\n    </ul>\n    <strong>3. Phosphodiester Bond (in Nucleic Acids &mdash; DNA/RNA):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>A central phosphate group ($-\\text{PO}_4^{3-}$) forms two ester bonds simultaneously: one with the 3'-OH of the pentose sugar of one nucleotide, and the other with the 5'-OH of the sugar of the adjacent nucleotide.</li>\n      <li>$$\\text{Sugar}_1\\text{-3'-O-PO}_2^-\\text{-O-5'-Sugar}_2$$</li>\n      <li>This repeating $\\mathbf{3'-5'\\text{ phosphodiester linkage}}$ creates the continuous sugar-phosphate backbone of nucleic acids.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Peptide bond: condensation between carboxyl and amino groups (-CO-NH-)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Glycosidic bond: ether linkage between anomeric carbon and adjacent hydroxyl (-C-O-C-)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phosphodiester bond: dual esterification of phosphate bridging 3'-OH and 5'-OH sugars</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is meant by tertiary structure of proteins?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition and Significance of Tertiary ($3^\\circ$) Protein Structure:</strong><br>\n    The <strong>tertiary structure</strong> of a protein refers to the overall three-dimensional spatial conformation achieved when a secondary polypeptide chain (with $\\alpha$-helices and $\\beta$-pleated sheets) folds extensively upon itself like a hollow woolen ball, producing a compact globular shape.<br><br>\n    <strong>1. Non-Covalent and Covalent Stabilizing Forces:</strong><br>\n    Tertiary conformation is maintained by diverse chemical interactions among amino acid $R$-side chains:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Hydrophobic Interactions:</strong> Non-polar aliphatic and aromatic side chains (leucine, valine, phenylalanine) cluster internally away from surrounding aqueous cytosol.</li>\n      <li><strong>Hydrogen Bonds:</strong> Formed between polar uncharged side chains.</li>\n      <li><strong>Ionic (Electrostatic) Bonds / Salt Bridges:</strong> Formed between positively charged basic groups (lysine, arginine) and negatively charged acidic groups (aspartate, glutamate).</li>\n      <li><strong>Disulfide Bonds ($-S-S-$):</strong> Strong covalent linkages formed between two cysteine residues via oxidation of sulfhydryl ($-SH$) groups.</li>\n    </ul>\n    <strong>2. Biological Significance:</strong><br>\n    Tertiary structure is <strong>absolutely mandatory for biological activity</strong>. Folding brings distant amino acid residues together in 3D space to sculpt geometric pockets called <strong>active sites</strong>, enabling enzymes to bind specific substrates with high catalytic efficiency. Denaturation destroys the $3^\\circ$ conformation, causing irreversible loss of enzymatic activity.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of tertiary structure as extensive 3D globular folding like a woolen ball</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stabilizing bonds: hydrophobic interactions, H-bonds, ionic bonds, and disulfide bridges</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Biological significance: creates active sites essential for enzymatic catalytic activity</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Find and write for each of the following: (a) 10 polysaccharides (b) 5 proteins (c) 5 lipids (d) 5 nucleic acids / nucleotides.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Catalog of Biomolecules with Biological Functions:</strong><br><br>\n    <strong>(a) 10 Polysaccharides:</strong>\n    <ol style=\"margin:2px 0 6px 20px; font-size:0.85rem;\">\n      <li><em>Starch:</em> Major plant carbohydrate energy reserve ($alpha$-amylose + $alpha$-amylopectin).</li>\n      <li><em>Glycogen:</em> \"Animal starch\" stored in liver and skeletal muscles.</li>\n      <li><em>Cellulose:</em> Structural unbranched $\beta$-1,4-glucan of plant cell walls (most abundant organic molecule on Earth).</li>\n      <li><em>Chitin:</em> Exoskeleton of arthropods and fungal cell walls (polymer of N-acetylglucosamine / NAG).</li>\n      <li><em>Inulin:</em> Storage polymer of fructose found in dahlia tubers (used in renal clearance testing).</li>\n      <li><em>Agar-agar:</em> Sulfated galactan from red algae (solidifying agent).</li>\n      <li><em>Pectin:</em> Calcium-magnesium pectate forming middle lamella of plant cells.</li>\n      <li><em>Hyaluronic acid:</em> Viscous synovial fluid lubricant in animal joints.</li>\n      <li><em>Heparin:</em> Potent physiological anticoagulant polysaccharide in blood.</li>\n      <li><em>Dextran:</em> Bacterial branched polymer used as emergency blood plasma volume expander.</li>\n    </ol>\n    <strong>(b) 5 Proteins:</strong>\n    <ol style=\"margin:2px 0 6px 20px; font-size:0.85rem;\">\n      <li><em>Collagen:</em> Most abundant protein in animal world; primary intercellular ground substance.</li>\n      <li><em>RuBisCO:</em> Ribulose-1,5-bisphosphate carboxylase-oxygenase; most abundant protein in whole biosphere.</li>\n      <li><em>Hemoglobin:</em> Quaternary tetrameric oxygen-transport metalloprotein in RBCs.</li>\n      <li><em>Insulin:</em> Peptide hormone of 51 amino acids regulating blood glucose homeostasis.</li>\n      <li><em>Immunoglobulin (Antibody):</em> Y-shaped defensive glycoproteins produced by plasma B-cells.</li>\n    </ol>\n    <strong>(c) 5 Lipids:</strong>\n    <ol style=\"margin:2px 0 6px 20px; font-size:0.85rem;\">\n      <li><em>Lecithin (Phosphatidylcholine):</em> Dominant phospholipid component of cell membranes.</li>\n      <li><em>Palmitic Acid:</em> Saturated 16-carbon fatty acid ($CH_3(CH_2)_{14}COOH$).</li>\n      <li><em>Arachidonic Acid:</em> Polyunsaturated 20-carbon fatty acid with 4 double bonds.</li>\n      <li><em>Cholesterol:</em> Four-ring sterol regulating membrane fluidity and steroid precursor.</li>\n      <li><em>Triglyceride:</em> Neutral storage fat (triester of glycerol + 3 fatty acids).</li>\n    </ol>\n    <strong>(d) 5 Nucleic Acids / Nucleotides:</strong>\n    <ol style=\"margin:2px 0 6px 20px; font-size:0.85rem;\">\n      <li><em>Deoxyribonucleic Acid (DNA):</em> Master double-helical genetic material of all cellular life.</li>\n      <li><em>Ribonucleic Acid (RNA):</em> Single-stranded genetic/catalytic molecule (mRNA, tRNA, rRNA).</li>\n      <li><em>Adenosine Triphosphate (ATP):</em> Universal cellular high-energy currency.</li>\n      <li><em>Adenylic Acid (AMP):</em> Nucleotide monomer composed of adenine + ribose + phosphate.</li>\n      <li><em>Uridylic Acid (UMP):</em> Pyrimidine ribonucleotide found exclusively in RNA.</li>\n    </ol>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">10 valid polysaccharides with brief biological roles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">5 valid proteins with functions (Collagen, RuBisCO, Insulin, Hemoglobin, Antibodies)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">5 valid lipids (Lecithin, Palmitic, Arachidonic, Cholesterol, Triglycerides)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">5 valid nucleic acids/nucleotides (DNA, RNA, ATP, AMP, UMP)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Proteins have primary, secondary, tertiary and quaternary structure. Discuss each.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The Four Hierarchical Levels of Protein Structural Organization (Linderstr&oslash;m-Lang):</strong><br><br>\n    <strong>1. Primary Structure ($1^\\circ$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The linear sequence of amino acids in a polypeptide chain encoded by mRNA codons.</li>\n      <li>Positional information: The first amino acid is at the <strong>N-terminus</strong> (amino terminal), and the last amino acid is at the <strong>C-terminus</strong> (carboxyl terminal).</li>\n      <li>Maintained strictly by covalent <strong>peptide bonds</strong>. Any mutation changing the primary sequence can alter protein function (e.g., Sickle-cell anemia where Glu &rarr; Val at position 6 of $\\beta$-globin).</li>\n    </ul>\n    <strong>2. Secondary Structure ($2^\\circ$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Local folding of the polypeptide backbone into regular periodic spatial motifs stabilized by <strong>hydrogen bonds</strong> between the peptide $C=O$ and $N-H$ groups:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>$\\alpha$-Helix:</strong> Polypeptide chain is coiled into a right-handed spiral. Intrachain H-bonds form between the $C=O$ of residue $n$ and $N-H$ of residue $n+4$ (e.g., $\\alpha$-keratin in hair/wool).</li>\n          <li><strong>$\\beta$-Pleated Sheet:</strong> Polypeptide segments run parallel or antiparallel, joined by interchain or intrachain hydrogen bonds (e.g., silk fibroin).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Tertiary Structure ($3^\\circ$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Complex three-dimensional folding of secondary structure into a compact globular architecture.</li>\n      <li>Stabilized by hydrophobic interactions, ionic bonds, van der Waals forces, and covalent <strong>disulfide ($-S-S-$) bridges</strong>. Essential for enzymatic catalytic active site pockets (e.g., myoglobin, lysozyme).</li>\n    </ul>\n    <strong>4. Quaternary Structure ($4^\\circ$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Applies to multimeric proteins composed of two or more independent polypeptide chains (called <strong>subunits</strong> or protomers).</li>\n      <li>Subunits fit together in a precise geometric spatial arrangement. <em>Classic Example: Human Adult Hemoglobin ($HbA$)</em>, which is a tetramer composed of two identical $\\alpha$-subunits (141 amino acids each) and two identical $\\beta$-subunits (146 amino acids each) &mdash; ($2\\alpha + 2\\beta$).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Primary: linear sequence, N-terminal to C-terminal, peptide bonds</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secondary: alpha-helix and beta-pleated sheets stabilized by hydrogen bonds</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tertiary: 3D globular folding, hydrophobic/ionic/disulfide bonds, active sites</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quaternary: spatial fitting of multiple polypeptide subunits (e.g. Hemoglobin 2alpha + 2beta)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Find out how much cellulose is made by plants annually.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Global Annual Biosynthesis of Cellulose:</strong><br>\n    Cellulose is the primary structural homopolymer of $\\beta$-D-glucose units ($[C_6H_{10}O_5]_n$) in plant cell walls and is the <strong>most abundant organic macromolecule on Earth</strong>:<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Globally, terrestrial and aquatic photosynthetic vegetation synthesizes an estimated <strong>$10^{11}$ tonnes (approximately 100 billion tonnes or $100 \\times 10^9$ metric tons)</strong> of cellulose annually.</li>\n      <li>This colossal quantity represents roughly <strong>50% to 60% of all carbon fixed</strong> on Earth through photosynthesis each year.</li>\n      <li>Cotton fibers are nearly pure cellulose (~90%), whereas dry wood contains roughly 40% to 50% cellulose along with lignin and hemicellulose.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating approximately 10^11 tonnes (100 billion metric tons) synthesized annually</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention that it accounts for >50% of all annual photosynthetic carbon fixation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the important properties of enzymes.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Key Biochemical Properties of Enzymes (Biocatalysts):</strong><br><br>\n    <strong>1. Proteinaceous Nature:</strong><br>\n    Almost all enzymes are globular proteins possessing unique tertiary ($3^\\circ$) conformations (exceptions are catalytic RNA molecules called <strong>ribozymes</strong>, e.g., 23S rRNA).<br><br>\n    <strong>2. Unprecedented Catalytic Efficiency:</strong><br>\n    Enzymes accelerate chemical reaction rates by immense factors (ranging from $10^6$ to $10^{12}$ times). For instance, carbonic anhydrase hydrates 600,000 $CO_2$ molecules per second (turnover number = $36 \\times 10^6$ per min).<br><br>\n    <strong>3. Specificity of Action:</strong><br>\n    Enzymes display absolute or stereo-chemical substrate specificity: an enzyme typically catalyzes only one specific reaction or acts on one specific chemical bond (Lock-and-Key or Induced-Fit model).<br><br>\n    <strong>4. Unaltered at the End of Reaction:</strong><br>\n    Enzymes participate transiently in reactions by forming an unstable enzyme-substrate complex ($ES$), but are released completely chemically unchanged at reaction completion to catalyze new cycles.<br><br>\n    <strong>5. Lowering of Activation Energy:</strong><br>\n    Enzymes do not alter the overall free energy change ($\\Delta G$) or equilibrium constant ($K_{eq}$) of a reaction; they function strictly by lowering the <strong>activation energy barrier</strong> ($E_a$).<br><br>\n    <strong>6. Sensitivity to Temperature and pH:</strong><br>\n    Exhibit optimum catalytic activity at specific physiological temperature (37&deg;C in humans) and pH. High temperatures cause thermal denaturation, while low temperatures cause reversible inactivation.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Proteinaceous nature (with ribozyme exception) and active site architecture</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Enormous catalytic power and high substrate/reaction specificity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Unaltered at reaction completion & mechanism of lowering activation energy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sensitivity to environmental factors (optimum temperature and pH ranges)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the Watson-Crick model of DNA double helix.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The B-DNA Double Helix Model (James Watson &amp; Francis Crick, 1953):</strong><br>\n    Based on Rosalind Franklin &amp; Maurice Wilkins' X-ray diffraction data and Erwin Chargaff's rules, the B-form of DNA exhibits the following hallmark features:<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Two Polynucleotide Chains:</strong> DNA consists of two complementary helical polynucleotide chains wound around a common central imaginary axis in a right-handed spiral.</li>\n      <li><strong>2. Antiparallel Polarity:</strong> The two strands run in opposite directions: one strand has $5' \\rightarrow 3'$ polarity, and the complementary strand has $3' \\rightarrow 5'$ polarity.</li>\n      <li><strong>3. Sugar-Phosphate Backbone &amp; Inward Bases:</strong> The hydrophilic backbone is on the outside composed of alternating deoxyribose sugars and phosphate groups linked by $3'-5'$ phosphodiester bonds. The hydrophobic nitrogenous bases project inward perpendicular to the main axis.</li>\n      <li><strong>4. Complementary Base Pairing (Chargaff's Rule):</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Adenine (A) always pairs with Thymine (T) via <strong>two hydrogen bonds</strong> ($A = T$).</li>\n          <li>Guanine (G) always pairs with Cytosine (C) via <strong>three hydrogen bonds</strong> ($G \\equiv C$).</li>\n          <li>Consequently, a purine always pairs with a pyrimidine, maintaining a uniform constant helix diameter of <strong>2.0 nm (20 &Aring;)</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>5. Helical Dimensions:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Pitch of the helix (one complete $360^\\circ$ turn) = <strong>3.4 nm (34 &Aring;)</strong>.</li>\n          <li>There are approximately <strong>10 base pairs (bp)</strong> per helical turn.</li>\n          <li>Distance between two adjacent base pairs = <strong>0.34 nm (3.4 &Aring;)</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>6. Base Stacking Stability:</strong> The plane of one base pair stacks over the other in the double helix, conferring thermodynamic hydrophobic stability.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Two polynucleotide strands running in antiparallel orientation (5'->3' and 3'->5')</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sugar-phosphate external backbone and inward projecting nitrogenous bases</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complementary base pairing (A=T with 2 H-bonds; G=C with 3 H-bonds) & 2.0 nm width</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pitch of 3.4 nm, 10 bp per turn, and distance of 0.34 nm between base pairs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are co-factors? Describe the different types of co-factors with examples (prosthetic groups, co-enzymes, metal ions).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Co-factors:</strong><br>\n    Many enzymes are simple proteins, but numerous complex enzymes (called <strong>holoenzymes</strong>) require non-protein chemical components called <strong>co-factors</strong> to achieve catalytic activity. The proteinaceous portion of the enzyme is called the <strong>apoenzyme</strong>:\n    $$\\text{Holoenzyme (Active)} = \\text{Apoenzyme (Inactive Protein)} + \\text{Co-factor (Non-protein)}$$\n    If the co-factor is removed, the catalytic activity of the enzyme is completely lost.<br><br>\n    <strong>Three Distinct Categories of Co-factors:</strong><br><br>\n    <strong>1. Prosthetic Groups:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Non-protein organic compounds that are <strong>tightly and permanently bound</strong> to the apoenzyme by covalent or strong non-covalent forces.</li>\n      <li><em>Example:</em> <strong>Heme</strong> is the iron-porphyrin prosthetic group tightly attached to the active sites of <strong>catalase</strong> and <strong>peroxidase</strong>, which catalyze the decomposition of toxic hydrogen peroxide ($H_2O_2 \\rightarrow H_2O + \\frac{1}{2}O_2$).</li>\n    </ul>\n    <strong>2. Co-enzymes:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Non-protein organic compounds that are <strong>loosely and transiently bound</strong> to the apoenzyme, typically associating only during the course of catalysis. They function as transient carriers of electrons or chemical groups.</li>\n      <li>Most co-enzymes are derived from water-soluble vitamins:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>NAD</em> (Nicotinamide Adenine Dinucleotide) and <em>NADP</em> contain vitamin <strong>niacin</strong>.</li>\n          <li><em>FAD</em> and <em>FMN</em> contain vitamin <strong>riboflavin ($B_2$)</strong>.</li>\n          <li><em>Thiamine pyrophosphate (TPP)</em> contains vitamin <strong>thiamine ($B_1$)</strong>.</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Metal Ions (Co-factor Activators):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Inorganic metal cations that form coordination bonds with amino acid side chains at the active site and simultaneously with the substrate.</li>\n      <li><em>Examples:</em>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>$Zn^{2+}$:</strong> Essential co-factor for <strong>carboxypeptidase</strong>, carbonic anhydrase, and alcohol dehydrogenase.</li>\n          <li><strong>$Mg^{2+}$:</strong> Required by hexokinase, phosphofructokinase, and DNA/RNA polymerases.</li>\n          <li><strong>$Fe^{2+} / Fe^{3+}$:</strong> Component of cytochromes in electron transport chain.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of co-factor and formula: Holoenzyme = Apoenzyme + Co-factor</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prosthetic groups (tightly bound organic component) with Heme/Peroxidase example</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Co-enzymes (loosely bound vitamin derivatives) with NAD/NADP/Niacin example</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Metal ions (coordination complexes) with Zn2+/Carboxypeptidase example</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the competitive inhibition of enzymes with an example (malonate inhibiting succinate dehydrogenase).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Mechanism of Competitive Inhibition of Enzymes:</strong><br><br>\n    <strong>1. Molecular Principle:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Occurs when an inhibitor molecule closely resembles the natural substrate in its <strong>three-dimensional chemical and steric structure</strong>.</li>\n      <li>Due to structural similarity, the competitive inhibitor competes directly with the substrate for binding to the <strong>active site</strong> of the enzyme.</li>\n      <li>When the inhibitor binds to the active site, it forms an inactive Enzyme-Inhibitor ($EI$) complex, preventing substrate binding and reducing the reaction velocity.</li>\n      <li><strong>Reversibility:</strong> Competitive inhibition can be completely reversed by significantly increasing the concentration of the natural substrate.</li>\n      <li><strong>Kinetic Effects:</strong> $V_{max}$ remains unchanged, while $K_m$ (Michaelis constant) increases.</li>\n    </ul>\n    <strong>2. Classic Textbook Example &mdash; Inhibition of Succinate Dehydrogenase:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>In the Krebs cycle, the enzyme <strong>succinate dehydrogenase</strong> oxidizes <strong>succinate</strong> into fumarate.</li>\n      <li><strong>Malonate</strong> ($HOOC-CH_2-COOH$) has a 3-carbon dicarboxylic structure closely mimicking the 4-carbon substrate <strong>succinate</strong> ($HOOC-CH_2-CH_2-COOH$).</li>\n      <li>Malonate binds tightly to the active site of succinate dehydrogenase. Because malonate cannot be dehydrogenated, catalysis halts, blocking the Krebs cycle.</li>\n      <li><em>Clinical Application:</em> Sulfa drugs (sulfanilamide) competitively inhibit the bacterial enzyme that incorporates para-aminobenzoic acid (PABA) into folic acid, halting bacterial multiplication.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of structural similarity and competition for the active site</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reversibility by high substrate concentration & impact on Km and Vmax</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed example: Malonate mimicking succinate to inhibit succinate dehydrogenase</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Differentiate between homopolysaccharide and heteropolysaccharide.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Homopolysaccharides and Heteropolysaccharides:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Homopolysaccharide (Homoglycan)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Heteropolysaccharide (Heteroglycan)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Monomer Composition</td>\n            <td style=\"padding:8px 12px;\">Composed of only <strong>one single type of monosaccharide</strong> repeating unit throughout the entire polymer chain.</td>\n            <td style=\"padding:8px 12px;\">Composed of <strong>two or more different types of monosaccharides</strong> or their amino/acidic derivatives.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Hydrolysis Products</td>\n            <td style=\"padding:8px 12px;\">Complete acid or enzymatic hydrolysis yields only <strong>one kind of sugar</strong> (e.g., only glucose).</td>\n            <td style=\"padding:8px 12px;\">Hydrolysis yields a <strong>mixture of different sugars</strong>, uronic acids, and amino sugars.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Structural Complexity</td>\n            <td style=\"padding:8px 12px;\">Relatively uniform and simpler linear or branched architecture.</td>\n            <td style=\"padding:8px 12px;\">Highly complex, often modified with sulfate, carboxyl, or acetyl functional groups.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Representative Examples</td>\n            <td style=\"padding:8px 12px;\">\n              &bull; <strong>Starch</strong> (only $alpha$-glucose)<br>\n              &bull; <strong>Cellulose</strong> (only $\beta$-glucose)<br>\n              &bull; <strong>Glycogen</strong> (only $alpha$-glucose)<br>\n              &bull; <strong>Inulin</strong> (only fructose)\n            </td>\n            <td style=\"padding:8px 12px;\">\n              &bull; <strong>Peptidoglycan</strong> (NAG + NAM)<br>\n              &bull; <strong>Hyaluronic acid</strong> (D-glucuronic acid + NAG)<br>\n              &bull; <strong>Heparin</strong> and <strong>Chondroitin sulfate</strong><br>\n              &bull; <strong>Agar-agar</strong> (galactose + sulfated galactans)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Monomer composition: single type of monosaccharide vs two or more different types</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hydrolysis products comparison</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate examples for both (Starch/Cellulose/Inulin vs Peptidoglycan/Hyaluronic acid/Heparin)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why are lipids not strictly considered macromolecules?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Rationale Why Lipids Are Not Strictly Macromolecules:</strong><br><br>\n    <strong>1. Low Molecular Weight (<800 Daltons):</strong><br>\n    Biomacromolecules (such as proteins, nucleic acids, and polysaccharides) are characterized by having molecular weights exceeding <strong>10,000 Daltons</strong>. In sharp contrast, individual lipid molecules (fatty acids, triglycerides, and phospholipids like lecithin) have small molecular weights that <strong>never exceed 800 Daltons</strong>.<br><br>\n    <strong>2. Non-Polymeric Nature:</strong><br>\n    True macromolecules are polymers formed by the repetitive covalent bonding of monomeric sub-units (amino acids form proteins, nucleotides form DNA, glucose forms starch). Lipids are <strong>not polymers</strong>; a triglyceride is merely a single condensation ester of one glycerol molecule with three fatty acids.<br><br>\n    <strong>3. Reason for Presence in the Acid-Insoluble Fraction:</strong><br>\n    When living tissue is homogenized in trichloroacetic acid, cell membranes and organelle envelopes (plasma membrane, ER, mitochondria) are disrupted into fragments. Being hydrophobic and water-insoluble, these lipid fragments spontaneously aggregate into spherical <strong>vesicles (micelles / liposomes)</strong>. Because these large aggregates do not dissolve in aqueous acid, they fail to pass through the filter cloth and remain in the <strong>acid-insoluble retentate</strong> alongside true macromolecules.<br><br>\n    <strong>Conclusion:</strong> Structurally and biochemically, lipids belong to the <strong>biomicromolecules</strong>, but behaviorally they fractionate with the acid-insoluble macromolecular pool.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Molecular weight constraint: lipids have MW <800 Da, whereas macromolecules have MW >10,000 Da</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Non-polymeric chemical nature (triesters, not repeating polymer chains)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of hydrophobic vesicle aggregation causing retention in acid-insoluble fraction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is an active site of an enzyme? How does enzyme action lower activation energy?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. What is an Active Site?</strong><br>\n    An <strong>active site</strong> is a specific crevice, pocket, or cleft on the surface of an enzyme created by the folding of its tertiary ($3^\\circ$) polypeptide structure, lined with specific catalytic amino acid side chains. It is the designated site to which substrate molecules bind with high geometric and chemical complementarity to form an unstable intermediate <strong>Enzyme-Substrate ($ES$) complex</strong>.<br><br>\n    <strong>2. How Enzyme Action Lowers Activation Energy ($E_a$):</strong><br>\n    <strong>Activation energy</strong> is the minimum amount of energy required by reactant molecules to overcome the energy barrier and reach an unstable, high-energy <strong>transition state</strong> to convert into products.<br>\n    Enzymes drastically lower this barrier through several physical and chemical mechanisms:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Proximity and Orientation:</strong> Holds substrate molecules in the exact optimal spatial alignment for reactive bonds to collide.</li>\n      <li><strong>Substrate Strain (Induced Fit):</strong> Binding induces conformational changes that stretch and distort covalent bonds in the substrate, making them fragile and easier to cleave.</li>\n      <li><strong>Micro-environmental Catalysis:</strong> Provides specialized local environments (e.g., acidic/basic residues, hydrophobic pockets, metal ion coordination) that stabilize the transition state.</li>\n    </ul>\n    Consequently, a vastly larger proportion of reactant molecules possess sufficient thermal energy to achieve the lowered transition state, accelerating reaction rates millions of times without raising temperature.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of active site as tertiary pocket for substrate binding</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of activation energy barrier and transition state</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanisms of lowering Ea (proximity, bond strain, transition state stabilization)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the effect of temperature and pH on enzyme activity.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Impact of Temperature and pH on Enzymatic Catalytic Velocity:</strong><br><br>\n    <strong>1. Effect of Temperature:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Bell-Shaped Curve:</strong> Enzyme activity plotted against temperature displays a characteristic bell-shaped curve with a peak at an <strong>optimum temperature</strong> (typically 35&deg;C–40&deg;C in humans).</li>\n      <li><strong>Low Temperature (Below Optimum):</strong> At near-freezing temperatures, the enzyme is <strong>reversibly inactivated</strong> due to low kinetic energy; enzyme-substrate collisions are infrequent, but tertiary structure remains intact.</li>\n      <li><strong>Temperature Coefficient ($Q_{10}$):</strong> For every 10&deg;C rise in temperature up to optimum, reaction rate approximately doubles ($Q_{10} \\approx 2$).</li>\n      <li><strong>High Temperature (Above Optimum >45&deg;C–50&deg;C):</strong> Thermal energy disrupts weak hydrogen bonds, hydrophobic interactions, and ionic bridges maintaining the tertiary structure. The enzyme undergoes irreversible <strong>denaturation</strong>, destroying the active site. <em>(Exception: Thermophilic bacteria like Thermus aquaticus possess heat-stable enzymes surviving at 95&deg;C).</em></li>\n    </ul>\n    <strong>2. Effect of pH:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Optimum pH:</strong> Every enzyme exhibits maximum catalytic efficiency at a specific <strong>optimum pH</strong> (e.g., Pepsin at pH 1.5–2.0, Salivary Amylase at pH 6.8, Trypsin at pH 8.0).</li>\n      <li><strong>Mechanism of pH Sensitivity:</strong> Deviations from optimum pH alter the ionization states of acidic ($-COO^-$) and basic ($-NH_3^+$) amino acid side chains at the active site and substrate, preventing proper binding. Extreme acidic or alkaline pH causes protein denaturation.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Temperature effect: optimum temperature, reversible low-temp inactivation, high-temp thermal denaturation</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">pH effect: optimum pH with examples (pepsin pH 2, trypsin pH 8), alteration of charge/ionization states</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch9-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch9-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch9-q15')\">\n      <div class=\"q-num\">Question 15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are nucleic acids? Mention their components and functions.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Nucleic Acids:</strong><br>\n    <strong>Nucleic acids</strong> (DNA and RNA) are linear unbranched biopolymers of <strong>nucleotides</strong> (polynucleotides) that serve as the universal repository, replicator, and translator of hereditary genetic information in living systems.<br><br>\n    <strong>Three Fundamental Chemical Components of a Nucleotide:</strong><br>\n    <ol style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Nitrogenous Base:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Purines (double-ringed):</em> <strong>Adenine (A)</strong> and <strong>Guanine (G)</strong>.</li>\n          <li><em>Pyrimidines (single-ringed):</em> <strong>Cytosine (C)</strong>, <strong>Thymine (T)</strong> (in DNA only), and <strong>Uracil (U)</strong> (in RNA only).</li>\n        </ul>\n      </li>\n      <li><strong>Pentose Sugar (5-Carbon):</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>$\beta$-D-2-deoxyribose in DNA ($C_5H_{10}O_4$, lacking 2'-OH).</li>\n          <li>$\beta$-D-ribose in RNA ($C_5H_{10}O_5$, with 2'-OH).</li>\n        </ul>\n      </li>\n      <li><strong>Phosphate Group:</strong> Phosphoric acid ($H_3PO_4$) linking sugars via $3'-5'$ phosphodiester bonds.</li>\n    </ol>\n    <strong>Biological Functions of Nucleic Acids:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>DNA:</strong> Stores long-term genetic instructions; directs cellular protein synthesis through transcription; ensures fidelity of inheritance via semi-conservative replication.</li>\n      <li><strong>RNA:</strong> Directs protein synthesis via translation (mRNA templates, tRNA amino acid adapters, rRNA peptidyl transferase). Some RNAs act as catalytic ribozymes.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of nucleic acids as polynucleotides storing genetic code</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nitrogenous bases (Purines A/G vs Pyrimidines C/T/U)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pentose sugar (deoxyribose vs ribose) and phosphate group</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Functions of DNA (genetic mastercopy, replication) and RNA (translation, catalysis)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 8</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 10 (Cell Cycle and Cell Division) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[10] = "<section class=\"chapter-section\" id=\"c11b-ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 10</div>\n      <h2>Cell Cycle and Cell Division</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 16 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.67\"/></svg>\n      Eukaryotic Cell Cycle (Interphase &amp; M-Phase) and Meiotic Recombination\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Cell Cycle Wheel on Left -->\n      <g transform=\"translate(30, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">THE CELL CYCLE PHASES (24 HR DURATION)</text>\n        <circle cx=\"180\" cy=\"115\" r=\"75\" fill=\"#f8fafc\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n        \n        <!-- G1 Sector -->\n        <path d=\"M 180,115 L 180,40 A 75,75 0 0,1 250,90 Z\" fill=\"#ecfdf5\" stroke=\"#10b981\"/>\n        <text x=\"215\" y=\"70\" font-size=\"10\" font-weight=\"bold\" fill=\"#065f46\">G1 Phase</text>\n        <text x=\"215\" y=\"82\" font-size=\"7\" fill=\"#047857\">RNA/Protein synth</text>\n\n        <!-- S Sector -->\n        <path d=\"M 180,115 L 250,90 A 75,75 0 0,1 210,185 Z\" fill=\"#eff6ff\" stroke=\"#3b82f6\"/>\n        <text x=\"225\" y=\"140\" font-size=\"10\" font-weight=\"bold\" fill=\"#1e40af\">S Phase</text>\n        <text x=\"225\" y=\"152\" font-size=\"7\" fill=\"#1d4ed8\">DNA Replication 2C&rarr;4C</text>\n\n        <!-- G2 Sector -->\n        <path d=\"M 180,115 L 210,185 A 75,75 0 0,1 125,165 Z\" fill=\"#fefce8\" stroke=\"#eab308\"/>\n        <text x=\"160\" y=\"175\" font-size=\"10\" font-weight=\"bold\" fill=\"#854d0e\">G2 Phase</text>\n\n        <!-- M Phase Sector -->\n        <path d=\"M 180,115 L 125,165 A 75,75 0 0,1 180,40 Z\" fill=\"#fee2e2\" stroke=\"#ef4444\"/>\n        <text x=\"135\" y=\"80\" font-size=\"10\" font-weight=\"bold\" fill=\"#991b1b\">M Phase</text>\n        <text x=\"130\" y=\"92\" font-size=\"6.5\" fill=\"#7f1d1d\">P, M, A, T &amp; Cytokinesis</text>\n\n        <!-- G0 Quiescent arrow -->\n        <path d=\"M 235,50 Q 280,30 270,10\" stroke=\"#64748b\" stroke-width=\"1.5\" fill=\"none\" marker-end=\"url(#arrow)\"/>\n        <text x=\"290\" y=\"25\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#64748b\">G0 Phase (Quiescent)</text>\n      </g>\n\n      <!-- Meiosis Prophase I Stages on Right -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">PROPHASE I OF MEIOSIS &mdash; FIVE CONSECUTIVE SUB-STAGES</text>\n\n        <!-- 5 Sub-stages table -->\n        <g transform=\"translate(15, 35)\">\n          <rect x=\"0\" y=\"0\" width=\"370\" height=\"26\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n          <text x=\"10\" y=\"17\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#2563eb\">1. Leptotene:</text>\n          <text x=\"95\" y=\"17\" font-size=\"8\" fill=\"#334155\">Chromatin condenses; chromosomes become visible under light microscope.</text>\n\n          <rect x=\"0\" y=\"30\" width=\"370\" height=\"26\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n          <text x=\"10\" y=\"47\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#059669\">2. Zygotene:</text>\n          <text x=\"95\" y=\"47\" font-size=\"8\" fill=\"#334155\">Homologous chromosomes pair (<strong>Synapsis</strong>) forming bivalents / tetrads.</text>\n\n          <rect x=\"0\" y=\"60\" width=\"370\" height=\"26\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n          <text x=\"10\" y=\"77\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#ea580c\">3. Pachytene:</text>\n          <text x=\"95\" y=\"77\" font-size=\"8\" fill=\"#334155\"><strong>Crossing over</strong> mediated by <em>recombinase</em> enzyme at nodules.</text>\n\n          <rect x=\"0\" y=\"90\" width=\"370\" height=\"26\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n          <text x=\"10\" y=\"107\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#7c3aed\">4. Diplotene:</text>\n          <text x=\"95\" y=\"107\" font-size=\"8\" fill=\"#334155\">Synaptonemal complex dissolves; X-shaped <strong>Chiasmata</strong> become visible.</text>\n\n          <rect x=\"0\" y=\"120\" width=\"370\" height=\"26\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n          <text x=\"10\" y=\"137\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\">5. Diakinesis:</text>\n          <text x=\"95\" y=\"137\" font-size=\"8\" fill=\"#334155\"><strong>Terminalisation</strong> of chiasmata; nucleolus &amp; nuclear envelope vanish.</text>\n        </g>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 16: Interphase, Mitosis, Meiosis I & II, Crossing Over, Chiasmata & Syncytium</div>\n\n  <!-- c11b-ch10-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the average cell cycle span for a mammalian cell?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Average Cell Cycle Duration:</strong><br>\n    The average cell cycle duration for a typical proliferating human/mammalian somatic cell in culture is approximately <strong>24 hours</strong>.<br><br>\n    <strong>Temporal Distribution Across Phases:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Interphase (>95% of cycle):</strong> Lasts for roughly <strong>23 hours</strong>:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>$G_1$ Phase (Gap 1): ~8–10 hours</li>\n          <li>$S$ Phase (Synthesis): ~6–8 hours</li>\n          <li>$G_2$ Phase (Gap 2): ~4–5 hours</li>\n        </ul>\n      </li>\n      <li><strong>M-Phase (Mitosis + Cytokinesis):</strong> The actual dramatic division phase lasts for only <strong>about 1 hour</strong> (&lt;5% of total cell cycle duration).</li>\n    </ul>\n    <em>Comparative Note: Yeast (Saccharomyces cerevisiae) completes a cell cycle in just 90 minutes.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Stating 24 hours as the average cell cycle span for a mammalian cell</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Breakup: Interphase ~23 hours (>95%) and M-phase ~1 hour (<5%)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish cytokinesis from karyokinesis.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Karyokinesis and Cytokinesis:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Karyokinesis</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Cytokinesis</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Definition</td>\n            <td style=\"padding:8px 12px;\">Division of the cell's <strong>nucleus</strong> into two genetically identical daughter nuclei.</td>\n            <td style=\"padding:8px 12px;\">Division of the cell's <strong>cytoplasm</strong>, partitioning organelles into two separate daughter cells.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Timing in Cell Cycle</td>\n            <td style=\"padding:8px 12px;\">Precedes cytokinesis (occurs first during M-phase).</td>\n            <td style=\"padding:8px 12px;\">Follows karyokinesis (initiates during late anaphase / telophase).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Sequential Stages</td>\n            <td style=\"padding:8px 12px;\">Divided into four sequential stages: <strong>Prophase, Metaphase, Anaphase, and Telophase</strong>.</td>\n            <td style=\"padding:8px 12px;\">A continuous single mechanical event; no sub-phases.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Mechanism</td>\n            <td style=\"padding:8px 12px;\">Involves microtubular spindle apparatus, condensation of chromatin, and sister chromatid segregation.</td>\n            <td style=\"padding:8px 12px;\">Occurs via <strong>cleavage furrow</strong> (centripetal in animal cells) or <strong>cell plate formation</strong> via phragmoplast (centrifugal in plant cells).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition: nuclear division (karyokinesis) vs cytoplasmic division (cytokinesis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Order of occurrence and karyokinesis sub-phases (P, M, A, T)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism: spindle-mediated chromatid separation vs cleavage furrow / cell plate</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the events taking place during interphase.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Key Biochemical &amp; Morphological Events of Interphase (\"Resting / Preparation Phase\"):</strong><br>\n    Interphase is a period of intense metabolic activity during which the cell grows, replicates its genome, and prepares for division. It is subdivided into three successive phases:<br><br>\n    <strong>1. $G_1$ Phase (Gap 1 / Post-Mitotic Growth Phase):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The cell is metabolically exceptionally active and continuously grows in size.</li>\n      <li>Intense synthesis of RNA, structural proteins, and enzymes required for DNA replication (DNA polymerases, ligases, tubulin).</li>\n      <li>Replication of cellular organelles (mitochondria, ribosomes, endoplasmic reticulum).</li>\n      <li><em>DNA content remains constant at 2C; chromosome number remains 2n.</em></li>\n    </ul>\n    <strong>2. $S$ Phase (Synthesis Phase):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>DNA Replication:</strong> The quantity of nuclear DNA is accurately doubled from <strong>2C to 4C</strong> per cell ($2C \\rightarrow 4C$).</li>\n      <li><em>Critical Chromosome Rule:</em> <strong>Chromosome number is not changed</strong>; it remains strictly diploid ($2n$). Each chromosome now consists of two identical sister chromatids joined at a single centromere.</li>\n      <li>In animal cells, the <strong>centrosome (centriole pair) duplicates</strong> in the cytoplasm.</li>\n    </ul>\n    <strong>3. $G_2$ Phase (Gap 2 / Pre-Mitotic Phase):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Proteins essential for the assembly of the mitotic spindle apparatus (such as <strong>tubulin</strong>) are actively synthesized.</li>\n      <li>Cell continues to enlarge, synthesize ATP reserves, and checks for DNA replication errors (G2/M DNA damage checkpoint) before entering mitosis.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">G1 phase: intense metabolic growth, RNA/protein synthesis, organelle duplication</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">S phase: DNA doubling from 2C to 4C without changing chromosome number (2n) & centriole duplication</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">G2 phase: tubulin spindle protein synthesis, ATP accumulation, and mitotic readiness</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is $G_0$ (quiescent phase) of cell cycle?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Concept of $G_0$ (Quiescent / Resting) Phase:</strong><br><br>\n    <strong>1. Definition:</strong><br>\n    The <strong>$G_0$ phase</strong> is an inactive, quiescent stage of the cell cycle where cells exit the active proliferative cell cycle at the $G_1$ checkpoint and suspend division, without undergoing cell death.<br><br>\n    <strong>2. Metabolic and Proliferative Characteristics:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Cells in $G_0$ remain <strong>metabolically active and functional</strong>, performing their differentiated physiological duties, but they no longer proliferate or replicate DNA unless specifically stimulated.</li>\n      <li>They can re-enter the $G_1$ phase and resume active cell division upon receiving appropriate mitogenic signals (growth factors, tissue injury).</li>\n    </ul>\n    <strong>3. Examples:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>Permanent $G_0$:</em> Fully differentiated mature human <strong>heart muscle cells (cardiomyocytes)</strong> and <strong>neurons</strong>, which never divide in adult life.</li>\n      <li><em>Facultative / Conditional $G_0$:</em> <strong>Hepatocytes (liver cells)</strong> and fibroblasts remain in $G_0$ under normal conditions, but swiftly enter $G_1$ and proliferate to regenerate tissue following surgical resection or injury.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of G0 as exit from G1 into quiescent non-dividing state</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Metabolic status: cells remain fully active and differentiated but cease proliferation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Examples: Permanent (neurons, cardiac cells) vs Reversible (liver cells upon injury)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why is mitosis called equational division?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Reason Mitosis is Designated as Equational Division:</strong><br><br>\n    <strong>Mitosis</strong> is termed <strong>equational division</strong> because the number of chromosomes, their genetic composition, and their ploidy in the resulting daughter cells remain <strong>strictly equal and identical</strong> to that of the parent cell:<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>If a diploid parent cell has 46 chromosomes ($2n = 46$), each of the two daughter cells produced following mitotic division also receives exactly <strong>46 chromosomes ($2n = 46$)</strong>.</li>\n      <li><strong>Mechanism of Fidelity:</strong>\n        <ol style=\"margin:2px 0 4px 15px;\">\n          <li>During the 'S' phase of interphase, the DNA content of each chromosome is duplicated (forming two genetically identical sister chromatids attached at a single centromere).</li>\n          <li>During <strong>anaphase</strong> of mitosis, the centromere of each chromosome splits longitudinally, and the two sister chromatids are pulled apart to opposite poles as independent daughter chromosomes.</li>\n          <li>Consequently, each daughter nucleus receives an identical, complete set of genetic instructions without any numerical reduction or alteration of alleles (unlike meiosis where chromosome number is halved from $2n$ to $n$).</li>\n        </ol>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear statement: chromosome number in daughter cells remains identical to parent cell (2n to 2n)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism: S-phase replication followed by equational centromere splitting in anaphase</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the stage of cell cycle at which one of the following events occur:<br>(i) Chromosomes are moved to spindle equator.<br>(ii) Centromere splits and chromatids separate.<br>(iii) Pairing between homologous chromosomes takes place.<br>(iv) Crossing over between homologous chromosomes takes place.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Identification of Stages:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Event</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Exact Stage of Cell Division</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Biochemical / Cellular Basis</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(i) Chromosomes moved to spindle equator</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Metaphase (of Mitosis / Metaphase I or II)</td>\n            <td style=\"padding:8px 12px;\">Kinetochore spindle microtubules pull chromosomes into alignment along the metaphase plate (congression).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(ii) Centromere splits and chromatids separate</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Anaphase (of Mitosis) / Anaphase II (of Meiosis)</td>\n            <td style=\"padding:8px 12px;\">Cohesin cleavage causes simultaneous centromeric division; sister chromatids migrate to opposite poles.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(iii) Pairing between homologous chromosomes</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Zygotene (Sub-stage of Prophase I of Meiosis)</td>\n            <td style=\"padding:8px 12px;\"><strong>Synapsis</strong> occurs via assembly of the proteinaceous synaptonemal complex, forming bivalents.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(iv) Crossing over between homologous chromosomes</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Pachytene (Sub-stage of Prophase I of Meiosis)</td>\n            <td style=\"padding:8px 12px;\">Enzyme <strong>recombinase</strong> catalyzes reciprocal non-sister chromatid exchange at recombination nodules.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Metaphase</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Anaphase (Mitosis) / Anaphase II (Meiosis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Zygotene of Prophase I</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) Pachytene of Prophase I</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch7-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch7-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch7-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the following: (a) synapsis (b) bivalent (c) chiasmata. Draw a diagram to illustrate your answer.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Botanical &amp; Cytological Definitions of Meiotic Phenomena:</strong><br><br>\n    <strong>(a) Synapsis:</strong><br>\n    The intimate, highly specific, longitudinal point-by-point pairing of maternal and paternal homologous chromosomes during the <strong>zygotene</strong> sub-stage of Prophase I of meiosis. It is mediated by the assembly of a tripartite proteinaceous ladder-like framework called the <strong>synaptonemal complex</strong>.<br><br>\n    <strong>(b) Bivalent (or Tetrad):</strong><br>\n    The complex formed by a pair of synapsed homologous chromosomes. Since it consists of two distinct paired chromosomes, it is called a <strong>bivalent</strong>; because each chromosome has already duplicated into two chromatids, the pair exhibits four chromatids, termed a <strong>tetrad</strong> (clearly visible in pachytene).<br><br>\n    <strong>(c) Chiasmata:</strong><br>\n    The distinct <strong>X-shaped points of physical attachment</strong> between non-sister chromatids of homologous chromosomes, first visible during the <strong>diplotene</strong> stage when the synaptonemal complex dissolves and paired homologues begin to repel each other. Chiasmata represent the physical cytological sites where previous genetic <strong>crossing over</strong> occurred in pachytene.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Synapsis: homologous pairing via synaptonemal complex in zygotene</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bivalent / Tetrad: pair of synapsed chromosomes showing 4 chromatids</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Chiasmata: X-shaped sites of crossing over visible in diplotene</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How does cytokinesis in plant cells differ from that in animal cells?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Cytokinesis in Plant Cells and Animal Cells:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Cytokinesis in Plant Cells</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Cytokinesis in Animal Cells</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Mechanism of Division</td>\n            <td style=\"padding:8px 12px;\">Occurs by <strong>Cell Plate formation</strong>.</td>\n            <td style=\"padding:8px 12px;\">Occurs by <strong>Cleavage Furrow</strong> constriction.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Direction of Progression</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Centrifugal:</strong> Starts at the center of the cell and grows outward towards the lateral parent cell walls.</td>\n            <td style=\"padding:8px 12px; color:#2563eb; font-weight:700;\"><strong>Centripetal:</strong> Initiates at the plasma membrane periphery as a shallow furrow and deepens inwards toward the center.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Structural Role</td>\n            <td style=\"padding:8px 12px;\">Golgi-derived vesicles and spindle remnants coalesce at the equator to form a <strong>phragmoplast</strong>, which matures into the calcium pectate <strong>middle lamella</strong>.</td>\n            <td style=\"padding:8px 12px;\">A contractile ring composed of <strong>actin and myosin microfilaments</strong> constricts beneath the plasma membrane to pinch the cell in two.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Influence of Cell Wall</td>\n            <td style=\"padding:8px 12px;\">Necessitated by the presence of a rigid, inextensible outer cellulosic cell wall that cannot invaginate.</td>\n            <td style=\"padding:8px 12px;\">Facilitated by the flexible, elastic outer plasma membrane (cell wall is absent).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Plant: Cell plate method, centrifugal direction, phragmoplast/middle lamella</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Animal: Cleavage furrow, centripetal direction, contractile actin ring</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Find examples where the four stages of mitosis are suitable for observation.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Ideal Biological Materials for Observing the Four Stages of Mitosis:</strong><br><br>\n    <strong>1. Onion Root Tip Meristem (<em>Allium cepa</em>):</strong><br>\n    The classic, most universally used material in school and university laboratories for observing all four stages of mitosis because:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Cells in the sub-apical growing zone are actively dividing with no chloroplasts to obstruct vision.</li>\n      <li>Chromosomes are large, distinct, relatively few in number ($2n = 16$), and stain intensely with acetocarmine or Feulgen reagent.</li>\n    </ul>\n    <strong>2. Stage-Specific Optimal Observational Markers:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Prophase:</strong> Observable in root tip squashes: chromatin condenses into distinct entangled threads; nucleolus disappears.</li>\n      <li><strong>Metaphase:</strong> Best observed in root tips treated briefly with <em>colchicine</em> (arrests spindle assembly). Chromosomes are most condensed, shortest, thickest, and aligned at the equatorial plate &mdash; <strong>ideal for karyotyping, morphology, and counting chromosome number</strong>.</li>\n      <li><strong>Anaphase:</strong> Clearly displays centromere splitting and the characteristic V, L, J, or i shapes of migrating chromatids.</li>\n      <li><strong>Telophase &amp; Cytokinesis:</strong> Observable in growing shoot/root tips showing cell plate formation by phragmoplast.</li>\n    </ul>\n    <strong>3. Other Examples:</strong> Shoot apical meristems, bone marrow aspirates in animals, and blastula stages of fish/frog embryos.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Naming Onion root tip (Allium cepa) as the prime biological material</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Suitability of metaphase for counting/morphology & anaphase for centromere shape observation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Can there be mitosis without DNA replication in 'S' phase?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: No, normal mitosis cannot occur without DNA replication in the 'S' phase.</strong><br><br>\n    <strong>Biological &amp; Genetic Justification:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The fundamental evolutionary mandate of mitosis is <strong>equational division</strong>: to deliver a complete, uncompromised, identical complement of genetic information to both daughter cells.</li>\n      <li>DNA replication during the 'S' phase creates two identical sister chromatids per chromosome ($2C \\rightarrow 4C$).</li>\n      <li>If a cell skipped the S phase and attempted mitosis with unreplicated DNA ($2C$), when centromeres split in anaphase, each daughter cell would receive only an incomplete, fragmented half-set of genetic material ($1C$). Such cells would suffer massive gene deletions, aneuploidy, and instantaneous cell death.</li>\n      <li>Stringent biochemical cell cycle surveillance mechanisms (the <strong>$G_2/M$ DNA replication checkpoint</strong>) detect un-replicated DNA and activate checkpoint kinases ($ATM/ATR, Chk1$) to inhibit Cyclin B-CDK1 (MPF), halting the cell cycle and preventing entry into mitosis until replication is 100% complete.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear answer: No, normal mitosis cannot occur without S-phase DNA replication</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of severe genetic loss / aneuploidy & G2/M checkpoint block</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Can there be DNA replication without cell division?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: Yes, DNA replication can occur without subsequent cell division.</strong><br><br>\n    <strong>Biological Phenomena and Examples:</strong><br><br>\n    <strong>1. Endomitosis / Endoreduplication:</strong><br>\n    A phenomenon where chromosomes repeatedly replicate and duplicate their DNA content within the nucleus without undergoing nuclear membrane breakdown or cell division. This leads to <strong>polyploidy</strong> (multiple sets of chromosomes, e.g., $4n, 8n, 16n$).\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>Examples:</em> Tapetal nutritive cells in angiosperm anthers, human liver cells (hepatocytes), and bone marrow megakaryocytes (can reach up to $64n$).</li>\n    </ul>\n    <strong>2. Polytene Chromosomes (Giant Salivary Gland Chromosomes):</strong><br>\n    In the salivary glands of dipteran flies (such as <em>Drosophila melanogaster</em> and <em>Chironomus</em>), DNA replicates up to 10 rounds (1,024 strands) without chromatid separation or cell division, forming colossal banded <strong>polytene chromosomes</strong>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer: Yes, DNA replication can occur without division</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of endoreduplication/polyploidy with examples (tapetum, hepatocytes, polytene chromosomes)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Analyse the events of prophase I of meiosis.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>In-Depth Analysis of Prophase I of Meiosis I:</strong><br>\n    Prophase I is exceptionally prolonged, intricate, and crucial because it is the phase where homologous genetic recombination occurs. It is divided into five consecutive sub-stages:<br><br>\n    <strong>1. Leptotene (Thin-Thread Stage):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Chromatin fibers progressively condense and coil into long, slender, visible chromosomes.</li>\n      <li>Chromosomes often orient their telomeres towards one side of the nuclear envelope in a \"bouquet\" arrangement.</li>\n    </ul>\n    <strong>2. Zygotene (Paired-Thread Stage):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Homologous chromosomes (one paternal, one maternal) recognize each other and pair point-for-point in an event called <strong>synapsis</strong>.</li>\n      <li>Stabilized by the formation of a proteinaceous ribonucleoprotein structure called the <strong>synaptonemal complex</strong>.</li>\n      <li>The paired complex is called a <strong>bivalent</strong>.</li>\n    </ul>\n    <strong>3. Pachytene (Thick-Thread Stage):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Bivalents are clearly visible as four-chromatid <strong>tetrads</strong>.</li>\n      <li><strong>Crossing Over:</strong> Non-sister chromatids of homologous chromosomes exchange genetic segments at <strong>recombination nodules</strong>. The reaction is enzyme-mediated, catalyzed by <strong>recombinase</strong>. Produces novel genetic variations.</li>\n    </ul>\n    <strong>4. Diplotene (Two-Thread Stage):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The synaptonemal complex undergoes dissolution. Paired homologous chromosomes repel each other, except at points of crossing over.</li>\n      <li>These persistent X-shaped crossing-over junction points are called <strong>chiasmata</strong>. <em>(Can remain arrested for years, e.g., in human oocytes as dictyotene).</em></li>\n    </ul>\n    <strong>5. Diakinesis (Moving-Apart Stage):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Marked by <strong>terminalisation of chiasmata</strong> (chiasmata shift toward chromosome tips like a zipper).</li>\n      <li>Meiotic spindle begins to assemble; nucleolus completely disappears, and the nuclear envelope disintegrates.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Leptotene: chromosome condensation and bouquet formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Zygotene: synapsis, synaptonemal complex, bivalent formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Pachytene: tetrads, crossing over at recombination nodules with recombinase</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">4. Diplotene: dissolution of complex, appearance of X-shaped chiasmata</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">5. Diakinesis: terminalisation of chiasmata, loss of nucleolus and nuclear envelope</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Discuss with your teacher: (a) haploid insects and lower plants where cell division occurs (b) some haploid cells in higher plants where cell division occurs.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Haploid Insects and Lower Plants Where Cell Division Occurs:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Male Honeybees (Drones) &mdash; Arrhenotoky:</strong> In the honeybee (<em>Apis mellifera</em>), males are haploid ($n = 16$). They develop parthenogenetically from unfertilized eggs. All their somatic tissues grow by mitosis. Drones produce sperm by specialized mitosis (without meiosis).</li>\n      <li><strong>Lower Plants (Algae &amp; Bryophytes):</strong> The entire dominant, vegetative, multi-cellular plant body of algae (e.g., <em>Volvox</em>, <em>Spirogyra</em>) and bryophytes (e.g., <em>Marchantia</em>, <em>Funaria</em>) is <strong>haploid ($n$)</strong>. It undergoes millions of mitotic cell divisions to produce haploid leafy shoots and gametes.</li>\n    </ul>\n    <strong>(b) Haploid Cells in Higher Plants (Gymnosperms &amp; Angiosperms) Where Cell Division Occurs:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Pollen Grain (Microgametophyte):</strong> The haploid microspore ($n$) divides mitotically into a vegetative cell and a generative cell. The generative cell further undergoes mitosis to yield <strong>two haploid male gametes</strong>.</li>\n      <li><strong>Embryo Sac (Female Gametophyte):</strong> The functional haploid megaspore ($n$) undergoes three successive rounds of <strong>free nuclear mitotic divisions</strong> to form the 8-nucleate, 7-celled female gametophyte (egg cell, synergids, antipodals).</li>\n      <li><strong>Gymnosperm Endosperm:</strong> Arises directly from mitotic division of the haploid megaspore prior to fertilization (haploid endosperm).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Male honeybees (drones) and haploid gametophytes of algae/bryophytes</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Higher plants: pollen generative cell mitosis and functional megaspore mitosis (embryo sac)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Can there be mitosis without cell division? What would be the consequence?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: Yes, karyokinesis (nuclear division) can occur repeatedly without being accompanied by cytokinesis (cell division).</strong><br><br>\n    <strong>Biological Consequence:</strong><br>\n    The failure of cytokinesis following nuclear division results in the formation of a multinucleate mass of protoplasm called a <strong>syncytium</strong> (in animals) or a <strong>coenocyte</strong> (in plants and fungi).<br><br>\n    <strong>Classic Biological Examples:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Liquid Endosperm of Coconut:</strong> The primary endosperm nucleus undergoes hundreds of successive free nuclear mitotic divisions without cytokinesis, creating the milky fluid consisting of thousands of free nuclei (liquid coconut water).</li>\n      <li><strong>Slime Molds (Myxomycetes):</strong> During the vegetative phase, plasmodium forms a large, creeping, multinucleate mass of protoplasm.</li>\n      <li><strong>Skeletal Muscle Fibres:</strong> Multinucleate syncytial fibers formed by cell fusion.</li>\n      <li><strong>Coenocytic Fungi &amp; Algae:</strong> <em>Rhizopus</em> (Phycomycetes) and <em>Vaucheria</em> possess continuous tubular hyphae filled with multinucleate cytoplasm.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative confirmation: karyokinesis without cytokinesis is common</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Consequence: formation of multinucleate condition (syncytium / coenocyte)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Classic examples: liquid endosperm of coconut, slime molds, skeletal muscle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q15')\">\n      <div class=\"q-num\">Question 15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the significance of meiosis?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Evolutionary and Biological Significance of Meiosis:</strong><br><br>\n    <strong>1. Maintenance of Species Chromosome Number (Conservation of Karyotype):</strong><br>\n    Meiosis reduces the chromosome number by half from diploid ($2n$) to haploid ($n$) during gametogenesis in sexually reproducing organisms. When two haploid gametes fuse during fertilization (syngamy: $n + n = 2n$), the species-specific diploid chromosome number is precisely restored across generations, preventing doubling of chromosome numbers.<br><br>\n    <strong>2. Generation of Genetic Diversity and Variations:</strong><br>\n    Meiosis is the primary engine of genetic novelty through two distinct mechanisms:\n    <ul style=\"margin:2px 0 4px 15px;\">\n      <li><em>Crossing Over (Pachytene of Prophase I):</em> Physical exchange of non-sister chromatid segments breaks linkages and creates recombinant allele combinations.</li>\n      <li><em>Independent Assortment (Metaphase / Anaphase I):</em> Random orientation and maternal/paternal segregation of bivalents at the equator yields $2^n$ unique gametic combinations ($2^{23} \\approx 8.4$ million combinations in humans).</li>\n    </ul>\n    <strong>3. Raw Material for Natural Selection and Organic Evolution:</strong><br>\n    The unique genetic combinations generated by meiosis confer phenotypic variability, enabling populations to adapt to fluctuating environments and providing the raw material upon which natural selection acts.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Conservation of species-specific chromosome number across generations via gametic halving</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Creation of genetic diversity via crossing over and independent assortment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of variations in natural selection and organic evolution</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch10-q16 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch10-q16\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch10-q16')\">\n      <div class=\"q-num\">Question 16</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the stage of meiosis in which:<br>(i) Homologous chromosomes separate while sister chromatids remain associated at their centromeres.<br>(ii) Sister chromatids separate.<br>(iii) Synapsis occurs.<br>(iv) Chiasmata become visible.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Exact Stages of Meiosis:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Biological Event</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Specific Stage of Meiosis</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Cytological Hallmark</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(i) Homologous chromosomes separate while sister chromatids remain attached</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Anaphase I</td>\n            <td style=\"padding:8px 12px;\">Disjunction of bivalents occurs; centromeres do NOT split.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(ii) Sister chromatids separate</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Anaphase II</td>\n            <td style=\"padding:8px 12px;\">Centromeres split; sister chromatids move to opposite poles as individual chromosomes.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(iii) Synapsis occurs</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Zygotene (Prophase I)</td>\n            <td style=\"padding:8px 12px;\">Pairing of homologous chromosomes via the synaptonemal complex.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(iv) Chiasmata become visible</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Diplotene (Prophase I)</td>\n            <td style=\"padding:8px 12px;\">X-shaped crossovers appear as the synaptonemal complex dissolves.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Anaphase I</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Anaphase II</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Zygotene of Prophase I</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) Diplotene of Prophase I</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 9</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 11 (Photosynthesis in Higher Plants) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[11] = "<section class=\"chapter-section\" id=\"c11b-ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 11</div>\n      <h2>Photosynthesis in Higher Plants</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><line x1=\"12\" y1=\"1\" x2=\"12\" y2=\"3\"/><line x1=\"12\" y1=\"21\" x2=\"12\" y2=\"23\"/><line x1=\"4.22\" y1=\"4.22\" x2=\"5.64\" y2=\"5.64\"/><line x1=\"18.36\" y1=\"18.36\" x2=\"19.78\" y2=\"19.78\"/><line x1=\"1\" y1=\"12\" x2=\"3\" y2=\"12\"/><line x1=\"21\" y1=\"12\" x2=\"23\" y2=\"12\"/><line x1=\"4.22\" y1=\"19.78\" x2=\"5.64\" y2=\"18.36\"/><line x1=\"18.36\" y1=\"5.64\" x2=\"19.78\" y2=\"4.22\"/></svg>\n      Non-Cyclic Photophosphorylation (Z-Scheme) &amp; C4 Kranz Anatomy\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Z-Scheme on Left -->\n      <g transform=\"translate(35, 20)\">\n        <text x=\"200\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Z-SCHEME OF LIGHT REACTION (NON-CYCLIC)</text>\n        \n        <!-- PS II -->\n        <rect x=\"30\" y=\"125\" width=\"60\" height=\"35\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2\"/>\n        <text x=\"60\" y=\"146\" font-size=\"9\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">PS II (P680)</text>\n        <text x=\"60\" y=\"180\" font-size=\"7.5\" fill=\"#dc2626\" text-anchor=\"middle\">H2O &rarr; 2e- + 1/2 O2 + 2H+</text>\n\n        <!-- Excitation Up -->\n        <line x1=\"60\" y1=\"125\" x2=\"60\" y2=\"50\" stroke=\"#16a34a\" stroke-width=\"2\" marker-end=\"url(#arrow)\"/>\n        <rect x=\"30\" y=\"40\" width=\"60\" height=\"24\" rx=\"4\" fill=\"#dbeafe\" stroke=\"#2563eb\"/>\n        <text x=\"60\" y=\"56\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Primary Acc.</text>\n\n        <!-- ETS Downhill -->\n        <line x1=\"90\" y1=\"55\" x2=\"190\" y2=\"125\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"3,2\"/>\n        <text x=\"145\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#334155\">ETS (Cyt b6f)</text>\n        <text x=\"145\" y=\"98\" font-size=\"7.5\" fill=\"#059669\">ADP + Pi &rarr; ATP</text>\n\n        <!-- PS I -->\n        <rect x=\"190\" y=\"125\" width=\"60\" height=\"35\" rx=\"6\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2\"/>\n        <text x=\"220\" y=\"146\" font-size=\"9\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">PS I (P700)</text>\n\n        <!-- Excitation Up -->\n        <line x1=\"220\" y1=\"125\" x2=\"220\" y2=\"50\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n        <rect x=\"190\" y=\"40\" width=\"60\" height=\"24\" rx=\"4\" fill=\"#dbeafe\" stroke=\"#2563eb\"/>\n        <text x=\"220\" y=\"56\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Primary Acc.</text>\n\n        <!-- Ferredoxin to NADP+ -->\n        <line x1=\"250\" y1=\"55\" x2=\"320\" y2=\"85\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n        <rect x=\"290\" y=\"85\" width=\"85\" height=\"30\" rx=\"4\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n        <text x=\"332\" y=\"103\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">NADP+ &rarr; NADPH</text>\n      </g>\n\n      <!-- C4 Kranz Anatomy on Right -->\n      <g transform=\"translate(460, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"360\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"180\" y=\"22\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">KRANZ ANATOMY (C4 PLANTS: MAIZE, SUGARCANE)</text>\n        \n        <!-- Vascular Bundle center -->\n        <circle cx=\"180\" cy=\"110\" r=\"30\" fill=\"#e2e8f0\" stroke=\"#475569\" stroke-width=\"1.5\"/>\n        <text x=\"180\" y=\"114\" font-size=\"8\" font-weight=\"bold\" fill=\"#334155\" text-anchor=\"middle\">Vascular Bundle</text>\n\n        <!-- Bundle Sheath Wreath Ring -->\n        <circle cx=\"180\" cy=\"110\" r=\"55\" fill=\"none\" stroke=\"#059669\" stroke-width=\"20\" stroke-opacity=\"0.25\"/>\n        <text x=\"180\" y=\"70\" font-size=\"8\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Bundle Sheath Cells (Kranz)</text>\n        <text x=\"180\" y=\"155\" font-size=\"7.5\" fill=\"#065f46\" text-anchor=\"middle\">&bull; Agranal Chloroplasts &bull; High RuBisCO</text>\n\n        <!-- Outer Mesophyll Cells -->\n        <text x=\"180\" y=\"180\" font-size=\"8\" fill=\"#475569\" text-anchor=\"middle\">Mesophyll Cells: Fix CO2 via PEP carboxylase into OAA</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 10: Z-Scheme, C3 vs C4 Pathways, Kranz Anatomy, RuBisCO & Limiting Factors</div>\n\n  <!-- c11b-ch11-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        By looking at a plant externally can you tell whether a plant is C3 or C4? Why and how?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer &amp; Scientific Explanation:</strong><br>\n    <strong>No, by merely observing the external morphology of a plant, one cannot definitively tell whether a plant possesses the $C_3$ or $C_4$ photosynthetic pathway.</strong><br><br>\n    <strong>Scientific Reasons:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>The distinction between $C_3$ and $C_4$ plants is grounded entirely in <strong>internal leaf anatomy (Kranz anatomy)</strong> and <strong>sub-cellular biochemistry</strong> (the initial carboxylation enzyme: RuBisCO in $C_3$ vs. PEP carboxylase in $C_4$), not in gross macroscopic leaf morphology.</li>\n      <li>However, an informed ecological deduction can often be made based on <strong>habitat and taxonomic family</strong>:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>$C_4$ plants are predominantly tropical and subtropical grasses adapted to arid, high-temperature, high-light environments (e.g., Maize, Sugarcane, Sorghum, Amaranth).</li>\n          <li>$C_4$ plants frequently possess xerophytic features (thick cuticle, vertically oriented linear leaves to minimize transpiration) and maintain high vigor under intense sunlight and drought without wilting.</li>\n          <li>Conversely, typical temperate crops like Wheat, Rice, Barley, and Spinach are $C_3$ plants.</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>Conclusion:</strong> Definitive confirmation requires examining a transverse section of the leaf under a microscope to check for <strong>Kranz anatomy</strong>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear answer: No, cannot definitively tell by external morphology alone</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation: C3 vs C4 difference is anatomical/biochemical, though habitat (tropical arid) offers clues</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        By looking at which internal structure of a plant can you tell whether a plant is C3 or C4? Explain.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Internal Anatomical Structure: Kranz Anatomy</strong><br>\n    A plant can be definitively classified as $C_3$ or $C_4$ by examining the microscopic transverse section of its leaf for the presence or absence of <strong>Kranz anatomy</strong> (from the German word <em>'Kranz'</em> meaning wreath or crown):<br><br>\n    <strong>1. Anatomical Features of $C_4$ Plants (Kranz Anatomy Present):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Bundle Sheath Ring:</strong> Vascular bundles are encircled by one or several concentric layers of large, tightly packed cells called <strong>bundle sheath cells</strong>, forming a prominent wreath-like ring.</li>\n      <li><strong>Dimorphic Chloroplasts:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Bundle sheath chloroplasts:</em> Exceptionally large, lack grana (<strong>agranal</strong>), and store abundant starch grains. Rich in RuBisCO.</li>\n          <li><em>Mesophyll chloroplasts:</em> Smaller, possess well-developed grana (<strong>granal</strong>), and rich in PEP carboxylase (lack RuBisCO).</li>\n        </ul>\n      </li>\n      <li><strong>No Intercellular Spaces:</strong> Bundle sheath cells have thick walls impervious to gaseous exchange and lack intercellular spaces, trapping $CO_2$.</li>\n    </ul>\n    <strong>2. Anatomical Features of $C_3$ Plants (Kranz Anatomy Absent):</strong>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Leaves lack specialized bundle sheath rings. Mesophyll is differentiated into palisade and spongy parenchyma, and all chloroplasts are uniform (monomorphic) and granal.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Kranz anatomy in leaf transverse section</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Features of C4 Kranz anatomy (concentric bundle sheath cells, thick walls, no intercellular spaces)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dimorphic chloroplasts: agranal in bundle sheath vs granal in mesophyll</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Even though very few cells in a C4 plant carry out the biosynthetic-Calvin pathway, yet they are highly productive. Can you discuss why?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why $C_4$ Plants Exhibit Superior Photosynthetic Productivity:</strong><br>\n    In $C_4$ plants (e.g., Maize, Sugarcane), the Calvin cycle occurs exclusively in the specialized bundle sheath cells. Despite this spatial localization, $C_4$ plants have nearly double the photosynthetic yield of $C_3$ plants due to the following evolutionary adaptations:<br><br>\n    <strong>1. Complete Elimination of Photorespiration ($C_2$ Cycle):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>In $C_3$ plants, RuBisCO binds $O_2$ under high light and temperature, initiating photorespiration which wastes over 25–40% of fixed carbon and ATP without producing sugars.</li>\n      <li>In $C_4$ plants, <strong>photorespiration is completely absent</strong>.</li>\n    </ul>\n    <strong>2. Efficient $CO_2$-Concentrating Mechanism:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Primary $CO_2$ fixation occurs in mesophyll cells via <strong>PEP carboxylase</strong>, an enzyme with exceptionally high affinity for $HCO_3^-$ and zero affinity for oxygen ($O_2$).</li>\n      <li>$C_4$ organic acids (malate / aspartate) are shuttled into bundle sheath cells and decarboxylated, releasing a massive surge of $CO_2$ directly around RuBisCO.</li>\n      <li>This elevates the internal $CO_2$ concentration at the RuBisCO active site to saturating levels, completely suppressing its oxygenase activity and ensuring 100% carboxylation efficiency.</li>\n    </ul>\n    <strong>3. Tolerance to High Temperature and Water Stress:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>$C_4$ plants have higher temperature optima (30&deg;C–45&deg;C) and twice the water-use efficiency of $C_3$ plants, losing half as much water per gram of fixed $CO_2$.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Total absence of wasteful photorespiration in C4 plants</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Operation of CO2-concentrating pump via PEP carboxylase delivering high CO2 to bundle sheath</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">High light/temperature optima and superior water use efficiency</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        RuBisCO is an enzyme that acts both as a carboxylase and oxygenase. Why do you think RuBisCO carries out more carboxylation in C4 plants?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why RuBisCO Carboxylase Activity Dominates in $C_4$ Plants:</strong><br><br>\n    <strong>1. Dual Catalytic Affinity of RuBisCO:</strong><br>\n    RuBisCO (Ribulose-1,5-bisphosphate carboxylase-oxygenase) possesses a single active site that binds both $CO_2$ and $O_2$ competitively. Whether it acts as a carboxylase (synthesizing $PGA$) or an oxygenase (initiating photorespiration forming phosphoglycolate) is determined by the <strong>relative ratio of $CO_2$ to $O_2$ concentration</strong> at its catalytic site.<br><br>\n    <strong>2. Spatial Separation and the $C_4$ Biochemical Pump:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>In $C_4$ plants, RuBisCO is strictly localized inside the <strong>bundle sheath cells</strong> (completely absent in mesophyll cells).</li>\n      <li>Mesophyll cells fix atmospheric $CO_2$ into 4-carbon malate/aspartate via <strong>PEP carboxylase</strong>.</li>\n      <li>These $C_4$ acids are translocated through plasmodesmata into bundle sheath cells, where they are actively <strong>decarboxylated</strong> to release $CO_2$ and pyruvate.</li>\n      <li>This active decarboxylation maintains an artificially <strong>enormous partial pressure of $CO_2$</strong> immediately around RuBisCO.</li>\n      <li>Furthermore, bundle sheath chloroplasts lack granal thylakoids (agranal), meaning photolysis of water ($O_2$ evolution) does not occur in bundle sheath cells; hence, local $O_2$ levels remain negligible.</li>\n    </ul>\n    <strong>Conclusion:</strong> With overwhelming $CO_2$ concentration and virtually no $O_2$ competition, RuBisCO functions exclusively as a <strong>carboxylase</strong>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of competitive binding of CO2 and O2 at the RuBisCO active site</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of C4 dicarboxylic acid decarboxylation in creating exceptionally high local CO2 in bundle sheath</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Agranal nature of bundle sheath chloroplasts minimizing O2 competition, ensuring 100% carboxylation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Suppose there were plants that had a high concentration of Chlorophyll b, but lacked chlorophyll a, would it carry out photosynthesis? Then why do plants have accessory pigments?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Could a Plant Without Chlorophyll a Carry Out Photosynthesis?</strong><br>\n    <strong>No, the plant would not be able to carry out photosynthesis.</strong><br>\n    <em>Biological Justification:</em> <strong>Chlorophyll $a$ is the essential primary reaction center pigment</strong> (forming $P680$ in PS II and $P700$ in PS I). Only chlorophyll $a$ has the unique biophysical redox property of ejecting high-energy electrons upon photo-excitation to drive the photochemical electron transport chain and photolysis of water. All other pigments merely funnel excitation resonance energy to chlorophyll $a$.<br><br>\n    <strong>2. Why Do Plants Have Accessory Pigments (Chlorophyll b, Carotenoids, Xanthophylls)?</strong><br>\n    Accessory pigments are indispensable for two vital adaptive reasons:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Broadening the Absorption Spectrum of Light:</strong> Chlorophyll $a$ absorbs light primarily in the blue and red wavelengths. Accessory pigments absorb light at intermediary wavelengths (blue-green, yellow) where chlorophyll $a$ has low absorption, and transfer this harvested photon energy to the reaction center via resonance energy transfer (inductive resonance).</li>\n      <li><strong>Photoprotection Against Photo-Oxidation:</strong> Under intense solar irradiance, excess light can generate toxic reactive oxygen species (singlet oxygen) that destroy chlorophyll $a$. <strong>Carotenoids (carotenes and xanthophylls)</strong> act as molecular \"shields\" that quench excess excitation energy and dissipate it safely as heat, preventing photo-oxidative solarization.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear answer: No, because chlorophyll a is the sole photochemical reaction center pigment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role 1: Broadening light absorption spectrum to harvest wider photon wavelengths</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role 2: Photoprotection (carotenoids preventing photo-oxidation of chlorophyll a)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why is the colour of a leaf kept in the dark frequently yellow, or pale green? Which pigment do you think is more stable?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Why Leaves Kept in the Dark Turn Yellow or Pale Green (Etiolation):</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>The biosynthesis of green <strong>chlorophyll</strong> is light-dependent: light is strictly required to convert the precursor protochlorophyllide into active chlorophyll $a$ and $b$.</li>\n      <li>When a green plant is placed in prolonged darkness, new chlorophyll cannot be synthesized. Furthermore, existing chlorophyll molecules undergo continuous enzymatic degradation and breakdown by the enzyme chlorophyllase.</li>\n      <li>As chlorophyll degrades, the underlying yellow/orange <strong>carotenoid pigments (carotenes and xanthophylls)</strong> are unmasked, turning the leaf pale yellow &mdash; a physiological condition called <strong>etiolation</strong>.</li>\n    </ul>\n    <strong>2. Which Pigment is More Stable?</strong><br>\n    <strong>Carotenoids are significantly more chemically stable than chlorophylls.</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Chlorophyll molecules possess a delicate porphyrin ring with a central magnesium atom that rapidly degrades in the dark or under extreme stress.</li>\n      <li>Carotenoids are stable tetraterpenoid hydrocarbons that persist much longer in the absence of light, accounting for the characteristic yellow foliage in dark-kept plants and autumn leaves.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of light requirement for chlorophyll biosynthesis and dark degradation</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Unmasking of yellow carotenoid pigments leading to etiolation</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of carotenoids as more stable than chlorophylls with biochemical rationale</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Look at leaves of the same plant on the shady side and on the sunny side of a tree, or compare the leaves of potted plant kept in sunlight with one kept in shade. Which of them has a darker green colour? Why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer &amp; Scientific Explanation:</strong><br>\n    The leaves grown on the <strong>shady side (or shade-adapted plant)</strong> have a distinctly <strong>darker green colour</strong> than leaves exposed to direct bright sunlight.<br><br>\n    <strong>Physiological &amp; Photobiological Reasons:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Compensatory Pigment Synthesis in Low Light:</strong> In shade conditions, light intensity is a limiting factor. To optimize photon capture in dim, diffused light, shade-adapted leaves synthesize a <strong>higher concentration of chlorophyll</strong> (especially chlorophyll $b$) and package more thylakoids per granum. This elevated chlorophyll density per unit leaf area imparts a rich, dark-green appearance.</li>\n      <li><strong>2. Horizontal Chloroplast Orientation:</strong> In shade leaves, chloroplasts orient themselves parallel to the leaf surface (perpendicular to incident light rays) along the upper walls of palisade cells to intercept maximum available photons.</li>\n      <li><strong>3. Sun Leaves Adapt to Avoid Photo-Oxidation:</strong> Leaves on the sunny side receive saturating light intensities. They possess fewer chlorophyll molecules per chloroplast to avoid photo-inhibition and light-induced solarization. Their chloroplasts align along vertical lateral cell walls (parastrophy) to minimize excessive light absorption, making sun leaves appear lighter, yellowish-green.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification: Shade leaves are darker green than sun leaves</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Higher chlorophyll content and granal stacking to harvest limited light in shade</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Chloroplast orientation (face-on in shade vs profile/parastrophy in sun) and photoinhibition prevention</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Figure 13.10 shows the effect of light on the rate of photosynthesis. Based on the graph, answer the following:<br>(a) At which point/s (A, B or C) in the curve is light a limiting factor?<br>(b) What could be the limiting factor/s in region A?<br>(c) What do C and D represent on the curve?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Analysis of Blackman's Law of Limiting Factors Light Curve:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(a) At which point/s is light a limiting factor?</strong><br>\n      Light is a limiting factor at <strong>Point A</strong> (and along the linear ascending slope between A and B). In this region, any increase in light intensity results in a direct, proportional increase in the rate of photosynthesis.</li>\n      <li><strong>(b) What could be the limiting factor/s in region A?</strong><br>\n      In region A, <strong>Light Intensity</strong> itself is the primary limiting factor. <em>(Additionally, if light is made abundant, carbon dioxide concentration or temperature could become secondary limiting factors as per Blackman's Law).</em></li>\n      <li><strong>(c) What do C and D represent on the curve?</strong><br>\n      <ul style=\"margin:2px 0 4px 15px;\">\n        <li><strong>Point C represents Light Saturation:</strong> The plateau point where photosynthesis reaches its maximum velocity ($V_{max}$). Here, light is no longer limiting; other factors ($CO_2$ concentration or enzymatic temperature) have become limiting. Light saturation occurs at roughly 10% of full sunlight.</li>\n        <li><strong>Region D represents Photo-inhibition / Solarization:</strong> If light intensity is increased beyond point D, the rate of photosynthesis does not increase; rather, excessive radiation causes the breakdown (photo-oxidation) of chlorophyll pigments and destructive photo-inhibition.</li>\n      </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Point A (linear phase where light limits rate)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Light intensity is the limiting factor in region A</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) C = Light saturation point (10% full sunlight); D = Plateau / Photo-oxidation zone</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give comparison between the following: (a) C3 and C4 pathways (b) Cyclic and non-cyclic photophosphorylation (c) Anatomy of leaf in C3 and C4 plants.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between $C_3$ and $C_4$ Photosynthetic Pathways:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 8px;\">Feature</th><th style=\"padding:6px 8px;\">$C_3$ Pathway (Calvin Cycle)</th><th style=\"padding:6px 8px;\">$C_4$ Pathway (Hatch-Slack)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">Primary $CO_2$ Acceptor</td><td style=\"padding:6px 8px;\">RuBP (5-Carbon keto-sugar)</td><td style=\"padding:6px 8px;\">PEP (Phosphoenolpyruvate &mdash; 3C)</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">First Stable Product</td><td style=\"padding:6px 8px;\">3-PGA (3-Phosphoglyceric acid &mdash; 3C)</td><td style=\"padding:6px 8px;\">OAA (Oxaloacetic acid &mdash; 4C)</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">Photorespiration</td><td style=\"padding:6px 8px; color:#dc2626; font-weight:700;\">High (wastes 25–40% energy)</td><td style=\"padding:6px 8px; color:#16a34a; font-weight:700;\">Completely absent</td></tr>\n          <tr><td style=\"padding:6px 8px; font-weight:700;\">ATP per Hexose Fixed</td><td style=\"padding:6px 8px;\">18 ATP + 12 NADPH</td><td style=\"padding:6px 8px;\">30 ATP + 12 NADPH</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Cyclic vs. Non-Cyclic Photophosphorylation:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 8px;\">Feature</th><th style=\"padding:6px 8px;\">Cyclic Photophosphorylation</th><th style=\"padding:6px 8px;\">Non-Cyclic Photophosphorylation (Z-Scheme)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">Photosystems Involved</td><td style=\"padding:6px 8px;\">Only <strong>PS I ($P700$)</strong> participates.</td><td style=\"padding:6px 8px;\">Both <strong>PS II ($P680$) and PS I ($P700$)</strong> participate.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">Photolysis of $H_2O$ &amp; $O_2$ Evolution</td><td style=\"padding:6px 8px; color:#dc2626;\">Absent; no oxygen released.</td><td style=\"padding:6px 8px; color:#16a34a;\">Present; $O_2$ evolved by water-splitting complex.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 8px; font-weight:700;\">Products Synthesized</td><td style=\"padding:6px 8px;\"><strong>Only ATP</strong> (no NADPH formed).</td><td style=\"padding:6px 8px;\"><strong>Both ATP and NADPH</strong> synthesized.</td></tr>\n          <tr><td style=\"padding:6px 8px; font-weight:700;\">Location</td><td style=\"padding:6px 8px;\">Stroma lamellae membranes (lacks PS II &amp; NADP reductase).</td><td style=\"padding:6px 8px;\">Granal thylakoid membranes.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(c) Anatomy of Leaf in $C_3$ vs. $C_4$ Plants:</strong><br>\n    $C_3$ leaves have undifferentiated or standard mesophyll, no Kranz wreath ring, and monomorphic chloroplasts. $C_4$ leaves have distinct <strong>Kranz anatomy</strong>, thick-walled bundle sheath cells, and dimorphic chloroplasts (agranal bundle sheath vs granal mesophyll).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) C3 vs C4 pathways: primary acceptor, 1st stable product, photorespiration, ATP cost</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cyclic vs Non-cyclic: photosystems, photolysis/O2 release, products (ATP vs ATP+NADPH)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Leaf anatomy: Kranz anatomy, bundle sheath rings, dimorphic chloroplasts</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch11-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch11-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch11-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the external and internal factors that affect photosynthesis?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Factors Regulating the Rate of Photosynthesis (Blackman's Law of Limiting Factors):</strong><br><br>\n    <strong>A. External (Environmental) Factors:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Light:</strong> Governed by light intensity, wavelength quality (maximum in red and blue regions), and photoperiod duration. Light saturation occurs at ~10% full sunlight.</li>\n      <li><strong>2. Carbon Dioxide Concentration:</strong> Major limiting factor in atmosphere (~0.04% or 400 ppm). Increasing $CO_2$ up to 0.05% (500 ppm) increases photosynthesis ($C_4$ saturates at 360 ppm, $C_3$ saturates at 450 ppm; exploited in greenhouse crops like tomatoes and bell peppers).</li>\n      <li><strong>3. Temperature:</strong> Dark enzymatic reactions are temperature-sensitive. $C_4$ plants have a high optimum (30&deg;C–45&deg;C), whereas $C_3$ plants have a lower optimum (20&deg;C–25&deg;C).</li>\n      <li><strong>4. Water:</strong> Water stress causes stomatal closure, choking $CO_2$ supply, and causes leaf wilting, reducing surface area.</li>\n    </ul>\n    <strong>B. Internal (Plant) Factors:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Number, Size, Age and Orientation of Leaves:</strong> Young fully expanded leaves perpendicular to sunlight display maximal photosynthetic rates.</li>\n      <li><strong>2. Mesophyll Cells &amp; Chloroplasts:</strong> Higher number of chloroplasts per cell accelerates photosynthetic capacity.</li>\n      <li><strong>3. Internal $CO_2$ Concentration:</strong> Maintained by stomatal aperture conductance.</li>\n      <li><strong>4. Amount of Chlorophyll:</strong> Adequate chlorophyll concentration is necessary for light harvesting.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">External: Light (intensity, quality, duration) and CO2 concentration (C3 vs C4 saturation)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">External: Temperature (enzymatic optimum) and Water stress / stomatal closure</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Internal: Leaf age/size/orientation, mesophyll chloroplast count, chlorophyll amount</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 10</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 12 (Respiration in Plants) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[12] = "<section class=\"chapter-section\" id=\"c11b-ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 12</div>\n      <h2>Respiration in Plants</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 9 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"/></svg>\n      Cellular Respiration: Krebs Cycle &amp; Mitochondrial Electron Transport Chain\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Krebs Cycle on Left -->\n      <g transform=\"translate(30, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">KREBS (TCA) CYCLE IN MITOCHONDRIAL MATRIX</text>\n        <circle cx=\"180\" cy=\"115\" r=\"70\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-dasharray=\"6,3\"/>\n        \n        <!-- Steps around circle -->\n        <rect x=\"135\" y=\"40\" width=\"90\" height=\"22\" rx=\"4\" fill=\"#ecfdf5\" stroke=\"#059669\"/>\n        <text x=\"180\" y=\"55\" font-size=\"8\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Citrate (6C)</text>\n\n        <rect x=\"220\" y=\"105\" width=\"105\" height=\"22\" rx=\"4\" fill=\"#fef3c7\" stroke=\"#d97706\"/>\n        <text x=\"272\" y=\"120\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">&alpha;-Ketoglutarate (5C)</text>\n\n        <rect x=\"135\" y=\"165\" width=\"90\" height=\"22\" rx=\"4\" fill=\"#eff6ff\" stroke=\"#2563eb\"/>\n        <text x=\"180\" y=\"180\" font-size=\"8\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Succinate (4C)</text>\n\n        <rect x=\"35\" y=\"105\" width=\"100\" height=\"22\" rx=\"4\" fill=\"#fdf4ff\" stroke=\"#a21caf\"/>\n        <text x=\"85\" y=\"120\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#701a75\" text-anchor=\"middle\">Oxaloacetate (4C)</text>\n\n        <text x=\"180\" y=\"112\" font-size=\"8\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Acetyl-CoA (2C)</text>\n        <text x=\"180\" y=\"124\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">+ OAA &rarr; Citric Acid</text>\n      </g>\n\n      <!-- Mitochondrial ETS on Right -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">ELECTRON TRANSPORT SYSTEM (ETS &amp; ATP SYNTHESIS)</text>\n\n        <!-- Inner membrane representation -->\n        <rect x=\"15\" y=\"70\" width=\"370\" height=\"35\" fill=\"#fef2f2\" stroke=\"#f87171\" stroke-width=\"1.5\"/>\n        <text x=\"200\" y=\"92\" font-size=\"8\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Mitochondrial Inner Membrane (Complexes I, II, III, IV)</text>\n\n        <text x=\"200\" y=\"55\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\" text-anchor=\"middle\">Intermembrane Space (High H+ Gradient: Proton Reservoir)</text>\n        <text x=\"200\" y=\"130\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\" text-anchor=\"middle\">Mitochondrial Matrix (Low H+ Concentration)</text>\n\n        <!-- ATP Synthase F0-F1 -->\n        <g transform=\"translate(290, 60)\">\n          <rect x=\"10\" y=\"10\" width=\"16\" height=\"35\" fill=\"#7c3aed\"/>\n          <circle cx=\"18\" cy=\"62\" r=\"14\" fill=\"#a78bfa\" stroke=\"#6d28d9\"/>\n          <text x=\"18\" y=\"66\" font-size=\"7\" font-weight=\"bold\" fill=\"#ffffff\" text-anchor=\"middle\">F1</text>\n          <text x=\"18\" y=\"86\" font-size=\"7\" fill=\"#4c1d95\" text-anchor=\"middle\">ATP</text>\n        </g>\n        <text x=\"250\" y=\"165\" font-size=\"8\" fill=\"#334155\">&bull; Chemiosmotic ATP synthesis via Fo-F1 ATP synthase complex</text>\n        <text x=\"250\" y=\"180\" font-size=\"8\" fill=\"#334155\">&bull; 1 NADH &rarr; 3 ATP &nbsp;|&nbsp; 1 FADH2 &rarr; 2 ATP</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 9: Glycolysis, Krebs Cycle, ETS, ATP Balance, Amphibolic Pathway & RQ</div>\n\n  <!-- c11b-ch12-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Differentiate between: (a) Respiration and Combustion (b) Glycolysis and Fermentation (c) Aerobic respiration and Anaerobic respiration.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between Cellular Respiration and Combustion:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Parameter</th><th style=\"padding:6px 10px;\">Cellular Respiration</th><th style=\"padding:6px 10px;\">Combustion</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Nature of Process</td><td style=\"padding:6px 10px;\">Biological, intracellular enzymatic reaction.</td><td style=\"padding:6px 10px;\">Non-biological, physico-chemical burning.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Temperature</td><td style=\"padding:6px 10px;\">Occurs at constant physiological body temperature (~37&deg;C).</td><td style=\"padding:6px 10px;\">Occurs at high ignition temperatures.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Energy Release</td><td style=\"padding:6px 10px;\">Stepwise release trapped in chemical bonds of <strong>ATP</strong> (~40% efficiency).</td><td style=\"padding:6px 10px;\">Sudden uncontrolled release as light and heat.</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Enzymes</td><td style=\"padding:6px 10px;\">Regulated by a series of distinct intracellular enzymes.</td><td style=\"padding:6px 10px;\">No enzymes involved.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Differences Between Glycolysis and Fermentation:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Parameter</th><th style=\"padding:6px 10px;\">Glycolysis (EMP Pathway)</th><th style=\"padding:6px 10px;\">Fermentation (Anaerobic)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Substrate &amp; Product</td><td style=\"padding:6px 10px;\">1 Glucose breaks down into <strong>2 molecules of Pyruvic acid</strong>.</td><td style=\"padding:6px 10px;\">Pyruvic acid converts into <strong>Ethyl alcohol + $CO_2$</strong> or <strong>Lactic acid</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Net ATP Yield</td><td style=\"padding:6px 10px;\">Net <strong>2 ATP + 2 $NADH + H^+$</strong> synthesized.</td><td style=\"padding:6px 10px;\">No additional ATP produced beyond glycolysis (reoxidizes NADH to $NAD^+$).</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Occurrence</td><td style=\"padding:6px 10px;\">Universal first step in all living cells (aerobic &amp; anaerobic).</td><td style=\"padding:6px 10px;\">Occurs in anaerobic microorganisms (yeast) and hypoxic muscles.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(c) Differences Between Aerobic and Anaerobic Respiration:</strong><br>\n    Aerobic respiration completely oxidizes glucose into $CO_2$ and $H_2O$ using molecular $O_2$ via glycolysis, Krebs cycle, and ETS in mitochondria, yielding ~36 to 38 ATP. Anaerobic respiration occurs without $O_2$ in cytoplasm, causing incomplete oxidation into ethanol or lactic acid, yielding only 2 net ATP (&lt;7% of available chemical energy).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Respiration vs Combustion: biological/enzymatic vs physical, stepwise ATP trapping vs heat/light</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Glycolysis vs Fermentation: glucose to pyruvate vs pyruvate to alcohol/lactate, ATP yields</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Aerobic vs Anaerobic: O2 requirement, complete vs incomplete oxidation, 36-38 ATP vs 2 ATP</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are respiratory substrates? Name the most common respiratory substrate.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Definition of Respiratory Substrates:</strong><br>\n    <strong>Respiratory substrates</strong> are energy-rich organic compounds present within living protoplasm that undergo intracellular enzymatic oxidation (catabolic cleavage of carbon-carbon covalent bonds) during cellular respiration to release metabolic energy stored in the form of ATP.<br><br>\n    <strong>Major Types of Substrates:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Carbohydrates:</strong> (Glucose, fructose, sucrose, starch, glycogen).</li>\n      <li><strong>Fats / Lipids:</strong> (Triglycerides, fatty acids &mdash; yielding maximum energy per gram upon $\beta$-oxidation).</li>\n      <li><strong>Proteins:</strong> (Hydrolyzed into amino acids and oxidized during starvation or prolonged fasting &mdash; protoplasmic respiration).</li>\n      <li><strong>Organic Acids:</strong> (Malic acid, citric acid in succulents).</li>\n    </ul>\n    <strong>2. Most Common Respiratory Substrate:</strong><br>\n    The most universally preferred and primary respiratory substrate in all living organisms is <strong>Glucose ($C_6H_{12}O_6$)</strong>. Complex carbohydrates (starch, sucrose) are initially enzymatically hydrolyzed into hexoses (glucose/fructose) before entering the glycolytic pathway (floating respiration).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of respiratory substrates as oxidizable organic compounds releasing ATP</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Glucose (hexose monosaccharide) as the most common respiratory substrate</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give the schematic representation of glycolysis.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Schematic 10-Step Sequence of Glycolysis (EMP Pathway &mdash; Embden, Meyerhof, Parnas):</strong><br>\n    Occurs in the <strong>cytosol (cytoplasm)</strong> of all living cells; anaerobic process.<br><br>\n    <div style=\"background:#f8fafc; padding:14px; border-radius:8px; border:1px solid #cbd5e1; font-family:'JetBrains Mono',monospace; font-size:0.8rem; line-height:1.7;\">\n      1. Glucose (6C) + ATP &rarr; <strong>Glucose-6-phosphate</strong> (6C) + ADP &nbsp;[Enzyme: Hexokinase]<br>\n      2. Glucose-6-phosphate &harr; <strong>Fructose-6-phosphate</strong> (6C) &nbsp;[Phosphoglucoisomerase]<br>\n      3. Fructose-6-phosphate + ATP &rarr; <strong>Fructose-1,6-bisphosphate</strong> (6C) + ADP &nbsp;[Phosphofructokinase - PFK]<br>\n      4. Fructose-1,6-bisphosphate &harr; <strong>Glyceraldehyde-3-phosphate (PGAL &mdash; 3C)</strong> + <strong>DHAP (3C)</strong> &nbsp;[Aldolase]<br>\n      5. DHAP &harr; <strong>Glyceraldehyde-3-phosphate (PGAL &mdash; 3C)</strong> &nbsp;[Triose phosphate isomerase]<br>\n      <em>(From this point, all reactions occur twice per glucose molecule):</em><br>\n      6. 2 PGAL + 2 $NAD^+ + 2 H_3PO_4$ &harr; <strong>2 molecules of 1,3-Bisphosphoglycerate (1,3-BPGA)</strong> + 2 $NADH + 2H^+$ &nbsp;[GAPDH]<br>\n      7. 2 (1,3-BPGA) + 2 ADP &harr; <strong>2 molecules of 3-Phosphoglycerate (3-PGA)</strong> + <strong>2 ATP</strong> &nbsp;[Phosphoglycerate kinase]<br>\n      8. 2 (3-PGA) &harr; <strong>2 molecules of 2-Phosphoglycerate (2-PGA)</strong> &nbsp;[Phosphoglycerate mutase]<br>\n      9. 2 (2-PGA) &harr; <strong>2 molecules of Phosphoenolpyruvate (PEP &mdash; 3C)</strong> + $2 H_2O$ &nbsp;[Enolase]<br>\n      10. 2 PEP + 2 ADP &rarr; <strong>2 molecules of Pyruvic Acid (3C)</strong> + <strong>2 ATP</strong> &nbsp;[Pyruvate kinase]\n    </div>\n    <br>\n    <strong>Net Balance Sheet of Glycolysis:</strong><br>\n    $$\\text{Glucose} + 2\\text{ADP} + 2\\text{P}_i + 2\\text{NAD}^+ \\longrightarrow 2\\text{ Pyruvate} + 2\\text{ATP (net)} + 2\\text{NADH} + 2\\text{H}^+ + 2\\text{H}_2\\text{O}$$\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate listing of Preparatory Phase (steps 1 to 5; consumption of 2 ATP)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate listing of Pay-off Phase (steps 6 to 10; generation of 4 ATP + 2 NADH)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct net balance sheet: 2 Pyruvate + 2 net ATP + 2 NADH</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the main steps in aerobic respiration? Where does it take place?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Four Sequential Stages of Aerobic Respiration and Their Cellular Sites:</strong><br><br>\n    <strong>1. Glycolysis (EMP Pathway):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>Site:</em> <strong>Cytoplasm (Cytosol)</strong> of the cell.</li>\n      <li><em>Process:</em> Partial oxidation of 1 glucose (6C) into 2 pyruvic acid (3C), yielding net 2 ATP and 2 $NADH+H^+$. Independent of $O_2$.</li>\n    </ul>\n    <strong>2. Oxidative Decarboxylation of Pyruvate (Link Reaction / Gateway Step):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>Site:</em> <strong>Mitochondrial Matrix</strong>.</li>\n      <li><em>Process:</em> Pyruvate dehydrogenase multienzyme complex converts 2 pyruvates into 2 molecules of <strong>Acetyl-CoA (2C)</strong>, releasing 2 $CO_2$ and 2 $NADH+H^+$.</li>\n    </ul>\n    <strong>3. Tricarboxylic Acid Cycle (TCA Cycle / Krebs Cycle):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>Site:</em> <strong>Mitochondrial Matrix</strong> (except succinate dehydrogenase on inner membrane).</li>\n      <li><em>Process:</em> Complete cyclical oxidation of Acetyl-CoA. Two turns of the cycle yield 4 $CO_2$, 6 $NADH+H^+$, 2 $FADH_2$, and 2 GTP (ATP) via substrate-level phosphorylation.</li>\n    </ul>\n    <strong>4. Oxidative Phosphorylation &amp; Electron Transport System (ETS):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>Site:</em> <strong>Inner Mitochondrial Membrane (Cristae)</strong>.</li>\n      <li><em>Process:</em> High-energy electrons from NADH and $FADH_2$ traverse electron carrier complexes (I, II, III, IV), pumping $H^+$ into the intermembrane space. The proton gradient drives ATP synthesis via $F_0-F_1$ ATP synthase complex (Complex V), while molecular oxygen acts as terminal electron and proton acceptor, forming metabolic water ($H_2O$).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. Glycolysis in Cytoplasm (glucose to pyruvate)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Link Reaction in Mitochondrial Matrix (pyruvate to acetyl-CoA)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Krebs TCA cycle in Mitochondrial Matrix (complete oxidation, CO2 release)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">4. ETS & Oxidative Phosphorylation in Inner Mitochondrial Membrane</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain ETS (Electron Transport System) and oxidative phosphorylation.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Comprehensive Architecture of Mitochondrial ETS &amp; Oxidative Phosphorylation:</strong><br><br>\n    <strong>1. Electron Transport System (ETS):</strong><br>\n    Located in the inner mitochondrial membrane, ETS consists of five multiprotein complexes and mobile electron carriers:<br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Complex I (NADH Dehydrogenase):</strong> Oxidizes mitochondrial matrix $NADH+H^+$, transferring electrons through FMN and Fe-S clusters to mobile lipid carrier <strong>Ubiquinone (CoQ)</strong>, pumping 4 $H^+$ across into the intermembrane space.</li>\n      <li><strong>Complex II (Succinate Dehydrogenase):</strong> Transfers electrons from succinate-derived $FADH_2$ via Fe-S to Ubiquinone (does not pump protons). Reduced ubiquinone ($UQH_2$) transfers electrons to Complex III.</li>\n      <li><strong>Complex III (Cytochrome $bc_1$ Complex):</strong> Passes electrons from $UQH_2$ to mobile peripheral protein carrier <strong>Cytochrome c</strong>, pumping 4 $H^+$ across into intermembrane space.</li>\n      <li><strong>Complex IV (Cytochrome c Oxidase):</strong> Contains cytochromes $a$ and $a_3$, and two copper centers ($Cu_A, Cu_B$). Transfers 4 electrons to terminal acceptor: molecular oxygen ($O_2$), which combines with matrix $H^+$ to form metabolic water ($2H^+ + \\frac{1}{2}O_2 + 2e^- \\rightarrow H_2O$), pumping 2 $H^+$ across.</li>\n    </ul>\n    <strong>2. Oxidative Phosphorylation &amp; Peter Mitchell's Chemiosmotic Hypothesis:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Proton pumping creates a steep electrochemical proton gradient (proton motive force, $\\Delta p$) across the inner membrane: intermembrane space becomes highly acidic with positive charge relative to the matrix.</li>\n      <li><strong>Complex V ($F_0-F_1$ ATP Synthase):</strong> Protons flow back into matrix down their gradient through the transmembrane channel $F_0$. The passage of protons induces conformational rotation of the catalytic $F_1$ headpiece, condensing ADP and $P_i$ into <strong>ATP</strong>.</li>\n      <li><em>Stoichiometry:</em> Oxidation of 1 molecule of $NADH+H^+$ yields approximately <strong>3 ATP</strong>; oxidation of 1 molecule of $FADH_2$ yields approximately <strong>2 ATP</strong>.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Complexes I, II, III, IV and role of mobile carriers (Ubiquinone, Cytochrome c)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of molecular oxygen as terminal electron acceptor forming water</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Chemiosmotic proton gradient generation in intermembrane space</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Complex V (F0-F1 ATP synthase) and ATP yield (1 NADH = 3 ATP; 1 FADH2 = 2 ATP)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish between the following: (a) Aerobic respiration and Fermentation (b) Glycolysis and Citric acid cycle.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Differences Between Aerobic Respiration and Fermentation:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Trait</th><th style=\"padding:6px 10px;\">Aerobic Respiration</th><th style=\"padding:6px 10px;\">Fermentation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">$O_2$ Requirement</td><td style=\"padding:6px 10px;\">Strictly requires molecular oxygen ($O_2$).</td><td style=\"padding:6px 10px;\">Occurs in complete absence of oxygen.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">End Products</td><td style=\"padding:6px 10px;\">Completely oxidized to <strong>$CO_2$ and $H_2O$</strong>.</td><td style=\"padding:6px 10px;\">Incomplete breakdown to <strong>Ethyl alcohol + $CO_2$</strong> or <strong>Lactic acid</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">ATP Yield</td><td style=\"padding:6px 10px;\">High energy yield: <strong>36 to 38 ATP</strong> per glucose.</td><td style=\"padding:6px 10px;\">Very low yield: only <strong>2 ATP</strong> per glucose (&lt;7% energy).</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Cellular Site</td><td style=\"padding:6px 10px;\">Initiates in cytoplasm, completed in <strong>mitochondria</strong>.</td><td style=\"padding:6px 10px;\">Confined entirely to the <strong>cytoplasm</strong>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(b) Differences Between Glycolysis and Citric Acid (Krebs) Cycle:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:6px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:6px 10px;\">Trait</th><th style=\"padding:6px 10px;\">Glycolysis (EMP)</th><th style=\"padding:6px 10px;\">Citric Acid Cycle (TCA)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Location</td><td style=\"padding:6px 10px;\"><strong>Cytosol (Cytoplasm)</strong>.</td><td style=\"padding:6px 10px;\"><strong>Mitochondrial Matrix</strong>.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">Pathway Shape</td><td style=\"padding:6px 10px;\">Linear 10-step sequence.</td><td style=\"padding:6px 10px;\">Cyclic catalytic pathway regenerating oxaloacetate.</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:6px 10px; font-weight:700;\">$CO_2$ Release</td><td style=\"padding:6px 10px;\">Zero $CO_2$ is evolved.</td><td style=\"padding:6px 10px;\">Evolves 2 molecules of $CO_2$ per acetyl-CoA (4 $CO_2$ per glucose).</td></tr>\n          <tr><td style=\"padding:6px 10px; font-weight:700;\">Hydrogen Carriers</td><td style=\"padding:6px 10px;\">Produces only $NADH+H^+$ (no $FADH_2$).</td><td style=\"padding:6px 10px;\">Produces both <strong>$NADH+H^+$ and $FADH_2$</strong>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Aerobic vs Fermentation: O2, end products, ATP yield (36-38 vs 2), location</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Glycolysis vs Citric acid cycle: cytosol vs matrix, linear vs cyclic, CO2 evolution, FADH2 generation</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the assumptions made during the calculation of net gain of ATP?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Theoretical Assumptions Made in Calculating the Theoretical Net 36–38 ATP Yield:</strong><br>\n    The classic textbook calculation of a net gain of 36 or 38 ATP per oxidized glucose molecule is an idealized theoretical estimate based on the following specific assumptions:<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Sequential, Stepwise Orderly Pathway:</strong> It is assumed that glycolysis, the link reaction, the TCA cycle, and the ETS occur in a strict, continuous, unbroken linear pipeline, with one pathway immediately feeding into the next.</li>\n      <li><strong>2. 100% Transfer of Cytosolic NADH into Mitochondria:</strong> Assumes that the 2 $NADH$ synthesized during glycolysis in the cytoplasm are quantitatively transferred across mitochondrial membranes via glycerol-phosphate shuttle or malate-aspartate shuttle into ETS for oxidative phosphorylation without loss.</li>\n      <li><strong>3. No Intermediates Diverted for Biosynthesis:</strong> Assumes that none of the biochemical intermediates in the pathway are siphoned off into anabolic side pathways (e.g., assumes glucose-6-P is not drawn into pentose shunt, acetyl-CoA is not used for fatty acid synthesis, $alpha$-ketoglutarate is not transaminated into glutamate, and oxaloacetate is not used for pyrimidines).</li>\n      <li><strong>4. Glucose as Sole Substrate:</strong> Assumes that glucose is the exclusive, solitary respiratory substrate utilized, and no fats, amino acids, or organic acids enter intermediate stages of the cycle.</li>\n    </ul>\n    <em>Reality in Living Cells: In living protoplasm, all pathways operate simultaneously; intermediates are constantly diverted for cellular anabolism, meaning the actual physiological ATP yield is typically around 30 to 32 ATP.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Assumption of strict sequential, uninterrupted pathway (Glycolysis -> Link -> TCA -> ETS)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quantitative shuttle transfer of cytoplasmic NADH into mitochondria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Assumption that no intermediates are withdrawn for biosynthesis & glucose is sole substrate</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Discuss \"The respiratory pathway is an amphibolic pathway.\"\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why the Respiratory Pathway is Classified as Amphibolic (Dual Function):</strong><br><br>\n    <strong>1. Traditional View &mdash; Catabolic Pathway:</strong><br>\n    Traditionally, cellular respiration was regarded purely as a <strong>catabolic pathway</strong> (destructive breakdown process) because large organic macromolecules (carbohydrates, lipids, proteins) are broken down into simple molecules ($CO_2$ and $H_2O$) to release energy in the form of ATP.<br><br>\n    <strong>2. Modern Understanding &mdash; Anabolic Intermediary Roles:</strong><br>\n    Biochemical evidence demonstrates that respiration does not merely break down substrates; its intermediates serve as the vital starting precursors for synthesizing diverse essential cellular biomolecules (anabolism):\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Acetyl-CoA:</strong> When the cell requires fatty acids, sterols (cholesterol), carotenoids, or gibberellins, Acetyl-CoA is withdrawn from the respiratory gateway and channeled into <strong>fatty acid / lipid synthesis</strong>.</li>\n      <li><strong>$alpha$-Ketoglutarate:</strong> An intermediate of the Krebs cycle that undergoes reductive amination to synthesize <strong>glutamic acid</strong> and subsequent amino acids.</li>\n      <li><strong>Oxaloacetate (OAA):</strong> Transaminated into <strong>aspartic acid</strong>, which serves as a building block for pyrimidine nitrogenous bases.</li>\n      <li><strong>Succinyl-CoA:</strong> Withdrawn from the TCA cycle to synthesize the porphyrin rings of <strong>chlorophyll, cytochromes, and hemoglobin</strong>.</li>\n      <li><strong>Dihydroxyacetone Phosphate (DHAP):</strong> Reduced to <strong>glycerol</strong> for lipid synthesis.</li>\n    </ul>\n    <strong>Conclusion:</strong><br>\n    Because the respiratory pathway is simultaneously involved in both <strong>catabolism (breakdown)</strong> and <strong>anabolism (synthesis)</strong>, it is scientifically termed an <strong>amphibolic pathway</strong> rather than simply catabolic.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of amphibolic as possessing dual catabolic and anabolic functions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Catabolic aspect: breakdown of carbohydrates, fats, proteins to yield ATP</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Anabolic aspect: Acetyl-CoA (fatty acids), alpha-ketoglutarate (amino acids), succinyl-CoA (chlorophyll/heme)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Logical conclusion establishing why amphibolic is the scientifically accurate term</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch12-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch12-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch12-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define RQ (Respiratory Quotient). What is its value for fats, carbohydrates and proteins?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Respiratory Quotient (RQ / Respiratory Ratio):</strong><br>\n    The <strong>Respiratory Quotient (RQ)</strong> is the volumetric ratio of carbon dioxide ($CO_2$) evolved to the volume of oxygen ($O_2$) consumed in cellular respiration over a given period:\n    $$\\mathbf{RQ = \\frac{\\text{Volume of } CO_2 \\text{ evolved}}{\\text{Volume of } O_2 \\text{ consumed}}}$$\n    The value of RQ depends entirely on the chemical nature of the respiratory substrate being oxidized.<br><br>\n    <strong>Exact RQ Values for Different Substrates:</strong><br><br>\n    <strong>1. Carbohydrates &mdash; $\\text{RQ} = 1.0$:</strong><br>\n    $$\\text{C}_6\\text{H}_{12}\\text{O}_6 + 6\\text{O}_2 \\longrightarrow 6\\text{CO}_2 + 6\\text{H}_2\\text{O} + \\text{Energy}$$\n    $$\\text{RQ} = \\frac{6\\text{ CO}_2}{6\\text{ O}_2} = \\mathbf{1.0}$$\n    Because carbohydrates contain equal proportions of oxygen and hydrogen atoms, the volume of $CO_2$ evolved equals the volume of $O_2$ consumed.<br><br>\n    <strong>2. Fats / Lipids &mdash; $\\text{RQ} = 0.7$ (Less than 1.0):</strong><br>\n    Example: Oxidation of Triolein / Tripalmitin ($C_{51}H_{98}O_6$):\n    $$2\\text{C}_{51}\\text{H}_{98}\\text{O}_6 + 145\\text{O}_2 \\longrightarrow 102\\text{CO}_2 + 98\\text{H}_2\\text{O} + \\text{Energy}$$\n    $$\\text{RQ} = \\frac{102\\text{ CO}_2}{145\\text{ O}_2} = \\mathbf{0.7}$$\n    Fats are oxygen-poor and hydrogen-rich; therefore, they consume far more external oxygen to oxidize their hydrocarbon chains.<br><br>\n    <strong>3. Proteins &mdash; $\\text{RQ} \\approx 0.9$:</strong><br>\n    Proteins (amino acids) also contain less oxygen relative to carbon and hydrogen, yielding an average RQ of approximately <strong>0.85 to 0.9</strong>.<br><br>\n    <em>Additional Values: Organic acids (Malate/Citrate) have $\\text{RQ} > 1.0$ (e.g., Malic acid RQ = 1.33); Anaerobic respiration has $\\text{RQ} = \\infty$ ($CO_2/0$).</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mathematical definition and formula of Respiratory Quotient (RQ)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Carbohydrate RQ = 1.0 with balanced chemical equation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fat RQ = 0.7 with tripalmitin equation (oxygen-poor explanation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Protein RQ ≈ 0.9</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 11</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 13 (Plant Growth and Development) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[13] = "<section class=\"chapter-section\" id=\"c11b-ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 13</div>\n      <h2>Plant Growth and Development</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 11 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg>\n      Plant Growth Kinetics (Sigmoid Curve) &amp; Phytohormone Regulatory Actions\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Sigmoid Growth Curve on Left -->\n      <g transform=\"translate(40, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">TYPICAL SIGMOID (S-SHAPED) GROWTH CURVE</text>\n        <!-- Axes -->\n        <line x1=\"40\" y1=\"180\" x2=\"340\" y2=\"180\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <line x1=\"40\" y1=\"180\" x2=\"40\" y2=\"35\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <text x=\"35\" y=\"30\" font-size=\"8\" fill=\"#334155\" text-anchor=\"end\">Size / Weight of Organ (W)</text>\n        <text x=\"190\" y=\"196\" font-size=\"8.5\" fill=\"#334155\" text-anchor=\"middle\">Time (t) &rarr;</text>\n\n        <!-- S-curve -->\n        <path d=\"M 40,175 C 100,173 140,150 190,105 C 240,60 270,55 330,55\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"3\"/>\n        \n        <!-- Phases labels -->\n        <text x=\"90\" y=\"165\" font-size=\"8\" font-weight=\"bold\" fill=\"#64748b\">1. Lag Phase</text>\n        <text x=\"160\" y=\"115\" font-size=\"8\" font-weight=\"bold\" fill=\"#15803d\">2. Log (Exponential) Phase</text>\n        <text x=\"260\" y=\"45\" font-size=\"8\" font-weight=\"bold\" fill=\"#b91c1c\">3. Stationary Phase</text>\n        \n        <text x=\"190\" y=\"145\" font-size=\"8.5\" font-style=\"italic\" fill=\"#065f46\">W1 = W0 &bull; e^(rt)</text>\n      </g>\n\n      <!-- Phytohormone Roles on Right -->\n      <g transform=\"translate(430, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"390\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"195\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">FIVE MAJOR PLANT GROWTH REGULATORS (PGRs)</text>\n\n        <rect x=\"15\" y=\"35\" width=\"360\" height=\"28\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"52\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#15803d\">Auxins (IAA, NAA, 2,4-D):</text>\n        <text x=\"155\" y=\"52\" font-size=\"7.5\" fill=\"#334155\">Apical dominance, root initiation, weedicide</text>\n\n        <rect x=\"15\" y=\"66\" width=\"360\" height=\"28\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"83\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0369a1\">Gibberellins (GA3):</text>\n        <text x=\"155\" y=\"83\" font-size=\"7.5\" fill=\"#334155\">Stem elongation (sugarcane), bolting, malting</text>\n\n        <rect x=\"15\" y=\"97\" width=\"360\" height=\"28\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"114\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#7c3aed\">Cytokinins (Kinetin, Zeatin):</text>\n        <text x=\"165\" y=\"114\" font-size=\"7.5\" fill=\"#334155\">Cell division, overcomes apical dominance, delay senescence</text>\n\n        <rect x=\"15\" y=\"128\" width=\"360\" height=\"28\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"145\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#ea580c\">Ethylene (C2H4, Ethephon):</text>\n        <text x=\"165\" y=\"145\" font-size=\"7.5\" fill=\"#334155\">Fruit ripening, triple response, abscission promoter</text>\n\n        <rect x=\"15\" y=\"159\" width=\"360\" height=\"28\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"176\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\">Abscisic Acid (ABA):</text>\n        <text x=\"155\" y=\"176\" font-size=\"7.5\" fill=\"#334155\">\"Stress hormone\", stomatal closure, seed dormancy</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 11: Growth Kinetics, Phytohormones, Photoperiodism, Vernalisation & Stress Physiology</div>\n\n  <!-- c11b-ch13-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define growth, differentiation, development, dedifferentiation, redifferentiation, determinate growth, meristem and growth rate.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Precise Botanical Definitions of Developmental Terms:</strong><br><br>\n    <strong>1. Growth:</strong> An irreversible, permanent increase in the size, volume, surface area, or dry biomass of an organ, cell, or organism, accompanied by metabolic energy consumption (anabolism).<br><br>\n    <strong>2. Differentiation:</strong> The process by which structurally unspecialized meristematic cells undergo permanent biochemical and structural changes in their cell walls and protoplasm to perform specific physiological duties (e.g., loss of protoplasm and lignification of xylem tracheary elements).<br><br>\n    <strong>3. Development:</strong> The complete progression of events and changes that an organism undergoes throughout its entire life cycle from the germination of a seed, through growth, differentiation, flowering, seed setting, senescence, to death ($Development = Growth + Differentiation$).<br><br>\n    <strong>4. Dedifferentiation:</strong> The biological capacity of living, mature, fully differentiated permanent cells to regain the power of mitotic cell division under specific hormonal stimuli (e.g., formation of interfascicular cambium and cork cambium / phellogen from mature parenchymatous cortical cells).<br><br>\n    <strong>5. Redifferentiation:</strong> The process whereby secondary meristematic cells (produced by dedifferentiation) once again lose their capacity to divide and mature into specialized permanent tissues (e.g., secondary xylem, secondary phloem, and cork).<br><br>\n    <strong>6. Determinate Growth:</strong> A growth pattern wherein an organ or organism ceases growth after reaching a characteristic, genetically fixed size and shape (e.g., leaves, flowers, and fruits).<br><br>\n    <strong>7. Meristem:</strong> A specialized region of continuously dividing, undifferentiated, isodiametric embryonic plant cells possessing dense cytoplasm, thin cellulosic walls, and prominent nuclei (e.g., apical, lateral, and intercalary meristems).<br><br>\n    <strong>8. Growth Rate:</strong> The mathematically measured increase in plant growth per unit of time (arithmetic: $L_t = L_0 + rt$; or geometric: $W_1 = W_0 e^{rt}$).\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of Growth, Differentiation & Development</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of Dedifferentiation & Redifferentiation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of Determinate growth, Meristem & Growth rate</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why is not any one parameter good enough to demonstrate growth in plants?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why Multiple Quantitative Parameters Are Required to Measure Plant Growth:</strong><br><br>\n    At the fundamental cellular level, growth is a direct consequence of an increase in the amount of <strong>protoplasm</strong>. Because directly measuring cellular protoplasmic mass inside living, intact tissues is technically impossible without destroying the plant, biologists measure parameters that are proportionally correlated with protoplasmic expansion.<br><br>\n    However, no solitary parameter is universally applicable to all organs or tissues because plants exhibit diverse growth habits:\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Fresh Weight:</strong> Highly unreliable because it fluctuates wildly depending on the water status, humidity, and transpiration rate of the plant; water absorption increases fresh weight without true synthesis of dry protoplasmic matter.</li>\n      <li><strong>2. Dry Weight:</strong> The most accurate index of growth (true biomass), but requires destroying and desiccating the plant tissue in an oven at 80&deg;C, terminating further measurement of that individual.</li>\n      <li><strong>3. Length / Height:</strong> Ideal for linear organs like stems, roots, and pollen tubes (a pollen tube increases strictly in length), but completely useless for measuring planar organs like leaves or spherical organs like fruits.</li>\n      <li><strong>4. Surface Area:</strong> Appropriate for measuring the expansion of a dorsiventral leaf blade, but cannot quantify the growth of roots or tree trunks.</li>\n      <li><strong>5. Volume:</strong> Useful for measuring fruits (e.g., watermelon, apple), but inappropriate for slender filaments.</li>\n      <li><strong>6. Cell Number:</strong> A single maize root apical meristem generates >17,500 new cells per hour, whereas a watermelon cell can increase in volume by 350,000 times without dividing.</li>\n    </ul>\n    <strong>Conclusion:</strong> Different growth parameters must be tailored to the specific organ, developmental stage, and experimental objective.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Protoplasmic increase cannot be measured directly</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Limitations of single parameters: fresh weight (water fluctuations), dry weight (destructive)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Organ-specific suitability: length (pollen tube), area (leaves), volume (fruits), cell number (root apex)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe briefly: (a) Arithmetic growth (b) Geometric growth (c) Sigmoid growth curve (d) Absolute and relative growth rates.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Detailed Description of Growth Kinetics:</strong><br><br>\n    <strong>(a) Arithmetic Growth:</strong><br>\n    Following mitotic cell division, only <strong>one daughter cell continues to divide</strong>, while the other daughter cell differentiates and matures into a permanent cell.\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Produces a constant, linear increase in growth over time.</li>\n      <li><strong>Mathematical Formula:</strong> $$\\mathbf{L_t = L_0 + rt}$$ (where $L_t$ = length at time $t$, $L_0$ = initial length, $r$ = growth rate / elongation per unit time). When plotted against time, it yields a <strong>straight line</strong> (e.g., root or shoot elongation at constant velocity).</li>\n    </ul>\n    <strong>(b) Geometric Growth:</strong><br>\n    Both daughter cells resulting from mitotic division <strong>retain the capacity to divide</strong> and continue dividing repeatedly ($1 \\rightarrow 2 \\rightarrow 4 \\rightarrow 8 \\rightarrow 16 \\dots$).\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Growth proceeds exponentially.</li>\n      <li><strong>Mathematical Formula:</strong> $$\\mathbf{W_1 = W_0 e^{rt}}$$ (where $W_1$ = final size, $W_0$ = initial size, $r$ = relative growth rate, $t$ = time, $e$ = base of natural logarithms).</li>\n    </ul>\n    <strong>(c) Sigmoid (S-shaped) Growth Curve:</strong><br>\n    A characteristic S-shaped curve obtained when the cumulative biomass or organ size is plotted against time under natural, limited nutrient conditions. Characterized by three successive phases:\n    <ol style=\"margin:2px 0 4px 20px;\">\n      <li><em>Lag Phase:</em> Initial slow, preparatory growth period.</li>\n      <li><em>Log (Exponential) Phase:</em> Rapid, maximal, exponential growth.</li>\n      <li><em>Stationary (Senescent) Phase:</em> Growth slows down and reaches a plateau due to nutrient limitation and internal genetic constraints.</li>\n    </ol>\n    <strong>(d) Absolute vs. Relative Growth Rates:</strong><br>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Absolute Growth Rate (AGR):</strong> Measurement and comparison of total net growth per unit of time ($AGR = \\frac{\\text{Total Growth}}{\\text{Time}}$).</li>\n      <li><strong>Relative Growth Rate (RGR):</strong> Growth per unit of time expressed on a <strong>per-unit initial parameter basis</strong> ($RGR = \\frac{\\text{Growth in given time}}{\\text{Initial parameter} \\times \\text{Time}}$). It reflects the comparative biological efficiency (efficiency index) of the system.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Arithmetic growth: 1 cell divides, linear curve, Lt = L0 + rt</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Geometric growth: both daughter cells divide, exponential curve, W1 = W0 e^rt</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Sigmoid curve: Lag, Log/Exponential, and Stationary phases</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Absolute growth rate (total growth/time) vs Relative growth rate (per unit initial basis)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        List five main groups of natural plant growth regulators. Write a note on discovery, physiological functions and agricultural applications of any one of them.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Five Main Groups of Natural Plant Growth Regulators (Phytohormones):</strong><br>\n    1. <strong>Auxins</strong> &nbsp;|&nbsp; 2. <strong>Gibberellins</strong> &nbsp;|&nbsp; 3. <strong>Cytokinins</strong> &nbsp;|&nbsp; 4. <strong>Ethylene</strong> &nbsp;|&nbsp; 5. <strong>Abscisic Acid (ABA)</strong>.<br><br>\n    <strong>Comprehensive Account of AUXINS:</strong><br><br>\n    <strong>1. Discovery of Auxins:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>First observed by <strong>Charles Darwin and his son Francis Darwin (1880)</strong> while studying the phototropic curvature of the coleoptiles of canary grass (<em>Phalaris canariensis</em>); they concluded that an influence was transmitted from the tip to the sub-apical zone causing bending.</li>\n      <li><strong>Frits Went (1928)</strong> successfully isolated the diffusible chemical substance from oat (<em>Avena sativa</em>) coleoptile tips in agar blocks, demonstrating curvature (Avena curvature test) and naming it <strong>Auxin</strong> (Greek <em>auxein</em> = to grow). First chemically isolated from human urine as Indole-3-acetic acid (IAA).</li>\n    </ul>\n    <strong>2. Physiological Functions of Auxin:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Apical Dominance:</strong> High concentrations of auxin produced by the shoot apical bud suppress the outgrowth of lateral (axillary) buds. Decapitation allows bushy lateral branching (utilized in tea plucking and hedge-making).</li>\n      <li><strong>Cell Elongation:</strong> Stimulates proton pumping, loosening cell walls (acid growth hypothesis).</li>\n      <li><strong>Root Initiation:</strong> Induces adventitious root formation in stem cuttings.</li>\n      <li><strong>Prevents Early Abscission:</strong> Prevents premature drop of young leaves and fruits, but promotes abscission of older, senescent leaves.</li>\n    </ul>\n    <strong>3. Agricultural and Horticultural Applications:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Rooting of Cuttings:</strong> Synthetic auxins (NAA &mdash; Naphthalene acetic acid, IBA &mdash; Indole butyric acid) are widely used as rooting powders for rapid vegetative propagation.</li>\n      <li><strong>Parthenocarpy:</strong> Applied to unpollinated flowers to induce seedless fruits (e.g., in tomatoes).</li>\n      <li><strong>Selective Weedicide / Herbicide:</strong> Synthetic auxin <strong>2,4-D (2,4-Dichlorophenoxyacetic acid)</strong> is extensively sprayed to selectively eradicate broad-leaved dicot weeds in cereal (monocot) crop fields and lawns.</li>\n      <li><strong>Flowering Promotion:</strong> Promotes uniform synchronous flowering and fruit set in pineapples and litchi.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Listing five main classes of PGRs (Auxins, Gibberellins, Cytokinins, Ethylene, ABA)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Discovery: Darwin’s canary grass coleoptiles and Went’s Avena curvature test</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physiological roles: Apical dominance, cell elongation, root initiation, anti-abscission</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Agricultural applications: Rooting hormone (IBA/NAA), weedicide (2,4-D), parthenocarpy</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What do you understand by photoperiodism and vernalisation? Describe their significance.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Photoperiodism:</strong><br>\n    <strong>Photoperiodism</strong> is the physiological response of plants to the relative lengths of day (light period) and night (dark period) in regulating flowering (first discovered by Garner and Allard, 1920, in Maryland Mammoth tobacco).\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Short Day Plants (SDP):</strong> Require a photoperiod shorter than a critical day length and an uninterrupted long dark period to flower (e.g., Tobacco, Soybean, Chrysanthemum, Rice).</li>\n      <li><strong>Long Day Plants (LDP):</strong> Require a photoperiod longer than a critical day length to flower (e.g., Wheat, Radish, Spinach, Henbane).</li>\n      <li><strong>Day-Neutral Plants (DNP):</strong> Flowering is independent of photoperiod length (e.g., Tomato, Sunflower, Maize, Pea).</li>\n      <li><em>Significance:</em> The site of light perception is the <strong>leaves</strong>, which synthesize a hypothetical mobile floral stimulus called <strong>florigen</strong> that migrates to shoot apices. Enables crop scheduling, commercial floriculture, and growing off-season flowers.</li>\n    </ul>\n    <strong>2. Vernalisation:</strong><br>\n    <strong>Vernalisation</strong> is the promotion of flowering by a mandatory period of low-temperature (chilling / cold treatment, typically 1&deg;C to 5&deg;C) during the seed or vegetative seedling stage (first reported by T.D. Lysenko).\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><em>Examples:</em> Winter varieties of wheat, barley, and rye. If planted in spring, winter wheat fails to flower; when exposed to cold winter, it flowers in summer. Also in biennials (sugarbeet, cabbage, carrot).</li>\n      <li><em>Significance:</em> Prevents premature flowering late in the growing season before the plant has attained full vegetative maturity; allows temperate winter crops to be grown in spring. Gibberellins ($GA_3$) can substitute for cold vernalization.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of photoperiodism, critical daylength, SDP vs LDP vs DNP</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Site of perception (leaves) and agricultural significance in floriculture</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of vernalisation as cold-induced flowering and winter cereal examples</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance of vernalisation (prevents precocious flowering; GA substitution)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why is abscisic acid also known as stress hormone?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why Abscisic Acid (ABA) is Termed the \"Plant Stress Hormone\":</strong><br><br>\n    <strong>Abscisic Acid (ABA)</strong> is synthesized in large quantities whenever a plant experiences adverse, harsh, or stressful environmental conditions (such as severe water deficit / drought, extreme cold, salinity, or high temperature), triggering emergency survival responses:<br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Rapid Stomatal Closure Under Water Stress:</strong><br>\n      During drought or soil water deficit, roots detect moisture stress and export ABA via xylem to leaves. ABA binds to plasma membrane receptors on guard cells, stimulating a massive efflux of potassium ($K^+$) and chloride ($Cl^-$) ions. Loss of turgor causes immediate <strong>stomatal closure</strong>, drastically reducing transpiration and conserving water.</li>\n      <li><strong>2. Induction of Seed and Bud Dormancy:</strong><br>\n      ABA inhibits seed germination and precocious embryo sprouting (vivipary). It induces <strong>seed dormancy</strong>, enabling seeds to withstand desiccation, extreme winter freezing, and heat until favorable conditions return.</li>\n      <li><strong>3. Stress-Resistant Protein Synthesis:</strong><br>\n      Upregulates gene expression of protective molecular chaperones called Late Embryogenesis Abundant (LEA) proteins and heat-shock proteins that stabilize cellular membranes and enzymes during cellular dehydration.</li>\n      <li><strong>4. Antagonist to Growth Promoters:</strong><br>\n      Acts as an internal metabolic brake, counteracting the effects of growth stimulators (Gibberellins and Auxins).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of ABA as stress hormone triggered by drought/salinity/cold</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed mechanism of stomatal closure via K+ efflux from guard cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Induction of seed/bud dormancy and synthesis of protective desiccation proteins</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        \"Both growth and differentiation in higher plants are open.\" Comment.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Commentary: Open Form of Growth and Differentiation in Higher Plants:</strong><br><br>\n    <strong>1. Open Form of Growth:</strong><br>\n    Unlike animals that show closed, determinate, unitary growth (where the adult body plan and organ number are fixed early in embryogenesis), higher plants retain the remarkable capacity for <strong>unlimited, continuous growth throughout their lifespan</strong>.\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>This perpetual growth is due to the presence of localized groups of perpetually dividing embryonic cells called <strong>meristems</strong> at specific locations (Root Apical Meristems, Shoot Apical Meristems, and Lateral Meristems).</li>\n      <li>New cells, tissues, leaves, branches, flowers, and roots are continuously and iteratively added to the plant body. Hence, plant growth is termed <strong>open</strong>.</li>\n    </ul>\n    <strong>2. Open Form of Differentiation:</strong><br>\n    Differentiation in plants is also open because the final developmental fate of a cell derived from the same meristem is not rigidly predetermined; rather, it is dictated by its <strong>spatial location</strong> and chemical microenvironment:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Cells positioned peripherally differentiate into epidermal cells; cells positioned deeper differentiate into cortical or vascular parenchyma.</li>\n      <li>Furthermore, fully differentiated, mature permanent cells retain developmental <strong>totipotency</strong>: they can dedifferentiate into secondary meristems (phellogen, interfascicular cambium) and redifferentiate into entirely new tissue types depending on hormonal concentrations (Auxin/Cytokinin ratio).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of open growth: perpetual addition of new organs via apical/lateral meristems</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of open differentiation: cell fate governed by location, dedifferentiation, and plasticity</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        \"Both a short day plant and a long day plant can flower simultaneously in a given place.\" Explain.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Explanation: Simultaneous Flowering of SDP and LDP:</strong><br><br>\n    <strong>Yes, a Short Day Plant (SDP) and a Long Day Plant (LDP) can flower simultaneously in the exact same geographic location under specific photoperiodic conditions.</strong><br><br>\n    <strong>Photoperiodic Mechanism:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>Flowering is not determined by an absolute universal number of daylight hours, but by whether the ambient day length is <strong>shorter or longer than the plant's own specific Critical Day Length (CDL)</strong>.</li>\n      <li>Each species possesses its own unique genetically determined CDL:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>A <em>Short Day Plant</em> flowers when the day length is <strong>less than its CDL</strong>.</li>\n          <li>A <em>Long Day Plant</em> flowers when the day length is <strong>greater than its CDL</strong>.</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>Concrete Numerical Example:</strong><br>\n    Suppose in a given geographical location during spring or autumn, the actual natural day length is <strong>12 hours</strong>:\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Consider an SDP (e.g., <em>Xanthium</em>) whose critical day length is <strong>14 hours</strong>. Since the actual day length (12 hours) is <em>less than</em> its critical day length (14 hours), this SDP will flower.</li>\n      <li>Consider an LDP (e.g., <em>Hyoscyamus</em>) whose critical day length is <strong>10 hours</strong>. Since the actual day length (12 hours) is <em>greater than</em> its critical day length (10 hours), this LDP will also flower.</li>\n    </ul>\n    <strong>Conclusion:</strong> Whenever the natural day length falls simultaneously below the CDL of the short-day plant and above the CDL of the long-day plant, both plants will flower concurrently side-by-side.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative statement and definition of species-specific Critical Day Length (CDL)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">SDP flowers when photoperiod < CDL; LDP flowers when photoperiod > CDL</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear hypothetical numerical example showing an intermediate daylength satisfying both plants</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which one of the plant growth regulators would you use if you are asked to:<br>(a) induce rooting in a twig<br>(b) quickly ripen a fruit<br>(c) delay leaf senescence<br>(d) induce growth in axillary buds<br>(e) 'bolt' a rosette plant<br>(f) induce immediate stomatal closure in leaves?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Appropriate Plant Growth Regulators for Specific Horticultural Applications:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Target Horticultural Application</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Designated Phytohormone (PGR)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Specific Chemical Compound / Action</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) Induce rooting in a twig</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Auxin</td>\n            <td style=\"padding:8px 12px;\"><strong>IBA (Indole-3-butyric acid)</strong> or <strong>NAA</strong> rooting powder.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) Quickly ripen a fruit</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Ethylene</td>\n            <td style=\"padding:8px 12px;\">Gaseous <strong>Ethylene ($C_2H_4$)</strong> or aqueous <strong>Ethephon</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) Delay leaf senescence</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Cytokinin</td>\n            <td style=\"padding:8px 12px;\"><strong>Kinetin / Zeatin</strong> (Richmond-Lang effect; promotes nutrient mobilization).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(d) Induce growth in axillary buds</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Cytokinin</td>\n            <td style=\"padding:8px 12px;\">Overcomes apical dominance imposed by terminal auxin.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(e) 'Bolt' a rosette plant</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Gibberellin</td>\n            <td style=\"padding:8px 12px;\"><strong>$GA_3$</strong> (induces internode elongation prior to flowering in cabbage/beet).</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(f) Induce immediate stomatal closure</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Abscisic Acid (ABA)</td>\n            <td style=\"padding:8px 12px;\">Acts as antitranspirant by stimulating $K^+$ efflux from guard cells.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Auxin (IBA/NAA) & (b) Ethylene / Ethephon</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Cytokinin & (d) Cytokinin</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Gibberellin (GA3) & (f) Abscisic acid (ABA)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Would a defoliated plant respond to photoperiodic cycle? Why?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Answer: No, a defoliated plant will NOT respond to the photoperiodic cycle.</strong><br><br>\n    <strong>Scientific Explanation:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Leaves are the Sole Sites of Photoperiodic Perception:</strong> Experimental evidence demonstrates that the light or dark duration (photoperiod) is perceived exclusively by the <strong>leaves</strong> of a plant, not by the stem, apex, or roots.</li>\n      <li><strong>Synthesis of the Florigen Stimulus:</strong> When mature leaves receive the critical inductive photoperiodic cycle, their photoreceptors (phytochromes) trigger the expression of the <em>CONSTANS</em> and <em>FLOWERING LOCUS T (FT)</em> genes, synthesizing the mobile floral hormone called <strong>florigen</strong>.</li>\n      <li><strong>Translocation to Shoot Apex:</strong> Florigen is transported through the phloem conduits to the vegetative shoot apical meristem, where it reprograms the apical meristem to transform into a floral meristem.</li>\n      <li><strong>Defoliation Consequence:</strong> If all leaves are completely removed (defoliated), the plant lacks the organ to perceive light signals or synthesize florigen. Even if a defoliated plant is given ideal critical photoperiods, it will remain vegetative and fail to flower. Even a single intact leaf is sufficient to perceive the stimulus and induce flowering.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear answer: No, a defoliated plant cannot perceive photoperiodic cycles</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation: Leaves are the exclusive site of light perception and florigen synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch13-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch13-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch13-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What would be expected to happen if: (a) $GA_3$ is applied to rice seedlings (b) dividing cells stop differentiating (c) a rotten fruit gets mixed with unripe fruits (d) you forget to add cytokinin to the culture medium?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Expected Biological Outcomes and Mechanistic Explanations:</strong><br><br>\n    <strong>(a) If $GA_3$ is applied to rice seedlings:</strong><br>\n    The seedlings will exhibit extreme, abnormal <strong>internodal stem elongation</strong>, becoming tall, slender, pale, and unable to support their own weight &mdash; mimicking the classic <em>\"bakanae\"</em> (foolish seedling) disease of rice discovered by Kurosawa (1926) caused by the fungus <em>Gibberella fujikuroi</em>.<br><br>\n    <strong>(b) If dividing cells stop differentiating:</strong><br>\n    The dividing cells will fail to specialize into dermal, ground, or vascular tissues (xylem, phloem). The tissue will form an unorganized, undifferentiated, irregular proliferating mass of parenchymatous cells called a <strong>callus</strong> or tumorous mass, halting organogenesis and normal plant development.<br><br>\n    <strong>(c) If a rotten (over-ripe) fruit gets mixed with unripe fruits:</strong><br>\n    Over-ripe or damaged fruits synthesize and release large quantities of volatile gaseous <strong>Ethylene ($C_2H_4$)</strong> into the surrounding air. Ethylene diffuses into adjacent unripe fruits, triggering a climacteric respiratory surge that causes <strong>premature and rapid ripening</strong> of all stored fruits, potentially leading to spoilage.<br><br>\n    <strong>(d) If you forget to add cytokinin to the culture medium:</strong><br>\n    In plant tissue culture, <strong>cytokinins</strong> are strictly required for mitotic cell division (cytokinesis) and shoot organogenesis. In the complete absence of cytokinin, explant cells will fail to divide; cell division and shoot bud differentiation will not occur, leading to culture failure. <em>(High auxin with no cytokinin promotes only root induction, but zero shoot formation).</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) GA3: extreme stem elongation mimicking \"foolish seedling\" disease</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Cessation of differentiation: formation of undifferentiated callus/tumor</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Rotten fruit: ethylene release triggering rapid ripening of unripe fruits</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Omission of cytokinin: failure of cell division and shoot bud differentiation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 12</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 14 (Breathing and Exchange of Gases) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[14] = "<section class=\"chapter-section\" id=\"c11b-ch14\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 14</div>\n      <h2>Breathing and Exchange of Gases</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 3v13m0 0l-4-4m4 4l4-4M5 21h14\"/></svg>\n      Alveolar Diffusion Boundary &amp; Oxygen-Hemoglobin Dissociation Curve\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Oxygen Dissociation Curve on Left -->\n      <g transform=\"translate(40, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">OXYGEN-HEMOGLOBIN DISSOCIATION CURVE (SIGMOID)</text>\n        <!-- Axes -->\n        <line x1=\"40\" y1=\"180\" x2=\"330\" y2=\"180\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <line x1=\"40\" y1=\"180\" x2=\"40\" y2=\"35\" stroke=\"#334155\" stroke-width=\"2\"/>\n        <text x=\"35\" y=\"30\" font-size=\"8\" fill=\"#334155\" text-anchor=\"end\">% Saturation of Hb</text>\n        <text x=\"185\" y=\"196\" font-size=\"8.5\" fill=\"#334155\" text-anchor=\"middle\">Partial Pressure of Oxygen (pO2 in mm Hg) &rarr;</text>\n\n        <!-- Sigmoid Curve -->\n        <path d=\"M 40,180 C 80,170 110,120 160,70 C 210,50 260,45 320,45\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        \n        <!-- P50 marker -->\n        <line x1=\"125\" y1=\"112\" x2=\"125\" y2=\"180\" stroke=\"#dc2626\" stroke-dasharray=\"3,2\"/>\n        <line x1=\"40\" y1=\"112\" x2=\"125\" y2=\"112\" stroke=\"#dc2626\" stroke-dasharray=\"3,2\"/>\n        <text x=\"125\" y=\"190\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#dc2626\">P50 (~27 mm Hg)</text>\n\n        <!-- Right Shift (Bohr Effect) -->\n        <path d=\"M 60,180 C 100,175 140,135 190,85 C 240,60 280,50 320,50\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"1.8\" stroke-dasharray=\"4,2\"/>\n        <text x=\"210\" y=\"115\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#ea580c\">Right Shift (Bohr Effect):</text>\n        <text x=\"210\" y=\"127\" font-size=\"7\" fill=\"#475569\">&uarr; pCO2, &uarr; H+ (low pH), &uarr; Temp</text>\n      </g>\n\n      <!-- Diffusion Membrane on Right -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">THE RESPIRATORY DIFFUSION MEMBRANE (&lt; 1 mm THICK)</text>\n\n        <!-- Alveolus Air Space -->\n        <rect x=\"20\" y=\"40\" width=\"160\" height=\"60\" rx=\"6\" fill=\"#eff6ff\" stroke=\"#93c5fd\"/>\n        <text x=\"100\" y=\"65\" font-size=\"9\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Alveolar Cavity</text>\n        <text x=\"100\" y=\"80\" font-size=\"7.5\" fill=\"#1d4ed8\" text-anchor=\"middle\">pO2 = 104 mm Hg | pCO2 = 40 mm Hg</text>\n\n        <!-- Capillary Blood -->\n        <rect x=\"220\" y=\"40\" width=\"160\" height=\"60\" rx=\"6\" fill=\"#fef2f2\" stroke=\"#fca5a5\"/>\n        <text x=\"300\" y=\"65\" font-size=\"9\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Pulmonary Capillary</text>\n        <text x=\"300\" y=\"80\" font-size=\"7.5\" fill=\"#7f1d1d\" text-anchor=\"middle\">pO2 = 40 mm Hg | pCO2 = 45 mm Hg</text>\n\n        <!-- Diffusion Membrane 3 Layers -->\n        <rect x=\"20\" y=\"115\" width=\"360\" height=\"70\" rx=\"6\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"30\" y=\"132\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#059669\">Three Essential Microscopic Diffusion Layers:</text>\n        <text x=\"30\" y=\"148\" font-size=\"8\" fill=\"#334155\">1. <strong>Squamous epithelium</strong> of alveolar wall (single cell thin)</text>\n        <text x=\"30\" y=\"162\" font-size=\"8\" fill=\"#334155\">2. <strong>Endothelium</strong> of alveolar blood capillaries</text>\n        <text x=\"30\" y=\"176\" font-size=\"8\" fill=\"#334155\">3. <strong>Basement substance</strong> supporting both epithelial layers (Total &lt; 0.5 &mu;m)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 10: Respiratory Volumes, Diffusion Membrane, CO2 Transport, Bohr Effect & Regulation</div>\n\n  <!-- c11b-ch14-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define vital capacity. What is its significance?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Definition of Vital Capacity (VC):</strong><br>\n    <strong>Vital Capacity (VC)</strong> is the maximum volume of air a person can breathe out after a forceful, maximal inhalation (or the maximum volume of air a person can breathe in after a forceful, maximal exhalation).<br>\n    Mathematically, Vital Capacity is the sum of three pulmonary volumes:\n    $$\\mathbf{VC = ERV + TV + IRV}$$\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li><strong>TV (Tidal Volume):</strong> Volume of air inspired or expired during normal quiet breathing (~500 mL).</li>\n      <li><strong>IRV (Inspiratory Reserve Volume):</strong> Extra volume that can be forcibly inspired (~2500 to 3000 mL).</li>\n      <li><strong>ERV (Expiratory Reserve Volume):</strong> Extra volume that can be forcibly expired (~1000 to 1100 mL).</li>\n      <li><em>Normal Value:</em> Approximately <strong>3500 mL to 4500 mL</strong> in healthy young adults (higher in athletes, divers, and males).</li>\n    </ul>\n    <strong>2. Clinical &amp; Physiological Significance of Vital Capacity:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Index of Lung Functional Capacity:</strong> Serves as a vital diagnostic spirometric indicator of pulmonary fitness and respiratory reserve. High VC ensures superior oxygen supply during strenuous exercise.</li>\n      <li><strong>Diagnosis of Restrictive Lung Diseases:</strong> Vital capacity is significantly reduced in restrictive pulmonary disorders (pulmonary fibrosis, silicosis, scoliosis) due to loss of alveolar elasticity and chest wall compliance.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of Vital Capacity (maximal exhalation after maximal inhalation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: VC = ERV + TV + IRV and normal range (3500–4500 mL)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physiological significance: index of lung reserve and clinical diagnosis of restrictive disorders</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        State the volume of air remaining in the lungs after a normal breathing.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Functional Residual Capacity (FRC):</strong><br>\n    The volume of air that remains in the lungs after a normal, quiet expiration is termed the <strong>Functional Residual Capacity (FRC)</strong>.<br><br>\n    <strong>Formula and Numerical Calculation:</strong><br>\n    $$\\mathbf{FRC = ERV + RV}$$\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>ERV (Expiratory Reserve Volume):</strong> The additional volume of air a person can expire by forceful expiration (~1000 to 1100 mL).</li>\n      <li><strong>RV (Residual Volume):</strong> The volume of air that always remains in the lungs even after maximal forceful expiration, preventing alveolar collapse (~1100 to 1200 mL).</li>\n    </ul>\n    $$\\text{FRC} = 1000\\text{ mL (ERV)} + 1200\\text{ mL (RV)} = \\mathbf{2100 \\text{ to } 2300\\text{ mL}}$$\n    <br>\n    <strong>Physiological Importance:</strong><br>\n    The presence of FRC ensures continuous, uninterrupted diffusion of oxygen and carbon dioxide across alveolar capillaries even during the expiratory pause between breaths.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification as Functional Residual Capacity (FRC)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: FRC = ERV + RV with standard values (1000–1100 mL + 1100–1200 mL)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final normal volume range (~2100 to 2300 mL) & physiological role preventing collapse</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Diffusion of gases occurs only in alveolar region and not in other parts of respiratory system. Why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why Gaseous Exchange is Confined Exclusively to the Alveolar Region:</strong><br><br>\n    The human respiratory tract is anatomically divided into two distinct functional zones:<br>\n    1. <strong>Conducting Zone:</strong> External nostrils &rarr; Pharynx &rarr; Larynx &rarr; Trachea &rarr; Bronchi &rarr; Terminal Bronchioles.<br>\n    2. <strong>Respiratory (Exchange) Zone:</strong> Respiratory bronchioles &rarr; Alveolar ducts &rarr; <strong>Alveoli</strong>.<br><br>\n    <strong>Scientific Reasons for Alveolar Exclusivity:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>1. Microscopic Thinness of Diffusion Membrane (&lt; 0.5 $\\mu m$):</strong><br>\n      The conducting zone is lined by thick pseudostratified ciliated columnar epithelium with goblet cells, thick basement membranes, and rigid cartilaginous rings, creating an impenetrable physical barrier to diffusion. In contrast, the alveolar wall consists of an ultra-thin <strong>single layer of simple squamous epithelium</strong> closely apposed to capillary endothelium, with a total diffusion thickness of less than half a micrometer (0.2–0.5 $\\mu m$), minimizing diffusion resistance.</li>\n      <li><strong>2. Immense Surface Area:</strong><br>\n      The human lungs contain approximately <strong>300 million alveoli</strong>, providing a colossal combined exchange surface area of <strong>70 to 80 $\\text{m}^2$</strong> (equivalent to a tennis court). The conducting zone has negligible surface area.</li>\n      <li><strong>3. Extensive Capillary Vascularization:</strong><br>\n      Alveoli are completely enveloped by a dense, anastomosing sheet of pulmonary capillary networks where RBCs flow in single file, maximizing gas contact time.</li>\n      <li><strong>4. Surfactant Lining:</strong><br>\n      Alveoli are lined with dipalmitoylphosphatidylcholine (surfactant) which reduces surface tension and maintains alveolar patency.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Anatomical contrast: Conducting zone (thick, ciliated, cartilaginous) vs Alveoli</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ultra-thin diffusion membrane (<0.5 μm) composed of simple squamous epithelium</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Colossal surface area (~70-80 m2 across 300 million alveoli) & dense capillary mesh</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the major transport mechanisms for $CO_2$? Explain.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The Three Major Physiological Transport Mechanisms for Carbon Dioxide ($CO_2$) in Blood:</strong><br>\n    Tissue cells produce $CO_2$ through catabolism, which is transported by blood to the lungs via three pathways:<br><br>\n    <strong>1. As Bicarbonate Ions ($HCO_3^-$) &mdash; 70% of Total $CO_2$:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li>The primary and predominant mode. $CO_2$ diffuses into RBCs where the zinc-containing enzyme <strong>carbonic anhydrase</strong> accelerates the reversible hydration of $CO_2$ by 10 million times:\n      $$\\text{CO}_2 + \\text{H}_2\\text{O} \\xrightleftharpoons{\\text{Carbonic Anhydrase}} \\text{H}_2\\text{CO}_3 \\xrightleftharpoons{\\text{Carbonic Anhydrase}} \\text{H}^+ + \\text{HCO}_3^-$$</li>\n      <li>$HCO_3^-$ diffuses out of RBCs into blood plasma. To maintain electrical neutrality, chloride ions ($Cl^-$) diffuse from plasma into RBCs &mdash; a phenomenon called the <strong>Chloride Shift (Hamburger's Phenomenon)</strong>. At the alveoli, the reaction reverses, expelling $CO_2$.</li>\n    </ul>\n    <strong>2. As Carbamino-Hemoglobin ($Hb-CO_2$) &mdash; 20% to 25% of Total $CO_2$:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li>$CO_2$ binds reversibly to the free amino ($-NH_2$) groups of globin polypeptide chains (not to heme):\n      $$\\text{Hb-NH}_2 + \\text{CO}_2 \\xrightleftharpoons{} \\text{Hb-NH-COO}^- + \\text{H}^+$$</li>\n      <li>At tissue level ($pCO_2$ high, $pO_2$ low), binding is favored. At alveolar level ($pO_2$ high, $pCO_2$ low), $O_2$ binding to heme displaces $CO_2$ from globin (<strong>Haldane Effect</strong>).</li>\n    </ul>\n    <strong>3. In Dissolved State in Plasma &mdash; ~7% of Total $CO_2$:</strong>\n    <ul style=\"margin:2px 0 6px 20px;\">\n      <li>Because $CO_2$ has a solubility roughly <strong>20 to 25 times higher than $O_2$</strong> in water, approximately 7% dissolves directly into the aqueous phase of blood plasma as carbonic acid.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">1. As bicarbonate ions (70%) via carbonic anhydrase & chloride shift (Hamburger phenomenon)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. As carbamino-hemoglobin (20–25%) with Haldane effect explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. In dissolved state in plasma (7%) due to high solubility of CO2</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What will be the $pO_2$ and $pCO_2$ in the atmospheric air compared to those in the alveolar air? Being:<br>(i) $pO_2$ lesser, $pCO_2$ higher<br>(ii) $pO_2$ higher, $pCO_2$ lesser<br>(iii) $pO_2$ higher, $pCO_2$ higher<br>(iv) $pO_2$ lesser, $pCO_2$ lesser.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Correct Option: (ii) $pO_2$ higher, $pCO_2$ lesser</strong><br><br>\n    <strong>Quantitative Comparison of Partial Pressures (in mm Hg):</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Respiratory Gas</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Atmospheric Air (at Sea Level)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Alveolar Air (Lungs)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Net Diffusion Gradient</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">$pO_2$ (Oxygen)</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">159 mm Hg (Higher)</td>\n            <td style=\"padding:8px 12px; font-weight:700;\">104 mm Hg (Lesser)</td>\n            <td style=\"padding:8px 12px;\">$O_2$ flows from atmosphere into alveoli.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">$pCO_2$ (Carbon Dioxide)</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">0.3 mm Hg (Lesser)</td>\n            <td style=\"padding:8px 12px; font-weight:700;\">40 mm Hg (Higher)</td>\n            <td style=\"padding:8px 12px;\">$CO_2$ flows from alveoli into atmosphere.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <em>Reason: Inhaled atmospheric air mixes with residual alveolar air (FRC) and becomes humidified with water vapor ($pH_2O = 47\\text{ mm Hg}$), which dilutes $pO_2$ down to 104 mm Hg, while continuous capillary excretion of $CO_2$ raises alveolar $pCO_2$ to 40 mm Hg.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of (ii) pO2 higher, pCO2 lesser in atmospheric air compared to alveolar air</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerical values: Atmospheric (pO2 = 159, pCO2 = 0.3) vs Alveolar (pO2 = 104, pCO2 = 40 mm Hg)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the process of inspiration under normal conditions.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Biomechanical Process of Normal Inspiration (Inhalation):</strong><br>\n    Inspiration is an <strong>active process</strong> driven by the contraction of primary inspiratory muscles, which generates a negative intra-thoracic pressure gradient according to Boyle's Law ($P \\propto 1/V$):<br><br>\n    <ol style=\"margin:4px 0 8px 20px;\">\n      <li><strong>Contraction and Flattening of the Diaphragm:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>The dome-shaped, muscular diaphragm contracts under motor stimulation from <strong>phrenic nerves</strong>, flattening downwards toward the abdominal cavity.</li>\n          <li>This expands the volume of the thoracic cavity along the <strong>antero-posterior (vertical) axis</strong> (responsible for ~75% of air entry in quiet breathing).</li>\n        </ul>\n      </li>\n      <li><strong>Contraction of External Intercostal Muscles:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Stimulated by intercostal nerves, the <strong>external intercostal muscles</strong> contract, pulling the ribs and the sternum upwards and outwards.</li>\n          <li>This increases the volume of the thoracic cavity along the <strong>dorso-ventral axis</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Expansion of Pulmonary Volume:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Because the parietal pleura adheres to the thoracic wall and visceral pleura adheres to lung tissue with pleural fluid between them, thoracic expansion forces the elastic lungs to expand proportionally.</li>\n        </ul>\n      </li>\n      <li><strong>Negative Pressure Gradient:</strong>\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Lung expansion drops intra-pulmonary pressure below atmospheric pressure (to about <strong>$-1 \\text{ to } -2\\text{ mm Hg}$</strong> relative to atmosphere).</li>\n          <li>Atmospheric air rushes down its pressure gradient through the respiratory tract into the alveoli until pressures equalize (Tidal Volume ~500 mL).</li>\n        </ul>\n      </li>\n    </ol>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Inspiration as an active process based on Boyle's law</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contraction and flattening of diaphragm expanding antero-posterior axis</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contraction of external intercostals elevating ribs/sternum along dorso-ventral axis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Drop in intra-pulmonary pressure below atmospheric causing air inflow</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How is respiration regulated? (Medullary rhythm center, pneumotaxic center in pons, chemosensitive area sensitive to $CO_2$ and $H^+$).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Neural and Chemical Regulation of Respiration:</strong><br>\n    Respiration is automatically adjusted to meet the body's metabolic oxygen demands and eliminate excess $CO_2$ through coordinated neural centers in the brainstem and peripheral chemoreceptors:<br><br>\n    <strong>A. Neural Regulatory Centers:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Respiratory Rhythm Center (Medulla Oblongata):</strong> The primary regulatory center responsible for generating the basic, involuntary rhythmic cycle of inspiration (dorsal respiratory group) and expiration (ventral respiratory group).</li>\n      <li><strong>2. Pneumotaxic Center (Pons Varolii):</strong> Located dorsally in the upper pons. It acts as an off-switch: it transmits inhibitory signals to the inspiratory center, limiting the duration of inspiration and thereby <strong>altering respiratory rate</strong>. Strong signals produce rapid, shallow breathing.</li>\n      <li><strong>3. Apneustic Center (Lower Pons):</strong> Sends stimulatory signals to prolong inspiration (acts antagonistically to the pneumotaxic center).</li>\n    </ul>\n    <strong>B. Chemical Regulation (Chemoreceptive Reflexes):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Central Chemosensitive Area:</strong> Situated adjacent to the medullary rhythm center. Highly sensitive to increases in <strong>$CO_2$ partial pressure ($pCO_2$)</strong> and <strong>hydrogen ion concentration ($[H^+]$ / decreased pH)</strong> in cerebrospinal fluid. Accumulation of $CO_2$ and $H^+$ triggers urgent nerve impulses to the rhythm center, accelerating depth and rate of breathing (hyperventilation) to blow off $CO_2$.</li>\n      <li><strong>2. Peripheral Chemoreceptors:</strong> Receptors located in the <strong>carotid bodies</strong> (at bifurcation of carotid arteries, innervated by glossopharyngeal nerve IX) and <strong>aortic bodies</strong> (on aortic arch, innervated by vagus nerve X). They detect rising arterial $pCO_2$, acidosis, and severe hypoxemia ($pO_2 < 60\\text{ mm Hg}$), sending immediate reflex signals to the respiratory center.</li>\n    </ul>\n    <em>Critical Note: The role of oxygen ($pO_2$) in normal respiratory regulation is quite insignificant; $CO_2$ and $H^+$ are the true primary chemical drivers of human breathing.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Medullary respiratory rhythm center generating basic rhythmic cycle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pneumotaxic center in pons limiting inspiration duration and altering breathing rate</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Central chemosensitive area responding to elevated CO2 and H+ ions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Peripheral chemoreceptors (aortic and carotid bodies) & insignificant role of O2 in routine regulation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the effect of $pCO_2$ on oxygen transport? (Bohr effect, shift of oxygen dissociation curve).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Effect of $pCO_2$ on Oxygen Transport &mdash; The Bohr Effect (Christian Bohr, 1904):</strong><br><br>\n    <strong>1. The Bohr Effect Phenomenon:</strong><br>\n    The affinity of hemoglobin for oxygen is inversely related to both blood acidity ($H^+$ concentration) and the partial pressure of carbon dioxide ($pCO_2$). An increase in $pCO_2$ causes the oxygen-hemoglobin dissociation curve to <strong>shift to the right</strong>, decreasing hemoglobin's oxygen-binding affinity and promoting the <strong>dissociation (unloading) of $O_2$</strong> to tissues.<br><br>\n    <strong>2. Molecular Mechanism at the Tissue Level:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Actively metabolizing tissues (e.g., exercising skeletal muscles) consume $O_2$ and generate large quantities of $CO_2$, raising local $pCO_2$ and $[H^+]$ (lactic acid, carbonic acid).</li>\n      <li>$CO_2$ diffuses into erythrocytes and hydrates to form carbonic acid, releasing $H^+$ ions.</li>\n      <li>$H^+$ ions bind specifically to histidine residues in deoxyhemoglobin, stabilizing the low-affinity <strong>T-state (tense conformation)</strong> of the hemoglobin tetramer.</li>\n      <li>This conformational change forces hemoglobin to release its bound oxygen molecules precisely where active tissues require it most.</li>\n    </ul>\n    <strong>3. Reverse Effect at the Alveolar Level:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>In the lungs, $CO_2$ is rapidly expired; hence, $pCO_2$ is low and pH is alkaline.</li>\n      <li>This shifts the oxygen dissociation curve back to the <strong>left</strong>, stabilizing the high-affinity <strong>R-state (relaxed conformation)</strong> of hemoglobin, promoting maximal oxygen loading to form oxyhemoglobin.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of Bohr effect: elevated pCO2 lowers hemoglobin-O2 affinity, shifting curve to the right</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tissue-level mechanism: high pCO2 and H+ induce O2 unloading to exercising cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Alveolar reversal: low pCO2 and high pH shift curve left for maximal O2 loading</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What happens to the respiratory process in a man going up a hill? (High altitude sickness, hypoxia, hyperventilation, polycythemia).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Physiological Responses &amp; Acclimatization at High Altitude:</strong><br><br>\n    <strong>1. Environmental Challenge &mdash; Hypoxia:</strong><br>\n    As an individual ascends a high mountain (>2500–3500 meters), the barometric atmospheric pressure drops significantly (from 760 mm Hg at sea level to &lt;500 mm Hg). Consequently, although the percentage of oxygen remains 21%, the <strong>partial pressure of oxygen ($pO_2$) declines sharply</strong>, leading to arterial oxygen desaturation, known as <strong>hypoxia</strong>.<br><br>\n    <strong>2. Acute Effects &mdash; High Altitude Sickness:</strong><br>\n    An un-acclimatized person rapidly develops <strong>Acute Mountain Sickness (AMS)</strong> within 8–24 hours, characterized by:\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Severe breathlessness (dyspnea) and rapid fatigue.</li>\n      <li>Nausea, vomiting, throbbing headache, dizziness, and insomnia.</li>\n    </ul>\n    <strong>3. Immediate Compensatory Physiological Mechanisms:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Hyperventilation:</strong> Hypoxia stimulates peripheral carotid body chemoreceptors, driving the respiratory rhythm center to accelerate the rate and depth of breathing.</li>\n      <li><strong>Tachycardia:</strong> Heart rate and cardiac output increase to accelerate oxygen delivery.</li>\n    </ul>\n    <strong>4. Long-Term Acclimatization Mechanisms:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Polycythemia:</strong> Chronic renal hypoxia triggers the juxtaglomerular cells of kidneys to secrete the peptide hormone <strong>erythropoietin (EPO)</strong>. EPO stimulates bone marrow hematopoiesis, drastically increasing total RBC count and hemoglobin concentration (polycythemia).</li>\n      <li><strong>Elevated 2,3-BPG:</strong> RBCs synthesize more 2,3-bisphosphoglycerate, shifting the oxygen dissociation curve to the right to enhance tissue $O_2$ release.</li>\n      <li><strong>Breathing Rate Normalizes:</strong> Alveolar ventilation remains chronically elevated with increased vascular capillarization.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Low atmospheric pressure causing hypoxia (reduced arterial pO2)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Acute mountain sickness symptoms: breathlessness, headache, fatigue, dizziness</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Immediate compensatory hyperventilation via carotid chemoreceptors</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Long-term acclimatization: Erythropoietin (EPO) release, polycythemia, and 2,3-BPG synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch14-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch14-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch14-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the site of gaseous exchange in an insect?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Site and Working Mechanism of Gaseous Exchange in Insects:</strong><br><br>\n    In insects (e.g., Cockroach, Grasshopper), the circulatory system lacks hemoglobin and plays zero role in gas transport. Instead, gas exchange occurs directly at the cellular level through an intricate network of internal air tubes called the <strong>Tracheal System</strong>:<br><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>1. Spiracles:</strong> Atmospheric air enters the body through 10 pairs of lateral valved openings called <strong>spiracles</strong> (2 pairs thoracic, 8 pairs abdominal).</li>\n      <li><strong>2. Tracheal Trunks:</strong> Spiracles lead into wide internal longitudinal <strong>tracheae</strong>, reinforced by spiral cuticular chitinous rings (taenidia) that prevent tube collapse.</li>\n      <li><strong>3. Tracheoles (The Actual Exchange Site):</strong><br>\n      The tracheae branch repeatedly into microscopic, non-taenidial, blind-ended terminal tubes called <strong>tracheoles</strong> (diameter &lt; 1 $\\mu m$).\n      <ul style=\"margin:2px 0 4px 15px;\">\n        <li>The tips of tracheoles are filled with watery <strong>tracheolar fluid</strong> and terminate in direct, intimate contact with the plasma membranes of individual body tissue cells.</li>\n        <li><strong>Gaseous Exchange Mechanism:</strong> Oxygen diffuses directly from the air in tracheoles into the tracheolar fluid and across cell membranes into mitochondria. Simultaneously, metabolic carbon dioxide diffuses from tissue cells into tracheoles and is expelled through spiracles.</li>\n      </ul>\n      </li>\n    </ul>\n    <strong>Conclusion:</strong> The true microscopic sites of gaseous exchange are the <strong>thin, fluid-filled endings of tracheoles</strong> directly bathing tissues.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Tracheoles (tracheal system) as the microscopic site of gas exchange</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direct diffusion mechanism from tracheolar fluid into individual tissue cells without blood involvement</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 13</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(15)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 15 (Body Fluids and Circulation) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[15] = "<section class=\"chapter-section\" id=\"c11b-ch15\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 15</div>\n      <h2>Body Fluids and Circulation</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 15 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/></svg>\n      Human Cardiac Cycle &amp; Standard Electrocardiogram (ECG) Waves\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Standard ECG Waveform on Left -->\n      <g transform=\"translate(40, 25)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">STANDARD NORMAL ELECTROCARDIOGRAM (ECG)</text>\n        \n        <!-- Grid baseline -->\n        <line x1=\"20\" y1=\"120\" x2=\"340\" y2=\"120\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n        \n        <!-- ECG Wave -->\n        <path d=\"M 20,120 L 50,120 Q 65,95 80,120 L 105,120 L 115,135 L 130,45 L 145,150 L 155,120 L 200,120 Q 230,85 260,120 L 330,120\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.8\" stroke-linecap=\"round\"/>\n\n        <!-- Wave labels -->\n        <!-- P wave -->\n        <circle cx=\"65\" cy=\"107\" r=\"3\" fill=\"#2563eb\"/>\n        <text x=\"65\" y=\"90\" font-size=\"9\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">P Wave</text>\n        <text x=\"65\" y=\"145\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">Atrial Depol.</text>\n\n        <!-- QRS Complex -->\n        <circle cx=\"130\" cy=\"45\" r=\"3\" fill=\"#16a34a\"/>\n        <text x=\"130\" y=\"32\" font-size=\"10\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">QRS Complex</text>\n        <text x=\"130\" y=\"170\" font-size=\"7.5\" fill=\"#065f46\" text-anchor=\"middle\">Ventricular Depolarisation</text>\n\n        <!-- T wave -->\n        <circle cx=\"230\" cy=\"102\" r=\"3\" fill=\"#d97706\"/>\n        <text x=\"230\" y=\"85\" font-size=\"9\" font-weight=\"bold\" fill=\"#b45309\" text-anchor=\"middle\">T Wave</text>\n        <text x=\"230\" y=\"145\" font-size=\"7\" fill=\"#64748b\" text-anchor=\"middle\">Ventricular Repol.</text>\n      </g>\n\n      <!-- Double Circulation Map on Right -->\n      <g transform=\"translate(420, 25)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">HUMAN DOUBLE CIRCULATION (PULMONARY &amp; SYSTEMIC)</text>\n\n        <!-- Pulmonary circulation block -->\n        <rect x=\"25\" y=\"40\" width=\"350\" height=\"36\" rx=\"4\" fill=\"#eff6ff\" stroke=\"#3b82f6\"/>\n        <text x=\"35\" y=\"55\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e40af\">1. Pulmonary Circulation:</text>\n        <text x=\"35\" y=\"68\" font-size=\"7.5\" fill=\"#334155\">Right Ventricle &rarr; Pulmonary Artery &rarr; Lungs &rarr; Pulmonary Veins &rarr; Left Atrium</text>\n\n        <!-- Systemic circulation block -->\n        <rect x=\"25\" y=\"85\" width=\"350\" height=\"36\" rx=\"4\" fill=\"#fef2f2\" stroke=\"#ef4444\"/>\n        <text x=\"35\" y=\"100\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#991b1b\">2. Systemic Circulation:</text>\n        <text x=\"35\" y=\"113\" font-size=\"7.5\" fill=\"#334155\">Left Ventricle &rarr; Aorta &rarr; Systemic Tissues &rarr; Vena Cava &rarr; Right Atrium</text>\n\n        <!-- Cardiac Cycle Stats -->\n        <rect x=\"25\" y=\"130\" width=\"350\" height=\"48\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"35\" y=\"146\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">&bull; Duration of Cardiac Cycle: 0.8 seconds (Heart Rate = 72 beats/min)</text>\n        <text x=\"35\" y=\"160\" font-size=\"8\" fill=\"#334155\">&bull; Stroke Volume = 70 mL &nbsp;|&nbsp; Cardiac Output = 70 &times; 72 &asymp; 5.0 Litres/min</text>\n        <text x=\"35\" y=\"172\" font-size=\"7.5\" fill=\"#64748b\">&bull; Heart Sounds: Lubb (AV valves closure) &amp; Dubb (Semilunar valves closure)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 15: Formed Elements, Blood Groups, Double Circulation, ECG Waves & Cardiac Disorders</div>\n\n  <!-- c11b-ch15-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the components of the formed elements in the erythrocyte, leukocyte and thrombocytes.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Detailed Components of Formed Elements of Blood (45% of Total Blood Volume):</strong><br><br>\n    <strong>1. Erythrocytes (Red Blood Cells &mdash; RBCs):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Count: 5.0 to 5.5 million per $\\text{mm}^3$ of blood.</li>\n      <li>Components: Biconcave circular enucleate discs packed with the iron-bearing chromoprotein <strong>Hemoglobin</strong> ($12–16\\text{ g/100 mL}$), carbonic anhydrase enzyme, plasma membrane with surface blood group antigens (A, B, Rh).</li>\n    </ul>\n    <strong>2. Leukocytes (White Blood Cells &mdash; WBCs):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Count: 6,000 to 8,000 per $\\text{mm}^3$ of blood. Nucleated defensive cells categorized into:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>Granulocytes:</em>\n            <br>&bull; <strong>Neutrophils (60–65%):</strong> Multilobed nucleus; phagocytic engulfment of bacteria.\n            <br>&bull; <strong>Eosinophils (2–3%):</strong> Bilobed nucleus; defense against parasites, allergic reactions.\n            <br>&bull; <strong>Basophils (0.5–1%):</strong> S-shaped nucleus; secretes histamine, serotonin, and heparin.\n          </li>\n          <li><em>Agranulocytes:</em>\n            <br>&bull; <strong>Lymphocytes (20–25%):</strong> B-lymphocytes (produce antibodies) and T-lymphocytes (cell-mediated immunity).\n            <br>&bull; <strong>Monocytes (6–8%):</strong> Kidney-shaped nucleus; transform into phagocytic tissue macrophages.\n          </li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Thrombocytes (Blood Platelets):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Count: 150,000 to 350,000 per $\\text{mm}^3$. Non-nucleated cellular fragments derived from bone marrow <strong>megakaryocytes</strong>; contain thromboplastin, serotonin, and platelet factor 3 (PF3) essential for blood coagulation.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Erythrocytes: count, enucleate biconcave shape, hemoglobin and blood group antigens</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Leukocytes: granulocytes (neutrophils, eosinophils, basophils) & agranulocytes (lymphocytes, monocytes)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thrombocytes: origin from megakaryocytes and clotting factors</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the importance of plasma proteins? (Albumin for osmotic balance, Globulins for antibodies/defense, Fibrinogen for blood clotting).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Physiological Importance of the Three Major Plasma Proteins (6–8% of Plasma):</strong><br><br>\n    <strong>1. Fibrinogen (~0.3 g/100 mL):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Synthesized exclusively by the liver; soluble high-molecular weight glycoprotein precursor.</li>\n      <li><em>Role:</em> Essential for <strong>blood coagulation (hemostasis)</strong>. In the clotting cascade, thrombin cleaves fibrinogen into insoluble, sticky <strong>fibrin threads</strong> that form a mesh trapping RBCs to seal injured blood vessels and stop hemorrhage.</li>\n    </ul>\n    <strong>2. Globulins (~2.0 to 2.5 g/100 mL):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Subdivided into $alpha$, $\beta$, and $gamma$ (gamma) globulins:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><em>$gamma$-Globulins (Immunoglobulins / Antibodies):</em> Synthesized by plasma B-lymphocytes; act as the primary defense mechanism against bacterial and viral pathogens.</li>\n          <li><em>$alpha$ and $\beta$-Globulins:</em> Transport lipid hormones, iron (transferrin), and copper (ceruloplasmin).</li>\n        </ul>\n      </li>\n    </ul>\n    <strong>3. Albumins (~4.0 to 4.5 g/100 mL &mdash; Most Abundant):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Smallest plasma proteins synthesized by liver.</li>\n      <li><em>Role:</em> Responsible for maintaining <strong>blood colloidal osmotic (oncotic) pressure</strong> (~25 to 28 mm Hg). This pressure pulls water from interstitial spaces back into capillary lumen, preventing tissue edema. Also transports bilirubin and free fatty acids.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Fibrinogen: role in blood clotting cascade (conversion to fibrin mesh)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Globulins: defensive role of gamma-globulins (antibodies / immunoglobulins)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Albumins: primary role in maintaining colloidal osmotic / oncotic pressure and preventing edema</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match Column I with Column II:<br>(a) Eosinophils &mdash;&mdash;&mdash;&mdash;&mdash; (i) Coagulation<br>(b) RBC &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (ii) Universal recipient<br>(c) AB group &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (iii) Resist infections &amp; allergic response<br>(d) Platelets &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (iv) Contraction of heart<br>(e) Systole &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (v) Gas transport\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Column Matching:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Column I</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Column II (Correct Match)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Physiological Significance</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) Eosinophils</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Resist infections &amp; allergic response</td>\n            <td style=\"padding:8px 12px;\">Degranulate histaminase and major basic protein during helminthic infections and allergies.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) RBC</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(v) Gas transport</td>\n            <td style=\"padding:8px 12px;\">Transports $O_2$ (as oxyhemoglobin) and $CO_2$ via hemoglobin and carbonic anhydrase.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) AB group</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Universal recipient</td>\n            <td style=\"padding:8px 12px;\">Possesses both A and B antigens on RBCs, but has <strong>no antibodies (anti-A or anti-B)</strong> in plasma.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(d) Platelets</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Coagulation</td>\n            <td style=\"padding:8px 12px;\">Release thromboplastin and platelet factor 3 to initiate thrombus formation.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(e) Systole</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Contraction of heart</td>\n            <td style=\"padding:8px 12px;\">Rhythmic active muscular contraction phase of atria (0.1s) and ventricles (0.3s).</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>Final Option Matching Sequence:</strong><br>\n    <strong>(a) &rarr; (iii), &nbsp; (b) &rarr; (v), &nbsp; (c) &rarr; (ii), &nbsp; (d) &rarr; (i), &nbsp; (e) &rarr; (iv)</strong>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) to (iii) Resist infections & allergic response</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) to (v) Gas transport</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) to (ii) Universal recipient</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) to (i) Coagulation & (e) to (iv) Contraction of heart</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why do we consider blood as a connective tissue?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Justification for Classifying Blood as a Specialized Fluid Connective Tissue:</strong><br><br>\n    <strong>1. Common Embryological Origin:</strong><br>\n    Like all other connective tissues (bone, cartilage, areolar tissue, adipose), blood is derived embryologically from the embryonic <strong>mesoderm</strong>.<br><br>\n    <strong>2. Structural Matrix Composition:</strong><br>\n    A classic histological definition of connective tissue requires widely spaced living cells suspended within an abundant non-living extracellular ground substance (matrix). In blood, formed elements (RBCs, WBCs, platelets) are suspended within a fluid matrix called <strong>plasma</strong>.<br><br>\n    <strong>3. Physiological Connecting Function:</strong><br>\n    Connective tissues connect and integrate different organs and anatomical systems of the body. Blood continuously circulates through closed vessels, physically and physiologically linking every tissue: it transports oxygen from lungs to deep tissues, nutrients from intestines to liver and muscles, metabolic wastes from cells to kidneys, and endocrine hormones from ductless glands to distant target receptors.<br><br>\n    <em>Distinguishing Exception: Unlike proper connective tissues where fibers (collagen/elastin) are secreted by resident cells, blood plasma fibers are soluble precursors (fibrinogen) that polymerize into insoluble fibrin fibers only during clotting.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mesodermal embryological origin shared with other connective tissues</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural organization: widely spaced cells suspended in extracellular matrix (plasma)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physiological function of linking and integrating distant body organs and systems</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the difference between lymph and blood?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Differences Between Blood and Lymph:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Parameter</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Blood</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Lymph (Tissue Fluid / Interstitial Fluid)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. Colour</td>\n            <td style=\"padding:8px 12px; color:#dc2626; font-weight:700;\">Bright red (oxygenated) or dark purplish-red (deoxygenated) due to hemoglobin.</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\">Colorless to pale straw-colored fluid (lacks hemoglobin).</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. Formed Elements</td>\n            <td style=\"padding:8px 12px;\">Contains abundant <strong>RBCs, all classes of WBCs, and platelets</strong>.</td>\n            <td style=\"padding:8px 12px;\"><strong>RBCs and platelets are completely absent.</strong> Contains predominantly <strong>lymphocytes</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">3. Protein &amp; Nutrient Content</td>\n            <td style=\"padding:8px 12px;\">High protein concentration (6–8% plasma proteins including abundant albumin, fibrinogen).</td>\n            <td style=\"padding:8px 12px;\">Significantly lower protein content and low calcium/phosphorus; higher in metabolic wastes.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">4. Fat Content</td>\n            <td style=\"padding:8px 12px;\">Normal soluble lipoprotein transport.</td>\n            <td style=\"padding:8px 12px;\">Rich in emulsified dietary fats absorbed from intestinal villi via specialized lymph vessels (<strong>lacteals</strong>) as chylomicrons.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">5. Circulation Direction</td>\n            <td style=\"padding:8px 12px;\">Circular closed pathway: Heart &rarr; Arteries &rarr; Capillaries &rarr; Veins &rarr; Heart.</td>\n            <td style=\"padding:8px 12px;\"><strong>Unidirectional flow:</strong> Tissues &rarr; Lymphatic vessels &rarr; Thoracic duct &rarr; Subclavian veins &rarr; Blood.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Colour and presence of RBCs in blood vs complete absence in lymph</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formed elements: blood has all 3 vs lymph has predominantly lymphocytes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Protein content, fat absorption in lacteals, and unidirectional flow</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is meant by double circulation? What is its significance?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Definition of Double Circulation:</strong><br>\n    <strong>Double circulation</strong> is a specialized circulatory system found in birds and mammals where blood passes through the four-chambered heart <strong>twice during one complete systemic cardiac cycle</strong>. The deoxygenated and oxygenated blood streams are completely separated by interatrial and interventricular septa, preventing any mixing.<br><br>\n    <strong>The Two Distinct Circuits of Double Circulation:</strong><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>A. Pulmonary Circulation:</strong><br>\n      Deoxygenated blood from the <strong>Right Ventricle</strong> is pumped into the Pulmonary Artery &rarr; Pulmonary Capillaries in Lungs (releases $CO_2$, absorbs $O_2$) &rarr; Pulmonary Veins &rarr; delivers oxygenated blood to the <strong>Left Atrium</strong>.</li>\n      <li><strong>B. Systemic Circulation:</strong><br>\n      Oxygenated blood from the <strong>Left Ventricle</strong> is pumped under high pressure into the massive <strong>Aorta</strong> &rarr; Systemic Arteries &rarr; Capillaries of body tissues (delivers $O_2$, takes up $CO_2$) &rarr; Systemic Veins &rarr; Superior and Inferior Vena Cava &rarr; returns deoxygenated blood to the <strong>Right Atrium</strong>.</li>\n    </ul>\n    <strong>2. Biological Significance of Double Circulation:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Zero Mixing of Oxygenated and Deoxygenated Blood:</strong> Guarantees delivery of blood with maximum oxygen saturation to tissues.</li>\n      <li><strong>Supports High Metabolic Demands of Homeothermy:</strong> Birds and mammals are warm-blooded (endothermic); maintaining constant elevated core body temperatures requires colossal cellular ATP production and intense oxygen delivery.</li>\n      <li><strong>Differential Pressure Regulation:</strong> Allows pulmonary circuit to operate under safe <strong>low hydrostatic pressure</strong> (~25/10 mm Hg) to protect delicate alveolar membranes from pulmonary edema, while systemic circuit operates under <strong>high pressure</strong> (~120/80 mm Hg) to propel blood through extensive systemic vascular beds against gravity.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of double circulation (blood passing twice through heart per cycle)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed pathways: Pulmonary circuit vs Systemic circuit</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance: Zero mixing of blood, homeothermy energy demands, differential pressure regulation</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the differences between: (a) Blood and Lymph (b) Open and Closed system of circulation (c) Systole and Diastole (d) P-wave and T-wave.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>(a) Blood vs. Lymph:</strong><br>\n    Blood is red, contains RBCs, high protein content, and circulates in a closed circuit. Lymph is colorless, lacks RBCs, contains predominantly lymphocytes, carries dietary fats from lacteals, and flows unidirectionally from tissues to venous blood.<br><br>\n    <strong>(b) Open vs. Closed System of Circulation:</strong><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.83rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n            <th style=\"padding:4px 8px;\">Trait</th><th style=\"padding:4px 8px;\">Open Circulatory System</th><th style=\"padding:4px 8px;\">Closed Circulatory System</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:4px 8px; font-weight:700;\">Vessels</td><td style=\"padding:4px 8px;\">Blood pumped by heart into large open spaces/sinuses (hemocoel). Capillaries absent.</td><td style=\"padding:4px 8px;\">Blood flows strictly confined within continuous closed network of blood vessels (arteries, veins, capillaries).</td></tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\"><td style=\"padding:4px 8px; font-weight:700;\">Pressure &amp; Velocity</td><td style=\"padding:4px 8px;\">Very low pressure, sluggish flow; poor regulation of flow to specific organs.</td><td style=\"padding:4px 8px;\">High hydrostatic pressure, rapid velocity; tightly regulated by vasomotor constriction.</td></tr>\n          <tr><td style=\"padding:4px 8px; font-weight:700;\">Examples</td><td style=\"padding:4px 8px;\">Arthropods (cockroach, crab) and Non-cephalopod Molluscs (pila).</td><td style=\"padding:4px 8px;\">Annelids (earthworm), Cephalopods (squid), and all <strong>Vertebrates</strong>.</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>(c) Systole vs. Diastole:</strong><br>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>Systole:</em> The phase of active muscular <strong>contraction</strong> of the heart chambers (atrial systole = 0.1 s; ventricular systole = 0.3 s), during which chamber volume decreases and blood is pumped out under high pressure.</li>\n      <li><em>Diastole:</em> The phase of muscular <strong>relaxation and dilation</strong> of heart chambers (joint diastole = 0.4 s; ventricular diastole = 0.5 s), during which chambers refill with returning venous blood under low pressure.</li>\n    </ul>\n    <strong>(d) P-Wave vs. T-Wave of Electrocardiogram (ECG):</strong><br>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><em>P-Wave:</em> Small positive upward deflection representing <strong>atrial depolarisation</strong>, which leads directly to the mechanical contraction (systole) of both atria.</li>\n      <li><em>T-Wave:</em> Broader, smooth positive upward deflection representing <strong>ventricular repolarisation</strong> (return of ventricles from excited to resting electrical state), marking the end of ventricular systole.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Blood vs Lymph differentiation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Open vs Closed circulation (capillaries, pressure, flow control, examples)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Systole (active contraction/pumping) vs Diastole (relaxation/refilling)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) P-wave (atrial depolarisation) vs T-wave (ventricular repolarisation)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the evolutionary change in the pattern of heart among the vertebrates.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Evolutionary Trajectory of the Vertebrate Heart (from Single to Double Circulation):</strong><br><br>\n    <strong>1. Two-Chambered Heart &mdash; Fishes (Class Pisces):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Consists of <strong>one atrium and one ventricle</strong> (plus accessory sinus venosus and conus arteriosus).</li>\n      <li><strong>Single Circulation (Venous Heart):</strong> The heart receives and pumps only deoxygenated blood. Blood pumped by ventricle goes to gills for oxygenation and flows directly to systemic tissues before returning to atrium.</li>\n    </ul>\n    <strong>2. Three-Chambered Heart &mdash; Amphibians (Frogs, Salamanders):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Consists of <strong>two atria and a single undivided ventricle</strong>.</li>\n      <li>Left atrium receives oxygenated blood from lungs/skin; right atrium receives deoxygenated blood from body. Both atria empty into the single ventricle, where <strong>mixing of oxygenated and deoxygenated blood occurs</strong> (incomplete double circulation).</li>\n    </ul>\n    <strong>3. Incomplete Four-Chambered Heart &mdash; Reptiles (Except Crocodiles):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Consists of two atria and a <strong>partially partitioned ventricle</strong> with an incomplete interventricular septum. Mixing of blood is reduced but still occurs (incomplete double circulation).</li>\n      <li><em>Crocodiles</em> possess a fully partitioned four-chambered heart.</li>\n    </ul>\n    <strong>4. Complete Four-Chambered Heart &mdash; Birds (Aves) and Mammals:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Consists of <strong>two atria and two completely separated ventricles</strong> divided by interatrial and interventricular septa.</li>\n      <li><strong>Complete Double Circulation:</strong> Complete anatomical separation of pulmonary and systemic circuits; zero mixing of oxygenated and deoxygenated blood, fulfilling the high metabolic requirements of homeothermy.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Fishes: 2-chambered venous heart with single circulation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Amphibians: 3-chambered heart with single ventricle and blood mixing</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reptiles: incomplete 4-chambered heart with partial septum (crocodile exception)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Birds and Mammals: 4-chambered heart with complete double circulation and no mixing</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Why do we call our heart myogenic?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why the Human Heart is Designated as Myogenic:</strong><br><br>\n    <strong>1. Intrinsic Origin of Heartbeat in Muscle Cells (Myocytes):</strong><br>\n    In the human heart, the rhythmic electrical impulse for contraction (action potential) is generated <strong>intrinsically by specialized auto-rhythmic cardiac muscular tissue (nodal tissue)</strong>, entirely independent of external nervous stimulation.<br>\n    The primary site of origin is the <strong>Sino-Atrial (SA) node</strong>, which consists of modified, self-excitable neuromuscular cells situated in the upper wall of the right atrium.<br><br>\n    <strong>2. Contrast with Neurogenic Hearts:</strong><br>\n    In contrast, <strong>neurogenic hearts</strong> (found in invertebrates like annelids and arthropods) require external rhythmic nerve impulses from motor nerve ganglia to initiate contraction. If the motor nerve is severed, a neurogenic heart stops beating immediately.<br><br>\n    <strong>3. Experimental Proof of Myogenic Nature:</strong><br>\n    If a mammalian or human heart is completely excised from the body, severed from all cranial and spinal nerves, and placed in a warm, oxygenated Ringer-Locke nutrient perfusion solution, it <strong>continues to beat rhythmically and autonomously for hours</strong>.<br><br>\n    <em>Regulatory Note: Extrinsic autonomic nerves (sympathetic accelerator and parasympathetic vagus nerves) merely modulate the heart rate, but do NOT initiate the heartbeat.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of myogenic: heartbeat initiated intrinsically by specialized auto-rhythmic nodal muscle cells (SA node)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast with neurogenic hearts (invertebrates) and evidence of excised heart continuing to beat</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Sino-atrial node is called the pacemaker of our heart. Why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why the Sino-Atrial (SA) Node is Designated as the Natural Pacemaker:</strong><br><br>\n    <strong>1. Anatomical Location:</strong><br>\n    The <strong>Sino-Atrial (SA) node</strong> is a crescent-shaped patch of specialized auto-rhythmic neuromuscular tissue located in the right upper corner of the wall of the <strong>right atrium</strong>, close to the opening of the superior vena cava.<br><br>\n    <strong>2. Highest Intrinsic Rate of Action Potential Generation:</strong><br>\n    While all components of the nodal conduction system (SA node, AV node, Bundle of His, Purkinje fibers) possess inherent rhythmicity, the SA node exhibits the <strong>highest intrinsic frequency of spontaneous electrical depolarization</strong>:\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>SA Node:</strong> Generates <strong>70 to 75 action potentials per minute</strong> (average ~72/min).</li>\n      <li><em>AV Node:</em> Generates only ~40 to 60 action potentials per minute.</li>\n      <li><em>Purkinje Fibers:</em> Generate only ~20 to 35 action potentials per minute.</li>\n    </ul>\n    <strong>3. Dominant Pacemaking Function:</strong><br>\n    Because the SA node fires fastest, its electrical wave of excitation spreads rapidly across atrial syncytial muscle fibers, depolarizing and capturing control of all subsidiary nodal tissues before they can reach their own spontaneous threshold. It thus sets and dictates the rhythmic pace of contraction for the entire heart, rightfully earning the title of the <strong>pacemaker</strong>.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Location of SA node in upper lateral wall of right atrium</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Generates maximum frequency of action potentials (70–75/min)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Overrides slower subsidiary centers and dictates the rhythmic pace of cardiac cycle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the significance of atrio-ventricular node and atrio-ventricular bundle in the functioning of heart?\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Functional Significance of the AV Node and AV Bundle (Bundle of His):</strong><br><br>\n    <strong>1. Significance of the Atrio-Ventricular (AV) Node:</strong><br>\n    Situated in the lower-left corner of the right atrium close to the atrio-ventricular septum.\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>AV Nodal Delay (~0.1 second):</strong> The electrical impulse conducted from the SA node across atrial walls is delayed by approximately <strong>0.1 second (100 milliseconds)</strong> at the AV node due to thin, slow-conducting fibers.</li>\n      <li><em>Physiological Cruciality:</em> This brief delay ensures that <strong>atria have completely finished their mechanical contraction (atrial systole)</strong> and emptied their full volume of blood into the relaxed ventricles <em>before</em> the massive ventricles are stimulated to contract. Without this delay, atria and ventricles would contract simultaneously, preventing proper ventricular filling.</li>\n      <li><strong>Reserve Pacemaker:</strong> If the SA node fails, the AV node can take over as secondary pacemaker, generating 40–60 beats/min to sustain life.</li>\n    </ul>\n    <strong>2. Significance of the Atrio-Ventricular (AV) Bundle (Bundle of His &amp; Purkinje Fibers):</strong><br>\n    The dense non-conducting fibrous atrio-ventricular ring acts as an electrical insulator between atria and ventricles.\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The <strong>AV Bundle (Bundle of His)</strong> is the <strong>sole electrical bridge</strong> through which action potentials can cross from atria into the ventricles.</li>\n      <li>It bifurcates into Right and Left Bundle Branches, branching into colossal <strong>Purkinje fibers</strong> that conduct action potentials at an extraordinary velocity (~4 meters/second).</li>\n      <li>This ensures that both ventricles contract synchronously from the <strong>apex upward toward the base</strong>, efficiently squeezing blood upward into the aorta and pulmonary artery.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">AV node location and critical AV nodal delay (0.1s)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Importance of delay: allows atria to completely empty before ventricles contract</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">AV bundle as the sole electrical bridge through fibrous insulation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Purkinje fibers conducting high-speed synchronized contraction from apex upward</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define a cardiac cycle and the cardiac output.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>1. Definition of Cardiac Cycle:</strong><br>\n    The <strong>cardiac cycle</strong> is the complete, orderly sequence of coordinated electrical, mechanical, pressure, and volume events that occur in the heart from the beginning of one heartbeat to the beginning of the next.<br>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>At a resting heart rate of 72 beats per minute, the total duration of a single cardiac cycle is:\n      $$\\text{Duration} = \\frac{60\\text{ seconds}}{72} = \\mathbf{0.8\\text{ seconds}}$$</li>\n      <li>Comprises: (i) Atrial systole (0.1 s), (ii) Ventricular systole (0.3 s), and (iii) Joint diastole (0.4 s).</li>\n    </ul>\n    <strong>2. Definition of Cardiac Output (CO):</strong><br>\n    <strong>Cardiac output</strong> is the total volume of blood pumped out by <strong>each ventricle per minute</strong>.<br>\n    It is mathematically calculated as the product of the <strong>Stroke Volume (SV)</strong> and the <strong>Heart Rate (HR)</strong>:\n    $$\\mathbf{\\text{Cardiac Output (CO)} = \\text{Stroke Volume (SV)} \\times \\text{Heart Rate (HR)}}$$\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Stroke Volume:</strong> Volume of blood ejected by each ventricle during one beat (~70 mL).</li>\n      <li><strong>Heart Rate:</strong> Number of heartbeats per minute (~72 beats/min).</li>\n    </ul>\n    $$\\text{CO} = 70\\text{ mL} \\times 72\\text{ beats/min} = 5040\\text{ mL/min} \\approx \\mathbf{5.0 \\text{ Litres/minute}}$$\n    <em>Physiological Variability: In trained endurance athletes, cardiac output can increase four- to five-fold during intense exertion (up to 25–30 L/min) due to higher stroke volume.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of Cardiac Cycle and duration calculation (0.8 seconds at 72 bpm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of Cardiac Output: formula CO = Stroke Volume x Heart Rate</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Standard calculation (~70 mL x 72 = ~5.0 Litres/min) and athlete variation</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q13 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q13\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q13')\">\n      <div class=\"q-num\">Question 13</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain heart sounds. (Lubb: closure of AV tricuspid/bicuspid valves; Dubb: closure of semilunar valves).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Acoustic and Clinical Analysis of Heart Sounds:</strong><br>\n    During each cardiac cycle, two prominent clinical heart sounds are audible through a stethoscope placed on the precordium, produced by the vibration of heart walls and blood eddies associated with the <strong>sudden snapping closure of cardiac valves</strong>:<br><br>\n    <strong>1. First Heart Sound &mdash; \"Lubb\" ($S_1$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Cause:</strong> Produced by the simultaneous, sharp closure of the <strong>atrio-ventricular (AV) valves</strong> (the tricuspid valve on the right and bicuspid / mitral valve on the left) at the very onset of <strong>ventricular systole</strong>.</li>\n      <li><strong>Acoustic Character:</strong> Relatively lower pitched, dull, booming, and longer in duration (~0.10 to 0.14 seconds).</li>\n      <li><strong>Clinical Significance:</strong> Marks the beginning of ventricular contraction and prevents backflow of blood into atria.</li>\n    </ul>\n    <strong>2. Second Heart Sound &mdash; \"Dubb\" ($S_2$):</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Cause:</strong> Produced by the abrupt, synchronized closure of the <strong>semilunar valves</strong> (aortic and pulmonary semilunar valves) at the onset of <strong>ventricular diastole</strong>.</li>\n      <li><strong>Acoustic Character:</strong> Sharper, higher pitched, snapping, and shorter in duration (~0.08 to 0.10 seconds).</li>\n      <li><strong>Clinical Significance:</strong> Marks the beginning of ventricular relaxation and prevents backflow of blood from aorta and pulmonary trunk into ventricles.</li>\n    </ul>\n    <em>Clinical Pathology: Defective, leaking, or stenosed valves generate abnormal murmurs / hissing sounds.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">First sound \"Lubb\": closure of AV valves (tricuspid/bicuspid) at onset of ventricular systole</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Second sound \"Dubb\": closure of semilunar valves (aortic/pulmonary) at onset of ventricular diastole</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q14 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q14\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q14')\">\n      <div class=\"q-num\">Question 14</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw a standard ECG and explain the different segments. (P wave: atrial depolarisation; QRS complex: ventricular depolarisation; T wave: ventricular repolarisation).\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Clinical Interpretation of Standard Electrocardiogram (ECG) Deflections:</strong><br>\n    An Electrocardiogram (ECG) is a graphic recording of the electrical potentials generated by the heart muscle during each cardiac cycle, recorded using standard limb electrodes:<br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">ECG Waveform</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Electrical Event Represented</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Mechanical Cardiac Correlation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">1. P-Wave</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Atrial Depolarisation</strong></td>\n            <td style=\"padding:8px 12px;\">Spread of excitation from SA node over both atria, leading to mechanical <strong>atrial contraction (systole)</strong>.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">2. QRS Complex</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Ventricular Depolarisation</strong></td>\n            <td style=\"padding:8px 12px;\">Rapid spread of impulse through Bundle of His and Purkinje fibers; initiates <strong>ventricular contraction (systole)</strong> just after Q-wave. The number of QRS complexes per minute determines <strong>heart rate</strong>.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">3. T-Wave</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:700;\"><strong>Ventricular Repolarisation</strong></td>\n            <td style=\"padding:8px 12px;\">Return of ventricles from excited to resting state; marks the end of ventricular systole and entry into ventricular diastole.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">P wave: electrical atrial depolarisation leading to atrial systole</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">QRS complex: ventricular depolarisation leading to ventricular systole & determining heart rate</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">T wave: ventricular repolarisation marking the end of ventricular systole</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch15-q15 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch15-q15\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch15-q15')\">\n      <div class=\"q-num\">Question 15</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Mention common circulatory disorders: Hypertension, Coronary Artery Disease (Atherosclerosis), Angina Pectoris, Heart Failure.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Clinical Pathology of Common Human Cardiovascular Disorders:</strong><br><br>\n    <strong>1. Hypertension (High Blood Pressure):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Condition where arterial blood pressure is persistently higher than normal (normal = $120/80\\text{ mm Hg}$).</li>\n      <li>Diagnosed when repeated resting readings exceed <strong>$140/90\\text{ mm Hg}$</strong> ($140 = \\text{systolic}, 90 = \\text{diastolic}$).</li>\n      <li>Leads to cardiac hypertrophy and damages vital organs: brain (cerebral stroke), kidneys (renal failure), and retina.</li>\n    </ul>\n    <strong>2. Coronary Artery Disease (CAD / Atherosclerosis):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Progressive narrowing and loss of elasticity of coronary arteries supplying oxygenated blood to heart musculature.</li>\n      <li>Caused by pathological deposition of <strong>calcium, fat, cholesterol, and fibrous tissue (atheromatous plaques)</strong> inside coronary lumen, obstructing coronary circulation.</li>\n    </ul>\n    <strong>3. Angina Pectoris (\"Angina\"):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Severe, acute, suffocating retrosternal chest pain that radiates down the left shoulder and arm.</li>\n      <li>Occurs due to transient <strong>myocardial ischemia</strong> (insufficient blood and oxygen flow reaching the heart muscle). Triggered by physical exertion or emotional stress.</li>\n    </ul>\n    <strong>4. Heart Failure:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>The state of heart when it cannot pump blood effectively enough to meet the metabolic demands of the body.</li>\n      <li>Often called <strong>congestive heart failure</strong> because lungs become congested with fluid. <em>(Distinct from Cardiac Arrest &mdash; when heart stops beating; and Heart Attack / Myocardial Infarction &mdash; when heart muscle dies due to total coronary artery occlusion).</em></li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Hypertension: definition (>140/90 mm Hg) and clinical consequences</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Coronary Artery Disease (Atherosclerosis): cholesterol/calcium plaque deposition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Angina Pectoris: acute chest pain due to transient myocardial ischemia</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Heart Failure: inadequate pumping efficiency vs cardiac arrest / heart attack</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 14</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(16)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 16 (Excretory Products and their Elimination) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[16] = "<section class=\"chapter-section\" id=\"c11b-ch16\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">16</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 16</div>\n      <h2>Excretory Products and their Elimination</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M12 2v20M2 12h20\"/><circle cx=\"12\" cy=\"12\" r=\"7\"/></svg>\n      Nephron Architecture &amp; The Medullary Counter-Current Multiplier\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Counter-Current Mechanism Graphic on Left -->\n      <g transform=\"translate(40, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">LOOP OF HENLE: COUNTER-CURRENT MULTIPLIER</text>\n        \n        <!-- Cortex boundary line -->\n        <line x1=\"20\" y1=\"50\" x2=\"340\" y2=\"50\" stroke=\"#94a3b8\" stroke-dasharray=\"3,2\"/>\n        <text x=\"330\" y=\"45\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"end\">Renal Cortex (300 mOsm/L)</text>\n        <text x=\"330\" y=\"180\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"end\">Inner Medulla (1200 mOsm/L)</text>\n\n        <!-- Hairpin Loop of Henle -->\n        <!-- Descending limb -->\n        <path d=\"M 80,50 L 80,165 Q 115,190 150,165 L 150,50\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n        \n        <!-- Arrows on limbs -->\n        <text x=\"65\" y=\"105\" font-size=\"12\" fill=\"#2563eb\">&darr;</text>\n        <text x=\"60\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\">Descending Limb</text>\n        <text x=\"40\" y=\"125\" font-size=\"7.5\" fill=\"#1e40af\">Permeable to H2O</text>\n        <text x=\"40\" y=\"137\" font-size=\"7.5\" fill=\"#1e40af\">Impermeable to NaCl</text>\n\n        <!-- Ascending limb -->\n        <text x=\"165\" y=\"105\" font-size=\"12\" fill=\"#dc2626\">&uarr;</text>\n        <text x=\"170\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\">Ascending Limb</text>\n        <text x=\"170\" y=\"125\" font-size=\"7.5\" fill=\"#991b1b\">Impermeable to H2O</text>\n        <text x=\"170\" y=\"137\" font-size=\"7.5\" fill=\"#991b1b\">Active transport of NaCl</text>\n\n        <!-- Medullary gradient labels -->\n        <text x=\"115\" y=\"70\" font-size=\"7.5\" fill=\"#334155\" text-anchor=\"middle\">300 mOsm/L</text>\n        <text x=\"115\" y=\"115\" font-size=\"7.5\" fill=\"#334155\" text-anchor=\"middle\">600 mOsm/L</text>\n        <text x=\"115\" y=\"155\" font-size=\"7.5\" fill=\"#334155\" text-anchor=\"middle\">900 mOsm/L</text>\n        <text x=\"115\" y=\"185\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\" text-anchor=\"middle\">1200 mOsm/L (Hairpin)</text>\n      </g>\n\n      <!-- JGA & RAAS Regulation on Right -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">HORMONAL OSMOREGULATION: RAAS &amp; ADH FEEDBACK</text>\n\n        <rect x=\"20\" y=\"38\" width=\"360\" height=\"42\" rx=\"4\" fill=\"#eff6ff\" stroke=\"#93c5fd\"/>\n        <text x=\"30\" y=\"55\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e40af\">1. Renin-Angiotensin-Aldosterone System (RAAS):</text>\n        <text x=\"30\" y=\"70\" font-size=\"7.5\" fill=\"#334155\">JG Cells secrete Renin &rarr; Angiotensinogen &rarr; Angiotensin II &rarr; Aldosterone (&uarr; Na+/H2O)</text>\n\n        <rect x=\"20\" y=\"88\" width=\"360\" height=\"42\" rx=\"4\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n        <text x=\"30\" y=\"105\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#166534\">2. Antidiuretic Hormone (ADH / Vasopressin):</text>\n        <text x=\"30\" y=\"120\" font-size=\"7.5\" fill=\"#334155\">Hypothalamus/Neurohypophysis &rarr; acts on DCT &amp; Collecting Duct (&uarr; Aquaporins)</text>\n\n        <rect x=\"20\" y=\"138\" width=\"360\" height=\"42\" rx=\"4\" fill=\"#fef2f2\" stroke=\"#fca5a5\"/>\n        <text x=\"30\" y=\"155\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#991b1b\">3. Atrial Natriuretic Factor (ANF &mdash; Antagonist):</text>\n        <text x=\"30\" y=\"170\" font-size=\"7.5\" fill=\"#334155\">Atrial walls secrete ANF in response to high BP &rarr; Vasodilation &amp; &darr; Renin</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 12: GFR, Counter-Current Multiplier, RAAS & JGA, Micturition & Uricotelism</div>\n\n  <!-- c11b-ch16-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define Glomerular Filtration Rate (GFR).\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Definition of Glomerular Filtration Rate (GFR):</strong><br>\n    The <strong>Glomerular Filtration Rate (GFR)</strong> is the total volume of protein-free filtrate formed in the Bowman's capsules of <strong>both kidneys combined per unit of time</strong> (typically expressed per minute).<br><br>\n    <strong>Standard Physiological Values:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>In a healthy adult human, the normal GFR is approximately <strong>125 mL/minute</strong>.</li>\n      <li>This equates to a staggering <strong>180 Litres per day</strong> ($125 \\text{ mL/min} \\times 60 \\times 24 = 180,000\\text{ mL/day}$).</li>\n    </ul>\n    <strong>Significance of Massive Tubular Reabsorption:</strong><br>\n    Although 180 Litres of filtrate are produced daily, the average volume of urine released is only about <strong>1.5 Litres per day</strong>. This demonstrates that approximately <strong>99% of the glomerular filtrate is reabsorbed</strong> by the renal tubules back into blood peritubular capillaries.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition: volume of filtrate formed by both kidneys per unit time</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Standard physiological values: 125 mL/min (~180 Litres/day) and 99% reabsorption note</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the autoregulatory mechanism of GFR. (Myogenic mechanism and Juxtaglomerular Apparatus - JGA via Renin-Angiotensin-Aldosterone System / RAAS).\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Autoregulatory Feedback Mechanisms of GFR in Kidneys:</strong><br>\n    Human kidneys possess an efficient intrinsic autoregulatory mechanism that maintains a relatively constant GFR despite wide physiological fluctuations in systemic arterial blood pressure (between 80 and 180 mm Hg):<br><br>\n    <strong>1. Juxtaglomerular Apparatus (JGA) &amp; RAAS Feedback:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Structure of JGA:</strong> A specialized microscopic neuro-endocrine structure formed by the cellular modification of the <strong>distal convoluted tubule (macula densa)</strong> and the <strong>afferent arteriole (juxtaglomerular / JG cells)</strong> at their point of contact.</li>\n      <li><strong>Activation Cascade:</strong>\n        <ol style=\"margin:2px 0 4px 15px;\">\n          <li>A fall in glomerular blood flow / blood pressure / GFR stimulates the JG cells to synthesize and release the proteolytic enzyme <strong>Renin</strong> into circulation.</li>\n          <li>Renin cleaves circulating plasma <em>angiotensinogen</em> into <em>angiotensin I</em>.</li>\n          <li>Angiotensin Converting Enzyme (ACE) in lung capillaries converts it into <strong>Angiotensin II</strong>, a potent systemic vasoconstrictor that elevates glomerular hydrostatic pressure and GFR.</li>\n          <li>Angiotensin II also stimulates the adrenal cortex to secrete <strong>Aldosterone</strong>, which drives active $Na^+$ and water reabsorption in the DCT and collecting duct, expanding blood volume and normalizing GFR.</li>\n        </ol>\n      </li>\n    </ul>\n    <strong>2. Myogenic Autoregulatory Mechanism:</strong><br>\n    When renal arterial pressure rises, the smooth muscle of the afferent arteriole automatically stretches and reflexively constricts (myogenic contraction), increasing vascular resistance to prevent damage to delicate glomerular capillaries.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Concept of intrinsic autoregulation maintaining GFR between 80–180 mm Hg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structure of JGA: macula densa of DCT and JG cells of afferent arteriole</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Renin-Angiotensin-Aldosterone System (RAAS) cascade restoring GFR and blood pressure</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Myogenic vasoconstriction of afferent arteriole</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Indicate whether the following statements are true or false:<br>(a) Micturition is carried out by a reflex.<br>(b) ADH helps in water elimination, making urine hypotonic.<br>(c) Protein-free fluid is filtered from blood plasma into the Bowman's capsule.<br>(d) Henle's loop plays an important role in concentrating the urine.<br>(e) Glucose is actively reabsorbed in the proximal convoluted tubule.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Validation of Statements with Scientific Explanations:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(a) Micturition is carried out by a reflex. &mdash; TRUE</strong><br>\n      <em>Reason:</em> Stretching of the urinary bladder wall stimulates sensory stretch receptors, transmitting signals to the CNS to initiate the autonomic <strong>micturition reflex</strong>.</li>\n      <li><strong>(b) ADH helps in water elimination, making urine hypotonic. &mdash; FALSE</strong><br>\n      <em>Correction:</em> ADH (Antidiuretic Hormone) prevents diuresis; it facilitates <strong>water reabsorption</strong> from the DCT and collecting duct, making the excreted urine <strong>concentrated and hypertonic</strong>.</li>\n      <li><strong>(c) Protein-free fluid is filtered from blood plasma into the Bowman's capsule. &mdash; TRUE</strong><br>\n      <em>Reason:</em> Ultrafiltration across the three-layered glomerular membrane allows water, glucose, urea, and ions to pass, but completely blocks large plasma proteins and formed cellular elements.</li>\n      <li><strong>(d) Henle's loop plays an important role in concentrating the urine. &mdash; TRUE</strong><br>\n      <em>Reason:</em> The Loop of Henle functions as a counter-current multiplier, establishing an osmotic gradient from 300 to 1200 mOsm/L in the medullary interstitium to extract water.</li>\n      <li><strong>(e) Glucose is actively reabsorbed in the proximal convoluted tubule. &mdash; TRUE</strong><br>\n      <em>Reason:</em> 100% of filtered glucose is reabsorbed in the PCT via secondary active $Na^+$-glucose co-transporters (SGLT-2).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) True</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False (correct statement: ADH promotes water reabsorption, making urine hypertonic)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) True & (e) True</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give a brief account of the counter current mechanism.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>The Counter-Current Mechanism of Urine Concentration in Mammals:</strong><br>\n    Humans excrete urine that is nearly <strong>four times more concentrated (1200 mOsm/L)</strong> than initial glomerular filtrate (300 mOsm/L). This exceptional water-conserving capacity is generated by the counter-current mechanism operating between the <strong>Loop of Henle</strong> (multiplier) and the <strong>Vasa Recta</strong> (exchanger) in juxtamedullary nephrons:<br><br>\n    <strong>1. Meaning of Counter-Current Flow:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>In the two limbs of the Loop of Henle, tubular filtrate flows in opposite directions (downward in descending limb, upward in ascending limb).</li>\n      <li>Similarly, blood flows in opposite directions in the two parallel limbs of the capillary vasa recta.</li>\n    </ul>\n    <strong>2. Differential Permeability of the Loop of Henle (The Multiplier):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Descending Limb:</strong> Highly permeable to water ($H_2O$) via abundant aquaporin-1 channels, but virtually impermeable to electrolytes ($NaCl$). As filtrate descends, water is drawn into the hypertonic medullary interstitium by osmosis, concentrating the filtrate up to <strong>1200 mOsm/L</strong> at the hairpin tip.</li>\n      <li><strong>Ascending Limb:</strong> Completely impermeable to water, but permeable to electrolytes. Its thick segment actively pumps out $NaCl$ into the medullary interstitium, maintaining high medullary hyperosmolarity while diluting tubular filtrate.</li>\n    </ul>\n    <strong>3. Role of Vasa Recta (The Exchanger):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>$NaCl$ enters the descending limb of vasa recta and is returned to interstitium by ascending limb. Water absorbed from the descending loop of Henle is carried away by ascending vasa recta, preventing dilution of the medullary gradient.</li>\n    </ul>\n    <strong>4. Final Concentration in Collecting Duct:</strong><br>\n    As tubular fluid passes down the collecting duct through the hypertonic medullary gradient (300 &rarr; 600 &rarr; 900 &rarr; 1200 mOsm/L), water is continuously reabsorbed into blood under ADH regulation, producing hypertonic urine.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Opposite directional flows in Loop of Henle and Vasa Recta defining counter-current</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Descending limb (water permeable, NaCl impermeable) concentrating filtrate to 1200 mOsm/L</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ascending limb (water impermeable, active NaCl pumping) building medullary gradient</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vasa recta preserving medullary hypertonicity and final water extraction in collecting duct</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the role of liver, lungs and skin in excretion.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Excretory Roles of Accessory Organs Beyond Kidneys:</strong><br><br>\n    <strong>1. Lungs:</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Continuously eliminate massive amounts of gaseous metabolic wastes: approximately <strong>200 mL of carbon dioxide ($CO_2$) per minute</strong> (~18 Litres/day).</li>\n      <li>Also eliminate significant amounts of water vapor (~400 mL/day) in expired air.</li>\n    </ul>\n    <strong>2. Liver (The Primary Detoxifying &amp; Urea Factory):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Synthesizes <strong>Urea</strong> via the <strong>Ornithine (Urea) Cycle</strong> from highly toxic ammonia ($NH_3$) produced during protein deamination.</li>\n      <li>Excretes <strong>bile pigments (Bilirubin and Biliverdin)</strong> derived from the catabolic degradation of hemoglobin from worn-out erythrocytes.</li>\n      <li>Excretes cholesterol, degraded steroid hormones, vitamins, and inactivated drugs through bile into the digestive tract, ultimately expelled in feces.</li>\n    </ul>\n    <strong>3. Skin (Integumentary Excretion):</strong>\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li><strong>Sweat Glands:</strong> Secrete watery sweat primarily for thermoregulation, which carries metabolic wastes including $NaCl$, small amounts of urea, lactic acid, and amino acids.</li>\n      <li><strong>Sebaceous Glands:</strong> Secrete an oily lipid fluid called <strong>sebum</strong>, which eliminates sterols, fatty acids, hydrocarbons, and waxes, providing a protective antibacterial mantle.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Lungs: elimination of massive CO2 (200 mL/min) and water vapor</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Liver: urea synthesis (ornithine cycle), bile pigments (bilirubin/biliverdin), cholesterol, drugs</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Skin: sweat glands (NaCl, urea, lactic acid) and sebaceous glands (sterols, waxes in sebum)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain micturition.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Physiological Process of Micturition (Urination):</strong><br><br>\n    <strong>1. Definition:</strong><br>\n    <strong>Micturition</strong> is the physiological act of voluntarily releasing and emptying stored urine from the urinary bladder through the urethra to the outside of the body.<br><br>\n    <strong>2. The Micturition Neural Reflex Arc:</strong><br>\n    <ol style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Bladder Filling &amp; Stretch Activation:</strong> As urine accumulates in the bladder, its muscular walls stretch. When volume reaches roughly <strong>300 to 400 mL</strong>, mechanoreceptive <strong>stretch receptors</strong> in the bladder wall are stimulated.</li>\n      <li><strong>Transmission to CNS:</strong> Stretch receptors generate sensory afferent action potentials transmitted to the sacral spinal cord micturition center and cerebral cortex.</li>\n      <li><strong>Parasympathetic Motor Outflow:</strong> In response, autonomic motor nerve fibers fire efferent impulses causing:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li>Active, sustained contraction of the smooth <strong>detrusor muscle</strong> of the bladder wall.</li>\n          <li>Simultaneous relaxation of the involuntary <strong>internal urethral sphincter</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Voluntary Control:</strong> The <strong>external urethral sphincter</strong> consists of skeletal muscle innervated by the somatic pudendal nerve, controlled consciously by the cerebral cortex. When voluntary relaxation of the external sphincter is initiated, urine is forcefully expelled.</li>\n    </ol>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of micturition and bladder filling capacity (300–400 mL)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stretch receptor sensory afferent signaling to spinal cord and cortex</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Parasympathetic detrusor contraction with internal & external sphincter relaxation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the items of Column I with Column II:<br>(a) Ammonotelism &mdash;&mdash;&mdash;&mdash;&mdash; (i) Birds<br>(b) Bowman's capsule &mdash;&mdash;&mdash;&mdash; (ii) Water reabsorption<br>(c) Micturition &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (iii) Bony fish<br>(d) Uricotelism &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (iv) Renal tubule<br>(e) ADH &mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash;&mdash; (v) Urinary bladder\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Column Matching:</strong><br><br>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse:collapse; margin:8px 0; font-size:0.86rem;\">\n        <thead>\n          <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n            <th style=\"padding:8px 12px; color:#065f46;\">Column I</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Column II (Correct Match)</th>\n            <th style=\"padding:8px 12px; color:#065f46;\">Physiological Justification</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(a) Ammonotelism</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Bony fish</td>\n            <td style=\"padding:8px 12px;\">Excretes highly toxic ammonia directly across gills, requiring abundant water.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(b) Bowman's capsule</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Renal tubule</td>\n            <td style=\"padding:8px 12px;\">Double-walled epithelial cup enclosing the glomerulus, initiating the nephron tubule.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(c) Micturition</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(v) Urinary bladder</td>\n            <td style=\"padding:8px 12px;\">Process of emptying urine stored in the muscular urinary bladder.</td>\n          </tr>\n          <tr style=\"border-bottom:1px solid #e2e8f0;\">\n            <td style=\"padding:8px 12px; font-weight:700;\">(d) Uricotelism</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Birds</td>\n            <td style=\"padding:8px 12px;\">Excretes insoluble uric acid paste/pellets with minimum water loss for flight adaptation.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 12px; font-weight:700;\">(e) ADH</td>\n            <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Water reabsorption</td>\n            <td style=\"padding:8px 12px;\">Increases aquaporin permeability in DCT/collecting duct, driving water reabsorption.</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n    <br>\n    <strong>Final Option Matching Sequence:</strong><br>\n    <strong>(a) &rarr; (iii), &nbsp; (b) &rarr; (iv), &nbsp; (c) &rarr; (v), &nbsp; (d) &rarr; (i), &nbsp; (e) &rarr; (ii)</strong>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) to (iii) Bony fish</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) to (iv) Renal tubule</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) to (v) Urinary bladder</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) to (i) Birds & (e) to (ii) Water reabsorption</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is meant by the term osmoregulation?\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Scientific Definition of Osmoregulation:</strong><br>\n    <strong>Osmoregulation</strong> is the physiological homeostatic process by which an organism actively maintains and regulates the <strong>optimal water balance and osmotic concentration (osmolarity)</strong> of its internal body fluids (blood, lymph, and intercellular tissue fluid) within narrow physiological limits, irrespective of fluctuations in external environmental salinity or humidity.<br><br>\n    <strong>Core Objectives of Osmoregulation:</strong><br>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Prevents excessive intracellular swelling (cytolysis) in hypotonic environments.</li>\n      <li>Prevents cellular dehydration, shrinkage, and crenation in hypertonic environments.</li>\n      <li>Maintains strict electrolyte concentrations ($Na^+, K^+, Cl^-, Ca^{2+}, HCO_3^-$) to preserve the membrane resting potential of excitable neurons and muscle cells.</li>\n    </ul>\n    <em>Primary Organs: Human kidneys, contractile vacuoles in freshwater amoeba, antennal green glands in prawns, and salt glands in marine birds.</em>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition: regulation of water volume and osmotic solute concentration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cellular importance (preventing lysis/crenation, preserving electrical potentials)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Terrestrial animals are generally either ureotelic or uricotelic, not ammonotelic, why?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Why Terrestrial Animals Avoid Ammonotelism and Evolve Ureotelism / Uricotelism:</strong><br><br>\n    <strong>1. High Toxicity and Water Requirement of Ammonia:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Ammonia ($NH_3$) is the direct, primary metabolic product of amino acid deamination. However, it is <strong>extremely toxic</strong> to protoplasm because it readily crosses cell membranes, raises intracellular pH, and disrupts mitochondrial ATP synthesis.</li>\n      <li>To eliminate ammonia safely without poisoning tissues, it must be excreted in a highly dilute solution. The excretion of <strong>1 gram of ammonia requires approximately 300 to 500 mL of water</strong>.</li>\n      <li>Only aquatic animals (aquatic amphibians, bony fishes, aquatic invertebrates) that have an unlimited supply of surrounding water can afford this massive water expenditure (<strong>ammonotelism</strong>).</li>\n    </ul>\n    <strong>2. Evolutionary Imperative of Water Conservation on Land:</strong>\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li>Terrestrial animals face the chronic challenge of continuous water loss (transpiration, evaporation, feces) and limited freshwater availability.</li>\n      <li>Losing 500 mL of water per gram of nitrogen would lead to fatal dehydration in land animals.</li>\n      <li>Consequently, terrestrial animals utilize metabolic energy (ATP) to convert ammonia into far less toxic nitrogenous wastes:\n        <ul style=\"margin:2px 0 4px 15px;\">\n          <li><strong>Ureotelism (Mammals, adult amphibians):</strong> Ammonia is converted in the liver via the Ornithine cycle into <strong>Urea</strong>, which is 100,000 times less toxic than ammonia and requires only <strong>~50 mL of water per gram</strong>.</li>\n          <li><strong>Uricotelism (Reptiles, birds, land snails, insects):</strong> Ammonia is converted into <strong>Uric Acid</strong>, which is practically non-toxic, highly insoluble in water, and excreted as a thick semisolid paste with minimal water loss (<strong>~5 to 10 mL of water per gram</strong>), an adaptation crucial for flight weight reduction and cleidoic egg development.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">High toxicity of ammonia requiring 300–500 mL water per gram for excretion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Terrestrial water scarcity making ammonotelism lethal due to rapid dehydration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion into less toxic Urea (Ureotelism) or insoluble Uric acid paste (Uricotelism)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What is the significance of juxtaglomerular apparatus (JGA) in kidney function?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Crucial Physiological Significance of the Juxtaglomerular Apparatus (JGA):</strong><br><br>\n    <strong>1. Real-Time Sensing of Renal Perfusion and Osmolarity:</strong><br>\n    The JGA acts as an intelligent microscopic auto-feedback control center that constantly monitors:\n    <ul style=\"margin:2px 0 4px 20px;\">\n      <li>Glomerular blood pressure and renal blood flow (via baroreceptive <strong>JG cells</strong> in the afferent arteriole).</li>\n      <li>Sodium chloride concentration ($[Na^+]$ and $[Cl^-]$) in the late tubular fluid (via chemoreceptive <strong>macula densa</strong> cells of the DCT).</li>\n    </ul>\n    <strong>2. The Renin-Angiotensin-Aldosterone System (RAAS) Cascade:</strong><br>\n    When blood pressure, renal blood flow, or GFR drops:\n    $$\\text{JG Cells} \\xrightarrow{\\text{secrete}} \\mathbf{Renin} \\xrightarrow{+ \\text{Angiotensinogen}} \\text{Angiotensin I} \\xrightarrow{+ \\text{ACE}} \\mathbf{Angiotensin II}$$\n    <ul style=\"margin:4px 0 6px 20px;\">\n      <li><strong>Potent Vasoconstriction:</strong> Angiotensin II constricts systemic arterioles and efferent glomerular arterioles, raising glomerular capillary hydrostatic pressure and immediately restoring normal GFR.</li>\n      <li><strong>Aldosterone Secretion:</strong> Stimulates adrenal cortex to release aldosterone, which increases active $Na^+$ and water reabsorption in the DCT and collecting duct.</li>\n      <li><strong>Thirst Stimulation &amp; ADH:</strong> Stimulates hypothalamus to induce drinking behavior and release ADH.</li>\n    </ul>\n    <strong>Conclusion:</strong> JGA prevents catastrophic renal failure during hypovolemia, hemorrhage, or severe dehydration.\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Sensory role of JGA (JG cells detecting pressure and macula densa detecting NaCl in DCT)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Secretion of Renin initiating the Angiotensin II & Aldosterone hormonal cascade</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Restoration of glomerular hydrostatic pressure, blood volume, and normal GFR</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the following:<br>(a) A chordate animal having flame cells as excretory structures.<br>(b) Cortical portions projecting between the medullary pyramids in the human kidney.<br>(c) A loop of capillary running parallel to the Henle's loop.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Precise Anatomical Terms:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li><strong>(a) A chordate animal having flame cells (protonephridia) as excretory structures:</strong><br>\n      <strong><em>Amphioxus</em> (<em>Branchiostoma</em>)</strong> &mdash; Cephalochordata. <em>(Note: While flame cells / solenocytes are typical of Platyhelminthes, Amphioxus is the unique chordate exhibiting them).</em></li>\n      <li><strong>(b) Cortical portions projecting between the medullary pyramids in the human kidney:</strong><br>\n      <strong>Columns of Bertini</strong> (or <strong>Renal Columns</strong>).</li>\n      <li><strong>(c) A loop of capillary running parallel to the Henle's loop:</strong><br>\n      <strong>Vasa Recta</strong> (hairpin-shaped peritubular capillaries arising from efferent arterioles of juxtamedullary nephrons).</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Amphioxus (Branchiostoma)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Columns of Bertini (Renal columns)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Vasa Recta</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch16-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch16-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch16-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fill in the gaps:<br>(a) Ascending limb of Henle's loop is _______ to water whereas the descending limb is _______ to it.<br>(b) Reabsorption of water from distal parts of the tubules is facilitated by hormone _______.<br>(c) Dialysis fluid contains all the constituents as in plasma except _______.<br>(d) A healthy adult human excretes (on an average) _______ gm of urea/day.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n    <strong>Accurate Textual Completions:</strong><br><br>\n    <ul style=\"margin:4px 0 8px 20px;\">\n      <li>(a) Ascending limb of Henle's loop is <strong>impermeable</strong> to water whereas the descending limb is <strong>permeable</strong> to it.</li>\n      <li>(b) Reabsorption of water from distal parts of the tubules is facilitated by hormone <strong>Antidiuretic Hormone (ADH) / Vasopressin</strong>.</li>\n      <li>(c) Dialysis fluid contains all the constituents as in plasma except <strong>nitrogenous wastes (such as urea, uric acid, creatinine)</strong>.</li>\n      <li>(d) A healthy adult human excretes (on an average) <strong>25 to 30</strong> gm of urea/day.</li>\n    </ul>\n  </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(a) impermeable ; permeable</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Antidiuretic Hormone (ADH) / Vasopressin</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) nitrogenous wastes (urea)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) 25 to 30 gm of urea/day</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(15)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 15</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(17)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 17 (Locomotion and Movement) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[17] = "<section class=\"chapter-section\" id=\"c11b-ch17\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">17</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 17</div>\n      <h2>Locomotion and Movement</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official Step-by-Step Marking Rubrics &amp; Structural Diagrams</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><path d=\"M18 10h-1.26A8 8 0 1 0 9 20h9a5 5 0 0 0 0-10z\"/></svg>\n      Figure 17.1: Microscopic Sarcomere Architecture &amp; Sliding Filament Cross-Bridge Cycle\n    </div>\n    <svg viewBox=\"0 0 850 250\" width=\"100%\" height=\"auto\" style=\"max-height:250px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"230\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Left: Relaxed vs Contracted Sarcomere -->\n      <g transform=\"translate(30, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">SARCOMERE ANATOMY (Z-LINE TO Z-LINE)</text>\n        \n        <!-- Left Z-line -->\n        <path d=\"M 40,45 L 35,70 L 45,95 L 35,120 L 45,145 L 40,170\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n        <text x=\"40\" y=\"185\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Z-Line</text>\n\n        <!-- Right Z-line -->\n        <path d=\"M 320,45 L 315,70 L 325,95 L 315,120 L 325,145 L 320,170\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2.5\"/>\n        <text x=\"320\" y=\"185\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Z-Line</text>\n\n        <!-- Thin Actin filaments (Blue) -->\n        <line x1=\"40\" y1=\"70\" x2=\"155\" y2=\"70\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"40\" y1=\"95\" x2=\"155\" y2=\"95\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"40\" y1=\"120\" x2=\"155\" y2=\"120\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"40\" y1=\"145\" x2=\"155\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n\n        <line x1=\"205\" y1=\"70\" x2=\"320\" y2=\"70\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"205\" y1=\"95\" x2=\"320\" y2=\"95\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"205\" y1=\"120\" x2=\"320\" y2=\"120\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n        <line x1=\"205\" y1=\"145\" x2=\"320\" y2=\"145\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n\n        <!-- Thick Myosin filaments (Orange/Red) in middle -->\n        <line x1=\"100\" y1=\"82\" x2=\"260\" y2=\"82\" stroke=\"#ea580c\" stroke-width=\"6\"/>\n        <line x1=\"100\" y1=\"107\" x2=\"260\" y2=\"107\" stroke=\"#ea580c\" stroke-width=\"6\"/>\n        <line x1=\"100\" y1=\"132\" x2=\"260\" y2=\"132\" stroke=\"#ea580c\" stroke-width=\"6\"/>\n\n        <!-- M-line center -->\n        <line x1=\"180\" y1=\"58\" x2=\"180\" y2=\"155\" stroke=\"#64748b\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\"/>\n        <text x=\"180\" y=\"168\" font-size=\"8\" fill=\"#64748b\" text-anchor=\"middle\">M-Line</text>\n\n        <!-- Band annotations -->\n        <text x=\"180\" y=\"40\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#ea580c\" text-anchor=\"middle\">&larr; A-Band (Anisotropic &bull; Constant) &rarr;</text>\n        <rect x=\"155\" y=\"65\" width=\"50\" height=\"20\" rx=\"3\" fill=\"#fef3c7\" stroke=\"#f59e0b\" stroke-width=\"1\"/>\n        <text x=\"180\" y=\"78\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#b45309\" text-anchor=\"middle\">H-Zone</text>\n        <text x=\"70\" y=\"200\" font-size=\"8\" fill=\"#2563eb\" text-anchor=\"middle\">I-Band (Actin only)</text>\n        <text x=\"290\" y=\"200\" font-size=\"8\" fill=\"#2563eb\" text-anchor=\"middle\">I-Band (Actin only)</text>\n      </g>\n\n      <!-- Right: Sliding Filament Cross-Bridge Cycle -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"205\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"22\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">CROSS-BRIDGE MOLECULAR MECHANISM</text>\n\n        <rect x=\"15\" y=\"35\" width=\"370\" height=\"36\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"49\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">1. Ca2+ Release &amp; Tropomyosin Displacement:</text>\n        <text x=\"25\" y=\"62\" font-size=\"7.5\" fill=\"#334155\">Ca2+ binds Troponin C &rarr; unmasks myosin-binding sites on actin filament.</text>\n\n        <rect x=\"15\" y=\"76\" width=\"370\" height=\"36\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"90\" font-size=\"8\" font-weight=\"bold\" fill=\"#2563eb\">2. Cross-Bridge Formation:</text>\n        <text x=\"25\" y=\"103\" font-size=\"7.5\" fill=\"#334155\">Myosin head hydrolyzes ATP (ADP + Pi) and binds actin active site.</text>\n\n        <rect x=\"15\" y=\"117\" width=\"370\" height=\"36\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"131\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\">3. Power Stroke (Sliding):</text>\n        <text x=\"25\" y=\"144\" font-size=\"7.5\" fill=\"#334155\">Myosin head tilts 45&deg;, sliding actin toward M-line (I-band &amp; H-zone shorten).</text>\n\n        <rect x=\"15\" y=\"158\" width=\"370\" height=\"36\" rx=\"4\" fill=\"#ffffff\" stroke=\"#cbd5e1\"/>\n        <text x=\"25\" y=\"172\" font-size=\"8\" font-weight=\"bold\" fill=\"#7c3aed\">4. Cross-Bridge Detachment &amp; Resetting:</text>\n        <text x=\"25\" y=\"185\" font-size=\"7.5\" fill=\"#334155\">Fresh ATP binds myosin head; cross-bridge breaks, resetting the cycle.</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 10: Sarcomere Anatomy, Sliding Filament Theory, Muscle Contraction, Joints &amp; Skeletal System</div>\n\n  <!-- c11b-ch17-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw the diagram of a sarcomere of skeletal muscle showing different regions.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Microscopic Diagrammatic Representation of a Sarcomere:</strong><br>\n            A <strong>sarcomere</strong> is the basic structural and functional contractile unit of a myofibril in skeletal muscle, extending from one <strong>Z-line</strong> to the adjacent <strong>Z-line</strong> (~2.5 &mu;m in relaxed state).<br><br>\n\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:16px; margin:14px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:10px;\">\n                Diagram: Structure of a Sarcomere (Relaxed Muscle Fiber)\n              </div>\n              <svg viewBox=\"0 0 760 210\" width=\"100%\" height=\"auto\" style=\"max-height:210px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"10\" y=\"10\" width=\"740\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n\n                <!-- Z-lines -->\n                <path d=\"M 60,35 L 50,65 L 70,95 L 50,125 L 70,155 L 60,185\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/>\n                <text x=\"60\" y=\"200\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Z-Line</text>\n\n                <path d=\"M 700,35 L 690,65 L 710,95 L 690,125 L 710,155 L 700,185\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"3\"/>\n                <text x=\"700\" y=\"200\" font-size=\"10\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Z-Line</text>\n\n                <!-- Thin Actin Filaments (Blue) -->\n                <line x1=\"60\" y1=\"65\" x2=\"320\" y2=\"65\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"60\" y1=\"95\" x2=\"320\" y2=\"95\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"60\" y1=\"125\" x2=\"320\" y2=\"125\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"60\" y1=\"155\" x2=\"320\" y2=\"155\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n\n                <line x1=\"440\" y1=\"65\" x2=\"700\" y2=\"65\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"440\" y1=\"95\" x2=\"700\" y2=\"95\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"440\" y1=\"125\" x2=\"700\" y2=\"125\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <line x1=\"440\" y1=\"155\" x2=\"700\" y2=\"155\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n\n                <!-- Thick Myosin Filaments (Orange) -->\n                <line x1=\"220\" y1=\"80\" x2=\"540\" y2=\"80\" stroke=\"#ea580c\" stroke-width=\"8\"/>\n                <line x1=\"220\" y1=\"110\" x2=\"540\" y2=\"110\" stroke=\"#ea580c\" stroke-width=\"8\"/>\n                <line x1=\"220\" y1=\"140\" x2=\"540\" y2=\"140\" stroke=\"#ea580c\" stroke-width=\"8\"/>\n\n                <!-- M-Line in center -->\n                <line x1=\"380\" y1=\"50\" x2=\"380\" y2=\"170\" stroke=\"#475569\" stroke-width=\"2\" stroke-dasharray=\"3,3\"/>\n                <text x=\"380\" y=\"180\" font-size=\"9\" font-weight=\"bold\" fill=\"#475569\" text-anchor=\"middle\">M-Line</text>\n\n                <!-- Zone brackets & labels -->\n                <!-- Sarcomere indicator -->\n                <line x1=\"60\" y1=\"25\" x2=\"700\" y2=\"25\" stroke=\"#15803d\" stroke-width=\"1.5\"/>\n                <text x=\"380\" y=\"20\" font-size=\"10\" font-weight=\"bold\" fill=\"#15803d\" text-anchor=\"middle\">&larr; ONE SARCOMERE (~2.5 &mu;m) &rarr;</text>\n\n                <!-- A-band -->\n                <line x1=\"220\" y1=\"38\" x2=\"540\" y2=\"38\" stroke=\"#ea580c\" stroke-width=\"1.5\"/>\n                <text x=\"380\" y=\"34\" font-size=\"9\" font-weight=\"bold\" fill=\"#ea580c\" text-anchor=\"middle\">&larr; A-Band (Anisotropic &bull; Myosin length) &rarr;</text>\n\n                <!-- H-Zone -->\n                <rect x=\"320\" y=\"65\" width=\"120\" height=\"90\" fill=\"#fef3c7\" opacity=\"0.4\" stroke=\"#f59e0b\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/>\n                <text x=\"380\" y=\"100\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#b45309\" text-anchor=\"middle\">H-Zone (Only Myosin)</text>\n\n                <!-- I-Bands -->\n                <text x=\"140\" y=\"52\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#2563eb\" text-anchor=\"middle\">I-Band (Isotropic &bull; Actin only)</text>\n                <text x=\"620\" y=\"52\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#2563eb\" text-anchor=\"middle\">I-Band (Isotropic &bull; Actin only)</text>\n              </svg>\n            </div>\n\n            <strong>Detailed Anatomical Regions of the Sarcomere:</strong>\n            <ul style=\"margin:4px 0 6px 20px;\">\n              <li><strong>1. Z-Line (Krause's Membrane):</strong> A thin, dark, zigzag elastic protein disc (consisting of &alpha;-actinin) that bisects each I-band and firmly anchors the thin actin filaments. The repeating unit between two successive Z-lines constitutes a sarcomere.</li>\n              <li><strong>2. I-Band (Isotropic Band):</strong> The light band containing only thin actin filaments (does not contain thick filaments). It is isotropic under polarized light.</li>\n              <li><strong>3. A-Band (Anisotropic Band):</strong> The dark central band containing the entire length of the thick myosin filaments, partially overlapped at its lateral edges by thin actin filaments. Its length remains strictly constant during contraction.</li>\n              <li><strong>4. H-Zone (Hensen's Zone):</strong> The paler central region of the A-band that is not overlapped by thin actin filaments in the relaxed state. Contains thick filaments only.</li>\n              <li><strong>5. M-Line (Mittelscheibe):</strong> A delicate proteinaceous membrane running centrally down the H-zone that holds adjacent thick myosin filaments together.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat, accurate labelled diagram of sarcomere showing Z-line, I-band, A-band, H-zone, and M-line</span><span class=\"marking-marks\">2.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Z-line and I-band (actin only)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of A-band (myosin), H-zone (un-overlapped zone), and central M-line</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define the sliding filament theory of muscle contraction.\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Definition of Sliding Filament Theory (H.E. Huxley and A.F. Huxley, 1954):</strong><br>\n            The <strong>sliding filament theory</strong> states that the contraction of a muscle fibre occurs by the <strong>sliding of thin (actin) filaments over thick (myosin) filaments</strong> towards the center of the sarcomere (M-line), without any physical shortening or change in length of either the actin or myosin filaments themselves.<br><br>\n            <strong>Key Morphological Consequences During Contraction:</strong>\n            <ul style=\"margin:4px 0 6px 20px;\">\n              <li>The two successive <strong>Z-lines are pulled closer together</strong>, leading to the overall shortening (contraction) of the sarcomere.</li>\n              <li>The <strong>I-bands (light bands) shorten</strong> in length as actin filaments overlap more deeply with myosin.</li>\n              <li>The <strong>H-zone narrows progressively and disappears</strong> completely during maximal contraction.</li>\n              <li>The <strong>A-bands (dark bands) retain their original, constant length</strong> throughout contraction and relaxation, because the length of thick myosin filaments does not change.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Precise definition: sliding of thin actin filaments over thick myosin filaments toward sarcomere center</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural changes: Z-lines pulled inward, I-bands shorten, H-zone disappears, A-band remains constant</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Describe the important steps in muscle contraction.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Sequential Physiological Steps in Skeletal Muscle Contraction:</strong><br><br>\n            <ol style=\"margin:4px 0 8px 20px;\">\n              <li><strong>Neural Signal &amp; Action Potential:</strong><br>\n              A motor impulse from the Central Nervous System (CNS) travels along a somatic motor neuron to reach the <strong>neuromuscular junction (motor end-plate)</strong>. The axon terminal releases the neurotransmitter <strong>acetylcholine (ACh)</strong> into the synaptic cleft, generating an action potential in the sarcolemma (muscle cell membrane).</li>\n              \n              <li><strong>T-Tubule Transmission &amp; Calcium Release:</strong><br>\n              The action potential propagates rapidly over the sarcolemma and travels deep inside through transverse <strong>T-tubules</strong>. This depolarisation triggers the release of large quantities of stored <strong>calcium ions ($Ca^{2+}$)</strong> from the terminal cisternae of the <strong>sarcoplasmic reticulum</strong> into the sarcoplasm.</li>\n\n              <li><strong>Unmasking Active Sites on Actin:</strong><br>\n              In relaxed muscle, the protein <strong>tropomyosin</strong> physically covers and masks the myosin-binding sites on actin. The released $Ca^{2+}$ binds specifically to the <strong>Troponin C</strong> subunit, inducing a conformational change that pulls tropomyosin aside, completely unmasking the active catalytic binding sites on F-actin.</li>\n\n              <li><strong>Cross-Bridge Formation &amp; Power Stroke:</strong><br>\n              The globular head of myosin acts as an active ATPase enzyme. It hydrolyzes ATP:\n              $$ATP \\xrightarrow{\\text{Myosin ATPase}} ADP + P_i + \\text{Energy}$$\n              The energized myosin head binds to the exposed active site on actin to form a <strong>cross-bridge</strong>.<br>\n              Myosin releases $ADP$ and $P_i$ and tilts its head $45^\\circ$ toward the M-line (the <strong>power stroke</strong>), pulling the attached actin filaments inward toward the center of the sarcomere.</li>\n\n              <li><strong>Cross-Bridge Detachment &amp; Reactivation:</strong><br>\n              A fresh molecule of ATP binds to the myosin head, breaking the cross-bridge. Hydrolysis of this new ATP recocks the myosin head into its energized state, ready for another cycle of binding and pulling as long as $Ca^{2+}$ remains available.</li>\n\n              <li><strong>Relaxation:</strong><br>\n              When motor nerve firing ceases, active calcium pumps ($Ca^{2+}$-ATPase) pump $Ca^{2+}$ ions back into the sarcoplasmic reticulum. With sarcoplasmic $[Ca^{2+}]$ dropping below $10^{-7}\\text{ M}$, troponin returns to its resting state, tropomyosin re-masks the active sites on actin, and the thin filaments slide back to their relaxed position.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1. Motor neuron impulse, ACh release, and sarcolemmal action potential</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. T-tubule depolarization and Ca2+ release from sarcoplasmic reticulum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Ca2+ binding to Troponin C and unmasking of active sites on actin</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">4. ATP hydrolysis, cross-bridge formation, power stroke, and inward sliding of actin</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">5. Cross-bridge detachment by fresh ATP and active Ca2+ reuptake leading to relaxation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write true or false. If false, change the statement so that it is true:<br>\n        (a) Actin is present in the thin filament.<br>\n        (b) H-zone of striated muscle fibre represents both thick and thin filaments.<br>\n        (c) The human skeleton has 206 bones.<br>\n        (d) There are 11 pairs of ribs in man.<br>\n        (e) The sternum is present on the ventral side of the body.\n      </div>\n      <div class=\"q-marks\">[2.5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Evaluation and Scientific Corrections of Statements:</strong><br><br>\n            <ul style=\"margin:4px 0 8px 20px;\">\n              <li><strong>(a) Actin is present in the thin filament. &mdash; TRUE</strong><br>\n              <em>Scientific Basis:</em> Thin myofilaments consist of two helically wound filamentous F-actin polymers, accompanied by tropomyosin and troponin regulatory proteins.</li>\n\n              <li><strong>(b) H-zone of striated muscle fibre represents both thick and thin filaments. &mdash; FALSE</strong><br>\n              <strong>Corrected Statement:</strong> The H-zone of a striated muscle fibre represents <strong>only thick (myosin) filaments</strong> (it is the central region of the A-band not overlapped by thin actin filaments in the relaxed state).</li>\n\n              <li><strong>(c) The human skeleton has 206 bones. &mdash; TRUE</strong><br>\n              <em>Scientific Basis:</em> The adult human skeleton is composed of exactly 206 bones (80 in the axial skeleton and 126 in the appendicular skeleton).</li>\n\n              <li><strong>(d) There are 11 pairs of ribs in man. &mdash; FALSE</strong><br>\n              <strong>Corrected Statement:</strong> There are <strong>12 pairs (24 total) of ribs</strong> in humans (pairs 1–7 are true vertebrosternal ribs, pairs 8–10 are false vertebrochondral ribs, and pairs 11–12 are floating vertebral ribs).</li>\n\n              <li><strong>(e) The sternum is present on the ventral side of the body. &mdash; TRUE</strong><br>\n              <em>Scientific Basis:</em> The sternum (breastbone) is a flat bone situated along the mid-ventral axis of the thoracic cage.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) True</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) False &amp; corrected: H-zone contains only thick myosin filaments without actin overlap</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) True</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) False &amp; corrected: 12 pairs of ribs in humans</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) True</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write the difference between:<br>\n        (a) Actin and Myosin<br>\n        (b) Red and White muscles<br>\n        (c) Pectoral and Pelvic girdle\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Differences Between Actin and Myosin Filaments:</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0 10px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Actin (Thin Filament)</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Myosin (Thick Filament)</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Diameter &amp; Structure</td>\n                    <td style=\"padding:6px 10px;\">Thin (~7 nm); polymer of two helically wound F-actins.</td>\n                    <td style=\"padding:6px 10px;\">Thick (~15 nm); polymer of ~300 meromyosin molecules.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Associated Proteins</td>\n                    <td style=\"padding:6px 10px;\">Contains regulatory proteins <strong>tropomyosin</strong> and <strong>troponin</strong>.</td>\n                    <td style=\"padding:6px 10px;\">Composed of heavy meromyosin (HMM) and light meromyosin (LMM).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Location in Sarcomere</td>\n                    <td style=\"padding:6px 10px;\">Found in the light isotropic <strong>I-band</strong>; anchored to the Z-line.</td>\n                    <td style=\"padding:6px 10px;\">Forms the dark anisotropic <strong>A-band</strong>; held centrally by the M-line.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Enzymatic Activity</td>\n                    <td style=\"padding:6px 10px;\">Lacks intrinsic ATPase activity.</td>\n                    <td style=\"padding:6px 10px;\">Globular head possesses active <strong>ATPase site</strong> and actin-binding site.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n\n            <strong>(b) Differences Between Red and White Muscle Fibres:</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0 10px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Red Muscle Fibres (Type I / Aerobic)</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">White Muscle Fibres (Type II / Anaerobic)</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Myoglobin Content</td>\n                    <td style=\"padding:6px 10px; color:#b91c1c; font-weight:700;\">High concentration (gives deep red appearance).</td>\n                    <td style=\"padding:6px 10px;\">Very low / scarce (gives pale, whitish appearance).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Mitochondria &amp; Respiration</td>\n                    <td style=\"padding:6px 10px;\">Abundant mitochondria; relies on <strong>aerobic respiration</strong>.</td>\n                    <td style=\"padding:6px 10px;\">Fewer mitochondria; relies on <strong>anaerobic glycolysis</strong>.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Contraction &amp; Fatigue</td>\n                    <td style=\"padding:6px 10px;\">Slow, sustained contraction; <strong>highly resistant to fatigue</strong> (e.g., extensor back muscles).</td>\n                    <td style=\"padding:6px 10px;\">Fast, powerful twitch; <strong>fatigues rapidly</strong> due to lactic acid build-up (e.g., eyeball muscles).</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Sarcoplasmic Reticulum</td>\n                    <td style=\"padding:6px 10px;\">Moderate development.</td>\n                    <td style=\"padding:6px 10px;\">Extensively developed for explosive, fast $Ca^{2+}$ release.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n\n            <strong>(c) Differences Between Pectoral and Pelvic Girdle:</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Pectoral Girdle (Shoulder)</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Pelvic Girdle (Hip)</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Location &amp; Limb Supported</td>\n                    <td style=\"padding:6px 10px;\">Located in shoulder region; articulates the upper forelimbs.</td>\n                    <td style=\"padding:6px 10px;\">Located in hip/pelvic region; articulates the lower hindlimbs.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Bone Composition</td>\n                    <td style=\"padding:6px 10px;\">Composed of 2 halves; each has 2 bones: <strong>clavicle (collar bone)</strong> and <strong>scapula</strong>.</td>\n                    <td style=\"padding:6px 10px;\">Composed of 2 coxal bones; each formed by the fusion of 3 bones: <strong>ilium, ischium, and pubis</strong>.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Articulating Cavity</td>\n                    <td style=\"padding:6px 10px;\">Features a shallow <strong>glenoid cavity</strong> for the head of the humerus (high mobility).</td>\n                    <td style=\"padding:6px 10px;\">Features a deep cup-shaped <strong>acetabulum</strong> for the head of the femur (weight-bearing &amp; stability).</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Actin (thin, I-band, troponin/tropomyosin) vs Myosin (thick, A-band, HMM/LMM, ATPase)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Red muscle (high myoglobin, aerobic, fatigue-resistant) vs White muscle (anaerobic, rapid fatigue)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Pectoral girdle (clavicle, scapula, glenoid cavity) vs Pelvic girdle (ilium, ischium, pubis, acetabulum)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match Column I with Column II:<br>\n        <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.85rem;\">\n          <tr style=\"font-weight:700; color:#15803d;\"><td style=\"width:50%;\">Column I</td><td>Column II</td></tr>\n          <tr><td>(a) Smooth muscle</td><td>(i) Myoglobin</td></tr>\n          <tr><td>(b) Tropomyosin</td><td>(ii) Thin filament</td></tr>\n          <tr><td>(c) Red muscle</td><td>(iii) Sutures</td></tr>\n          <tr><td>(d) Skull</td><td>(iv) Involuntary</td></tr>\n        </table>\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Accurate Column Matching and Anatomical Rationales:</strong><br><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.86rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n                    <th style=\"padding:8px 12px; color:#065f46;\">Column I</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Column II (Correct Match)</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Scientific Rationale</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(a) Smooth muscle</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Involuntary</td>\n                    <td style=\"padding:8px 12px;\">Smooth muscle fibres in visceral organs (gut, blood vessels) are non-striated and function involuntarily via the autonomic nervous system.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(b) Tropomyosin</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Thin filament</td>\n                    <td style=\"padding:8px 12px;\">Tropomyosin is a filamentous protein running along the grooves of the F-actin helix in the thin myofilament.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(c) Red muscle</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Myoglobin</td>\n                    <td style=\"padding:8px 12px;\">Red muscle fibres contain abundant amounts of oxygen-storing red pigment myoglobin.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:8px 12px; font-weight:700;\">(d) Skull</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Sutures</td>\n                    <td style=\"padding:8px 12px;\">Cranial bones of the skull are immovably fused together by dense fibrous connective tissue joints called sutures.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n            <br>\n            <strong>Summary of Correct Pairs:</strong><br>\n            <strong>(a) &rarr; (iv), &nbsp; (b) &rarr; (ii), &nbsp; (c) &rarr; (i), &nbsp; (d) &rarr; (iii)</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) to (iv) Involuntary</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) to (ii) Thin filament</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) to (i) Myoglobin</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) to (iii) Sutures</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the different types of movements exhibited by the cells of the human body?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>The Three Major Types of Movements Exhibited by Human Cells:</strong><br><br>\n            <strong>1. Amoeboid Movement:</strong>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><em>Mechanism:</em> Effected by streaming of cytoplasm (protoplasm) and the formation of blunt pseudopodial projections, driven by actin microfilaments of the cytoskeleton.</li>\n              <li><em>Examples in Humans:</em> <strong>Macrophage leukocytes</strong> and <strong>neutrophil leukocytes</strong> crawling through capillary endothelial walls via <strong>diapedesis</strong> to engulf cellular debris and invading pathogens in infected tissues.</li>\n            </ul>\n\n            <strong>2. Ciliary Movement:</strong>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><em>Mechanism:</em> Coordinated, rhythmic, wave-like beating of thousands of hair-like <strong>cilia</strong> ($9 + 2$ axoneme structure) lining luminal surfaces.</li>\n              <li><em>Examples in Humans:</em>\n                <ul style=\"margin:2px 0 4px 15px;\">\n                  <li>Inner ciliated epithelium of the <strong>respiratory tract (trachea and bronchi)</strong> sweeping inhaled dust particles and trapped mucus upward toward the throat.</li>\n                  <li>Inner ciliated lining of the <strong>Fallopian tubes (oviducts)</strong> propelling the ovum from the ovary toward the uterus.</li>\n                </ul>\n              </li>\n            </ul>\n\n            <strong>3. Muscular Movement:</strong>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><em>Mechanism:</em> Produced by the coordinated contraction and relaxation of specialized muscular tissues containing actin-myosin contractile machinery.</li>\n              <li><em>Examples in Humans:</em> Movement of the <strong>limbs (walking, running), jaws (mastication), tongue (speech and swallowing)</strong>, and peristalsis of the digestive canal.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1. Amoeboid movement: pseudopodia, actin microfilaments, macrophages/neutrophils (diapedesis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">2. Ciliary movement: coordinated cilia in respiratory tract &amp; Fallopian tubes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">3. Muscular movement: contractile actin-myosin in limbs, jaw, tongue, and locomotion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        How do you distinguish between a skeletal muscle and a cardiac muscle?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Comparative Analysis: Skeletal Muscle vs. Cardiac Muscle:</strong><br><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.85rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Skeletal Muscle</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Cardiac Muscle</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Location</td>\n                    <td style=\"padding:6px 10px;\">Attached to bones of skeleton (biceps, triceps, quadriceps).</td>\n                    <td style=\"padding:6px 10px; color:#b91c1c; font-weight:700;\">Confined exclusively to the myocardium (wall of the heart).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Voluntary / Involuntary</td>\n                    <td style=\"padding:6px 10px;\"><strong>Voluntary</strong> (under conscious control of the somatic nervous system).</td>\n                    <td style=\"padding:6px 10px; color:#16a34a; font-weight:700;\"><strong>Involuntary</strong> (governed automatically by cardiac pacemakers &amp; ANS).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Fibre Morphology</td>\n                    <td style=\"padding:6px 10px;\">Long, cylindrical, <strong>unbranched</strong> fibres.</td>\n                    <td style=\"padding:6px 10px;\">Short, cylindrical, <strong>branched</strong> and interconnected fibres.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Nuclear Condition</td>\n                    <td style=\"padding:6px 10px;\"><strong>Multinucleated (syncytial)</strong>; nuclei located peripherally.</td>\n                    <td style=\"padding:6px 10px;\"><strong>Uninucleated</strong> (or binucleated); nucleus centrally located.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Intercalated Discs</td>\n                    <td style=\"padding:6px 10px;\"><strong>Absent</strong>.</td>\n                    <td style=\"padding:6px 10px; color:#16a34a; font-weight:700;\"><strong>Present</strong> (specialized gap junctions ensuring wave synchronization as a functional syncytium).</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Fatigue Resistance</td>\n                    <td style=\"padding:6px 10px;\">Fatigues relatively quickly with prolonged vigorous exertion.</td>\n                    <td style=\"padding:6px 10px;\"><strong>Never fatigues</strong>; contracts rhythmically throughout lifetime without rest.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Location and voluntary control vs involuntary cardiac regulation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Morphology (unbranched syncytial vs branched uninucleated)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of intercalated discs and fatigue resistance in cardiac muscle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Name the type of joint between the following:<br>\n        (a) Atlas / axis<br>\n        (b) Carpal / metacarpal of thumb<br>\n        (c) Between phalanges<br>\n        (d) Femur / acetabulum<br>\n        (e) Between cranial bones<br>\n        (f) Between pubic bones in the pelvic girdle.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Precise Anatomical Identification of Joint Types:</strong><br><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.86rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n                    <th style=\"padding:8px 12px; color:#065f46;\">Articulating Bones</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Specific Joint Classification</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Movement Permitted</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(a) Atlas and Axis (C1 &amp; C2)</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Pivot Joint (Synovial)</td>\n                    <td style=\"padding:8px 12px;\">Uniaxial rotation around dens odontoid process (\"no\" movement of head).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(b) Carpal and Metacarpal of Thumb</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Saddle Joint (Synovial)</td>\n                    <td style=\"padding:8px 12px;\">Biaxial movement permitting opposable thumb rotation and grasp.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(c) Between Phalanges</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Hinge Joint (Synovial)</td>\n                    <td style=\"padding:8px 12px;\">Uniaxial flexion and extension in a single angular plane.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(d) Femur and Acetabulum</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Ball and Socket Joint (Hip Joint)</td>\n                    <td style=\"padding:8px 12px;\">Multiaxial movement in all planes with high stability for locomotion.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(e) Between Cranial Bones</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Fibrous Joint (Sutures)</td>\n                    <td style=\"padding:8px 12px;\">Completely immovable synarthrosis protecting the delicate brain.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:8px 12px; font-weight:700;\">(f) Between Pubic Bones in Pelvic Girdle</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">Cartilaginous Joint (Pubic Symphysis)</td>\n                    <td style=\"padding:8px 12px;\">Slightly movable amphiarthrosis; relaxes via relaxin hormone during childbirth.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Pivot joint &amp; (b) Saddle joint</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Hinge joint &amp; (d) Ball and socket joint</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Fibrous joint (sutures) &amp; (f) Cartilaginous joint (pubic symphysis)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch17-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch17-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch17-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fill in the blank spaces:<br>\n        (a) All mammals (except a few) have _______ cervical vertebra.<br>\n        (b) The number of phalanges in each limb of human is _______.<br>\n        (c) Thin filament of myofibril contains 2 'F' actins and two other proteins namely _______ and _______.<br>\n        (d) In a muscle fibre $Ca^{++}$ is stored in _______.<br>\n        (e) _______ and _______ pairs of ribs are called floating ribs.<br>\n        (f) The human cranium is made up of _______ bones.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Accurate Textual Completions:</strong><br><br>\n            <ul style=\"margin:4px 0 8px 20px;\">\n              <li>(a) All mammals (except a few like sloths and manatees) have <strong>seven (7)</strong> cervical vertebrae.</li>\n              <li>(b) The number of phalanges in each limb of human is <strong>14 (fourteen)</strong> (phalangeal formula: $2, 3, 3, 3, 3$).</li>\n              <li>(c) Thin filament of myofibril contains 2 'F' actins and two other proteins namely <strong>tropomyosin</strong> and <strong>troponin</strong>.</li>\n              <li>(d) In a muscle fibre $Ca^{++}$ is stored in the <strong>sarcoplasmic reticulum</strong> (cisternae).</li>\n              <li>(e) <strong>11th</strong> and <strong>12th</strong> pairs of ribs are called floating ribs (their ventral ends are completely free and unattached).</li>\n              <li>(f) The human cranium is made up of <strong>eight (8)</strong> bones (1 frontal, 2 parietal, 2 temporal, 1 occipital, 1 sphenoid, 1 ethmoid).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) seven (7) cervical vertebrae &amp; (b) 14 phalanges</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) tropomyosin and troponin &amp; (d) sarcoplasmic reticulum</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) 11th and 12th floating ribs &amp; (f) eight (8) cranial bones</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(16)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 16 (Excretory Products)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(18)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 18 (Neural Control and Coordination) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[18] = "<section class=\"chapter-section\" id=\"c11b-ch18\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">18</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 18</div>\n      <h2>Neural Control and Coordination</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 12 Verbatim Questions with Official Step-by-Step Marking Rubrics &amp; Detailed Structural Diagrams</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>\n      Figure 18.1: Action Potential Conduction &amp; Chemical Synaptic Transmission\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Action Potential Curve on Left -->\n      <g transform=\"translate(30, 20)\">\n        <text x=\"180\" y=\"20\" font-size=\"11\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">ACTION POTENTIAL OSCILLATION (VOLTAGE vs TIME)</text>\n        \n        <!-- Axes -->\n        <line x1=\"45\" y1=\"35\" x2=\"45\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n        <line x1=\"45\" y1=\"180\" x2=\"330\" y2=\"180\" stroke=\"#64748b\" stroke-width=\"1.5\"/>\n        \n        <!-- Y-axis labels -->\n        <text x=\"40\" y=\"45\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"end\">+30 mV</text>\n        <line x1=\"42\" y1=\"45\" x2=\"48\" y2=\"45\" stroke=\"#64748b\"/>\n        \n        <text x=\"40\" y=\"105\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"end\">0 mV</text>\n        <line x1=\"42\" y1=\"105\" x2=\"320\" y2=\"105\" stroke=\"#e2e8f0\" stroke-dasharray=\"2,2\"/>\n        \n        <text x=\"40\" y=\"130\" font-size=\"7.5\" fill=\"#64748b\" text-anchor=\"end\">-55 mV (Threshold)</text>\n        <line x1=\"42\" y1=\"130\" x2=\"320\" y2=\"130\" stroke=\"#fecaca\" stroke-dasharray=\"2,2\"/>\n        \n        <text x=\"40\" y=\"155\" font-size=\"7.5\" fill=\"#15803d\" font-weight=\"bold\" text-anchor=\"end\">-70 mV (RMP)</text>\n        <line x1=\"42\" y1=\"155\" x2=\"320\" y2=\"155\" stroke=\"#86efac\" stroke-dasharray=\"2,2\"/>\n\n        <!-- Action Potential Waveform -->\n        <path d=\"M 45,155 L 90,155 Q 110,155 125,130 L 160,45 Q 175,40 190,90 L 220,170 Q 240,178 260,165 L 300,155\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"3\"/>\n\n        <!-- Annotations -->\n        <text x=\"130\" y=\"80\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">Depolarisation</text>\n        <text x=\"130\" y=\"90\" font-size=\"7\" fill=\"#065f46\">(Na+ Influx)</text>\n        \n        <text x=\"210\" y=\"80\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\">Repolarisation</text>\n        <text x=\"210\" y=\"90\" font-size=\"7\" fill=\"#991b1b\">(K+ Efflux)</text>\n\n        <text x=\"235\" y=\"192\" font-size=\"7.5\" fill=\"#7c3aed\">Hyperpolarisation</text>\n      </g>\n\n      <!-- Chemical Synapse Diagram on Right -->\n      <g transform=\"translate(420, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"400\" height=\"195\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n        <text x=\"200\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">CHEMICAL SYNAPSE ULTRASTRUCTURE</text>\n\n        <!-- Presynaptic knob bulb -->\n        <path d=\"M 120,35 C 120,70 80,105 80,130 C 80,145 320,145 320,130 C 320,105 280,70 280,35\" fill=\"#eff6ff\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n        <text x=\"200\" y=\"55\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Pre-Synaptic Terminal Bulb</text>\n\n        <!-- Synaptic vesicles inside -->\n        <circle cx=\"150\" cy=\"85\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"180\" cy=\"75\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"210\" cy=\"85\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"240\" cy=\"78\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"170\" cy=\"115\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"230\" cy=\"115\" r=\"7\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <text x=\"255\" y=\"95\" font-size=\"7.5\" fill=\"#9d174d\">Synaptic Vesicles (ACh)</text>\n\n        <!-- Ca2+ channels and influx -->\n        <path d=\"M 85,90 L 105,90\" stroke=\"#e11d48\" stroke-width=\"3\"/>\n        <text x=\"75\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#e11d48\">Ca2+ &rarr;</text>\n\n        <!-- Exocytosis into cleft -->\n        <path d=\"M 190,130 C 190,137 210,137 210,130\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n        <circle cx=\"195\" cy=\"148\" r=\"2.5\" fill=\"#db2777\"/>\n        <circle cx=\"205\" cy=\"149\" r=\"2.5\" fill=\"#db2777\"/>\n        <circle cx=\"180\" cy=\"150\" r=\"2.5\" fill=\"#db2777\"/>\n        <circle cx=\"220\" cy=\"150\" r=\"2.5\" fill=\"#db2777\"/>\n\n        <!-- Synaptic cleft bracket -->\n        <text x=\"35\" y=\"152\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">Synaptic Cleft (~20 nm)</text>\n        <line x1=\"80\" y1=\"154\" x2=\"320\" y2=\"154\" stroke=\"#059669\" stroke-dasharray=\"2,2\"/>\n\n        <!-- Postsynaptic membrane -->\n        <rect x=\"80\" y=\"165\" width=\"240\" height=\"20\" rx=\"3\" fill=\"#ecfdf5\" stroke=\"#10b981\" stroke-width=\"2\"/>\n        <text x=\"200\" y=\"179\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#047857\" text-anchor=\"middle\">Post-Synaptic Membrane (Ligand-Gated Receptors)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 12: Brain, Eye &amp; Ear Anatomy, Reflex Arc, Action Potential, Synapse &amp; Sensory Perception</div>\n\n  <!-- c11b-ch18-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Briefly describe the structure of the following:<br>\n        (a) Brain<br>\n        (b) Eye<br>\n        (c) Ear\n      </div>\n      <div class=\"q-marks\">[6 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Structure of the Human Brain:</strong><br>\n            Protected inside the cranial cavity and surrounded by three cranial meninges: outer <em>dura mater</em>, delicate middle <em>arachnoid</em>, and highly vascular inner <em>pia mater</em>. Divided into three major anatomical parts:\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>1. Forebrain (Prosencephalon):</strong> Comprises <em>cerebrum</em>, <em>thalamus</em>, and <em>hypothalamus</em>. The cerebrum forms the bulk of the brain, divided into right and left cerebral hemispheres interconnected by a thick nerve tract called the <strong>corpus callosum</strong>. The cerebral cortex (grey matter) houses motor, sensory, and association areas. The thalamus acts as a major sensory relay station. The hypothalamus at its base regulates body temperature, hunger, thirst, circadian rhythms, and pituitary hormone synthesis.</li>\n              <li><strong>2. Midbrain (Mesencephalon):</strong> Located between thalamus and pons. Contains the <em>cerebral aqueduct</em> (canal of Sylvius) and dorsal four optic/auditory lobes called <strong>corpora quadrigemina</strong>.</li>\n              <li><strong>3. Hindbrain (Rhombencephalon):</strong> Comprises <em>pons</em> (interconnecting tracts), <em>cerebellum</em> (convoluted surface coordinating muscular posture and balance), and <em>medulla oblongata</em> (vital reflex center controlling respiration, cardiovascular reflexes, and gastric secretions). Medulla connects inferiorly with the spinal cord.</li>\n            </ul>\n\n            <strong>(b) Structure of the Human Eye:</strong><br>\n            Spherical organ located in the bony orbit of the skull. Its wall consists of three concentric tunics:\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>1. Fibrous Tunic (Outer):</strong> Posterior opaque white <strong>sclera</strong> and anterior transparent, avascular <strong>cornea</strong> which admits and refracts light rays.</li>\n              <li><strong>2. Vascular Tunic / Uvea (Middle):</strong> Highly vascular, bluish <strong>choroid</strong> layer. Anteriorly thickens into the <strong>ciliary body</strong> (contains ciliary muscles controlling lens curvature) and projects forward as the pigmented, visible <strong>iris</strong> with a central variable aperture called the <strong>pupil</strong>. The crystalline biconvex transparent <strong>lens</strong> is held in place by suspensory ligaments.</li>\n              <li><strong>3. Neural Tunic / Retina (Inner):</strong> Contains three neural cell layers: photoreceptors (outer), bipolar cells (middle), and ganglion cells (inner). Photoreceptors include <strong>rods</strong> (rhodopsin pigment, twilight/scotopic vision) and <strong>cones</strong> (photopic bright-light &amp; color vision). Lateral to the optic disc (blind spot) lies the <strong>macula lutea</strong> with its central depression, the <strong>fovea centralis</strong> (site of highest visual resolution, containing exclusively packed cones).</li>\n            </ul>\n\n            <strong>(c) Structure of the Human Ear:</strong><br>\n            Performs dual sensory modalities: hearing (phonoreception) and equilibrium (statoreception). Composed of three divisions:\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li><strong>1. External Ear:</strong> Consists of <strong>pinna</strong> (collects sound waves), <strong>external auditory canal</strong> (lined with wax/ceruminous glands), and the vibrating <strong>tympanic membrane (eardrum)</strong>.</li>\n              <li><strong>2. Middle Ear (Tympanic Cavity):</strong> Air-filled chamber housing three articulated ear ossicles: <strong>malleus (hammer)</strong> attached to eardrum, <strong>incus (anvil)</strong>, and <strong>stapes (stirrup)</strong> attached to the oval window (fenestra ovalis). Connected to the pharynx via the <strong>Eustachian tube</strong> to equalize pressure.</li>\n              <li><strong>3. Inner Ear (Labyrinth):</strong> Consists of bony labyrinth enclosing fluid-filled membranous labyrinth (endolymph inside, perilymph outside). Formed of the <strong>cochlea</strong> (hearing organ housing the basilar membrane with the <strong>Organ of Corti</strong> containing sensory hair cells) and the <strong>vestibular apparatus</strong> (3 semicircular canals and otolith organ &mdash; utricle &amp; saccule &mdash; maintaining dynamic and static equilibrium).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Brain: Forebrain (cerebrum, corpus callosum, hypothalamus), midbrain, and hindbrain</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Eye: Outer sclera/cornea, middle choroid/ciliary/iris, and inner retina (rods, cones, fovea)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Ear: External pinna/eardrum, middle ear ossicles &amp; Eustachian tube, inner cochlea &amp; vestibular apparatus</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Compare the following:<br>\n        (a) Central Neural System (CNS) and Peripheral Neural System (PNS)<br>\n        (b) Resting potential and Action potential<br>\n        (c) Choroid and Retina\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Central Neural System (CNS) vs. Peripheral Neural System (PNS):</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0 10px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Central Neural System (CNS)</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Peripheral Neural System (PNS)</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Components</td>\n                    <td style=\"padding:6px 10px;\">Consists exclusively of the <strong>Brain and Spinal Cord</strong>.</td>\n                    <td style=\"padding:6px 10px;\">Comprises all peripheral nerves: 12 pairs cranial nerves and 31 pairs spinal nerves.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Function</td>\n                    <td style=\"padding:6px 10px;\">Central integrative command, cognitive thinking, decision-making, and control center.</td>\n                    <td style=\"padding:6px 10px;\">Transmits afferent sensory inputs to CNS and efferent motor commands to peripheral effectors.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Subdivisions</td>\n                    <td style=\"padding:6px 10px;\">Forebrain, Midbrain, Hindbrain, and Spinal Cord.</td>\n                    <td style=\"padding:6px 10px;\">Somatic Neural System (voluntary) and Autonomic Neural System (sympathetic &amp; parasympathetic).</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n\n            <strong>(b) Resting Potential vs. Action Potential:</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0 10px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Resting Potential</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Action Potential</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">State of Fibre</td>\n                    <td style=\"padding:6px 10px;\">Resting, non-conducting polarized state of axonal membrane.</td>\n                    <td style=\"padding:6px 10px;\">Excited, actively propagating electrical impulse (wave of depolarization).</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Voltage Value</td>\n                    <td style=\"padding:6px 10px;\">Approximately <strong>$-70\\text{ mV}$</strong> (interior negative relative to exterior).</td>\n                    <td style=\"padding:6px 10px;\">Reverses to approximately <strong>$+30\\text{ mV}$</strong> (interior positive relative to exterior).</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Permeability</td>\n                    <td style=\"padding:6px 10px;\">Membrane permeable to $K^+$ and impermeable to $Na^+$; maintained by $Na^+/K^+$ ATPase pump ($3\\text{ Na}^+$ out : $2\\text{ K}^+$ in).</td>\n                    <td style=\"padding:6px 10px;\">Voltage-gated $Na^+$ channels open, causing massive, rapid influx of $Na^+$ ions down electrochemical gradient.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n\n            <strong>(c) Choroid vs. Retina:</strong><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.84rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:1.5px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Feature</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Choroid Layer</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Retina Layer</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Position &amp; Tunic</td>\n                    <td style=\"padding:6px 10px;\">Middle vascular tunic of eyeball.</td>\n                    <td style=\"padding:6px 10px;\">Innermost photosensitive neurosensory tunic of eyeball.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Structure</td>\n                    <td style=\"padding:6px 10px;\">Rich in blood vessels and dark melanin pigments to absorb stray light.</td>\n                    <td style=\"padding:6px 10px;\">Composed of three neural layers: photoreceptors (rods and cones), bipolar neurons, and ganglion cells.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Function</td>\n                    <td style=\"padding:6px 10px;\">Nutritive supply to ocular tissues; prevents internal light reflection.</td>\n                    <td style=\"padding:6px 10px;\">Phototransduction: converts photons of light into electrochemical nerve impulses transmitted via optic nerve.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) CNS (brain/spinal cord, processing) vs PNS (nerves, conduction)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Resting (-70 mV, Na+/K+ pump) vs Action potential (+30 mV, Na+ influx)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Choroid (vascular, middle) vs Retina (neural, photoreceptors, image capture)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the following processes:<br>\n        (a) Polarisation of the membrane of a nerve fibre<br>\n        (b) Depolarisation of the membrane of a nerve fibre<br>\n        (c) Conduction of a nerve impulse along an axon<br>\n        (d) Transmission of a nerve impulse across a chemical synapse\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Polarisation of the Nerve Membrane (Resting Potential):</strong><br>\n            In an unstimulated resting neuron, the inside of the axonal membrane is negatively charged relative to the outside. This resting membrane potential (approximately <strong>$-70\\text{ mV}$</strong>) is generated and maintained by:\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li>Differential permeability: the resting membrane is significantly more permeable to $K^+$ ions than to $Na^+$ ions and completely impermeable to large negatively charged intracellular proteins.</li>\n              <li>The active <strong>$Na^+/K^+$ ATPase pump</strong>, which consumes 1 ATP to transport $3\\text{ Na}^+$ outward into the ECF in exchange for bringing $2\\text{ K}^+$ inward into the axoplasm, creating an electrochemical polarity.</li>\n            </ul>\n\n            <strong>(b) Depolarisation of the Nerve Membrane (Action Potential Generation):</strong><br>\n            When a stimulus reaching threshold voltage ($-55\\text{ mV}$) is applied at a point on the polarized axonal membrane:\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li>Voltage-gated $Na^+$ channels immediately open, causing a massive influx of $Na^+$ into the axoplasm down its steep electrical and concentration gradient.</li>\n              <li>This influx rapidly overwhelms the negative charge, reversing the membrane polarity to approximately <strong>$+30\\text{ mV}$</strong> (inside becomes positive, outside negative). This transient electrical reversal is termed <strong>depolarisation</strong> or the <strong>action potential</strong>.</li>\n            </ul>\n\n            <strong>(c) Conduction of a Nerve Impulse Along an Axon:</strong><br>\n            At the depolarised site (site A), the inner surface is positive while at the adjacent resting site (site B), the inner surface is negative:\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li>A local electrical circuit forms: current flows on the inner axonal surface from site A to site B, and on the outer surface from site B to site A.</li>\n              <li>This current flow depolarises site B to its threshold, triggering an action potential at site B. Meanwhile, site A repolarises as voltage-gated $K^+$ channels open and $K^+$ rushes outward.</li>\n              <li>This self-propagating wave of sequential depolarisation travels smoothly along unmyelinated axons, or rapidly jumps from node to node (<strong>saltatory conduction</strong>) in myelinated axons.</li>\n            </ul>\n\n            <strong>(d) Transmission of a Nerve Impulse Across a Chemical Synapse:</strong><br>\n            <ol style=\"margin:2px 0 4px 20px;\">\n              <li>When the action potential arrives at the pre-synaptic axon terminal bulb, it opens voltage-gated $Ca^{2+}$ channels, causing an influx of $Ca^{2+}$ ions from the synaptic cleft into the bulb.</li>\n              <li>The $Ca^{2+}$ influx stimulates synaptic vesicles containing neurotransmitters (such as <strong>acetylcholine</strong>) to migrate and fuse with the pre-synaptic membrane.</li>\n              <li>Neurotransmitters are released into the narrow fluid-filled <strong>synaptic cleft (~20 nm)</strong> via exocytosis.</li>\n              <li>Neurotransmitter molecules diffuse across the cleft and bind to specific ligand-gated receptors on the post-synaptic membrane, opening ion channels that generate an Excitatory Post-Synaptic Potential (EPSP) or action potential in the post-synaptic neuron.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Polarisation: -70 mV, Na+/K+ pump (3 Na+ out / 2 K+ in), K+ permeability</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Depolarisation: Voltage-gated Na+ channels, Na+ influx, reversal to +30 mV</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Conduction: Local circuit between depolarised and resting segment, saltatory conduction</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Synaptic transmission: Ca2+ influx, vesicle exocytosis, ACh diffusion, receptor binding</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Draw labelled diagrams of the following:<br>\n        (a) A neuron<br>\n        (b) Brain<br>\n        (c) Eye<br>\n        (d) Ear\n      </div>\n      <div class=\"q-marks\">[8 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Detailed Anatomical Labelled Diagrams Required by NCERT:</strong><br><br>\n\n            <!-- (a) Neuron Diagram -->\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:14px; margin:10px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:8px;\">\n                (a) Diagrammatic Representation of a Multipolar Neuron\n              </div>\n              <svg viewBox=\"0 0 760 180\" width=\"100%\" height=\"auto\" style=\"max-height:180px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"5\" y=\"5\" width=\"750\" height=\"170\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n\n                <!-- Cell Body (Soma) on left -->\n                <polygon points=\"120,40 160,70 170,110 130,130 90,110 80,70\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n                <circle cx=\"125\" cy=\"85\" r=\"14\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"1.5\"/>\n                <circle cx=\"125\" cy=\"85\" r=\"5\" fill=\"#78350f\"/>\n                <text x=\"125\" y=\"112\" font-size=\"7.5\" fill=\"#78350f\" text-anchor=\"middle\">Nucleus</text>\n\n                <!-- Dendrites -->\n                <path d=\"M 80,70 L 30,50 M 80,70 L 40,75 M 120,40 L 90,15 M 120,40 L 140,15 M 90,110 L 50,130 M 90,110 L 60,150\" stroke=\"#d97706\" stroke-width=\"2\"/>\n                <text x=\"35\" y=\"40\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#b45309\">Dendrites</text>\n                <text x=\"125\" y=\"148\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">Cell Body (Cyton / Soma)</text>\n                <text x=\"125\" y=\"160\" font-size=\"7\" fill=\"#78350f\" text-anchor=\"middle\">with Nissl's granules</text>\n\n                <!-- Axon Hillock & Axon Trunk -->\n                <path d=\"M 170,85 L 600,85\" stroke=\"#2563eb\" stroke-width=\"4\"/>\n                <text x=\"185\" y=\"75\" font-size=\"7.5\" fill=\"#1e40af\">Axon Hillock</text>\n\n                <!-- Myelin Sheath Schwann cells -->\n                <rect x=\"220\" y=\"70\" width=\"70\" height=\"30\" rx=\"6\" fill=\"#bfdbfe\" stroke=\"#1d4ed8\" stroke-width=\"1.5\"/>\n                <circle cx=\"255\" cy=\"80\" r=\"3\" fill=\"#1e3a8a\"/>\n\n                <rect x=\"310\" y=\"70\" width=\"70\" height=\"30\" rx=\"6\" fill=\"#bfdbfe\" stroke=\"#1d4ed8\" stroke-width=\"1.5\"/>\n                <circle cx=\"345\" cy=\"80\" r=\"3\" fill=\"#1e3a8a\"/>\n\n                <rect x=\"400\" y=\"70\" width=\"70\" height=\"30\" rx=\"6\" fill=\"#bfdbfe\" stroke=\"#1d4ed8\" stroke-width=\"1.5\"/>\n                <circle cx=\"435\" cy=\"80\" r=\"3\" fill=\"#1e3a8a\"/>\n\n                <rect x=\"490\" y=\"70\" width=\"70\" height=\"30\" rx=\"6\" fill=\"#bfdbfe\" stroke=\"#1d4ed8\" stroke-width=\"1.5\"/>\n                <circle cx=\"525\" cy=\"80\" r=\"3\" fill=\"#1e3a8a\"/>\n\n                <!-- Labels for Schwann cell & Myelin -->\n                <text x=\"345\" y=\"60\" font-size=\"8\" font-weight=\"bold\" fill=\"#1d4ed8\" text-anchor=\"middle\">Myelin Sheath (Schwann Cell)</text>\n\n                <!-- Node of Ranvier -->\n                <line x1=\"300\" y1=\"55\" x2=\"300\" y2=\"105\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n                <text x=\"300\" y=\"120\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Node of Ranvier</text>\n\n                <!-- Axon Terminal & Synaptic Knobs -->\n                <path d=\"M 600,85 L 650,55 M 600,85 L 660,85 M 600,85 L 650,115\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n                <circle cx=\"650\" cy=\"55\" r=\"5\" fill=\"#f43f5e\"/>\n                <circle cx=\"660\" cy=\"85\" r=\"5\" fill=\"#f43f5e\"/>\n                <circle cx=\"650\" cy=\"115\" r=\"5\" fill=\"#f43f5e\"/>\n                <text x=\"700\" y=\"85\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#e11d48\">Synaptic Knobs</text>\n                <text x=\"700\" y=\"98\" font-size=\"7\" fill=\"#881337\">(with ACh vesicles)</text>\n              </svg>\n            </div>\n\n            <!-- (b) Brain Diagram -->\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:14px; margin:10px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:8px;\">\n                (b) Sagittal Section of the Human Brain\n              </div>\n              <svg viewBox=\"0 0 760 210\" width=\"100%\" height=\"auto\" style=\"max-height:210px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"5\" y=\"5\" width=\"750\" height=\"200\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n\n                <!-- Cerebrum dome -->\n                <path d=\"M 120,160 C 90,60 250,20 450,25 C 550,28 620,80 580,150\" fill=\"#fbcfe8\" stroke=\"#db2777\" stroke-width=\"2\"/>\n                <text x=\"320\" y=\"45\" font-size=\"11\" font-weight=\"bold\" fill=\"#be185d\">Cerebral Hemisphere (Cerebrum)</text>\n\n                <!-- Corpus Callosum curve -->\n                <path d=\"M 230,105 C 260,85 360,85 410,105\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"4\"/>\n                <text x=\"320\" y=\"80\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#6d28d9\" text-anchor=\"middle\">Corpus Callosum</text>\n\n                <!-- Thalamus & Hypothalamus -->\n                <ellipse cx=\"320\" cy=\"115\" rx=\"20\" ry=\"12\" fill=\"#fed7aa\" stroke=\"#ea580c\"/>\n                <text x=\"320\" y=\"118\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#9a3412\" text-anchor=\"middle\">Thalamus</text>\n\n                <path d=\"M 305,127 L 290,145\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n                <circle cx=\"290\" cy=\"148\" r=\"6\" fill=\"#fb923c\"/>\n                <text x=\"240\" y=\"145\" font-size=\"8\" font-weight=\"bold\" fill=\"#c2410c\">Hypothalamus</text>\n                <text x=\"240\" y=\"157\" font-size=\"7\" fill=\"#7c2d12\">&amp; Pituitary Gland</text>\n\n                <!-- Midbrain & Cerebral Aqueduct -->\n                <rect x=\"360\" y=\"125\" width=\"30\" height=\"20\" fill=\"#ddd6fe\" stroke=\"#7c3aed\"/>\n                <text x=\"430\" y=\"132\" font-size=\"8\" font-weight=\"bold\" fill=\"#5b21b6\">Midbrain &amp; Cerebral Aqueduct</text>\n\n                <!-- Pons -->\n                <path d=\"M 350,150 C 330,155 330,175 350,180\" fill=\"#e0e7ff\" stroke=\"#4f46e5\" stroke-width=\"1.5\"/>\n                <text x=\"310\" y=\"172\" font-size=\"8\" font-weight=\"bold\" fill=\"#3730a3\">Pons</text>\n\n                <!-- Cerebellum (hindbrain back) -->\n                <path d=\"M 460,135 C 530,135 560,170 510,195 C 460,205 440,180 440,150 Z\" fill=\"#bbf7d0\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n                <text x=\"500\" y=\"170\" font-size=\"9\" font-weight=\"bold\" fill=\"#15803d\">Cerebellum</text>\n\n                <!-- Medulla oblongata & spinal cord -->\n                <path d=\"M 355,180 L 355,200 L 375,200 L 375,180 Z\" fill=\"#fef08a\" stroke=\"#ca8a04\"/>\n                <text x=\"270\" y=\"195\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#854d0e\">Medulla Oblongata</text>\n                <text x=\"365\" y=\"210\" font-size=\"7.5\" fill=\"#475569\" text-anchor=\"middle\">&darr; Spinal Cord</text>\n              </svg>\n            </div>\n\n            <!-- (c) Eye Diagram -->\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:14px; margin:10px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:8px;\">\n                (c) Horizontal Section of the Human Eye\n              </div>\n              <svg viewBox=\"0 0 760 200\" width=\"100%\" height=\"auto\" style=\"max-height:200px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"5\" y=\"5\" width=\"750\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n\n                <!-- Eyeball spheres -->\n                <!-- Sclera (Outer) -->\n                <path d=\"M 220,50 C 380,20 540,50 540,105 C 540,160 380,190 220,160\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"4\"/>\n                <text x=\"560\" y=\"55\" font-size=\"8\" font-weight=\"bold\" fill=\"#475569\">Sclera (Outer fibrous)</text>\n\n                <!-- Choroid (Middle) -->\n                <path d=\"M 220,55 C 375,28 535,55 535,105 C 535,155 375,182 220,155\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.5\"/>\n                <text x=\"560\" y=\"70\" font-size=\"8\" font-weight=\"bold\" fill=\"#1d4ed8\">Choroid (Vascular)</text>\n\n                <!-- Retina (Inner) -->\n                <path d=\"M 230,62 C 370,38 525,62 525,105 C 525,148 370,172 230,148\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"3\"/>\n                <text x=\"560\" y=\"85\" font-size=\"8\" font-weight=\"bold\" fill=\"#c2410c\">Retina (Photoreceptors)</text>\n\n                <!-- Cornea (Anterior bulge) -->\n                <path d=\"M 220,50 C 160,70 160,140 220,160\" fill=\"none\" stroke=\"#06b6d4\" stroke-width=\"3\"/>\n                <text x=\"140\" y=\"105\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0891b2\" text-anchor=\"end\">Cornea &rarr;</text>\n\n                <!-- Crystalline Lens -->\n                <ellipse cx=\"250\" cy=\"105\" rx=\"12\" ry=\"32\" fill=\"#e0f2fe\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n                <text x=\"250\" y=\"152\" font-size=\"8\" font-weight=\"bold\" fill=\"#0369a1\" text-anchor=\"middle\">Lens</text>\n\n                <!-- Iris & Pupil -->\n                <path d=\"M 235,65 L 245,85\" stroke=\"#b45309\" stroke-width=\"4\"/>\n                <path d=\"M 235,145 L 245,125\" stroke=\"#b45309\" stroke-width=\"4\"/>\n                <text x=\"200\" y=\"75\" font-size=\"8\" font-weight=\"bold\" fill=\"#b45309\">Iris</text>\n                <text x=\"210\" y=\"107\" font-size=\"7.5\" fill=\"#0f172a\">Pupil</text>\n\n                <!-- Ciliary body -->\n                <circle cx=\"232\" cy=\"62\" r=\"5\" fill=\"#dc2626\"/>\n                <circle cx=\"232\" cy=\"148\" r=\"5\" fill=\"#dc2626\"/>\n                <text x=\"200\" y=\"55\" font-size=\"7.5\" fill=\"#dc2626\">Ciliary Body</text>\n\n                <!-- Chambers -->\n                <text x=\"205\" y=\"125\" font-size=\"6.5\" fill=\"#0284c7\">Aqueous</text>\n                <text x=\"350\" y=\"105\" font-size=\"9\" fill=\"#0369a1\">Vitreous Humor (Chamber)</text>\n\n                <!-- Fovea & Blind Spot & Optic Nerve -->\n                <circle cx=\"525\" cy=\"100\" r=\"3\" fill=\"#e11d48\"/>\n                <text x=\"560\" y=\"102\" font-size=\"8\" font-weight=\"bold\" fill=\"#be123c\">Fovea Centralis (Yellow Spot)</text>\n\n                <path d=\"M 522,125 L 580,135 M 522,135 L 580,145\" stroke=\"#64748b\" stroke-width=\"4\"/>\n                <text x=\"590\" y=\"132\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\">Blind Spot</text>\n                <text x=\"590\" y=\"145\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#0f172a\">&amp; Optic Nerve &rarr;</text>\n              </svg>\n            </div>\n\n            <!-- (d) Ear Diagram -->\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:14px; margin:10px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:8px;\">\n                (d) Diagrammatic Anatomy of the Human Ear\n              </div>\n              <svg viewBox=\"0 0 760 200\" width=\"100%\" height=\"auto\" style=\"max-height:200px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"5\" y=\"5\" width=\"750\" height=\"190\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n\n                <!-- Pinna (outer left) -->\n                <path d=\"M 120,40 C 60,35 60,165 120,165 C 130,165 130,145 110,135 C 80,120 80,75 110,65 Z\" fill=\"#fed7aa\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n                <text x=\"65\" y=\"30\" font-size=\"9\" font-weight=\"bold\" fill=\"#c2410c\">Pinna (External)</text>\n\n                <!-- Auditory Canal -->\n                <path d=\"M 120,85 L 260,85 M 120,115 L 260,115\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n                <text x=\"180\" y=\"102\" font-size=\"8\" fill=\"#475569\">Ear Canal (Meatus)</text>\n\n                <!-- Tympanic membrane (Eardrum) -->\n                <line x1=\"260\" y1=\"80\" x2=\"260\" y2=\"120\" stroke=\"#dc2626\" stroke-width=\"3\"/>\n                <text x=\"260\" y=\"70\" font-size=\"8\" font-weight=\"bold\" fill=\"#dc2626\" text-anchor=\"middle\">Tympanum</text>\n\n                <!-- Middle Ear Ossicles (Malleus, Incus, Stapes) -->\n                <!-- Malleus -->\n                <line x1=\"260\" y1=\"95\" x2=\"280\" y2=\"85\" stroke=\"#0f172a\" stroke-width=\"3\"/>\n                <!-- Incus -->\n                <line x1=\"280\" y1=\"85\" x2=\"300\" y2=\"90\" stroke=\"#0f172a\" stroke-width=\"3\"/>\n                <!-- Stapes -->\n                <line x1=\"300\" y1=\"90\" x2=\"315\" y2=\"90\" stroke=\"#0f172a\" stroke-width=\"3\"/>\n                <text x=\"290\" y=\"60\" font-size=\"8\" font-weight=\"bold\" fill=\"#0f172a\" text-anchor=\"middle\">Ear Ossicles (M-I-S)</text>\n\n                <!-- Eustachian tube downward -->\n                <path d=\"M 285,120 L 260,175 M 305,120 L 280,175\" stroke=\"#059669\" stroke-width=\"2\"/>\n                <text x=\"280\" y=\"185\" font-size=\"8\" font-weight=\"bold\" fill=\"#047857\">Eustachian Tube (to pharynx)</text>\n\n                <!-- Inner ear: Semicircular canals -->\n                <ellipse cx=\"370\" cy=\"65\" rx=\"18\" ry=\"12\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                <ellipse cx=\"385\" cy=\"55\" rx=\"12\" ry=\"18\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                <ellipse cx=\"360\" cy=\"55\" rx=\"12\" ry=\"18\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.5\"/>\n                <text x=\"440\" y=\"55\" font-size=\"8\" font-weight=\"bold\" fill=\"#6d28d9\">Semicircular Canals (Balance)</text>\n\n                <!-- Cochlea (coiled) -->\n                <path d=\"M 370,95 C 400,95 400,130 370,130 C 350,130 350,110 370,110 C 380,110 380,120 370,120\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"3.5\"/>\n                <text x=\"440\" y=\"115\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1d4ed8\">Cochlea (Organ of Corti &bull; Hearing)</text>\n\n                <!-- Auditory nerve -->\n                <path d=\"M 400,105 L 480,105\" stroke=\"#d97706\" stroke-width=\"3\"/>\n                <text x=\"490\" y=\"108\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#b45309\">Auditory Nerve (to Brain)</text>\n              </svg>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Neuron: Cyton, dendrites, nucleus, axon, myelin sheath, nodes of Ranvier, synaptic knobs</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Brain: Cerebrum, corpus callosum, thalamus, hypothalamus, midbrain, pons, cerebellum, medulla</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Eye: Cornea, iris, lens, ciliary body, sclera, choroid, retina, fovea, blind spot, optic nerve</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Ear: Pinna, auditory canal, tympanum, malleus, incus, stapes, cochlea, semicircular canals</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Write short notes on the following:<br>\n        (a) Neural coordination<br>\n        (b) Forebrain<br>\n        (c) Midbrain<br>\n        (d) Hindbrain<br>\n        (e) Retina<br>\n        (f) Ear ossicles<br>\n        (g) Cochlea<br>\n        (h) Organ of Corti<br>\n        (i) Synapse\n      </div>\n      <div class=\"q-marks\">[9 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Concise Scientific Explanations of Key Neurobiological Concepts:</strong><br><br>\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li><strong>(a) Neural Coordination:</strong> The physiological process through which the nervous system integrates and synchronizes the activities of multiple interdependent organs via rapid, point-to-point electrical nerve impulses, maintaining homeostatic equilibrium.</li>\n              <li><strong>(b) Forebrain:</strong> Composed of the cerebrum, thalamus, and hypothalamus. Center for conscious thought, memory, voluntary muscle actions, speech, thermoregulation, and endocrine regulation.</li>\n              <li><strong>(c) Midbrain:</strong> Located between the diencephalon and pons. Houses the cerebral aqueduct and four dorsal rounded optic/auditory reflex swelling lobes termed the <em>corpora quadrigemina</em>.</li>\n              <li><strong>(d) Hindbrain:</strong> Composed of the pons (fibre bridges), cerebellum (intricate convoluted tree of life / arbor vitae coordinating posture and fine motor skills), and medulla oblongata (vital involuntary control of cardiac rhythm, breathing rate, and swallowing).</li>\n              <li><strong>(e) Retina:</strong> Innermost photosensitive neural layer of the eyeball containing three layers of cells: outer photoreceptors (rods with rhodopsin for dim light; cones with photopsin for sharp color vision), middle bipolar cells, and inner ganglion cells forming the optic nerve.</li>\n              <li><strong>(f) Ear Ossicles:</strong> Three miniature articulating bones in the middle ear &mdash; <strong>Malleus (hammer)</strong>, <strong>Incus (anvil)</strong>, and <strong>Stapes (stirrup)</strong> &mdash; that mechanically amplify sound wave vibrations by approximately 20 times and transmit them from the eardrum to the oval window.</li>\n              <li><strong>(g) Cochlea:</strong> The coiled, snail-shell-shaped auditory portion of the inner ear labyrinth, divided into three longitudinal chambers: upper scala vestibuli, middle scala media (containing endolymph), and lower scala tympani.</li>\n              <li><strong>(h) Organ of Corti:</strong> The sensory receptor organ of hearing resting on the basilar membrane within the scala media of the cochlea, bearing rows of sensory hair cells whose apical stereocilia bend against the overlying tectorial membrane to generate auditory action potentials.</li>\n              <li><strong>(i) Synapse:</strong> The specialized anatomical junction between the terminal bulb of a pre-synaptic neuron and the dendrite/membrane of a post-synaptic neuron, through which electrical signals are transmitted via chemical neurotransmitters or direct gap junctions.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">1 Mark each for complete, scientifically accurate descriptions of items (a) through (i)</span><span class=\"marking-marks\">9 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give a brief account of the mechanism of synaptic transmission.\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Mechanism of Synaptic Transmission Across a Chemical Synapse:</strong><br><br>\n            <ol style=\"margin:2px 0 6px 20px;\">\n              <li><strong>Arrival of Action Potential:</strong> When a wave of depolarization (action potential) reaches the pre-synaptic axon terminal bulb, it depolarises the pre-synaptic membrane.</li>\n              <li><strong>Calcium Influx:</strong> The depolarisation triggers the opening of voltage-gated $Ca^{2+}$ channels. Extracellular calcium ions ($Ca^{2+}$) rush into the pre-synaptic knob down their steep gradient.</li>\n              <li><strong>Exocytosis of Neurotransmitter:</strong> The elevated intracellular $Ca^{2+}$ induces synaptic vesicles containing acetylcholine (ACh) to move toward, fuse with the pre-synaptic membrane, and release neurotransmitter molecules into the fluid-filled <strong>synaptic cleft (~20 nm)</strong> via exocytosis.</li>\n              <li><strong>Binding to Post-Synaptic Receptors:</strong> The neurotransmitter diffuses across the narrow cleft and binds specifically to ligand-gated chemoreceptors on the post-synaptic membrane.</li>\n              <li><strong>Post-Synaptic Potential Generation:</strong> Receptor binding opens ion channels, allowing an influx of $Na^+$ ions, which depolarises the post-synaptic membrane and generates a fresh action potential.</li>\n              <li><strong>Termination:</strong> Acetylcholine is rapidly hydrolyzed by the enzyme <strong>acetylcholinesterase (AChE)</strong> into acetate and choline, resetting the receptor for subsequent signals.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Action potential arrival and opening of voltage-gated Ca2+ channels</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vesicle exocytosis and release of acetylcholine into synaptic cleft</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Receptor binding, opening of ligand-gated channels, and post-synaptic action potential</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Enzymatic cleavage by acetylcholinesterase to terminate signal</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the role of $Na^+$ in the generation of action potential.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Critical Role of Sodium Ions ($Na^+$) in Action Potential Generation:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>1. Resting State Exclusion:</strong> At resting potential ($-70\\text{ mV}$), the axonal membrane is nearly impermeable to $Na^+$, and $Na^+/K^+$ pumps actively keep $[Na^+]$ tenfold higher outside the axon than inside.</li>\n              <li><strong>2. Threshold Stimulus:</strong> When a stimulus depolarises the membrane to the threshold potential ($-55\\text{ mV}$), voltage-gated $Na^+$ activation gates snap open.</li>\n              <li><strong>3. Explosive $Na^+$ Influx:</strong> Driven by both a concentration gradient (high outside to low inside) and an electrical gradient (attracted to negative interior), positively charged $Na^+$ ions rush into the axoplasm in a rapid surge.</li>\n              <li><strong>4. Polarity Reversal (Depolarisation):</strong> This influx cancels the internal negative charge and drives the membrane potential up to approximately <strong>$+30\\text{ mV}$</strong>. This sudden spike represents the <strong>action potential</strong>.</li>\n              <li><strong>5. Channel Inactivation:</strong> Within a millisecond, the inactivation gates of $Na^+$ channels close, stopping further sodium entry and allowing $K^+$ efflux to repolarize the membrane.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Resting state: Low Na+ permeability and high extracellular Na+ gradient</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Threshold trigger opening voltage-gated Na+ channels and rapid Na+ influx</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reversal of membrane potential from -70 mV to +30 mV (depolarisation spike)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Differentiate between:<br>\n        (a) Myelinated and non-myelinated axons<br>\n        (b) Dendrites and axons<br>\n        (c) Thalamus and Hypothalamus<br>\n        (d) Cerebrum and Cerebellum\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Comparative Analysis of Nervous System Structures:</strong><br><br>\n            <strong>(a) Myelinated vs. Non-Myelinated Axons:</strong><br>\n            • <em>Myelinated Axons:</em> Ensheathed with lipid-rich <strong>myelin sheath</strong> produced by Schwann cells (PNS) or oligodendrocytes (CNS), interrupted at periodic gaps called <strong>Nodes of Ranvier</strong>. Exhibits ultra-fast <strong>saltatory conduction</strong> (up to 120 m/s); found in cranial and spinal nerves.<br>\n            • <em>Non-Myelinated Axons:</em> Enclosed by Schwann cells that do not form a multi-layered myelin wrapping; lack Nodes of Ranvier. Exhibits slow, continuous wave conduction (1–2 m/s); common in autonomic and somatic neural systems.<br><br>\n\n            <strong>(b) Dendrites vs. Axons:</strong><br>\n            • <em>Dendrites:</em> Short, highly branched tapering cytoplasmic processes containing Nissl's granules; conduct impulses <strong>centripetally (towards the soma)</strong>.<br>\n            • <em>Axon:</em> Single, long, cylindrical process lacking Nissl's granules; originates at the axon hillock and conducts impulses <strong>centrifugally (away from the soma)</strong> to terminal synaptic knobs.<br><br>\n\n            <strong>(c) Thalamus vs. Hypothalamus:</strong><br>\n            • <em>Thalamus:</em> Large egg-shaped sensory/motor relay station wrapped by the cerebrum that filters and channels all sensory inputs (except olfaction) to appropriate cortical areas.<br>\n            • <em>Hypothalamus:</em> Located at the base of the thalamus; contains autonomic centers for body temperature regulation, hunger, thirst, circadian clock, and synthesizes neurohormones controlling pituitary secretion.<br><br>\n\n            <strong>(d) Cerebrum vs. Cerebellum:</strong><br>\n            • <em>Cerebrum:</em> Largest part of the forebrain; center of memory, conscious thought, sensory interpretation, reasoning, and voluntary motor output.<br>\n            • <em>Cerebellum:</em> Part of the hindbrain; features a highly folded convoluted surface (arbor vitae) that unconsciously coordinates voluntary muscle movements, maintaining posture, balance, and equilibrium.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Myelinated (Schwann, Nodes of Ranvier, saltatory) vs Non-myelinated (continuous conduction)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Dendrites (branched, afferent to soma) vs Axon (single, efferent from soma)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Thalamus (sensory relay) vs Hypothalamus (homeostasis, temperature, pituitary control)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Cerebrum (intelligence, memory, cortex) vs Cerebellum (balance, motor coordination)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Answer briefly:<br>\n        (a) Which part of the brain controls body temperature?<br>\n        (b) Which part of the brain is responsible for matching the orientation of food?<br>\n        (c) Name the communication junction between two neurons.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Precise Scientific Answers:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Control of Body Temperature:</strong><br>\n              The <strong>Hypothalamus</strong> (acts as the body's central thermostat, initiating sweating, shivering, and vasodilation/vasoconstriction).</li>\n\n              <li><strong>(b) Matching the Orientation of Food / Head-Eye Reflexes:</strong><br>\n              The <strong>Midbrain</strong> (specifically the <em>corpora quadrigemina</em> and superior colliculi, which coordinate visual and auditory tracking reflexes).</li>\n\n              <li><strong>(c) Communication Junction Between Two Neurons:</strong><br>\n              A <strong>Synapse</strong> (specifically chemical or electrical synapse).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Hypothalamus</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Midbrain (corpora quadrigemina / superior colliculi)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Synapse</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define the following:<br>\n        (a) Synapse<br>\n        (b) Resting membrane potential<br>\n        (c) Action potential\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Standard Neurobiological Definitions:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Synapse:</strong> An anatomically specialized functional junction between an axon terminal of one neuron and the dendrite, soma, or effector cell of another, separated by a narrow microscopic gap (synaptic cleft) across which nerve impulses are transmitted via chemical neurotransmitters or electrical gap junctions.</li>\n\n              <li><strong>(b) Resting Membrane Potential (RMP):</strong> The steady electrical potential difference across the plasma membrane of an unexcited, non-conducting neuron (typically <strong>$-70\\text{ mV}$</strong>), wherein the inside of the cell is negatively charged relative to the outside due to unequal distribution of $Na^+$ and $K^+$ ions maintained by $Na^+/K^+$ ATPase pumps.</li>\n\n              <li><strong>(c) Action Potential (Nerve Impulse):</strong> A rapid, all-or-none electrical wave of depolarisation and repolarisation (reversing membrane potential from $-70\\text{ mV}$ to $+30\\text{ mV}$ and back) that travels autonomously along an excitable plasma membrane in response to a threshold stimulus.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Synapse: specialized junction between neurons transmitting signals across synaptic cleft</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Resting membrane potential: -70 mV electrical gradient across non-conducting membrane</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Action potential: rapid all-or-none electrical depolarisation wave (+30 mV) propagating along axon</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q11 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q11\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q11')\">\n      <div class=\"q-num\">Question 11</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give a brief account of the functions of the following:<br>\n        (a) Corpus callosum<br>\n        (b) Hypothalamus<br>\n        (c) Amygdala<br>\n        (d) Semicircular canals\n      </div>\n      <div class=\"q-marks\">[4 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Key Physiological Functions:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Corpus Callosum:</strong> A wide, arched tract of commissural myelinated nerve fibers connecting the left and right cerebral hemispheres. It enables bidirectional inter-hemispheric communication, data sharing, cognitive synchronization, and memory integration between the two halves of the brain.</li>\n\n              <li><strong>(b) Hypothalamus:</strong> Master regulator of the autonomic nervous system and neuroendocrine axis:\n                <ul style=\"margin:2px 0 2px 15px;\">\n                  <li>Controls autonomic centers for heart rate, blood pressure, thermoregulation, hunger, thirst, and satiety.</li>\n                  <li>Synthesizes releasing and inhibiting hormones that control the anterior pituitary, as well as oxytocin and vasopressin.</li>\n                  <li>Part of the limbic system controlling emotional responses and sexual drive.</li>\n                </ul>\n              </li>\n\n              <li><strong>(c) Amygdala:</strong> An almond-shaped nucleus within the temporal lobe, forming an integral part of the <strong>limbic system</strong>. It processes fear, aggression, emotional memory, and threat detection, coordinating defensive autonomic behavioral responses.</li>\n\n              <li><strong>(d) Semicircular Canals:</strong> Three fluid-filled bony/membranous rings oriented at mutual right angles in the inner ear. The sensory <strong>crista ampullaris</strong> in their dilated ampullae detects angular acceleration and rotational head movement, maintaining dynamic bodily equilibrium and gaze stabilization.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Corpus callosum: inter-hemispheric communication and synchronization</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Hypothalamus: autonomic homeostasis, temperature, hunger, pituitary hormone control</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Amygdala: limbic emotional processing, fear, anger, and memory</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Semicircular canals: dynamic equilibrium and rotational acceleration detection via crista ampullaris</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch18-q12 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch18-q12\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch18-q12')\">\n      <div class=\"q-num\">Question 12</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Distinguish between:<br>\n        (a) Afferent neurons and efferent neurons<br>\n        (b) Impulse conduction in a myelinated nerve fibre and unmyelinated nerve fibre<br>\n        (c) Aqueous humor and vitreous humor<br>\n        (d) Blind spot and yellow spot (macula lutea)<br>\n        (e) Cranial nerves and spinal nerves\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Key Physiological and Anatomical Distinctions:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Afferent Neurons vs. Efferent Neurons:</strong><br>\n              • <em>Afferent (Sensory) Neurons:</em> Transmit sensory impulses from peripheral sensory receptors <strong>towards the CNS</strong>.<br>\n              • <em>Efferent (Motor) Neurons:</em> Transmit regulatory motor commands <strong>away from the CNS</strong> to peripheral effector organs (muscles and glands).</li>\n\n              <li><strong>(b) Conduction in Myelinated vs. Unmyelinated Nerve Fibre:</strong><br>\n              • <em>Myelinated Fibre:</em> Impulse jumps from one Node of Ranvier to the next (<strong>saltatory conduction</strong>), yielding extremely high conduction velocity (~100–120 m/s) with low ATP expenditure.<br>\n              • <em>Unmyelinated Fibre:</em> Impulse travels continuously down the entire axonal length (continuous propagation), yielding slower velocity (~1–2 m/s) with higher metabolic energy cost.</li>\n\n              <li><strong>(c) Aqueous Humor vs. Vitreous Humor:</strong><br>\n              • <em>Aqueous Humor:</em> Thin, clear, watery fluid filling the anterior chamber between cornea and lens, continually produced by ciliary processes and drained into Canal of Schlemm to nourish avascular lens and cornea.<br>\n              • <em>Vitreous Humor:</em> Transparent, gelatinous, non-renewing jelly filling the posterior cavity between lens and retina, providing intraocular pressure to keep retina flat against choroid.</li>\n\n              <li><strong>(d) Blind Spot vs. Yellow Spot (Macula Lutea / Fovea):</strong><br>\n              • <em>Blind Spot (Optic Disc):</em> Region medial to the posterior pole where the optic nerve exits and central retinal vessels enter; completely devoid of photoreceptors (zero visual perception).<br>\n              • <em>Yellow Spot (Fovea Centralis):</em> Thinned-out pit on the optical axis lateral to the blind spot, containing only densely packed cones with 1:1 ganglion synapses; site of maximum visual acuity and sharpest color resolution.</li>\n\n              <li><strong>(e) Cranial Nerves vs. Spinal Nerves:</strong><br>\n              • <em>Cranial Nerves:</em> 12 pairs of peripheral nerves originating directly from the brain/brainstem, innervating predominantly head, neck, and thoracic/abdominal viscera (vagus nerve).<br>\n              • <em>Spinal Nerves:</em> 31 pairs of mixed peripheral nerves arising segmentally from the spinal cord, innervating the trunk and upper/lower limbs.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Afferent (to CNS) vs Efferent (from CNS to effectors)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Myelinated (saltatory, fast) vs Unmyelinated (continuous, slow)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Aqueous (watery, anterior) vs Vitreous (gelatinous, posterior)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) Blind spot (no photoreceptors) vs Yellow spot (pure cones, maximum resolution)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(e) Cranial nerves (12 pairs from brain) vs Spinal nerves (31 pairs from spinal cord)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(17)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 17 (Locomotion &amp; Movement)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(19)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; cursor:pointer;\">Next: Ch 19 (Chemical Coordination) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[19] = "<section class=\"chapter-section\" id=\"c11b-ch19\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#16a34a;\">19</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#16a34a;\">CBSE Class 11 Biology &bull; Chapter 19</div>\n      <h2>Chemical Coordination and Integration</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 10 Verbatim Questions with Official Step-by-Step Marking Rubrics &amp; Endocrine Anatomy Diagrams</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:#f0fdf4; border:1.5px solid #86efac; border-radius:12px; padding:18px; margin-bottom:24px;\">\n    <div style=\"font-weight:800; color:#166534; font-size:0.95rem; margin-bottom:8px; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#16a34a\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"/></svg>\n      Figure 19.1: Endocrine Glands System &amp; Dual Mechanisms of Hormone Action\n    </div>\n    <svg viewBox=\"0 0 850 240\" width=\"100%\" height=\"auto\" style=\"max-height:240px; font-family:'Plus Jakarta Sans',sans-serif;\">\n      <rect x=\"10\" y=\"10\" width=\"830\" height=\"220\" rx=\"10\" fill=\"#ffffff\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      \n      <!-- Left: Peptide Hormone (Membrane Receptors & Second Messengers) -->\n      <g transform=\"translate(30, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"380\" height=\"200\" rx=\"8\" fill=\"#eff6ff\" stroke=\"#93c5fd\"/>\n        <text x=\"190\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">PEPTIDE / PROTEIN HORMONE (e.g., FSH, INSULIN)</text>\n        \n        <!-- Cell Membrane -->\n        <rect x=\"20\" y=\"35\" width=\"340\" height=\"12\" rx=\"3\" fill=\"#cbd5e1\" stroke=\"#94a3b8\"/>\n        <text x=\"190\" y=\"44\" font-size=\"7.5\" fill=\"#475569\" text-anchor=\"middle\">Target Cell Membrane (Lipid Bilayer)</text>\n\n        <!-- Hormone & Membrane Receptor -->\n        <circle cx=\"80\" cy=\"25\" r=\"7\" fill=\"#ef4444\"/>\n        <text x=\"95\" y=\"28\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#b91c1c\">Hormone</text>\n        \n        <path d=\"M 70,35 L 70,55 L 90,55 L 90,35\" fill=\"#f59e0b\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n        <text x=\"100\" y=\"52\" font-size=\"7\" fill=\"#b45309\">Membrane Receptor</text>\n\n        <!-- Generation of Second Messenger -->\n        <path d=\"M 80,55 L 80,75\" stroke=\"#2563eb\" stroke-width=\"2\" marker-end=\"url(#arrB)\"/>\n        <rect x=\"40\" y=\"75\" width=\"300\" height=\"30\" rx=\"4\" fill=\"#ffffff\" stroke=\"#93c5fd\"/>\n        <text x=\"190\" y=\"88\" font-size=\"8\" font-weight=\"bold\" fill=\"#1d4ed8\" text-anchor=\"middle\">Generation of 2nd Messenger (cAMP / IP3 / Ca2+)</text>\n        <text x=\"190\" y=\"99\" font-size=\"7\" fill=\"#475569\" text-anchor=\"middle\">Hormone does NOT enter target cell cytoplasm</text>\n\n        <!-- Biochemical Response -->\n        <path d=\"M 190,105 L 190,120\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n        <rect x=\"40\" y=\"120\" width=\"300\" height=\"30\" rx=\"4\" fill=\"#ffffff\" stroke=\"#93c5fd\"/>\n        <text x=\"190\" y=\"133\" font-size=\"8\" font-weight=\"bold\" fill=\"#047857\" text-anchor=\"middle\">Biochemical Cascades (Protein Kinase Activation)</text>\n        <text x=\"190\" y=\"144\" font-size=\"7\" fill=\"#475569\" text-anchor=\"middle\">Phosphorylation of key regulatory enzymes</text>\n\n        <!-- Physiological Response -->\n        <path d=\"M 190,150 L 190,165\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n        <rect x=\"40\" y=\"165\" width=\"300\" height=\"25\" rx=\"4\" fill=\"#dbeafe\" stroke=\"#3b82f6\"/>\n        <text x=\"190\" y=\"181\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e3a8a\" text-anchor=\"middle\">Physiological Effect (e.g., Ovarian Growth / Glucose Uptake)</text>\n      </g>\n\n      <!-- Right: Steroid Hormone (Intracellular Nuclear Receptors & Gene Expression) -->\n      <g transform=\"translate(435, 20)\">\n        <rect x=\"0\" y=\"0\" width=\"385\" height=\"200\" rx=\"8\" fill=\"#fdf4ff\" stroke=\"#f0abfc\"/>\n        <text x=\"192\" y=\"20\" font-size=\"10.5\" font-weight=\"bold\" fill=\"#86198f\" text-anchor=\"middle\">STEROID / IODOTHYRONINE HORMONE (e.g., ESTROGEN, T4)</text>\n\n        <!-- Cell Membrane -->\n        <rect x=\"20\" y=\"35\" width=\"345\" height=\"12\" rx=\"3\" fill=\"#cbd5e1\" stroke=\"#94a3b8\"/>\n        \n        <!-- Lipid-soluble hormone diffusing directly -->\n        <circle cx=\"60\" cy=\"25\" r=\"7\" fill=\"#a855f7\"/>\n        <path d=\"M 60,32 L 60,65\" stroke=\"#9333ea\" stroke-width=\"2\" stroke-dasharray=\"3,2\"/>\n        <text x=\"75\" y=\"28\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#7e22ce\">Steroid Hormone (Lipid Soluble)</text>\n        <text x=\"75\" y=\"55\" font-size=\"7\" fill=\"#6b21a8\">Diffuses freely through lipid bilayer</text>\n\n        <!-- Nucleus and Intracellular Receptor -->\n        <rect x=\"40\" y=\"70\" width=\"305\" height=\"115\" rx=\"6\" fill=\"#ffffff\" stroke=\"#e879f9\" stroke-width=\"1.5\"/>\n        <text x=\"192\" y=\"85\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#a21caf\" text-anchor=\"middle\">Nucleus &amp; Intracellular Receptor Complex</text>\n\n        <!-- Hormone Receptor Complex -->\n        <rect x=\"60\" y=\"95\" width=\"265\" height=\"24\" rx=\"4\" fill=\"#fae8ff\" stroke=\"#c084fc\"/>\n        <text x=\"192\" y=\"110\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#7e22ce\" text-anchor=\"middle\">Hormone-Receptor Complex binds to Genome / DNA</text>\n\n        <!-- mRNA & Protein Synthesis -->\n        <path d=\"M 192,119 L 192,130\" stroke=\"#a855f7\" stroke-width=\"2\"/>\n        <rect x=\"60\" y=\"130\" width=\"265\" height=\"24\" rx=\"4\" fill=\"#f3e8ff\" stroke=\"#a855f7\"/>\n        <text x=\"192\" y=\"145\" font-size=\"7.5\" font-weight=\"bold\" fill=\"#581c87\" text-anchor=\"middle\">Transcription &rarr; mRNA &rarr; New Protein Synthesis</text>\n\n        <!-- Physiological Response -->\n        <rect x=\"60\" y=\"160\" width=\"265\" height=\"20\" rx=\"3\" fill=\"#e9d5ff\" stroke=\"#9333ea\"/>\n        <text x=\"192\" y=\"174\" font-size=\"8\" font-weight=\"bold\" fill=\"#3b0764\" text-anchor=\"middle\">Physiological Response (Differentiation / Morphogenesis)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">NCERT Textbook Exercise 1 to 10: Endocrine Glands, Hormones, Mechanism of Hormone Action, Deficiencies &amp; Disorders</div>\n\n  <!-- c11b-ch19-q1 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Define the following:<br>\n        (a) Exocrine gland<br>\n        (b) Endocrine gland<br>\n        (c) Hormone\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Precise Scientific Definitions:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Exocrine Gland:</strong> Glands that pour their secretions (enzymes, mucus, sweat, sebum, saliva) through specialized ducts or tubes directly to target surfaces or internal cavities. <em>Examples:</em> Salivary glands, sweat glands, sebaceous glands, gastric glands, and exocrine pancreas (acini).</li>\n              <li><strong>(b) Endocrine Gland:</strong> Ductless glands that lack excretory ducts and pour their secretions (hormones) directly into the surrounding extracellular fluid and venous bloodstream, which transports them to distant target tissues. <em>Examples:</em> Pituitary gland, thyroid gland, adrenal gland, and parathyroid gland.</li>\n              <li><strong>(c) Hormone (Modern NCERT Definition):</strong> Hormones are <strong>non-nutrient chemicals</strong> that act as <strong>intercellular messengers</strong>, are produced in <strong>trace amounts</strong> by endocrine glands or specialized neurosecretory tissues, and are transported via the circulatory system to regulate physiological and biochemical processes in distant specific target cells.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Exocrine gland: ducted glands releasing secretions to body surfaces/cavities with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Endocrine gland: ductless glands secreting hormones directly into blood with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Hormone: non-nutrient chemicals, intercellular messengers, trace amounts, distant targets</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q2 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Diagrammatically indicate the location of the various endocrine glands in our body.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Anatomical Locations of Major Endocrine Glands in the Human Body:</strong><br><br>\n\n            <div style=\"background:#ffffff; border:1.5px solid #86efac; border-radius:10px; padding:16px; margin:10px 0; text-align:center;\">\n              <div style=\"font-weight:800; color:#15803d; font-size:0.9rem; margin-bottom:10px;\">\n                Diagram: Spatial Distribution of Human Endocrine Glands\n              </div>\n              <svg viewBox=\"0 0 760 360\" width=\"100%\" height=\"auto\" style=\"max-height:360px; font-family:'Plus Jakarta Sans',sans-serif;\">\n                <rect x=\"5\" y=\"5\" width=\"750\" height=\"350\" rx=\"8\" fill=\"#f8fafc\" stroke=\"#cbd5e1\"/>\n\n                <!-- Human Body Silhouette -->\n                <!-- Head & Neck -->\n                <circle cx=\"380\" cy=\"55\" r=\"28\" fill=\"#e2e8f0\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n                <rect x=\"372\" y=\"80\" width=\"16\" height=\"25\" fill=\"#e2e8f0\" stroke=\"#94a3b8\"/>\n                \n                <!-- Torso -->\n                <path d=\"M 330,105 L 430,105 L 415,240 L 345,240 Z\" fill=\"#f1f5f9\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/>\n\n                <!-- Pelvis & Legs indication -->\n                <path d=\"M 345,240 L 330,320 M 415,240 L 430,320\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n                <!-- 1. Hypothalamus & Pineal (Brain) -->\n                <circle cx=\"377\" cy=\"48\" r=\"4\" fill=\"#dc2626\"/>\n                <line x1=\"377\" y1=\"48\" x2=\"220\" y2=\"40\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n                <rect x=\"110\" y=\"30\" width=\"110\" height=\"22\" rx=\"4\" fill=\"#fee2e2\" stroke=\"#ef4444\"/>\n                <text x=\"165\" y=\"45\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#991b1b\" text-anchor=\"middle\">Hypothalamus</text>\n\n                <circle cx=\"385\" cy=\"45\" r=\"3\" fill=\"#7c3aed\"/>\n                <line x1=\"385\" y1=\"45\" x2=\"540\" y2=\"35\" stroke=\"#7c3aed\" stroke-width=\"1.5\"/>\n                <rect x=\"540\" y=\"25\" width=\"100\" height=\"22\" rx=\"4\" fill=\"#ede9fe\" stroke=\"#8b5cf6\"/>\n                <text x=\"590\" y=\"40\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#5b21b6\" text-anchor=\"middle\">Pineal Gland</text>\n\n                <!-- 2. Pituitary (Base of brain) -->\n                <circle cx=\"378\" cy=\"58\" r=\"4\" fill=\"#2563eb\"/>\n                <line x1=\"378\" y1=\"58\" x2=\"220\" y2=\"68\" stroke=\"#2563eb\" stroke-width=\"1.5\"/>\n                <rect x=\"110\" y=\"58\" width=\"110\" height=\"22\" rx=\"4\" fill=\"#dbeafe\" stroke=\"#3b82f6\"/>\n                <text x=\"165\" y=\"73\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#1e40af\" text-anchor=\"middle\">Pituitary Gland</text>\n\n                <!-- 3. Thyroid & Parathyroid (Neck) -->\n                <path d=\"M 374,90 Q 380,95 386,90\" fill=\"#f59e0b\" stroke=\"#d97706\" stroke-width=\"4\"/>\n                <line x1=\"374\" y1=\"92\" x2=\"220\" y2=\"98\" stroke=\"#d97706\" stroke-width=\"1.5\"/>\n                <rect x=\"100\" y=\"88\" width=\"120\" height=\"22\" rx=\"4\" fill=\"#fef3c7\" stroke=\"#f59e0b\"/>\n                <text x=\"160\" y=\"103\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#92400e\" text-anchor=\"middle\">Thyroid &amp; Parathyroid</text>\n\n                <!-- 4. Thymus (Chest / Sternum) -->\n                <ellipse cx=\"380\" cy=\"125\" rx=\"8\" ry=\"12\" fill=\"#10b981\" stroke=\"#059669\"/>\n                <line x1=\"388\" y1=\"125\" x2=\"540\" y2=\"120\" stroke=\"#059669\" stroke-width=\"1.5\"/>\n                <rect x=\"540\" y=\"110\" width=\"110\" height=\"22\" rx=\"4\" fill=\"#d1fae5\" stroke=\"#10b981\"/>\n                <text x=\"595\" y=\"125\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#065f46\" text-anchor=\"middle\">Thymus Gland</text>\n\n                <!-- 5. Adrenals (atop kidneys) -->\n                <polygon points=\"360,165 365,158 370,165\" fill=\"#ea580c\"/>\n                <polygon points=\"390,165 395,158 400,165\" fill=\"#ea580c\"/>\n                <line x1=\"360\" y1=\"162\" x2=\"220\" y2=\"155\" stroke=\"#ea580c\" stroke-width=\"1.5\"/>\n                <rect x=\"110\" y=\"145\" width=\"110\" height=\"22\" rx=\"4\" fill=\"#ffedd5\" stroke=\"#ea580c\"/>\n                <text x=\"165\" y=\"160\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#9a3412\" text-anchor=\"middle\">Adrenal Glands</text>\n\n                <!-- 6. Pancreas (Abdomen) -->\n                <ellipse cx=\"380\" cy=\"178\" rx=\"14\" ry=\"6\" fill=\"#0284c7\" stroke=\"#0369a1\"/>\n                <line x1=\"394\" y1=\"178\" x2=\"540\" y2=\"175\" stroke=\"#0369a1\" stroke-width=\"1.5\"/>\n                <rect x=\"540\" y=\"165\" width=\"100\" height=\"22\" rx=\"4\" fill=\"#e0f2fe\" stroke=\"#0284c7\"/>\n                <text x=\"590\" y=\"180\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#075985\" text-anchor=\"middle\">Pancreas</text>\n\n                <!-- 7. Ovary (Female pelvis) -->\n                <circle cx=\"370\" cy=\"225\" r=\"5\" fill=\"#db2777\"/>\n                <line x1=\"365\" y1=\"225\" x2=\"220\" y2=\"225\" stroke=\"#db2777\" stroke-width=\"1.5\"/>\n                <rect x=\"90\" y=\"215\" width=\"130\" height=\"22\" rx=\"4\" fill=\"#fce7f3\" stroke=\"#ec4899\"/>\n                <text x=\"155\" y=\"230\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#9d174d\" text-anchor=\"middle\">Ovary (in females)</text>\n\n                <!-- 8. Testis (Male scrotum) -->\n                <circle cx=\"390\" cy=\"270\" r=\"6\" fill=\"#0891b2\"/>\n                <line x1=\"396\" y1=\"270\" x2=\"540\" y2=\"265\" stroke=\"#0891b2\" stroke-width=\"1.5\"/>\n                <rect x=\"540\" y=\"255\" width=\"110\" height=\"22\" rx=\"4\" fill=\"#cffafe\" stroke=\"#06b6d4\"/>\n                <text x=\"595\" y=\"270\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#155e75\" text-anchor=\"middle\">Testis (in males)</text>\n              </svg>\n            </div>\n\n            <strong>Detailed Anatomical Distribution:</strong>\n            <ul style=\"margin:2px 0 4px 20px;\">\n              <li><strong>1. Hypothalamus:</strong> Basal part of the diencephalon, forebrain.</li>\n              <li><strong>2. Pituitary Gland:</strong> Located in a bony cavity of the sphenoid bone termed the <em>sella turcica</em>, attached to the hypothalamus via an infundibular stalk.</li>\n              <li><strong>3. Pineal Gland:</strong> Situated on the dorsal side of the forebrain.</li>\n              <li><strong>4. Thyroid Gland:</strong> Located in the neck on either side of the trachea, interconnected across the midline by a thin flap of tissue called the <em>isthmus</em>.</li>\n              <li><strong>5. Parathyroid Glands:</strong> Four small glands embedded on the posterior surface of the two lobes of the thyroid gland (one pair on each lobe).</li>\n              <li><strong>6. Thymus Gland:</strong> Located in the anterior thoracic mediastinum between the lungs, dorsal to the sternum on the ventral side of the aorta.</li>\n              <li><strong>7. Adrenal Glands:</strong> One pair of suprarenal glands situated atop the anterior pole of each kidney.</li>\n              <li><strong>8. Pancreas:</strong> Located in the loop of the duodenum in the abdominal cavity (heterocrine gland; endocrine part consists of Islets of Langerhans).</li>\n              <li><strong>9. Gonads:</strong> <em>Testes</em> located extra-abdominally inside the scrotal sac in males; <em>Ovaries</em> located in the lower abdominal pelvic cavity in females.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat human outline diagram showing accurate locations of endocrine glands</span><span class=\"marking-marks\">3 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate labeling of Hypothalamus, Pituitary, Thyroid, Adrenal, Pancreas, and Gonads</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q3 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        List the hormones secreted by the following:<br>\n        (a) Hypothalamus<br>\n        (b) Pituitary<br>\n        (c) Thyroid<br>\n        (d) Parathyroid<br>\n        (e) Adrenal<br>\n        (f) Pancreas<br>\n        (g) Testis<br>\n        (h) Ovary<br>\n        (i) Thymus<br>\n        (j) Atrium<br>\n        (k) Kidney<br>\n        (l) G-I Tract\n      </div>\n      <div class=\"q-marks\">[6 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Complete Comprehensive Hormonal Secretory Inventory:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Hypothalamus:</strong> Releasing hormones: GnRH, TRH, CRH, GHRH, PRH; Inhibiting hormones: Somatostatin (GHIH) and Dopamine (PIH). Synthesizes Oxytocin and Vasopressin (ADH).</li>\n              <li><strong>(b) Pituitary Gland:</strong>\n                <ul style=\"margin:2px 0 2px 15px;\">\n                  <li><em>Anterior Pituitary (Pars distalis):</em> Growth Hormone (GH), Thyroid-Stimulating Hormone (TSH), Adrenocorticotropic Hormone (ACTH), Luteinizing Hormone (LH), Follicle-Stimulating Hormone (FSH), and Prolactin (PRL).</li>\n                  <li><em>Intermediate Lobe (Pars intermedia):</em> Melanocyte-Stimulating Hormone (MSH).</li>\n                  <li><em>Posterior Pituitary (Pars nervosa):</em> Releases Oxytocin and Vasopressin (synthesized by hypothalamus).</li>\n                </ul>\n              </li>\n              <li><strong>(c) Thyroid Gland:</strong> Tetraiodothyronine / Thyroxine ($T_4$), Triiodothyronine ($T_3$), and Thyrocalcitonin (TCT &mdash; hypocalcemic hormone).</li>\n              <li><strong>(d) Parathyroid Gland:</strong> Parathyroid Hormone (PTH / Collip's hormone &mdash; hypercalcemic hormone).</li>\n              <li><strong>(e) Adrenal Glands:</strong>\n                <ul style=\"margin:2px 0 2px 15px;\">\n                  <li><em>Adrenal Cortex:</em> Mineralocorticoids (Aldosterone), Glucocorticoids (Cortisol), and Androgenic corticoids (DHEA).</li>\n                  <li><em>Adrenal Medulla:</em> Catecholamines &mdash; Adrenaline (Epinephrine) and Noradrenaline (Norepinephrine).</li>\n                </ul>\n              </li>\n              <li><strong>(f) Pancreas (Islets of Langerhans):</strong> &alpha;-cells secrete <strong>Glucagon</strong> (hyperglycemic); &beta;-cells secrete <strong>Insulin</strong> (hypoglycemic); &delta;-cells secrete <strong>Somatostatin</strong>.</li>\n              <li><strong>(g) Testis:</strong> Androgens, primarily <strong>Testosterone</strong> (secreted by Leydig / interstitial cells) and Inhibin.</li>\n              <li><strong>(h) Ovary:</strong> <strong>Estrogen</strong> (secreted by developing ovarian follicles), <strong>Progesterone</strong> (secreted by corpus luteum), Relaxin, and Inhibin.</li>\n              <li><strong>(i) Thymus Gland:</strong> <strong>Thymosins</strong> (promotes differentiation and maturation of T-lymphocytes).</li>\n              <li><strong>(j) Atrium of Heart:</strong> <strong>Atrial Natriuretic Factor (ANF)</strong> (causes vasodilation and lowers blood pressure).</li>\n              <li><strong>(k) Kidney (JG Cells):</strong> <strong>Erythropoietin (EPO)</strong> (stimulates erythropoiesis in bone marrow) and Renin.</li>\n              <li><strong>(l) Gastro-Intestinal (G-I) Tract:</strong> <strong>Gastrin</strong> (stimulates HCl &amp; pepsinogen), <strong>Secretin</strong> (stimulates water and bicarbonate secretion from pancreas), <strong>Cholecystokinin (CCK)</strong> (stimulates bile from gallbladder and pancreatic enzymes), and <strong>Gastric Inhibitory Peptide (GIP)</strong> (inhibits gastric secretion).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">0.5 Mark each for correctly listing all hormones of categories (a) through (l)</span><span class=\"marking-marks\">6 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q4 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Fill in the blanks:<br>\n        (a) Hormones ______<br>\n        (b) Thyroxine ______<br>\n        (c) Parathyroid hormone ______<br>\n        (d) Thyroid hormone ______\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Standard Textual Completions:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li>(a) Hormones are <strong>non-nutrient chemicals that act as intercellular messengers and are produced in trace amounts</strong>.</li>\n              <li>(b) Thyroxine regulates the <strong>basal metabolic rate (BMR) and cellular oxidative metabolism</strong> of the body.</li>\n              <li>(c) Parathyroid hormone (PTH) <strong>increases blood calcium ($Ca^{2+}$) levels</strong> by stimulating bone resorption, renal $Ca^{2+}$ reabsorption, and intestinal absorption.</li>\n              <li>(d) Thyroid hormone controls <strong>basic metabolic rate, red blood cell synthesis (erythropoiesis), and maintenance of water-electrolyte balance</strong>.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) non-nutrient chemicals / intercellular messengers in trace amounts</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) basal metabolic rate (BMR)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) increases blood calcium (Ca2+) levels (hypercalcemic)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) BMR, erythropoiesis, and water-electrolyte balance</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q5 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Explain the mechanism of hormone action.\n      </div>\n      <div class=\"q-marks\">[5 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Dual Molecular Mechanisms of Hormone Action:</strong><br>\n            Hormones produce biochemical effects on target tissues by binding specifically to high-affinity target proteins called <strong>hormone receptors</strong>. A hormone binds only to its specific receptor, forming a <strong>hormone-receptor complex (H-R complex)</strong>. Hormones act via two major biochemical pathways depending on their chemical nature:<br><br>\n\n            <strong>1. Mechanism of Peptide / Water-Soluble Hormones (Membrane Receptor &amp; Second Messengers):</strong><br>\n            • Hormones such as FSH, LH, TSH, ACTH, Insulin, and Glucagon are water-soluble proteins that cannot traverse the hydrophobic lipid bilayer of the plasma membrane.<br>\n            • They bind to <strong>extracellular membrane-bound receptors</strong> on the cell surface.<br>\n            • Formation of the H-R complex activates G-proteins and membrane-bound <strong>adenylate cyclase</strong> (or phospholipase C).<br>\n            • This catalyzes the conversion of intracellular ATP into <strong>secondary messengers</strong>, primarily <strong>cyclic AMP (cAMP)</strong>, $IP_3$, or $Ca^{2+}$.<br>\n            • These second messengers activate specific protein kinases, initiating enzyme cascades and cellular biochemical responses (e.g., glycogenolysis, steroidogenesis, ovarian follicular growth).<br><br>\n\n            <strong>2. Mechanism of Steroid and Iodothyronine Hormones (Intracellular Receptors &amp; Gene Expression):</strong><br>\n            • Hormones such as Estrogen, Progesterone, Testosterone, Cortisol, Aldosterone, and Thyroid hormones ($T_3, T_4$) are lipid-soluble and diffuse freely across the plasma membrane.<br>\n            • They bind to <strong>intracellular receptors</strong> (located either in the cytoplasm or mostly inside the nucleus).<br>\n            • The hormone-receptor complex translocates into the nucleus and binds to specific <strong>Hormone Response Elements (HRE)</strong> on chromosomal DNA.<br>\n            • This regulates transcription of target genes into messenger RNA (mRNA), directing the de novo synthesis of specific functional and structural proteins/enzymes, resulting in long-term physiological and morphological responses (e.g., uterine growth, tissue differentiation, metabolic rate regulation).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hormone-receptor complex concept and specificity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Peptide hormones: membrane-bound receptor, G-protein, cAMP/IP3/Ca2+ second messengers</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Steroid hormones: lipid bilayer diffusion, intracellular nuclear receptor, DNA gene transcription</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q6 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Give example(s) of:<br>\n        (a) Hyperglycemic hormone and hypoglycemic hormone<br>\n        (b) Hypercalcemic hormone<br>\n        (c) Gonadotrophic hormones<br>\n        (d) Progestational hormone<br>\n        (e) Blood pressure lowering hormone<br>\n        (f) Androgens and estrogens\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Precise Physiological Examples of Hormones:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Hyperglycemic &amp; Hypoglycemic Hormones:</strong><br>\n              • <em>Hyperglycemic Hormone (elevates blood glucose):</em> <strong>Glucagon</strong> (also Cortisol, Adrenaline, Growth Hormone).<br>\n              • <em>Hypoglycemic Hormone (lowers blood glucose):</em> <strong>Insulin</strong>.</li>\n\n              <li><strong>(b) Hypercalcemic Hormone:</strong><br>\n              <strong>Parathyroid Hormone (PTH / Collip's hormone)</strong> (increases blood $Ca^{2+}$ levels; contrasted with hypocalcemic Thyrocalcitonin).</li>\n\n              <li><strong>(c) Gonadotrophic Hormones:</strong><br>\n              <strong>Luteinizing Hormone (LH)</strong> and <strong>Follicle-Stimulating Hormone (FSH)</strong> (secreted by anterior pituitary gonadotrophs).</li>\n\n              <li><strong>(d) Progestational Hormone:</strong><br>\n              <strong>Progesterone</strong> (secreted by corpus luteum; maintains the endometrium for pregnancy).</li>\n\n              <li><strong>(e) Blood Pressure Lowering Hormone:</strong><br>\n              <strong>Atrial Natriuretic Factor (ANF)</strong> (released by heart atrial walls in response to elevated blood pressure; causes vasodilation and natriuresis).</li>\n\n              <li><strong>(f) Androgens and Estrogens:</strong><br>\n              • <em>Androgen:</em> <strong>Testosterone</strong> (and Dihydrotestosterone).<br>\n              • <em>Estrogen:</em> <strong>Estradiol</strong> (and Estrone, Estriol).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">0.5 Mark each for correct scientific identification of pairs (a) through (f)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q7 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Which hormonal deficiency is responsible for the following:<br>\n        (a) Diabetes mellitus<br>\n        (b) Goitre<br>\n        (c) Cretinism\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Hormonal Deficiencies and Associated Clinical Pathology:</strong><br><br>\n            <ul style=\"margin:2px 0 6px 20px;\">\n              <li><strong>(a) Diabetes Mellitus:</strong><br>\n              • <em>Deficient Hormone:</em> <strong>Insulin</strong> (secreted by &beta;-cells of Islets of Langerhans in the pancreas).<br>\n              • <em>Pathology:</em> Hyposecretion or cellular resistance to insulin prevents cellular glucose uptake, leading to prolonged hyperglycemia, glucosuria (glucose excretion in urine), and formation of harmful ketone bodies (ketoacidosis).</li>\n\n              <li><strong>(b) Simple Goitre:</strong><br>\n              • <em>Deficient Hormone:</em> <strong>Thyroxine ($T_4$) and Triiodothyronine ($T_3$)</strong> (due to dietary iodine deficiency).<br>\n              • <em>Pathology:</em> In the absence of dietary iodine, thyroid hormone production plummets. Lack of negative feedback triggers excessive pituitary TSH secretion, which overstimulates and enlarges the thyroid gland, presenting as a visible neck swelling.</li>\n\n              <li><strong>(c) Cretinism:</strong><br>\n              • <em>Deficient Hormone:</em> <strong>Thyroid hormones ($T_4, T_3$)</strong> during embryonic development, infancy, or early childhood (congenital hypothyroidism).<br>\n              • <em>Pathology:</em> Characterized by stunted physical growth, severe intellectual disability / mental retardation, deaf-mutism, abnormal skin, and delayed skeletal development.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) Diabetes mellitus: Insulin deficiency with hyperglycemia/glucosuria</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) Goitre: Thyroxine (T4/T3) deficiency caused by dietary iodine shortage</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) Cretinism: Congenital thyroid hormone deficiency causing stunted growth &amp; mental retardation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q8 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q8')\">\n      <div class=\"q-num\">Question 8</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Briefly mention the mechanism of action of FSH.\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Mechanism of Action of Follicle-Stimulating Hormone (FSH):</strong><br><br>\n            <ol style=\"margin:2px 0 6px 20px;\">\n              <li><strong>Chemical Nature &amp; Inability to Enter Cell:</strong> FSH is a glycoprotein (peptide) hormone. Because it is water-soluble and lipid-insoluble, it cannot cross the hydrophobic phospholipid bilayer of target ovarian granulosa cells.</li>\n              <li><strong>Membrane Receptor Binding:</strong> FSH binds specifically to high-affinity <strong>membrane-bound FSH receptors</strong> located on the outer surface of the ovarian cell membrane, forming a hormone-receptor complex.</li>\n              <li><strong>Generation of Second Messenger (cAMP):</strong> The formation of the hormone-receptor complex activates a stimulatory G-protein ($G_s$), which activates the enzyme <strong>adenylate cyclase</strong> on the inner face of the cell membrane. Adenylate cyclase converts ATP into <strong>cyclic AMP (cAMP)</strong> (the intracellular second messenger).</li>\n              <li><strong>Biochemical Cascades:</strong> Cyclic AMP activates protein kinase A (PKA), which phosphorylates specific intracellular enzymes and transcriptional factors.</li>\n              <li><strong>Physiological Response:</strong> These biochemical cascades stimulate <strong>ovarian follicular growth, maturation of Graafian follicles, and secretion of estrogen</strong>.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">FSH is a peptide hormone binding to extracellular membrane-bound receptors</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Generation of intracellular second messenger (cyclic AMP / cAMP) via adenylate cyclase</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Enzymatic phosphorylation leading to ovarian follicular development and estrogen synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q9 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q9')\">\n      <div class=\"q-num\">Question 9</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        Match the following:<br>\n        <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.85rem;\">\n          <tr style=\"font-weight:700; color:#15803d;\"><td style=\"width:50%;\">Column I</td><td>Column II</td></tr>\n          <tr><td>(a) $T_4$</td><td>(i) Hypothalamus</td></tr>\n          <tr><td>(b) PTH</td><td>(ii) Thyroid</td></tr>\n          <tr><td>(c) GnRH</td><td>(iii) Pituitary</td></tr>\n          <tr><td>(d) LH</td><td>(iv) Parathyroid</td></tr>\n        </table>\n      </div>\n      <div class=\"q-marks\">[2 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Accurate Column Matching and Endocrine Sources:</strong><br><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.86rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n                    <th style=\"padding:8px 12px; color:#065f46;\">Column I (Hormone)</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Column II (Secretory Source)</th>\n                    <th style=\"padding:8px 12px; color:#065f46;\">Biological Function</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(a) $T_4$ (Thyroxine)</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(ii) Thyroid</td>\n                    <td style=\"padding:8px 12px;\">Synthesized by follicular cells of the thyroid gland; regulates BMR.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(b) PTH (Parathyroid Hormone)</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iv) Parathyroid</td>\n                    <td style=\"padding:8px 12px;\">Synthesized by chief cells of parathyroid glands; hypercalcemic hormone.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:8px 12px; font-weight:700;\">(c) GnRH (Gonadotropin-Releasing Hormone)</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(i) Hypothalamus</td>\n                    <td style=\"padding:8px 12px;\">Neurosecretory peptide from hypothalamus stimulating pituitary gonadotrophs.</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:8px 12px; font-weight:700;\">(d) LH (Luteinizing Hormone)</td>\n                    <td style=\"padding:8px 12px; color:#16a34a; font-weight:800;\">(iii) Pituitary</td>\n                    <td style=\"padding:8px 12px;\">Secreted by anterior pituitary; triggers ovulation and corpus luteum formation in females, testosterone in males.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n            <br>\n            <strong>Summary of Correct Pairs:</strong><br>\n            <strong>(a) &rarr; (ii), &nbsp; (b) &rarr; (iv), &nbsp; (c) &rarr; (i), &nbsp; (d) &rarr; (iii)</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(a) to (ii) Thyroid</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(b) to (iv) Parathyroid</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(c) to (i) Hypothalamus</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(d) to (iii) Pituitary</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11b-ch19-q10 (NCERT Exercise) -->\n  <div class=\"q-card\" id=\"c11b-ch19-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11b-ch19-q10')\">\n      <div class=\"q-num\">Question 10</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#ecfdf5; color:#059669; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">NCERT Exercise</span><br>\n        What are the differences between diabetes mellitus and diabetes insipidus?\n      </div>\n      <div class=\"q-marks\">[3 Marks]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step Solution</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Clinical Comparison: Diabetes Mellitus vs. Diabetes Insipidus:</strong><br><br>\n            <div style=\"overflow-x:auto;\">\n              <table style=\"width:100%; border-collapse:collapse; margin:4px 0; font-size:0.85rem;\">\n                <thead>\n                  <tr style=\"background:#ecfdf5; border-bottom:2px solid #059669; text-align:left;\">\n                    <th style=\"padding:6px 10px; color:#065f46;\">Parameter</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Diabetes Mellitus</th>\n                    <th style=\"padding:6px 10px; color:#065f46;\">Diabetes Insipidus</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Hormonal Etiology</td>\n                    <td style=\"padding:6px 10px; color:#b91c1c; font-weight:700;\">Deficiency or cellular resistance to <strong>Insulin</strong> from pancreatic &beta;-cells.</td>\n                    <td style=\"padding:6px 10px; color:#2563eb; font-weight:700;\">Deficiency of <strong>Antidiuretic Hormone (ADH / Vasopressin)</strong> from hypothalamus/posterior pituitary.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Blood Glucose Level</td>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Elevated (<strong>Hyperglycemia</strong> &gt; 140–200 mg/dL).</td>\n                    <td style=\"padding:6px 10px;\">Completely <strong>normal</strong> blood glucose level.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Urine Characteristics</td>\n                    <td style=\"padding:6px 10px;\">Contains glucose (<strong>glucosuria</strong>), high specific gravity, contains ketone bodies in severe cases.</td>\n                    <td style=\"padding:6px 10px;\">Contains <strong>no glucose</strong>; extremely dilute, tasteless (insipid) urine with very low specific gravity.</td>\n                  </tr>\n                  <tr style=\"border-bottom:1px solid #e2e8f0;\">\n                    <td style=\"padding:6px 10px; font-weight:700;\">Polyuria Mechanism</td>\n                    <td style=\"padding:6px 10px;\">Osmotic diuresis caused by unreabsorbed luminal glucose pulling water.</td>\n                    <td style=\"padding:6px 10px;\">Failure of water reabsorption in collecting ducts due to absence of ADH-induced aquaporins (copious water loss up to 15–20 L/day).</td>\n                  </tr>\n                  <tr>\n                    <td style=\"padding:6px 10px; font-weight:700;\">Treatment</td>\n                    <td style=\"padding:6px 10px;\">Insulin injections, dietary carbohydrate regulation, metformin.</td>\n                    <td style=\"padding:6px 10px;\">Administration of synthetic vasopressin / desmopressin nasal spray.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hormonal cause: Insulin deficiency vs ADH/Vasopressin deficiency</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Blood glucose &amp; urine composition: Hyperglycemia/glucosuria vs normal glucose/dilute urine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mechanism of polyuria &amp; clinical treatment</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(18)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 18 (Neural Control)</button>\n    <a href=\"../ncert-solutions-class-11.html\" class=\"ch-nav-btn next\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#16a34a; color:white; font-weight:700; text-decoration:none; display:inline-block;\">Class 11 All Subjects Hub →</a>\n  </div>\n</section>";
